// data/kronoloji_cok_once1281_ortadogu.js — paketle.py İNCELTTİ: ic_not* alanları yayına gitmez (kaynak dosya değişmedi)
window.KRONOLOJI_COK_ONCE1281_ORTADOGU = [{"t":"1001-01-01","tur":"hukumdar","k":"hukumdar","b":"Ukaylî emîri Mukalled öldürüldü, yerine oğlu Karvâş geçti","gun":"Ocak 1001 (gün bilinmiyor)","yer":"Musul","yer_id":"Musul","kisiler":"Hüsâmüddevle Mukalled; Mu‘temidüddevle Karvâş","d":"Musul Ukaylî emîri Hüsâmüddevle Mukalled, Bağdat'ı ele geçirmeyi planladığı sırada bir Türk gulâmı tarafından öldürüldü. Yerine oğlu Karvâş (Kırvâş) geçti ve yaklaşık elli yıl sürecek emirliği boyunca Büveyhîler, Abbâsîler ve Fâtımîler arasındaki çekişmeden yararlanmaya çalıştı.","kaynak":"TDV: ukayliler (\"Bağdat’ı ele geçirmeyi planladığı sırada kendisinden intikam almak isteyen bir Türk gulâmı tarafından öldürüldü (Safer 391 / Ocak 1001).\")","taraflar":["ukayli"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1002-01-01","tur":"hukumdar","k":"hukumdar","b":"Hâcib Lü'lü' Hamdânî emîri Saîdüddevle'yi zehirleyerek yönetimi ele geçirdi","gun":"392 / 1002 (TDV yıl verir)","yer":"Halep","yer_id":"Halep","kisiler":"Saîdüddevle; Hâcib Lü'lü'","d":"Halep'te Hamdânî tahtını ele geçirmeyi uzun süredir planlayan hâcib Lü'lü', damadı Saîdüddevle'yi zehirleyerek ortadan kaldırdı. İki yıl kadar Saîdüddevle'nin oğulları adına ülkeyi yönetti; bu, Hamdânîler'in Halep kolunun fiilen sona ermesinin başlangıcı oldu.","kaynak":"TDV: hamdaniler (\"392 (1002) yılında, bir süreden beri Hamdânî tahtını ele geçirmeyi planlayan Hâcib Lü’lü’ damadı Saîdüddevle’yi zehirleyerek ortadan kaldırdı ve iki yıl kadar onun oğulları adına devleti yönetti.\")","taraflar":["hamdani-halep"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1010-08-15","tur":"vassal","k":"vassal","b":"Ukaylî Karvâş ve Harran Nümeyrîleri Fâtımî hâkimiyetini tanıdı","gun":"401 / 1010-11 (TDV yıl verir)","yer":"Musul, Harran","yer_id":"Musul","kisiler":"Karvâş b. Mukallid; Fâtımî Halifesi Hâkim-Biemrillâh","d":"Büveyhîler'in olumsuz tutumuna tepki gösteren Ukaylî emîri Karvâş, Musul'da hutbeyi Fâtımî Halifesi Hâkim-Biemrillâh adına okuttu; Harran'daki Nümeyrîler de aynı yıl Fâtımî hâkimiyetini tanıdı. Üzerine kuvvet sevkedilince Karvâş özür dileyip hutbeyi yeniden Abbâsî halifesi adına okutmaya döndü.","kaynak":"TDV: cezire (\"Ukaylîler’den Kırvaş b. Mukallid ile Harran’daki Nümeyrîler 401 (1010-11) yılında Fâtımîler’in hâkimiyetini tanıdılar.\"); ukayliler","taraflar":["ukayli","numeyri"],"onem":2,"dunya":2,"kapsam":"dis","etiket":["vassal","konu-siyasi","konu-dini"]},{"t":"1011-01-01","tur":"isyan","k":"isyan","b":"Mekke Emîri Ebü'l-Fütûh bağımsızlığını ilân edip adına hutbe okuttu","gun":"(TDV yıl verir)","yer":"Mekke","yer_id":"Mekke","kisiler":"Ebü'l-Fütûh el-Mûsevî; Hâkim-Biemrillâh","d":"Abbâsî-Fâtımî rekabetinden yararlanan Mekke Emîri Ebü'l-Fütûh el-Mûsevî, adına para bastırıp hutbe okutarak bağımsızlığını ilân etti. Ertesi yıl Remle'de Râşid-Billâh lakabıyla halifeliğini ilân edince Fâtımî Halifesi Hâkim, onun yokluğunda Mekke'ye amcazadesini atadı; ancak Ebü'l-Fütûh yönetimi geri aldı.","kaynak":"TDV: mekke (\"bağımsızlığını ilân ederek adına para bastırıp hutbe okuttu (402/1011; İbnü’l-Esîr, IX, 123)\")","taraflar":["mekke-serifligi","fatimi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["isyan","konu-siyasi"]},{"odak_yer":["Hemedan"],"t":"1012-12-22","tur":"bolunme","k":"bolunme","b":"Bahâüddevle'nin ölümüyle Büveyhî birliği parçalandı","gun":"1012 (TDV yıl verir)","yer":"Irak, Fars","kisiler":"Bahâüddevle; Sultânüddevle","d":"Büveyhî hükümdarı Bahâüddevle'nin ölümü üzerine oğulları arasında uzun bir hâkimiyet mücadelesi başladı. Hânedanın büyük gayretlerle kurduğu birlik dağıldı; Irak'ta Deylemli ve Türk askerler arasındaki çatışma da Büveyhî gücünü aşındırdı.","kaynak":"TDV: buveyhiler (\"Bahâüddevle’nin 1012’de ölümüyle oğulları arasında uzun süren bir hâkimiyet mücadelesi başladı ve Büveyhîler’in büyük gayretlerle kurdukları birlik parçalandı.\")","taraflar":["buveyhi"],"onem":2,"dunya":2,"kapsam":"ic","etiket":["bolunme","hukumdar","konu-siyasi"]},{"odak_yer":["Hille"],"t":"1018-04-01","tur":"hukumdar","k":"hukumdar","b":"Mezyedî emîri Ali b. Mezyed öldü, yerine oğlu I. Dübeys geçti","gun":"Nisan 1018 (gün bilinmiyor)","yer":"Hille bölgesi (Nîl, Câmiayn)","kisiler":"Ali b. Mezyed; Nûrüddevle I. Dübeys; Mukalled","d":"Mezyedîler'in kurucusu Senâüddevle Ali b. Mezyed uzun bir emirliğin ardından öldü ve yerine oğlu Nûrüddevle I. Dübeys geçti. Kardeşi Mukalled emirlikte hak iddia ederek ayaklandı, ancak yenilip Musul Ukaylîleri'ne sığındı.","kaynak":"TDV: mezyediler (\"Ali b. Mezyed, uzun süre emirlik yaptıktan sonra Zilkade 408’de (Nisan 1018) vefat edince yerine oğlu Nûrüddevle I. Dübeys geçti.\")","taraflar":["mezyedi"],"onem":1,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1021-01-01","tur":"hukumdar","k":"hukumdar","b":"Müşerrifüddevle Irak'a hâkim oldu; Sultânüddevle Irak'tan çekildi","gun":"1021 (TDV yıl verir)","yer":"Bağdat","yer_id":"Bağdat","kisiler":"Müşerrifüddevle; Sultânüddevle","d":"Irak'taki Deylemli-Türk çatışmasında Türk askerlerinin desteklediği Müşerrifüddevle b. Bahâüddevle Irak'a hâkim oldu. Kardeşi Sultânüddevle Irak üzerindeki hâkimiyetinden vazgeçmek zorunda kaldı; Büveyhî kolları arasındaki ayrılık derinleşti.","kaynak":"TDV: buveyhiler (\"Sonuçta Türkler’in desteklediği Müşerrifüddevle b. Bahâüddevle Irak’a hâkim oldu (1021).\")","taraflar":["buveyhi"],"onem":1,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1025-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Nümeyrî reisi Utayr öldürüldü; Urfa Mervânîler'e geçti","gun":"416 / 1025 (TDV yıl verir)","yer":"Urfa","yer_id":"Urfa","kisiler":"Utayr en-Nümeyrî; Nasrüddevle (Mervânî)","d":"Urfa, Benî Nümeyr reisi Utayr'ın nâibi Ahmed b. Muhammed'in kontrolündeydi. Nâibin Utayr'ı öldürtmesine kızan halk şehrin idaresini Mervânî emîri Nasrüddevle'ye verdi; onun kumandanı Zengî b. Evân şehri işgal etti. Nümeyrîler Urfa'yı kaybetti.","kaynak":"TDV: sanliurfa (\"Şehir 416 (1025) yılına kadar Benî Nümeyr kabilesinin reisi Utayr’ın nâibi Ahmed b. Muhammed’in kontrolünde kaldı.\")","taraflar":["numeyri"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","konu-siyasi"]},{"odak_yer":["Gazne"],"t":"1029-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Gazneli Mahmud Rey'i aldı; Büveyhîler'in Cibâl kolu sona erdi","gun":"1029 (TDV yıl verir)","yer":"Rey","kisiler":"Gazneli Mahmud; Mecdüddevle Rüstem","d":"Ömrünün son yıllarında batıya yönelen Gazneli Mahmud Rey'e hâkim oldu ve Büveyhîler'in Cibâl kolunun Rey şubesine son verdi. Aynı dönemde Hemedan ve İsfahan şubesi de Kâkûyîler'in eline geçmişti; Büveyhîler kuzey İran'ı kaybetti.","kaynak":"TDV: buveyhiler (\"Gazneli Mahmud ise ömrünün son yıllarında batıya yöneldi ve Rey şehrine hâkim olarak Büveyhîler’in Cibâl koluna son verdi (1029).\")","taraflar":["buveyhi","gazneli"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["toprak-kayip","savas","konu-askeri"]},{"odak_yer":["Kahire"],"t":"1029-05-01","tur":"savas","k":"savas","b":"Fâtımî ordusu Mirdâsîleri yendi; Sâlih b. Mirdâs öldü","gun":"Rebîülâhir 420 / Mayıs 1029 (gün bilinmiyor)","yer":"Suriye (Ukhuvâne, Taberiye gölü yakını)","kisiler":"Sâlih b. Mirdâs, Anuş Tegin ed-Dizberî","d":"Mirdâsîlerin Halep ve Humus'tan Sayda'ya uzanan yayılması Fâtımî Halifesi Zâhir'i rahatsız etti. Halife, Anuş Tegin ed-Dizberî kumandasında bir orduyu Suriye'ye gönderdi. Savaşı Fâtımîler kazandı, hânedanın kurucusu Sâlih b. Mirdâs öldü. Halep'i oğulları Nasr ve Simâl paylaştı; merkezî Suriye yeniden Fâtımî denetimine döndü.","kaynak":"TDV: mirdasiler (\"Savaş Fâtımî ordusunun zaferi ve Sâlih b. Mirdâs’ın ölümüyle sonuçlandı (Rebîülâhir 420 / Mayıs 1029).\")","taraflar":["mirdasi","fatimi"],"onem":3,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"odak_yer":["Hemedan"],"t":"1030-01-09","tur":"toprak-kayip","k":"toprak-kayip","b":"Büveyhî Celâlüddevle Mezyedî topraklarına saldırdı; Dübeys ülkesini terketti","gun":"421 / 1030 (TDV yıl verir)","yer":"Merkezî Irak","kisiler":"Celâlüddevle; I. Dübeys; Mukalled","d":"Büveyhî taht mücadelesinde Ebû Kâlîcâr'ı destekleyen Mezyedî emîri Dübeys'e karşı, galip gelen Celâlüddevle Benî Hafâce ve Dübeys'in kardeşi Mukalled ile birlikte saldırdı. Dübeys ülkesini terketmek zorunda kaldı; ardından yüklü bir meblağ ödeyerek anlaşma yaptı ve topraklarına dönebildi.","kaynak":"TDV: mezyediler (\"Dübeys ülkesini terketmek zorunda kaldı (421/1030).\")","taraflar":["buveyhi","mezyedi"],"onem":1,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","savas","konu-askeri"]},{"t":"1030-01-01","tur":"savas","k":"savas","b":"Mirdâsîler Azâz yakınında Bizans ordusunu yendi","yer_id":"Azez (A'zâz)","gun":"Şâban 421 / Ağustos 1030 (gün bilinmiyor)","yer":"Azâz","kisiler":"Şiblüddevle Nasr b. Sâlih, III. Romanos Argyros","d":"Antakya'daki Bizans valisinin birlikleri 1029'da Kaybar'da yenilince İmparator III. Romanos intikam için bizzat sefere çıktı. Mirdâsîler Azâz yakınında imparatorun ordusunu bozguna uğratıp büyük ganimet aldı. Bu sırada Nasr, kardeşi Simâl'in yokluğunda iç kaleyi de alarak Halep'e tek başına hâkim oldu; ardından Bizans'la anlaşıp ona tâbi oldu.","kaynak":"TDV: mirdasiler (\"Mirdâsîler, Azâz yakınında Bizans ordusunu yenilgiye uğratarak büyük ganimet ele geçirdiler (Şâban 421 / Ağustos 1030).\")","taraflar":["mirdasi","bizans"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1036-01-01","tur":"savas","k":"savas","b":"Nümeyrî İbn Vessâb Urfa'yı yağmaladı, patriği esir aldı","gun":"427 / 1036 (TDV yıl verir)","yer":"Urfa","yer_id":"Urfa","kisiler":"İbn Vessâb en-Nümeyrî","d":"1030-31'den beri Bizans kumandanı Maniakes'in elinde bulunan Urfa'ya Nümeyrîler'den İbn Vessâb ve müttefikleri saldırdı; Urfa patriği esir düştü ve şehir yağmalandı. İç kale Bizans garnizonunda kaldı ve 1037'deki anlaşmayla şehir Bizans imparatoruna teslim edildi.","kaynak":"TDV: sanliurfa (\"Urfa patriği 427’de (1036) Nümeyrîler’den İbn Vessâb ve müttefiklerinin eline esir düştü ve şehir yağmalandı.\")","taraflar":["numeyri","bizans"],"onem":1,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1038-05-09","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Nasr b. Sâlih öldürüldü; Fâtımî ordusu Halep'e girdi","gun":"Şâban 429 / Mayıs 1038 (gün bilinmiyor)","yer":"Halep","yer_id":"Halep","kisiler":"Şiblüddevle Nasr b. Sâlih, Anuş Tegin ed-Dizberî","d":"Nasr'ın Fâtımîlerle Humus karşılığında vardığı uzlaşmaya Vezir Anuş Tegin karşı çıkınca iki taraf yeniden savaştı. Nasr b. Sâlih bu savaşta öldürüldü, kardeşi Simâl Halep'te tutunamadı. Anuş Tegin 1038'de Halep'e girdi, ardından Bâlis ve Menbic'i de aldı; birinci Fâtımî Halep hâkimiyeti başladı.","kaynak":"TDV: mirdasiler (\"Yapılan savaşta Nasr b. Sâlih öldürüldü (Şâban 429 / Mayıs 1038)\")","taraflar":["fatimi","mirdasi"],"onem":3,"dunya":1,"kapsam":"dis","etiket":["savas","toprak-kazanc","konu-askeri"]},{"t":"1042-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Anuş Tegin'in ölümüyle Halep halkı kapıları Simâl'e açtı","gun":"433 (1042) (TDV yıl verir)","yer":"Halep","yer_id":"Halep","kisiler":"Muizzüddevle Simâl b. Sâlih","d":"Fâtımî valisi Anuş Tegin ölünce Halep halkı şehri Mirdâsî Simâl b. Sâlih'e teslim etti. Bizans da Fâtımî Devleti de Simâl'in Halep hâkimiyetini tanıdı. Böylece dört yıllık birinci Fâtımî dönemi sona erdi ve Mirdâsî emirliği yeniden kuruldu.","kaynak":"TDV: mirdasiler (\"Anuş Tegin’in ölümü üzerine (433/1042) Halep halkı şehrin kapılarını Simâl’e açtı.\")","taraflar":["mirdasi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-siyasi"]},{"t":"1044-01-01","tur":"birlesme","k":"birlesme","b":"Ebû Kâlîcâr Büveyhîler'in Irak, Fars ve Kirman kollarını birleştirdi","gun":"1044 (TDV yıl verir)","yer":"Bağdat, Şîraz","yer_id":"Bağdat","kisiler":"Ebû Kâlîcâr; Celâlüddevle","d":"Irak Büveyhî hükümdarı Celâlüddevle'nin ölümüyle Bağdat'ta hutbe Fars hükümdarı Ebû Kâlîcâr adına okundu. Böylece Irak, Fars ve Kirman kolları tek elde toplandı; ancak bu sırada Selçuklular Büveyhî topraklarına doğru ilerlemeye başlamıştı.","kaynak":"TDV: buveyhiler (\"Celâlüddevle’nin 1044’te ölümüyle Bağdat’ta hutbe Ebû Kâlîcâr adına okundu.\")","taraflar":["buveyhi"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["birlesme","hukumdar","konu-siyasi"]},{"t":"1044-04-21","tur":"savas","k":"savas","b":"Karvâş ve müttefikleri Musul'u yağmalayan Oğuzlar'ı yendi","gun":"21 Nisan 1044","yer":"Musul","yer_id":"Musul","kisiler":"Karvâş; I. Dübeys (Mezyedî)","d":"Irak Oğuzları (Yabgulular) 1043'te Musul'u ele geçirip yağmalamış, Karvâş gemiyle kaçmıştı. Karvâş, Ukaylîler ve Mezyedî Dübeys'in desteğiyle topladığı kuvvetlerle Oğuzlar'ı yendi ve ağır kayıp veren Oğuzlar'ı Nusaybin'e kadar kovaladı; Musul yeniden Ukaylîler'e geçti.","kaynak":"TDV: ukayliler (\"20 Ramazan 435 (21 Nisan 1044) tarihinde yapılan savaşta Oğuzlar yenilgiye uğradılar.\")","taraflar":["ukayli","mezyedi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","toprak-kazanc","konu-askeri"]},{"t":"1048-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Selçuklu Kavurd Kirman'ı aldı; Büveyhî Kirman kolu sona erdi","gun":"1048 (TDV yıl verir)","yer":"Kirman","yer_id":"Kirman","kisiler":"Kavurd; Ebû Kâlîcâr; el-Melikü'r-Rahîm Hüsrev Fîrûz","d":"Dandanakan sonrası paylaşımda Kirman'ı alan Çağrı Bey'in oğlu Kavurd bölgeye yürüyerek Büveyhî hâkimiyetine son verdi; Kirman Selçukluları kuruldu. Aynı yıl Ebû Kâlîcâr öldü ve oğlu Hüsrev Fîrûz el-Melikü'r-Rahîm lakabıyla Bağdat'ta yerine geçti.","kaynak":"TDV: buveyhiler (\"Daha sonra Kavurd Kirman üzerine yürüyerek bu bölgedeki Büveyhî hâkimiyetine son verdi (1048).\")","taraflar":["buveyhi","kirman-selcuklu"],"onem":2,"dunya":2,"kapsam":"dis","etiket":["toprak-kayip","hukumdar","konu-askeri"]},{"t":"1048-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Suleyhîler San‘a'yı ele geçirip başkent yaptı","gun":"(TDV yıl verir)","yer":"San‘a","yer_id":"Sana","kisiler":"Ali b. Muhammed es-Suleyhî; Ebû Hâşid el-Hâşidî","d":"Sa‘de ve batı Yemen hâkimlerinin saldırılarını püskürten Ali es-Suleyhî, Harâz bölgesinin tamamını aldıktan sonra Ebû Hâşid el-Hâşidî'yi yendi. Yemen'in başşehri San‘a'yı alıp devletinin merkezi yaptı; bu adım Sa‘de'deki Zeydî imamın düşmanlığını çekti.","kaynak":"TDV: suleyhiler (\"daha sonra Ebû Hâşid el-Hâşidî’yi yenilgiye uğratarak San‘a’yı ele geçirip merkez edindi (440/1048)\")","taraflar":["suleyhi"],"onem":3,"dunya":2,"kapsam":"ic","etiket":["savas","toprak-kazanc","konu-askeri"]},{"t":"1052-11-01","tur":"hukumdar","k":"hukumdar","b":"Ukaylî emîri Karvâş tutukluyken öldü; Kureyş b. Bedrân başa geçti","gun":"Kasım 1052 (gün bilinmiyor)","yer":"Musul","yer_id":"Musul","kisiler":"Karvâş; Alemüddin Kureyş b. Bedrân","d":"Kardeşi Ebû Kâlîcâr Bereket'in yönetimi fiilen ele almasından sonra yetkileri kısıtlanan Karvâş, yeğeni Kureyş b. Bedrân ile çekişmesi sonucunda tutuklandı ve öldü. Kureyş, aile içi rakipleriyle mücadele ederek Ukaylî emirliğinin başına geçti.","kaynak":"TDV: ukayliler (\"Karvâş Receb 444’te (Kasım 1052) öldü ve Musul’un doğusunda Ninevâ’da Tevbe tepesinde gömüldü.\")","taraflar":["ukayli"],"onem":1,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"odak_yer":["Sana"],"t":"1052-01-01","tur":"savas","k":"savas","b":"Necdülcâh Savaşı: Zeydî imam Ebü'l-Feth ed-Deylemî Suleyhîler'e yenilip öldü","gun":"(TDV yıl verir)","yer":"Necdülcâh","kisiler":"Ali es-Suleyhî; Ebü'l-Feth ed-Deylemî","d":"Suleyhîlerin San‘a'yı merkez yapması üzerine Sa‘de hâkimi Zeydî imam Ebü'l-Feth ed-Deylemî harekete geçti. Necdülcâh'taki savaşta imam yenildi ve öldürüldü. Zeydiyye maddesi de 1047'den itibaren Yemen'e Suleyhîlerin hâkim olduğunu, Zeydî imâmetinin 1138'e dek sönük kaldığını kaydeder.","kaynak":"TDV: suleyhiler (\"ancak imam 444’te (1052) Necdülcâh’ta yapılan savaşta yenildi ve maktul düştü\")","taraflar":["suleyhi","yemen-zeydi"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1055-12-21","tur":"toprak-kayip","k":"toprak-kayip","b":"Tuğrul Bey Bağdat'a girdi ve Irak'taki Büveyhî hâkimiyetine son verdi","gun":"18 Aralık 1055 (Bağdat'a giriş) · 21 Aralık 1055 (Büveyhî hâkimiyetinin sonu)","yer":"Bağdat","yer_id":"Bağdat","kisiler":"Tuğrul Bey; Halife Kāim-Biemrillâh; el-Melikü'r-Rahîm Hüsrev Fîrûz","d":"Besâsîrî'nin baskısından kurtulmak isteyen Halife Kāim-Biemrillâh'ın daveti üzerine Selçuklu Sultanı Tuğrul Bey 18 Aralık 1055'te Bağdat'a girdi. Çıkan olaylardan sorumlu tuttuğu Büveyhî el-Melikü'r-Rahîm'i ve kumandanlarını tutuklatarak Irak'ta bir asırdır süren Büveyhî hâkimiyetine son verdi. Abbâsî halifeliği bundan sonra Selçuklu siyasî hâkimiyeti altında sürdü.","kaynak":"TDV: kaim-biemrillah (\"Tuğrul Bey, olaylardan sorumlu tuttuğu Hüsrev Fîrûz ile ileri gelen kumandanlarını tutuklatarak Irak’ta bir asırdan beri süren Büveyhî hâkimiyetine son verdi (28 Ramazan 447 / 21 Aralık 1055).\")","taraflar":["abbasi","buyuk-selcuklu"],"onem":4,"dunya":4,"kapsam":"dis","etiket":["toprak-kayip","isgal","konu-siyasi"]},{"t":"1057-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Simâl Halep'i Fâtımîlere teslim edip Akkâ'ya çekildi","gun":"1057 (TDV yıl verir)","yer":"Halep","yer_id":"Halep","kisiler":"Muizzüddevle Simâl b. Sâlih, Müstansır-Billâh","d":"Benî Kilâb arasındaki kıskançlıklardan bunalan Simâl, Halep karşılığında Cübeyl, Beyrut ve Akkâ'nın kendisine verilmesini Fâtımî Halifesi Müstansır'dan istedi. Talebi kabul edilince Halep'i Fâtımîlere teslim edip Akkâ'ya gitti. İkinci Fâtımî Halep hâkimiyeti başladı, ancak Mirdâsî ailesi bu devre razı olmadı.","kaynak":"TDV: mirdasiler (\"Talebi kabul görünce Halep’i Fâtımîler’e teslim edip Akkâ’ya gitti (1057).\")","taraflar":["mirdasi","fatimi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","antlasma","konu-siyasi"]},{"t":"1057-01-19","tur":"savas","k":"savas","b":"Besâsîrî ve Mezyedî Dübeys Sincar'da Selçuklu ordusunu yendi; Kureyş Besâsîrî'ye katıldı","gun":"19 Ocak 1057","yer":"Sincar","yer_id":"Sincar","kisiler":"Arslan el-Besâsîrî; I. Dübeys; Kutalmış; Kureyş b. Bedrân","d":"Fâtımî halifesinin desteğiyle Selçuklular'a karşı Şiî bir cephe kurmaya çalışan Besâsîrî ile Mezyedî Dübeys, Sincar yakınında Kutalmış ve Ukaylî Kureyş kumandasındaki Selçuklu ordusunu ağır yenilgiye uğrattı. Yaralanan Kureyş Besâsîrî'ye katıldı ve Musul'da hutbe Fâtımî halifesi adına okundu. Tuğrul Bey bizzat sefere çıkarak bölgeyi yeniden itaate aldı.","kaynak":"TDV: mezyediler (\"Besâsîrî ile Dübeys, Sincar’da Kutalmış ile Kureyş kumandasındaki Selçuklu ordusunu mağlûp ettiler (19 Ocak 1057).\")","taraflar":["mezyedi","ukayli","buyuk-selcuklu"],"onem":2,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"odak_yer":["Sana"],"t":"1058-01-01","tur":"savas","k":"savas","b":"Zerâib Savaşı: Suleyhî, Necâh'ı ve müttefiklerini yendi","gun":"(TDV yıl verir)","yer":"Zerâib (Tihâme)","kisiler":"Ali es-Suleyhî; Necâh","d":"Hâşid ve İyân kabilelerinin ittifakını dağıtan Ali es-Suleyhî'nin Zebîd hâkimi Necâh ile ilişkileri bozuldu. Zerâib'de yapılan savaşta Necâh ve müttefikleri yenildi; bu, Tihâme'nin Suleyhîlere açılmasının ilk adımıydı.","kaynak":"TDV: suleyhiler (\"O sırada Necâh ile ilişkileri bozulan Suleyhî, Zerâib’de yapılan savaşta onu ve müttefiklerini mağlûp etti (450/1058).\")","taraflar":["suleyhi","necahi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1058-12-27","tur":"isgal","k":"isgal","b":"Besâsîrî Bağdat'ı işgal etti, halifeyi esir aldı ve hutbeyi Fâtımî halifesi adına okuttu","gun":"27 Aralık 1058","yer":"Bağdat","yer_id":"Bağdat","kisiler":"Arslan el-Besâsîrî; Halife Kāim-Biemrillâh; Kureyş b. Bedrân; I. Dübeys","d":"Tuğrul Bey kardeşi İbrâhim Yinal'ın isyanını bastırmak için Bağdat'tan ayrılınca Besâsîrî, Mezyedî Dübeys ve Ukaylî Kureyş'in desteğiyle Şiî bayraklarla şehre girdi. Halife Kāim-Biemrillâh esir alınıp Kureyş'in himayesine verildi, Bağdat'ta hutbe Fâtımî Halifesi Müstansır-Billâh adına okundu. Abbâsî hilâfetinin resmen ortadan kaldırılmaya en çok yaklaştığı an budur; işgal yaklaşık bir yıl sürdü.","kaynak":"TDV: ukayliler (\"Tuğrul Bey kardeşi İbrâhim Yinal’ın isyanını bastırmak için Bağdat’tan ayrılınca Arslan el-Besâsîrî, Şiî bayrakları ile şehre girip Halife Kāim-Biemrillâh’ı esir aldı (8 Zilkade 450 / 27 Aralık 1058).\")","taraflar":["abbasi","fatimi","ukayli","mezyedi","buyuk-selcuklu"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["isgal","konu-siyasi","konu-dini"]},{"odak_yer":["Nîşâbur"],"t":"1060-01-08","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Tuğrul Bey Besâsîrî işgalini sona erdirdi; Halife Kāim-Biemrillâh makamına döndü","gun":"Ocak 1060 (gün bilinmiyor)","yer":"Nehrevan, Bağdat","kisiler":"Tuğrul Bey; Halife Kāim-Biemrillâh; Kureyş b. Bedrân","d":"İbrâhim Yinal'ın isyanını bastıran Tuğrul Bey Irak'a dönünce Besâsîrî Bağdat'ı bırakıp Mezyedî Dübeys'e sığındı. Tuğrul'un talebiyle Kureyş halifeyi serbest bıraktı; Kāim-Biemrillâh Nehrevan'da Tuğrul Bey tarafından karşılanıp hilâfet makamına iade edildi. Besâsîrî kısa süre sonra Selçuklular'a yenilerek öldürüldü.","kaynak":"TDV: kaim-biemrillah (\"Bunun üzerine serbest bırakılan Kāim-Biemrillâh Nehrevan’da Tuğrul Bey tarafından karşılandı (Zilhicce 451 / Ocak 1060).\")","taraflar":["abbasi","ukayli","buyuk-selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","konu-siyasi"]},{"t":"1060-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Mirdâsîler Funeydik'te Fâtımîleri yendi; Mahmûd Halep'i aldı","yer_id":"Halep","gun":"1060 (TDV yıl verir)","yer":"Funeydik, Halep","kisiler":"Reşîdüddevle Mahmûd b. Nasr","d":"Mirdâsî kuvvetleri Funeydik'te Fâtımî ordusunu yendi; iki gün sonra Nasr'ın oğlu Reşîdüddevle Mahmûd Halep'i zaptetti. Ücretli Türk askerleri bu başarıda önemli rol oynadı. Fâtımîler Kuzey Suriye'den tamamen çekildi ve bir daha bu bölgeye dönemedi.","kaynak":"TDV: mirdasiler (\"Fâtımîler Kuzey Suriye’den tamamen çekildiler.\")","taraflar":["fatimi","mirdasi"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","toprak-kayip","konu-askeri"]},{"t":"1060-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Suleyhî, Necâh'ı zehirletip Zebîd'i ele geçirdi","gun":"(TDV yıl verir)","yer":"Zebîd","yer_id":"Zebîd","kisiler":"Ali es-Suleyhî; Necâh","d":"Ali es-Suleyhî, Necâh'a dostluk göstererek hediye ettiği bir câriye aracılığıyla onu zehirletti ve Necâhîlerin merkezi Zebîd'i aldı. Necâh'ın oğulları Kızıldeniz'deki Dehlek adasına kaçıp mücadeleyi oradan sürdürdü. Suleyhî ardından Fâtımî halifesinden Yemen'de açık davet izni aldı ve Hadramut, Aden gibi bölgelerdeki küçük emirlikleri kendine bağladı.","kaynak":"TDV: suleyhiler (\"Ardından kendisi için tehdit gördüğü Necâh’ı dostluk kurup hediye ettiği bir câriye vasıtasıyla zehirleterek Zebîd’i ele geçirdi (452/1060).\")","taraflar":["suleyhi","necahi"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","toprak-kayip","konu-siyasi"]},{"t":"1061-01-01","tur":"hukumdar","k":"hukumdar","b":"Şükür b. Ebü'l-Fütûh öldü; Mekke emirliği Benî Süleyman'a geçti","gun":"(TDV yıl verir)","yer":"Mekke","yer_id":"Mekke","kisiler":"Şükür b. Ebü'l-Fütûh; Hamza b. Vehhâs es-Süleymânî","d":"Yirmi üç yıl emirlik yapan Şükür çocuksuz ölünce kölesi Abûle yerine geçmek istedi ama kabul görmedi. Şeriflerin ikinci tabakasından Hamza b. Vehhâs es-Süleymânî emirliği ele geçirdi; 969'dan beri süren Benî Ca‘fer (Mûsevî) dönemi kapandı.","kaynak":"TDV: mekke (\"Ebü’l-Fütûh’tan sonra emîr olan, yirmi üç yıl bu görevi sürdüren ve çocuk bırakmadan ölen (453/1061) oğlu Şükür’ün yerine kölesi Abûle geçmek istedi.\")","taraflar":["mekke-serifligi"],"onem":1,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1063-11-30","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Suleyhî Ali b. Muhammed Mekke'ye girdi; emirlik Hevâşim'e geçti","gun":"30 Kasım 1063 (6 Zilhicce 455)","yer":"Mekke","yer_id":"Mekke","kisiler":"Ali b. Muhammed es-Suleyhî; Ebû Hâşim Muhammed b. Ca‘fer","d":"Fâtımî Halifesi Müstansır'ın isteğiyle hac mevsiminde büyük bir kuvvetle Mekke'ye gelen Ali es-Suleyhî, hutbeyi Fâtımî halifesi adına okuttu ve halka erzak dağıttı. Şehrin idaresini şeriflerden Ebû Hâşim Muhammed b. Ca‘fer'e bırakarak Yemen'e döndü; böylece Mekke emirliği Hevâşim (Benî Hâşim) koluna geçti.","kaynak":"TDV: mekke (\"6 Zilhicce 455’te (30 Kasım 1063) Mekke’yi ele geçiren Yemen Suleyhî Hükümdarı Ali b. Muhammed şehre çok miktarda erzak sevkederek halka ihsanlarda bulundu\")","taraflar":["suleyhi","mekke-serifligi","fatimi"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","vassal","konu-siyasi"]},{"t":"1065-04-20","tur":"hukumdar","k":"hukumdar","b":"Mahmûd Mercidâbık'ta Atıyye'yi yenip Halep'i geri aldı","yer_id":"Halep","gun":"11 Cemâziyelevvel 457 / 20 Nisan 1065","yer":"Mercidâbık, Halep","kisiler":"Reşîdüddevle Mahmûd b. Nasr, Ebû Züâbe Atıyye b. Sâlih, Hârûn b. Han","d":"Simâl'in ölümüyle Halep'e geçen amcası Atıyye, Türkmenlere baskın yaptırınca Türkmen beyi Hârûn yeğen Mahmûd'un hizmetine geçti. Mercidâbık civarındaki savaşta Atıyye yenildi. Mahmûd üç ayı aşan bir kuşatmadan sonra Halep'i ele geçirdi; Mirdâsî iç çekişmesi Türkmenlerin Suriye'deki ağırlığını arttırdı.","kaynak":"TDV: mirdasiler (\"Mercidâbık civarındaki savaşta Atıyye yenildi (11 Cemâziyelevvel 457 / 20 Nisan 1065)\")","taraflar":["mirdasi"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["savas","hukumdar","konu-siyasi"]},{"odak_yer":["Sana"],"t":"1067-01-01","tur":"hukumdar","k":"hukumdar","b":"Ali es-Suleyhî hac yolunda Necâhî Saîd el-Ahvel'in baskınında öldürüldü","gun":"(TDV yıl verir)","yer":"Mehcem yakınları","kisiler":"Ali es-Suleyhî; Saîd el-Ahvel; el-Melikü'l-Mükerrem Ahmed","d":"Oğlu el-Melikü'l-Mükerrem Ahmed'i vekil bırakıp hacca giden Ali es-Suleyhî, Mehcem yakınlarında Necâh'ın büyük oğlu Saîd el-Ahvel'in saldırısına uğradı; kardeşi ve hanedan mensuplarıyla birlikte öldürüldü, eşi esir alındı. Necâhîler Zebîd'i geri aldı; Suleyhî tahtına Mükerrem Ahmed geçti ve her yerde isyanlarla karşılaştı.","kaynak":"TDV: suleyhiler (\"459 (1067) yılında yerine oğlu el-Melikü’l-Mükerrem Ahmed’i vekil bırakarak hânedan mensuplarını ve bölgenin eski hâkimlerini yanına alıp hacca giden Suleyhî\")","taraflar":["suleyhi","necahi"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","hukumdar","konu-siyasi"]},{"t":"1067-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Karmatîler yerel isyanlarla Bahreyn adasını, ardından Katîf'i kaybetti","yer_id":"Katîf","gun":"(TDV yıl verir)","yer":"Bahreyn (Uvâl); Katîf","kisiler":"","d":"992'de Ukaylî Müntefik kolunun ağır darbesinden sonra kendi bölgelerine çekilen ve hac kervanlarına saldıramaz hale gelen Bahreyn Karmatîleri, yerel isyanlar sonucu önce Bahreyn adasındaki, ardından Katîf'teki hâkimiyetlerini yitirdi. Devletin elinde yalnız Lahsâ ve çevresi kaldı.","kaynak":"TDV: karmatiler (\"Karmatîler mahallî isyanlar sonucu 459’da (1067) Bahreyn’deki, ardından da Katîf’teki hâkimiyetlerini kaybettiler\")","taraflar":["karmati"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["toprak-kayip","isyan","konu-siyasi"]},{"t":"1068-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Mükerrem Ahmed Zebîd yakınında Necâhîler'i yenip şehri geri aldı","gun":"(TDV yıl verir)","yer":"Zebîd","yer_id":"Zebîd","kisiler":"el-Melikü'l-Mükerrem Ahmed; Saîd el-Ahvel","d":"İsyanları bastıran el-Melikü'l-Mükerrem Ahmed, annesini esir tutan Necâhîlerin üzerine yürüdü, Zebîd yakınındaki savaşı kazanıp şehre girdi ve annesini kurtardı. Saîd el-Ahvel Zebîd'i bir kez daha ele geçirdiyse de Mükerrem onu Cebelüşşair'de yenip öldürttü.","kaynak":"TDV: suleyhiler (\"460 (1068) yılında Zebîd yakınında yapılan savaşı kazanarak şehre girdi ve annesini kurtardı\")","taraflar":["suleyhi","necahi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","toprak-kazanc","konu-askeri"]},{"t":"1069-01-01","tur":"kusatma","k":"kusatma","b":"Abdullah b. Ali el-Uyûnî Karmatîler'i yenip Lahsâ'yı kuşatmaya başladı","gun":"(TDV yıl verir)","yer":"Lahsâ (Ahsâ)","yer_id":"Lahsa","kisiler":"Abdullah b. Ali el-Uyûnî","d":"Lahsâ'nın kuzeyindeki Abdülkays kabilesinin Benî Mürre b. Âmir kolunun lideri Abdullah b. Ali el-Uyûnî, yerli kabilelerle birlikte Karmatîleri yenerek onları başşehir Lahsâ'ya sıkıştırdı. Böylece yedi yıl sürecek kuşatma başladı.","kaynak":"TDV: karmatiler (\"462’de (1069-70), Lahsâ bölgesinin kuzey kesiminde yaşayan Abdülkays kabilesinin Benî Mürre b. Âmir kolunun lideri Abdullah b. Ali el-Uyûnî saldırıya geçti\")","taraflar":["karmati"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["kusatma","savas","konu-askeri"]},{"t":"1069-01-01","tur":"vassal","k":"vassal","b":"Mekke hutbeyi Fâtımîlerden Abbâsî halifesi ve Sultan Alparslan adına çevirdi","gun":"(TDV yıl verir)","yer":"Mekke","yer_id":"Mekke","kisiler":"Ebû Hâşim Muhammed b. Ca‘fer; Alparslan; Kāim-Biemrillâh","d":"Mısır'daki kıtlık yüzünden yeterli erzak gelmeyince Mekke Emîri Ebû Hâşim Muhammed b. Ca‘fer, yüz yıla yakın Fâtımîler adına okunan hutbeyi Abbâsî Halifesi Kāim ile Selçuklu Sultanı Alparslan adına okuttu. Alparslan emîre hil‘atler, 30.000 dinar ve yıllık tahsisat gönderdi.","kaynak":"TDV: mekke (\"Mekke Emîri Ebû Hâşim Muhammed b. Ca‘fer hutbeyi Abbâsî Halifesi Kāim-Biemrillâh ile Selçuklu Sultanı Alparslan adına okuttu (462/1069-70)\")","taraflar":["mekke-serifligi","abbasi","fatimi","buyuk-selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["vassal","konu-siyasi"]},{"t":"1070-07-31","tur":"vassal","k":"vassal","b":"Mahmûd Büyük Selçuklulara tâbi oldu; Halep'te Alparslan adına hutbe","gun":"19 Şevval 462 / 31 Temmuz 1070","yer":"Halep","yer_id":"Halep","kisiler":"Reşîdüddevle Mahmûd b. Nasr, Alparslan, Kāim-Biemrillâh","d":"Türkmen akınlarından bunalan Mirdâsî Mahmûd, Fâtımî bağından ayrılarak Büyük Selçuklulara tâbi oldu. Halep'te Abbâsî Halifesi Kāim-Biemrillâh ve Sultan Alparslan adına hutbe okutuldu. Alparslan Mısır seferi öncesi Halep'i iki ay kuşatınca Mahmûd sultanın huzuruna çıktı ve affedildi; Halep Selçuklu nüfuz alanına girdi.","kaynak":"TDV: mirdasiler (\"Abbâsî Halifesi Kāim-Biemrillâh ile Sultan Alparslan adına hutbe okuttu (19 Şevval 462 / 31 Temmuz 1070)\")","taraflar":["mirdasi","buyuk-selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["vassal","konu-siyasi"]},{"odak_yer":["Nîşâbur"],"t":"1075-08-16","tur":"toprak-kayip","k":"toprak-kayip","b":"Fâtımîler Suriye'deki yerlerini Selçuklulara kaptırdı; Bedr el-Cemâlî Mısır'da düzeni kurdu","gun":"468 (1075) (TDV yıl verir); Bedr el-Cemâlî'nin gelişi 466 (1074)","yer":"Suriye, Kahire","kisiler":"Bedr el-Cemâlî, Müstansır-Billâh, Atsız b. Uvak","d":"Mısır'daki ekonomik kriz ve askerî gruplar arası çatışmalar karşısında Halife Müstansır, Akkâ'daki kumandan Bedr el-Cemâlî'yi yardıma çağırdı; Bedr 466/1074'te gelip düzeni sağladı ve halifenin yetkilerini devraldı ('vezirlerin nüfuz asrı'). Aynı yıllarda Fâtımîler Suriye'deki yerlerini kaybetti; Dımaşk ve Filistin 468/1075'te Selçuklu emîri Atsız'ın eline geçti.","kaynak":"TDV: fatimiler (\"Sonuçta Fâtımîler Suriye bölgesindeki yerlerini kaybettiler ve buralar 468’de (1075) Selçuklular’ın eline geçti.\")","taraflar":["fatimi","buyuk-selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["toprak-kayip","konu-siyasi"]},{"odak_yer":["Karabiga"],"t":"1075-09-24","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Celâlüddevle Menbic'i Bizans'tan geri aldı","gun":"10 Safer 468 / 24 Eylül 1075","yer":"Menbic","kisiler":"Celâlüddevle Nasr b. Mahmûd, Ahmed Şah","d":"Mahmûd'un ölümüyle başa geçen Celâlüddevle, Halep'i kuşatan Süleyman Şah'ı kendisinin Selçuklu nâibi olduğunu bildirerek geri çevirdi. Türkmen beyi Ahmed Şah ile anlaşıp 1068'den beri Bizans'ın elinde olan Menbic'i geri aldı. Kısa süre sonra kendisini destekleyen Türkmenler tarafından öldürüldü (Mayıs 1076).","kaynak":"TDV: mirdasiler (\"Bizans’ın eline yeni geçmiş olan Menbic’i geri aldı (10 Safer 468 / 24 Eylül 1075)\")","taraflar":["mirdasi","bizans"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri"]},{"t":"1076-01-01","tur":"vassal","k":"vassal","b":"Mekke Emîri Ebû Hâşim hutbeyi yeniden Fâtımîler adına okuttu","gun":"(TDV yıl verir)","yer":"Mekke","yer_id":"Mekke","kisiler":"Ebû Hâşim Muhammed b. Ca‘fer","d":"Melikşah'ın Kâbe örtüsü göndermesi ve evlilik bağıyla Sünnî nüfuzu pekiştirme çabalarına rağmen Mekke emîri hutbeyi tekrar Fâtımîler adına okutmaya başladı. Hicaz'daki mücadelenin bu safhası Şiîler lehine kapandı; emîr 1079-80'de yeniden Abbâsî-Selçuklu tarafına döndü.","kaynak":"TDV: mekke (\"468 (1076) yılında Mekke Emîri Ebû Hâşim Muhammed b. Ca‘fer’in hutbeyi tekrar Fâtımîler adına okutmaya başlamasıyla\")","taraflar":["mekke-serifligi","fatimi","abbasi"],"onem":1,"dunya":1,"kapsam":"dis","etiket":["vassal","konu-siyasi"]},{"t":"1079-05-05","tur":"kusatma","k":"kusatma","b":"Tutuş ve Ukaylî Müslim Halep'i kuşattı","gun":"Zilkade 471 / Mayıs 1079 (gün bilinmiyor)","yer":"Halep","yer_id":"Halep","kisiler":"Tutuş, Şerefüddevle Müslim b. Kureyş, Sâbık b. Mahmûd","d":"Melikşah'ın Suriye'ye tayin ettiği kardeşi Tutuş Halep'i kuşattı; sultanın emriyle Musul Ukaylî emîri Müslim b. Kureyş de kuşatmaya katıldı. Yardıma gelen bir Türkmen emîri yenilince Tutuş kuşatmayı kaldırıp Diyarbekir'e yöneldi. Tutuş'un Suriye'deki baskısı Halep halkını şehri Müslim'e teslim etmeye yöneltti.","kaynak":"TDV: mirdasiler (\"Melik Tutuş Halep’i kuşatınca muhasaraya Melikşah’ın emriyle Musul Ukaylî Emîri Şerefüddevle Müslim b. Kureyş de katıldı (Zilkade 471 / Mayıs 1079).\")","taraflar":["mirdasi","suriye-selcuklu","ukayli"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["kusatma","konu-askeri"]},{"t":"1080-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Suleyhîler Aden'den Ma‘nîler'i sürdü, şehri Zürey‘î ailesine verdi","gun":"(TDV yıl verir)","yer":"Aden","yer_id":"Aden","kisiler":"el-Melikü'l-Mükerrem Ahmed; Abbas ve Mes‘ûd b. Mükerrem","d":"Aden'de Suleyhîlere tâbi Ma‘nîler vergi ödemeyi kesince Mükerrem Ahmed'in ordusu onları şehirden çıkardı. Yönetim, İsmâilî davetini yaymakla görevli dâî Mükerrem b. Zi'b'in oğulları Abbas ile Mes‘ûd'a yıllık vergi karşılığında verildi; Zürey‘î hanedanının temeli böyle atıldı.","kaynak":"TDV: zureyiler (\"el-Melikü’l-Mükerrem Ahmed b. Ali komutasındaki ordu Ma‘nîler’i şehirden sürdü (473/1080)\")","taraflar":["suleyhi"],"onem":2,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","vassal","konu-siyasi"]},{"t":"1084-05-10","tur":"toprak-kayip","k":"toprak-kayip","b":"Melikşah Musul'a sefer düzenleyip Ukaylî topraklarını başkasına iktâ etti","gun":"477 / 1084 (TDV yıl verir)","yer":"Musul","yer_id":"Musul","kisiler":"Sultan Melikşah; Şerefüddevle Müslim b. Kureyş","d":"Irak ve Suriye'de birleşik bir Arap devleti kurmaya yönelen Ukaylî Şerefüddevle Müslim'den rahatsız olan Selçuklu Sultanı Melikşah Musul'a sefer yaptı ve Ukaylî topraklarını başkasına iktâ etti. Horasan'daki isyan yüzünden bölgeden ayrılmak zorunda kalan sultan sonradan Müslim'in af talebini kabul etti.","kaynak":"TDV: ukayliler (\"… Melikşah Musul’a sefer düzenledi ve Ukaylîler’e ait toprakları başkasına iktâ etti (477/1084).\")","taraflar":["ukayli","buyuk-selcuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","konu-askeri"]},{"odak_yer":["Sana"],"t":"1084-01-01","tur":"hukumdar","k":"hukumdar","b":"Mükerrem Ahmed öldü; Seyyide Hürre Ervâ yönetimi fiilen eline aldı","gun":"(TDV yıl verir)","yer":"Zûcible","kisiler":"el-Melikü'l-Mükerrem Ahmed; Seyyide Hürre Ervâ; Sebe b. Ahmed","d":"Felç geçiren Mükerrem Ahmed devlet işlerini eşi Seyyide Hürre Ervâ'ya bırakmış, merkez San‘a'dan Zûcible'ye taşınmıştı. Mükerrem ölürken Sebe b. Ahmed'i halef göstermesine rağmen Ervâ, Fâtımî halifesinin onayıyla küçük oğlunu tahta çıkarıp yönetimi elinde tuttu.","kaynak":"TDV: suleyhiler (\"el-Melikü’l-Mükerrem 477 (1084) yılında ölmeden önce yerine önemli devlet adamlarından Ebû Himyer Sebe b. Ahmed b. Muzaffer es-Suleyhî’nin geçmesini vasiyet etti.\")","taraflar":["suleyhi"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"odak_yer":["İznik"],"t":"1085-06-20","tur":"savas","k":"savas","b":"Ukaylî Şerefüddevle Müslim, Anadolu Selçuklu Süleyman Şah'a karşı savaşta öldü","gun":"20 Haziran 1085","yer":"Kurzâhil (Halep yakını)","kisiler":"Şerefüddevle Müslim b. Kureyş; Süleyman Şah","d":"Anadolu Selçuklu Sultanı I. Süleyman Şah'ın Halep yönünde ilerlemesi ve Müslim'in Antakya yöresini yağmalatması gerilimi tırmandırdı. Kurzâhil'de yapılan savaşta yenilen Müslim öldürüldü; Süleyman Şah onu Halep Kapısı'nda defnetti. Müslim'in ölümüyle Ukaylî gücü hızla geriledi.","kaynak":"TDV: ukayliler (\"Kurzâhil mevkiinde yapılan savaşta yenilerek öldürülen Müslim (24 Safer 478 / 20 Haziran 1085) Süleyman Şah tarafından Halep Kapısı’nda defnedildi.\")","taraflar":["ukayli","selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","hukumdar","konu-askeri"]},{"odak_yer":["Irak"],"t":"1086-06-16","tur":"toprak-kazanc","k":"toprak-kazanc","b":"I. Sadaka Mezyedî emîri oldu; Dicle'nin batısına kadar merkezî Irak Mezyedîler'e geçti","gun":"Haziran-Temmuz 1086 (gün bilinmiyor)","yer":"Merkezî Irak","kisiler":"Seyfüddevle I. Sadaka; Sultan Melikşah","d":"Kısa süren Mansûr emirliğinin ardından Seyfüddevle I. Sadaka Mezyedî emirliğine geçti. Sultan Melikşah'ın huzuruna çıkarak emirlik menşurunu alan Sadaka'nın iktâları arttırıldı ve Dicle'nin batısına kadar uzanan merkezî Irak toprakları Mezyedî kontrolüne girdi.","kaynak":"TDV: mezyediler (\"Böylece Dicle’nin batısına kadar uzanan merkezî Irak toprakları Mezyedîler’in kontrolüne geçmiş oldu (Rebîülevvel 479 / Haziran-Temmuz 1086).\")","taraflar":["mezyedi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","hukumdar","konu-siyasi"]},{"odak_yer":["İznik"],"t":"1086-06-04","tur":"savas","k":"savas","b":"Aynüseylem Savaşı: Tutuş, Süleyman Şah'ı yendi","gun":"18 Safer 479 / 4 Haziran 1086","yer":"Aynüseylem (Halep yakını)","kisiler":"Tutuş, I. Süleyman Şah, Artuk Bey","d":"Antakya'yı alan Anadolu Selçuklu Sultanı I. Süleyman Şah Halep'i kuşatınca şehrin kumandanı Şerîf el-Huteytî Tutuş'u davet etti. İki Selçuklu hükümdarı Halep'e yaklaşık 5 km uzaklıktaki Aynüseylem'de karşılaştı. Artuk Bey'in manevralarıyla Tutuş kazandı, Süleyman Şah öldü. Tutuş Kuzey Suriye'nin tek hâkimi oldu.","kaynak":"TDV: selcuklular (\"Halep yakınlarında Aynüseylem denilen yerde meydana gelen savaş Tutuş’un galibiyeti ve Süleyman Şah’ın ölümüyle sonuçlandı (18 Safer 479 / 4 Haziran 1086).\")","taraflar":["suriye-selcuklu","selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1086-07-11","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Tutuş Halep şehrini ele geçirdi","gun":"26 Rebîülevvel 479 / 11 Temmuz 1086","yer":"Halep","yer_id":"Halep","kisiler":"Tutuş, Şerîf el-Huteytî","d":"Aynüseylem'den sonra Şerîf el-Huteytî şehri teslimde oyalanınca Tutuş Halep'i kuşatıp aldı, ancak iç kaleyi alamadı. Sultan Melikşah bu gelişmeden hoşnut olmayıp Tutuş'u Dımaşk'a geri çağırdı.","kaynak":"TDV: halep (\"ancak Tutuş 26 Rebîülevvel 479 (11 Temmuz 1086) günü şehri ele geçirdi.\")","taraflar":["suriye-selcuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri"]},{"t":"1086-12-03","tur":"toprak-kayip","k":"toprak-kayip","b":"Melikşah Halep'i teslim aldı; şehir Büyük Selçuklu şahnesine bağlandı","gun":"23 Şâban 479 / 3 Aralık 1086","yer":"Halep","yer_id":"Halep","kisiler":"Melikşah, Kasîmüddevle Aksungur, Tutuş","d":"Melikşah'ın emriyle Dımaşk'a dönen Tutuş'tan sonra sultan bizzat gelip Halep'i teslim aldı. Nizâmülmülk'ün tavsiyesiyle Aksungur Halep şahnesi, Yağısıyan Antakya, Bozan Urfa valisi yapıldı; Tutuş'un kuzeye yayılması engellendi ve bu şehirler merkeze bağlandı.","kaynak":"TDV: halep (\"Sultan Melikşah, bazı devlet adamı ve kumandanlarıyla birlikte gelerek 23 Şâban 479’da (3 Aralık 1086) şehri teslim aldı.\")","taraflar":["suriye-selcuklu","buyuk-selcuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","konu-siyasi"]},{"t":"1089-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Ceyyâş b. Necâh Zebîd'i son kez alıp Necâhî hâkimiyetini yeniden kurdu","gun":"(TDV yıl verir)","yer":"Zebîd","yer_id":"Zebîd","kisiler":"Ceyyâş b. Necâh","d":"Suleyhîlerle Necâhîler arasında Zebîd birkaç kez el değiştirmişti. Necâh'ın oğlu Ceyyâş Zebîd'i bu kez kalıcı olarak geri aldı ve Tihâme'de Necâhî hâkimiyeti 1159'a dek sürdü.","kaynak":"TDV: necahiler (\"Nihayet Ceyyâş b. Necâh 482’de (1089) Zebîd’i son defa ele geçirdi ve Necâhî hâkimiyetini yeniden sağladı.\")","taraflar":["necahi","suleyhi"],"onem":3,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","toprak-kayip","konu-askeri"]},{"t":"1089-01-01","tur":"vassal","k":"vassal","b":"Medine'de hutbe Abbâsî halifesi ve Sultan Melikşah adına okundu","gun":"(TDV yıl verir)","yer":"Medine","yer_id":"Medine","kisiler":"Melikşah; Muktedî-Biemrillâh","d":"Fâtımîlerin Haremeyn'deki nüfuzuna karşı Medine'yi Sünnî hâkimiyetine çekmeye çalışan Selçuklular, Melikşah döneminde sonuç aldı. Medine'nin Hüseynî emîrleri hutbeyi Abbâsî Halifesi Muktedî ile birlikte Sultan Melikşah adına okuttu.","kaynak":"TDV: medine (\"Selçuklular’ın Medine ile ilgisi Sultan Melikşah zamanında devam etti ve 482-483’te (1089-1090) Medine’de Halife Muktedî-Biemrillâh ile birlikte Melikşah adına hutbe okundu.\")","taraflar":["medine-emirligi","abbasi","buyuk-selcuklu"],"onem":1,"dunya":1,"kapsam":"dis","etiket":["vassal","konu-siyasi"]},{"t":"1090-03-06","tur":"kusatma","k":"kusatma","b":"Tutuş Humus'u alıp Ammâroğulları'nın Trablusşam'ını kuşattı","gun":"483 (1090) (TDV yıl verir)","yer":"Humus, Trablusşam","yer_id":"Humus","kisiler":"Tutuş, İbn Ammâr, Aksungur, Yağısıyan, Bozan","d":"Fâtımîlerin Suriye kıyısındaki ilerleyişi üzerine Melikşah'tan yardım alan Tutuş, Aksungur, Yağısıyan ve Bozan'ın kuvvetleriyle Humus'u ele geçirdi ve ardından Trablusşam'ı kuşattı. İbn Ammâr Tutuş'un kumandanlarını ve Aksungur'u vaadlerle kendi tarafına çekmeye çalıştı. Aksungur'un kuşatma aleyhine konuşması üzerine Tutuş kuşatmayı kaldırıp Dımaşk'a döndü.","kaynak":"TDV: humus--suriye (\"Humus 483 (1090) yılında Selçuklu Sultanı Melikşah’ın eline geçti.\")","taraflar":["suriye-selcuklu","beni-ammar-trablussam"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["kusatma","toprak-kazanc","konu-askeri"]},{"t":"1092-01-01","tur":"vassal","k":"vassal","b":"Melikşah'ın ölümüyle Mekke hutbesi yeniden Fâtımîlere döndü","gun":"(TDV yıl verir)","yer":"Mekke","yer_id":"Mekke","kisiler":"Melikşah","d":"1086-1092 arasında Abbâsî halifesine ve Selçuklu sultanına tâbi kalan Mekke emîri, Melikşah'ın ölümü üzerine hutbeleri yeniden Fâtımîler adına okutmaya başladı. Mekke bundan sonra 1174'e dek büyük ölçüde Fâtımî nüfuzunda kaldı.","kaynak":"TDV: mekke (\"Mekke emîri Melikşah’ın ölümü üzerine (485/1092) hutbeleri yeniden Fâtımîler adına okutmaya başladı.\")","taraflar":["mekke-serifligi","fatimi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["vassal","konu-siyasi"]},{"t":"1092-11-25","tur":"vassal","k":"vassal","b":"Medine'de hutbe Melikşah'ın oğlu Mahmud adına okundu","gun":"25 Kasım 1092 (22 Şevval 485)","yer":"Medine","yer_id":"Medine","kisiler":"Mahmud b. Melikşah","d":"Melikşah'ın ölümünden sonra Mekke hutbeyi Fâtımîlere çevirirken Medine, Selçuklu tahtına geçen oğlu Mahmud adına hutbe okuttu. Şehir sonraki yıllarda Selçuklu ve Fâtımî nüfuzları arasında gidip geldi.","kaynak":"TDV: medine (\"Sultan Melikşah’ın vefatı üzerine Medine’de hutbe hükümdar olan oğlu Mahmud adına okundu (22 Şevval 485 / 25 Kasım 1092).\")","taraflar":["medine-emirligi"],"onem":1,"dunya":1,"kapsam":"dis","etiket":["vassal","konu-siyasi"]},{"t":"1094-01-01","tur":"bolunme","k":"bolunme","b":"Nizâr-Müsta'lî bölünmesi: İsmâilî da'vet ikiye ayrıldı","gun":"487 (1094) (TDV yıl verir)","yer":"Kahire","yer_id":"Kahire","kisiler":"Müstansır-Billâh, Müsta'lî-Billâh, Nizâr, Efdal b. Bedr el-Cemâlî, Hasan Sabbâh","d":"Müstansır'ın ölümünden sonra Vezir Efdal, meşrû vâris sayılan büyük oğul Nizâr'ı uzaklaştırıp küçük oğlu Müsta'lî'yi halife yaptı. Mısır, Suriye, Yemen ve Hindistan İsmâilîlerinin çoğu Müsta'lî'yi tanıdı; İran İsmâilîleri Hasan Sabbâh önderliğinde Nizâr'ın imamlığını benimseyip Nizâriyye adıyla ayrıldı. Bölünme Fâtımî hilâfetinin dinî otoritesini kalıcı olarak zayıflattı; 1130'da Halife Âmir Nizârîlerce öldürüldü.","kaynak":"TDV: fatimiler (\"Müstansır’ın vefatından sonra Vezir Efdal Şehinşah’ın müdahalesiyle meşrû hak sahibi büyük oğlu Nizâr’ın azledilip yerine küçük oğlu Müsta‘lî’nin getirilmesi İsmâilî da‘vetini böldü.\")","taraflar":["fatimi"],"onem":3,"dunya":3,"kapsam":"ic","etiket":["bolunme","hukumdar","konu-dini"]},{"odak_yer":["Halep","Urfa"],"t":"1094-05-27","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Tutuş Nehriseb'în'de Aksungur'u yendi, Halep ve Urfa'yı aldı","gun":"9 Cemâziyelevvel 487 / 27 Mayıs 1094","yer":"Nehriseb'în (Tel Sultan yakını), Halep, Urfa","kisiler":"Tutuş, Kasîmüddevle Aksungur, Bozan, Kürboğa","d":"Melikşah'ın ölümünden sonra sultanlık iddiasıyla Berkyaruk'a karşı çıkan Tutuş, Berkyaruk tarafına geçen Halep valisi Aksungur ile Halep'e 36 km mesafede karşılaştı. Yûsuf b. Abak'ın saf değiştirmesiyle Tutuş kazandı, Aksungur esir edilip öldürüldü. Kısa sürede Halep, Harran ve Urfa da teslim oldu; Tutuş Suriye'den Azerbaycan'a uzanan bir alana hâkim oldu.","kaynak":"TDV: tutus (\"İki ordu 9 Cemâziyelevvel 487 (27 Mayıs 1094) tarihinde Halep’e yaklaşık 36 km.\")","taraflar":["suriye-selcuklu","buyuk-selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","toprak-kazanc","konu-askeri"]},{"odak_yer":["Halep"],"t":"1095-02-25","tur":"bolunme","k":"bolunme","b":"Tutuş Rey yakınında öldü; Suriye Selçukluları Halep ve Dımaşk kollarına ayrıldı","gun":"16 Safer 488 / 25 Şubat 1095","yer":"Dâşilû (Rey yakını), Halep, Dımaşk","kisiler":"Tutuş, Berkyaruk, Rıdvân, Dukak","d":"Büyük Selçuklu tahtı için Berkyaruk'a karşı savaşan Tutuş, askerlerinin karşı tarafa geçmesiyle yenildi ve savaş meydanında öldürüldü. Oğlu Rıdvân Halep'te, öbür oğlu Dukak Emîr Savtegin'in davetiyle Dımaşk'ta melik ilân edildi. Suriye Selçuklu devleti böylece fiilen ikiye bölündü; iki kardeşin çekişmesi Haçlıların gelişinde Suriye'yi zayıf bıraktı.","kaynak":"TDV: selcuklular (\"Tutuş’un ölümünden sonra Suriye Selçukluları, Halep ve Dımaşk Selçuklu melikliği olmak üzere ikiye ayrıldı.\")","taraflar":["suriye-selcuklu"],"onem":3,"dunya":2,"kapsam":"ic","etiket":["bolunme","hukumdar","konu-siyasi"]},{"t":"1098-07-04","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Fâtımî veziri Efdal Kudüs'ü Artuklu Sökmen ve İlgazi'den aldı","gun":"Şâban 491 / Temmuz 1098 (gün bilinmiyor)","yer":"Kudüs","yer_id":"Kudüs","kisiler":"Efdal b. Bedr el-Cemâlî, Sökmen, İlgazi","d":"Halep meliki Rıdvân ile Dımaşk meliki Dukak'ın çekişmesinden ve Büyük Selçuklu karışıklıklarından yararlanan Fâtımî veziri Efdal, Kudüs'ü bir süre kuşattıktan sonra Artuk Bey'in oğulları Sökmen ve İlgazi'den teslim aldı. Antakya emîri Yağısıyan'ın şehri geri alma girişimi başarısız oldu. Fâtımî hâkimiyeti bir yıl sürdü; şehir 1099'da Haçlılara geçti.","kaynak":"TDV: kudus (\"Kudüs’ü bir süre kuşattıktan sonra İlgazi ve Sökmen’den teslim aldı (Şâban 491 / Temmuz 1098).\")","taraflar":["fatimi"],"onem":3,"dunya":3,"kapsam":"dis","etiket":["kusatma","toprak-kazanc","konu-askeri"]},{"t":"1098-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Sebe b. Ahmed öldü; San‘a Suleyhîler'den çıkıp Hemdânîler'e geçti","gun":"(TDV yıl verir)","yer":"San‘a","yer_id":"Sana","kisiler":"Sebe b. Ahmed es-Suleyhî; Hâtim b. Gaşîm el-Mugallisî","d":"Ervâ adına ülkeyi yöneten Sebe b. Ahmed'in ölümüyle Suleyhîler San‘a'yı kaybetti. Bölgeyi Suleyhîlere tâbi olarak yöneten Hemdan kabilesinden Hâtim b. Gaşîm şehri ve çevresini alarak kendini sultan ilân etti ve Fâtımî desteğiyle Hemdânî hanedanını başlattı.","kaynak":"TDV: hemdaniler (\"Hemdânîler’den Hâtim b. Gaşîm (Ali) el-Mugallisî, San‘a ve civarını ele geçirip kendini sultan ilân ederek (1098) Hemdânîler hânedanını kurdu.\")","taraflar":["suleyhi"],"onem":3,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","kurulus","konu-siyasi"]},{"odak_yer":["Halep"],"t":"1101-07-30","tur":"toprak-kayip","k":"toprak-kayip","b":"Tuğtegin Ammâroğulları'nın Cebele'sini teslim aldı","gun":"30 Temmuz 1101","yer":"Cebele","kisiler":"Tuğtegin, Dukak","d":"Dımaşk meliki Dukak'ın Ammâroğulları idaresindeki Cebele'yi kuşatması sırasında atabeg Tuğtegin yaralandı. Dımaşk'a döndükten sonra Cebele hâkimiyle vardığı anlaşmayla şehri teslim aldı ve oğlu Böri'nin idaresine verdi. Ammâroğulları kıyıda Trablusşam çevresine sıkıştı.","kaynak":"TDV: tugtegin (\"Dımaşk’a döndükten sonra Cebele hâkimiyle yaptığı anlaşma neticesinde şehri teslim aldı (30 Temmuz 1101) ve oğlu Böri’nin idaresine verdi.\")","taraflar":["beni-ammar-trablussam","suriye-selcuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","konu-askeri"]},{"t":"1102-01-01","tur":"kusatma","k":"kusatma","b":"Raymond de Saint-Gilles Trablusşam'ı kuşatmaya başladı","gun":"495 (1102) (TDV yıl verir)","yer":"Trablusşam","yer_id":"Trablusşam","kisiler":"Raymond de Saint-Gilles, Fahrülmülk İbn Ammâr","d":"I. Haçlı Seferi'nin Toulouse kontu Raymond, Tortosa'yı aldıktan sonra Trablusşam'ı kuşattı ve şehre hâkim tepeye büyük bir kule (Mons Peregrinus) yaptırdı. Fahrülmülk İbn Ammâr ticaret filosu ve Mısır limanlarından gelen ikmalle yıllarca direndi; Raymond kuşatma sürerken 1105'te öldü. Selçuklu sultanından istenen yardım emîrler arası çekişme yüzünden gelmedi.","kaynak":"TDV: trablussam (\"Haçlı seferleri başladığında Raymond de Saint-Gilles büyük bir orduyla Trablusşam’ı kuşattı (495/1102)\")","taraflar":["beni-ammar-trablussam"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["kusatma","konu-askeri"]},{"t":"1104-07-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Mezyedîler Vâsıt ve Hît'i, ardından Basra (1106) ve Tikrît'i (1106) aldı","gun":"Temmuz 1104 (gün bilinmiyor)","yer":"Vâsıt, Hît, Basra, Tikrît","yer_id":"Vâsıt","kisiler":"I. Sadaka","d":"Berkyaruk ile Muhammed Tapar arasındaki taht kavgasından yararlanan I. Sadaka, 1102'de Câmiayn'ın yerinde kurduğu Hille'yi merkez yaptıktan sonra hâkimiyetini Irak'ın tamamına yaymaya çalıştı. Temmuz 1104'te Vâsıt ve Hît, Ocak 1106'da Basra, Ekim 1106'da Tikrît Mezyedîler'in eline geçti; bu, emirliğin en geniş sınırlarıdır.","kaynak":"TDV: mezyediler (\"Şevval 497’de (Temmuz 1104) Vâsıt ve Hît, Cemâziyelevvel 499’da (Ocak 1106) Basra, Safer 500’de (Ekim 1106) Tikrît Mezyedîler’in eline geçti.\")","taraflar":["mezyedi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri"]},{"odak_yer":["Antakya","Harran","Urfa"],"t":"1104-05-07","tur":"savas","k":"savas","b":"Harran Savaşı: Antakya ve Urfa Haçlıları Sökmen ile Çökürmüş'e yenildi","gun":"7 Mayıs 1104","yer":"Harran","kisiler":"Baudouin du Bourg, Josselin de Courtenay, Bohemund, Tankred, Sökmen, Çökürmüş","d":"Antakya prinkepsi Bohemund, Tankred ve Urfa kontu Baudouin du Bourg Harran'ı almak için sefere çıktı. Mardin hâkimi Artukoğlu Sökmen ile Musul valisi Çökürmüş'ün kuvvetleri Haçlıları ağır bir yenilgiye uğrattı; Baudouin ve Josselin esir düştü. Bohemund Avrupa'ya dönerek yeni sefer aradı; Haçlıların doğuya, el-Cezîre'ye yayılması durdu.","kaynak":"TDV: haclilar (\"Mardin Hâkimi Artukoğlu Sökmen ve Musul Valisi Çökürmüş’ün kuvvetleriyle yapılan savaşta (7 Mayıs 1104) kuzeni Josselin ile birlikte esir düşen\")","taraflar":["urfa-kontlugu","antakya-prinkipsligi","artuklu","buyuk-selcuklu"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"odak_yer":["Kudüs","Remle"],"t":"1105-08-27","tur":"savas","k":"savas","b":"Remle yöresinde Fâtımî-Dımaşk ordusu ile Kudüs Haçlıları çarpıştı","gun":"27 Ağustos 1105","yer":"Remle yöresi (Filistin)","kisiler":"Baudouin (I.), Emîr Sabar, Tuğtegin","d":"Tuğtegin Haçlılara karşı Fâtımî ordusuna Emîr Sabar idaresinde 1300 kişilik yardım gönderdi. Fâtımî ordusu Kudüs Kralı Baudouin'in ordusuyla şiddetli bir muharebeye girdi; iki taraf da ağır kayıp verdi. Fâtımîlerin Filistin'i geri alma çabaları bu savaştan sonra bir daha ciddi sonuç vermedi.","kaynak":"TDV: tugtegin (\"Fâtımî ordusunun 27 Ağustos 1105’te Kudüs Kralı Baudouin idaresindeki Haçlı ordusuyla giriştiği şiddetli muharebede her iki taraf da ağır kayıplar verdi.\")","taraflar":["kudus-kralligi","boriler"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1108-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Trablusşam Fâtımî hâkimiyetine girdi","gun":"501 (1108) (TDV yıl verir)","yer":"Trablusşam","yer_id":"Trablusşam","kisiler":"Fahrülmülk İbn Ammâr","d":"Uzun Haçlı kuşatmasıyla ikmal yolları kesilen Trablusşam'dan yardım aramak için Bağdat'a giden Fahrülmülk İbn Ammâr sonuç alamadı. Onun yokluğunda şehir Fâtımî hâkimiyetine girdi; Fahrülmülk Dımaşk'a döndüğünde bunu öğrenip Cebele'ye gitti. Şehir ertesi yıl Haçlılara düştü.","kaynak":"TDV: trablussam (\"501 (1108) yılında Fâtımî hâkimiyetine giren şehir\")","taraflar":["beni-ammar-trablussam"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-siyasi"]},{"t":"1108-01-01","yer_id":"Tiberya (Tabariyye / Tiberias)","tur":"savas","k":"savas","b":"Tuğtegin Taberiye yakınında Kont Gervaise'i esir aldı","gun":"501 (1108) (TDV yıl verir)","yer":"Taberiye","kisiler":"Tuğtegin, Gervaise","d":"Emîr Sabar'ın Vâdiimûsâ civarında Haçlı baskınına uğraması üzerine Tuğtegin Taberiye Kontluğu'nu ortadan kaldırmak için sefere çıktı. Taberiye yakınındaki savaşta Kont Gervaise ve askerlerinin bir kısmı esir düştü; anlaşma sağlanamayınca kont öldürüldü. Ardından Kudüs Kralı Baudouin barış istedi ve 502 (1108-09)'de antlaşma yapıldı.","kaynak":"TDV: tugtegin (\"Taberiye yakınlarında yapılan savaşta Kont Gervaise ve askerlerinin bir kısmı esir düştü (501/1108)\")","taraflar":["boriler","kudus-kralligi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"odak_yer":["Nîşâbur"],"t":"1108-03-04","tur":"savas","k":"savas","b":"Nu‘mâniye Savaşı: Sultan Muhammed Tapar Mezyedî Sadaka'yı yendi ve öldürdü","gun":"4 Mart 1108","yer":"Nu‘mâniye (Hille-Vâsıt arası)","kisiler":"I. Sadaka (Melikü'l-Arab); II. Dübeys; Sultan Muhammed Tapar","d":"Yayılmacı politika izleyen ve Sultan'a muhalif emîrleri koruyan Sadaka'yı bertaraf etmeye karar veren Selçuklu Sultanı Muhammed Tapar, Hille-Vâsıt arasındaki Nu‘mâniye'de onu yendi. Melikü'l-Arab lakaplı Sadaka savaşta öldü, oğlu Dübeys esir düştü ve Hille'ye dönmesine uzun süre izin verilmedi.","kaynak":"TDV: mezyediler (\"Hille-Vâsıt arasındaki Nu‘maniye’de meydana gelen savaşta Melikü’l-Arab lakabıyla tanınan Sadaka öldü, oğlu Nûrüddevle Ebü’l-Eaz Dübeys b. Sadaka da esir düştü (19 Receb 501 / 4 Mart 1108).\")","taraflar":["mezyedi","buyuk-selcuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","toprak-kayip","konu-askeri"]},{"t":"1110-01-01","tur":"bolunme","k":"bolunme","b":"Aden Zürey‘îleri Suleyhîler'den bağımsızlıklarını ilân etti","gun":"(TDV yıl verir)","yer":"Aden","yer_id":"Aden","kisiler":"Zürey‘ b. Abbas; Mes‘ûd b. Mükerrem","d":"Suleyhîlerin Necâhîlerle savaşı ve iç sorunlarla uğraşmasını fırsat bilen Aden'deki Zürey‘îler vergiyi keserek bağımsız oldular. Ancak amca ile yeğen kolları arasındaki ikili yönetim yüzünden uzun süre istikrar sağlanamadı.","kaynak":"TDV: zureyiler (\"Zürey‘îler, Suleyhîler’in Necâhîler’le ve iç sorunlarıyla meşgul olmasını fırsat bilerek 504 (1110) yılında bağımsızlıklarını ilân ettiler.\")","taraflar":["zureyi","suleyhi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["bolunme","konu-siyasi"]},{"t":"1110-01-01","tur":"hukumdar","k":"hukumdar","b":"Necâhî Mansûr, amcası İbrâhim'e karşı Suleyhî yardımıyla Zebîd'i geri aldı","gun":"(TDV yıl verir)","yer":"Zebîd","yer_id":"Zebîd","kisiler":"Mansûr b. Fâtik; İbrâhim b. Ceyyâş","d":"Ceyyâş'ın ölümünden sonra Necâhî hanedanında taht kavgaları başladı. Çocuk yaşta tahta çıkan Mansûr, amcası İbrâhim'in Zebîd'de yönetimi ele geçirmesi üzerine eski düşman Suleyhîlerden yardım istedi ve aldığı kuvvetle yeniden hâkim oldu. Bu dönemden itibaren Necâhî yönetimi vezirlerin eline geçmeye başladı.","kaynak":"TDV: necahiler (\"aldığı takviye kuvvetle yeniden hâkimiyet sağlayabildi (504/1110)\")","taraflar":["necahi","suleyhi"],"onem":1,"dunya":1,"kapsam":"ic","etiket":["hukumdar","isyan","konu-siyasi"]},{"odak_yer":["Antakya","Şeyzer"],"t":"1111-07-10","tur":"savas","k":"savas","b":"Mevdûd ve Tuğtegin Şeyzer önünde Antakya Haçlılarını yendi","gun":"505 (1111) (TDV yıl verir)","yer":"Şeyzer","kisiler":"Mevdûd b. Altuntegin, Tuğtegin, Sultan b. Ali, Tankred","d":"Antakya prinkepsi Tankred'in Şeyzer karşısına Tel İbn Ma'şer Kalesi'ni kurarak baskısını arttırması üzerine Münkızoğulları emîri Sultan b. Ali, Selçuklu emîri Mevdûd'dan yardım istedi. Dımaşk Atabegi Tuğtegin ile gelen ve Şeyzerli 500 piyadeyi ordusuna katan Mevdûd Haçlıları şehir önünde ağır bir yenilgiye uğrattı.","kaynak":"TDV: seyzer (\"Mevdûd, Haçlı ordusunu Şeyzer önlerinde ağır bir yenilgiye uğrattı (505/1111).\")","taraflar":["munkizogullari","boriler","antakya-prinkipsligi","buyuk-selcuklu"],"onem":2,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1113-12-10","tur":"hukumdar","k":"hukumdar","b":"Rıdvân b. Tutuş öldü; Halep'te Alparslan el-Ahres melik oldu","gun":"507 (1113) (TDV yıl verir)","yer":"Halep","yer_id":"Halep","kisiler":"Rıdvân b. Tutuş, Alparslan el-Ahres, Lü'lü'","d":"Haçlılara karşı başarısız kalıp Antakya'ya vergi ödemek zorunda kalan Rıdvân öldü. Yerine geçen oğlu Alparslan el-Ahres Bâtınîleri tasfiye etti ama 1114'te atabeg Lü'lü' tarafından öldürüldü; kardeşi Sultan Şah döneminde yönetim tamamen Lü'lü''nün elinde kaldı. Halep kolu hızla çözülme sürecine girdi.","kaynak":"TDV: selcuklular (\"Rıdvân b. Tutuş ölünce (507/1113) yerine oğullarından Alparslan Tâcüddevle el-Ahras geçirildi.\")","taraflar":["suriye-selcuklu"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"odak_yer":["Kudüs"],"t":"1113-06-28","tur":"savas","k":"savas","b":"Tuğtegin ve Mevdûd Kudüs Kralı Baudouin'i bozguna uğrattı","gun":"11 Muharrem 507 / 28 Haziran 1113","yer":"Taberiye yöresi (Sinnabra)","kisiler":"Tuğtegin, Mevdûd b. Altuntegin, Baudouin (I.), Rıdvân","d":"Kudüs kralının Dımaşk'a bağlı Beseniye bölgesini yağmalatması ve Mısır kervanlarını vurması üzerine Tuğtegin, Mevdûd ve Rıdvân'dan yardım istedi. Türk kuvvetlerinin âni baskınında Haçlı ordusu 2000 kadar kayıp verdi; kral esir düştü ama tanınmadığından kaçıp Taberiye'ye sığındı. Rıdvân'ın yalnız 100 atlı göndermesine kızan Tuğtegin adını hutbeden çıkardı.","kaynak":"TDV: tugtegin (\"Türk kuvvetlerinin âni baskınına uğrayan Haçlı ordusu 2000 kadar kayıp verdi (11 Muharrem 507 / 28 Haziran 1113)\")","taraflar":["boriler","kudus-kralligi","suriye-selcuklu","buyuk-selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1116-01-01","tur":"hukumdar","k":"hukumdar","b":"San‘a'da Hemdânîlerin ikinci kolu Benî Kubeyb iktidara geldi","gun":"(TDV yıl verir)","yer":"San‘a","yer_id":"Sana","kisiler":"Kadı Ahmed b. İmrân; Ma‘n b. Hâtim; Hişâm b. Kubeyb","d":"Hâtim b. Gaşîm'in oğlu Abdullah'ı zehirleterek 1110'da yerine Ma‘n'ı getiren Kadı Ahmed b. İmrân, altı yıl sonra Ma‘n'ı da indirip Hişâm b. Kubeyb'i tahta çıkardı. Böylece San‘a'da Hemdânîlerin ikinci sülâlesi dönemi başladı.","kaynak":"TDV: hemdaniler (\"Böylece San‘a’ya Hemdânîler’in ikinci sülâlesi Benî Kubeyb hâkim oldu.\")","taraflar":["hamdani-yemen"],"onem":1,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1118-08-06","tur":"hukumdar","k":"hukumdar","b":"Müsterşid-Billâh halife oldu; hilâfetin dünyevî gücünü yeniden canlandırma dönemi başladı","gun":"6 Ağustos 1118","yer":"Bağdat","yer_id":"Bağdat","kisiler":"Halife Müsterşid-Billâh","d":"Büyük Selçuklu Sultanı Muhammed Tapar'ın ölümünden sonra başlayan karışıklıklar sırasında halife olan Müsterşid-Billâh, Büveyhîler'in 945'te Bağdat'ı almasından beri kaybedilmiş olan dünyevî-siyasî hâkimiyeti yeniden kurmak için harekete geçti; ordu toplayıp Selçuklu sultanlarına ve Mezyedîler'e karşı sefere çıktı.","kaynak":"TDV: mustersid-billah (\"Babasının vefatının ardından hilâfet makamına geçti (16 Rebîülâhir 512 / 6 Ağustos 1118).\")","taraflar":["abbasi"],"onem":2,"dunya":2,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"odak_yer":["Antakya"],"t":"1119-06-28","tur":"savas","k":"savas","b":"Kanlı Meydan (Ager Sanguinis): İlgazi Antakya ordusunu yok etti","gun":"17 Rebîülevvel 513 / 28 Haziran 1119","yer":"Tel İfrîn (Sermedâ yöresi)","kisiler":"Necmeddin İlgazi, Ruggero di Salerno","d":"Mardin Artuklu Beyi Necmeddin İlgazi Tel İfrîn'de Antakya naibi Ruggero di Salerno'nun ordusunu kılıçtan geçirdi; Ruggero savaşta öldü. Kaynaklarda 'Kanlı Meydan' olarak anılan bu yenilgi Antakya'daki Norman hâkimiyetine büyük darbe vurdu; prinkepsliğin idaresini II. Bohemund'un gelişine (1126) kadar Kudüs Kralı II. Baudouin üstlendi.","kaynak":"TDV: haclilar (\"(17 Rebîülevvel 513 / 28 Haziran 1119)\")","taraflar":["antakya-prinkipsligi","artuklu"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1122-01-01","tur":"savas","k":"savas","b":"Urfa kontu Josselin, Artuklu Belek'e esir düştü","yer_id":"Suruç","gun":"1122 (TDV yıl verir)","yer":"Urfa yöresi, Harput","kisiler":"Josselin de Courtenay, Belek b. Behrâm","d":"Urfa Kontluğu'nu Dânişmendli ve Artuklulara karşı savunan Josselin de Courtenay, Artuklu Beyi Belek b. Behrâm'a esir düştü ve Harput Kalesi'ne hapsedildi. Ertesi yıl Kudüs Kralı II. Baudouin de Belek'e esir düştü. Josselin bir yıl sonra kurtulup Urfa'ya döndü.","kaynak":"TDV: haclilar (\"Urfa Kontluğu’nu Dânişmendliler’e ve Artuklular’a karşı savunan Josselin 1122’de Artuklu Beyi Belek b. Behrâm’a esir düştü\")","taraflar":["urfa-kontlugu","artuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"odak_yer":["Hille"],"t":"1123-03-01","tur":"savas","k":"savas","b":"Halife Müsterşid Mezyedî II. Dübeys'i yendi; Dübeys Ca‘ber'e kaçtı","gun":"517 / 1123 (TDV yıl verir)","yer":"Hille yöresi","kisiler":"Halife Müsterşid-Billâh; II. Dübeys","d":"Hilâfetin askerî gücünü yeniden kurmaya çalışan Halife Müsterşid-Billâh hazırlıklarını tamamlayıp Mezyedî II. Dübeys üzerine yürüdü ve onu yendi. Dübeys Ca‘ber Kalesi'ne kaçtı; ardından Urfa Kontu Josselin ve Kudüs Kralı Baudouin ile iş birliği yaptı.","kaynak":"TDV: mezyediler (\"517’de (1123) Halife Müsterşid-Billâh’a karşı girdiği mücadelede yenilerek Ca‘ber Kalesi’ne kaçtı.\")","taraflar":["mezyedi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1123-01-01","tur":"hukumdar","k":"hukumdar","b":"Necâhî emîri Mansûr veziri Enîs tarafından öldürüldü","gun":"(TDV yıl verir)","yer":"Zebîd","yer_id":"Zebîd","kisiler":"Mansûr b. Fâtik; Enîs el-Fâtikî","d":"Adına para bastıracak kadar güçlenen Vezir Enîs el-Fâtikî, gençlik çağına gelen emîr Mansûr'u kendi eliyle öldürdü. Necâhî devletinde emîrler bundan sonra vezirlerin ve saray kadınlarının gölgesinde kaldı; Ümmü Fâtik Alem'in nüfuzu bu dönemde yükseldi.","kaynak":"TDV: necahiler (\"Ancak Mansûr gençlik çağına geldiğinde onu kendi elleriyle öldürdü (517/1123).\")","taraflar":["necahi"],"onem":1,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1124-07-07","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Kudüs Krallığı Venedik donanmasıyla Sûr'u aldı","gun":"7 Temmuz 1124","yer":"Sûr (Tyrus)","yer_id":"Sûr (Tyre) — Lübnan","kisiler":"Geldemar (nâib), Venedik donanması","d":"Kral II. Baudouin'in Belek'e esir düştüğü yıl krallığı yöneten nâibin kumandasındaki Kudüs ordusu, Venedik donanmasının desteğiyle Sûr'u kuşatıp aldı. Böylece krallık Askalân dışındaki bütün Filistin kıyı şehirlerine sahip oldu; Fâtımîlerin Suriye kıyısındaki son büyük limanlarından biri düştü.","kaynak":"TDV: kudus (\"Onun yokluğunda Kudüs ordusu Venedik donanmasının desteğiyle 7 Temmuz 1124’te Sûr’u (Tyrus) zaptederek Askalân dışında bütün Filistin kıyı şehirlerine sahip oldu.\")","taraflar":["kudus-kralligi"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["kusatma","toprak-kazanc","konu-askeri"]},{"odak_yer":["Şeyzer"],"t":"1128-01-01","tur":"vassal","k":"vassal","b":"Şeyzer emîri Sultan b. Ali Zengî'nin himayesini kabul etti","gun":"522 (1128) (TDV yıl verir)","yer":"Şeyzer","kisiler":"Sultan b. Ali, İmâdüddin Zengî","d":"Bâtınî, Bizans ve Haçlı kuşatmalarıyla yıpranan Münkızoğulları emîri Sultan b. Ali, Musul Atabegi İmâdüddin Zengî'nin himayesini kabul etti. Şeyzer kısa süreli bir istikrar dönemi yaşadı; emirlik iç işlerinde bağımsız kalmakla birlikte Zengî nüfuz alanına girdi.","kaynak":"TDV: seyzer (\"Sultan b. Ali’nin Musul Atabegi İmâdüddin Zengî’nin himayesini kabul etmesinin (522/1128) ardından Şeyzer kısa süreli bir istikrar dönemi yaşadı.\")","taraflar":["munkizogullari"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["vassal","konu-siyasi"]},{"t":"1130-09-07","tur":"toprak-kayip","k":"toprak-kayip","b":"Zengî, Böri'nin oğlu Sevinç'i tutuklayıp Hama'yı aldı","gun":"Şevval 524 / Eylül 1130 (gün bilinmiyor)","yer":"Hama","yer_id":"Hama","kisiler":"İmâdüddin Zengî, Böri, Sevinç","d":"Halep'i alan Zengî Haçlılara karşı cihad çağrısı yapınca Dımaşk atabegi Böri 500 kişilik kuvvet gönderdi ve Hama valisi oğlu Sevinç'e Zengî'ye katılmasını emretti. Zengî Sevinç ve adamlarını tutuklattı, korunaksız kalan Hama'yı zaptetti. Hama'yı Şemsülmülûk İsmâil Ağustos 1133'te geri aldı.","kaynak":"TDV: tugteginliler (\"böylece korunaksız duruma düşürdüğü Hama’yı zaptetti (Şevval 524 / Eylül 1130).\")","taraflar":["boriler","zengi-musul"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","konu-askeri"]},{"t":"1133-08-05","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Şemsülmülûk İsmâil Banyas ve Hama'yı geri aldı","gun":"Şevval 527 / Ağustos 1133 (gün bilinmiyor)","yer":"Hama, Banyas","yer_id":"Hama","kisiler":"Şemsülmülûk İsmâil","d":"Böri'nin ölümüyle başa geçen Şemsülmülûk İsmâil önce Bâtınîlerin Haçlılara terkettiği Banyas'ı (Aralık 1132), ardından Zengî'nin Haçlılarla uğraşmasından yararlanarak Hama'yı geri aldı. Ardından Şeyzer'i kuşattı ve Akkâ, Nâsıra, Taberiye bölgelerine akınlar düzenledi.","kaynak":"TDV: tugteginliler (\"Ardından Zengî’nin Haçlılar’la uğraşmasından faydalanıp Hama’yı da geri aldı (Şevval 527 / Ağustos 1133).\")","taraflar":["boriler","zengi-musul"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri"]},{"odak_yer":["Hemedan"],"t":"1135-06-24","tur":"savas","k":"savas","b":"Dâymerc Savaşı: Halife Müsterşid Sultan Mesud'a yenilip esir düştü","gun":"24 Haziran 1135","yer":"Dâymerc (Hemedan yakını)","kisiler":"Halife Müsterşid-Billâh; Irak Selçuklu Sultanı Mesud","d":"Halife Müsterşid güçlü bir orduyla Irak Selçuklu Sultanı Mesud'un üzerine yürüdü, ancak Dâymerc'de ordusundaki Türk emîrlerin saf değiştirmesi yüzünden yenildi ve devlet adamlarıyla birlikte esir alındı. 29 Ağustos 1135'te Merâga yakınında bir suikastle öldürüldü; halifenin askerî-siyasî güç kurma girişimi ağır bir darbe aldı.","kaynak":"TDV: mustersid-billah (\"… yenilgiye uğradı ve devlet adamlarıyla birlikte esir edildi (10 Ramazan 529 / 24 Haziran 1135).\")","taraflar":["abbasi","irak-selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","hukumdar","konu-askeri"]},{"t":"1135-09-25","tur":"hukumdar","k":"hukumdar","b":"Mezyedî emîri II. Dübeys Sultan Mesud tarafından öldürüldü","gun":"25 Eylül 1135","yer":"Merâga","yer_id":"Merâga","kisiler":"II. Dübeys; Sultan Mesud; II. Sadaka","d":"Maceralı hayatı ve şairleri himayesiyle tanınan II. Dübeys, Irak Selçuklu Sultanı Mesud tarafından Halife Müsterşid'in ölümünden sorumlu tutularak öldürüldü. Yerine oğlu Seyfüddevle II. Sadaka geçti ve Mesud'un yanında yer aldı.","kaynak":"TDV: mezyediler (\"… II. Dübeys, Irak Selçuklu Sultanı Mesud tarafından Halife Müsterşid-Billâh’ın ölümünden sorumlu tutularak öldürüldü (14 Zilhicce 529 / 25 Eylül 1135).\") + TDV: dubeys-b-sadaka (\"sultanın Merâga'daki otağının kapısında … bekleyen Dübeys'e habersizce yaklaşıp onu katletti\") — YERİ veren kaynak; bulan: LAB-1003","taraflar":["mezyedi","irak-selcuklu"],"onem":1,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1137-01-01","tur":"savas","k":"savas","b":"Dımaşk ordusu Trablus Kontluğu'na girdi; Kont Pons öldü","yer_id":"Trablusşam","gun":"531 (1137) (TDV yıl verir)","yer":"Trablus Kontluğu toprakları","kisiler":"Emîr Bazvac, Pons, II. Raymond","d":"Türkmenlerle güçlendirilen Tuğteginli ordusu Emîr Bazvac kumandasında Trablus Kontluğu topraklarına girdi. Kont Pons bu savaşta öldü (TDV tugteginliler 'esir alındı' der, haclilar 'savaşta ölünce' der), yerine oğlu II. Raymond geçti. Pons'un ölümünden yararlanan Zengî, kontluğun Ba'rîn kalesini kuşattı ve yardıma gelen II. Raymond'u esir aldı.","kaynak":"TDV: haclilar (\"Pons, 1137’de Dımaşk müslümanlarına karşı yaptığı savaşta ölünce kontluğun başına oğlu II. Raimond geçti.\")","taraflar":["boriler","trablus-kontlugu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","hukumdar","konu-askeri"]},{"t":"1138-05-13","tur":"toprak-kayip","k":"toprak-kayip","b":"Humus, Zümrüd Hatun'un çeyizi olarak Zengî'ye bırakıldı","gun":"Ramazan 532 / Mayıs 1138 (gün bilinmiyor)","yer":"Humus","yer_id":"Humus","kisiler":"İmâdüddin Zengî, Zümrüd Hatun, Şehâbeddin Mahmud","d":"Dımaşk'ı savaşla alamayacağını anlayan Zengî, atabeg Şehâbeddin Mahmud'un annesi Zümrüd Hatun ile evlenmeyi istedi. Teklif kabul edildi ve Humus çeyiz olarak Musul Atabegliği'ne bırakıldı. Dımaşk Atabegliği kuzeydeki kalesini barış yoluyla yitirdi.","kaynak":"TDV: tugteginliler (\"Humus, Zümrüd Hatun’un çeyizi olarak Musul Atabegliği’ne bırakıldı (Ramazan 532 / Mayıs 1138).\")","taraflar":["boriler","zengi-musul"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","antlasma","konu-siyasi"]},{"t":"1138-01-01","tur":"hukumdar","k":"hukumdar","b":"Mütevekkil-Alellah Ahmed b. Süleyman imâmetini ilân etti; Zeydî devleti yeniden canlandı","gun":"(TDV yıl verir)","yer":"Sa‘de","yer_id":"Sa'de","kisiler":"Mütevekkil-Alellah Ahmed b. Süleyman","d":"Suleyhî hâkimiyeti boyunca sönük kalan Zeydî imâmeti, II. Zeydî İmamlar Devleti'nin kurucusu sayılan Ahmed b. Süleyman ile yeniden güç kazandı. İmam Sa‘de, Necran ve Bilâdücevf'i ele geçirdi, ardından San‘a'ya girdi ve hâkimiyetini 1170'e kadar sürdürdü; Hemdânî sultanı Hâtim b. Ahmed ile savaştı.","kaynak":"TDV: zeydiyye (\"Yemen’de II. Zeydî İmamlar Devleti’nin kurucusu olarak gösterilen, 532 (1138) yılında imâmetini ilân eden Mütevekkil-Alellah Ahmed b. Süleyman Sa‘de, Necran ve Bilâdücevf gibi bölgeleri ele geçirdi.\")","taraflar":["yemen-zeydi"],"onem":3,"dunya":1,"kapsam":"ic","etiket":["hukumdar","toprak-kazanc","konu-siyasi"]},{"t":"1138-01-01","tur":"hukumdar","k":"hukumdar","b":"Ali b. Sebe' Aden Zürey‘îlerinde iktidarı tek elde topladı","gun":"(TDV yıl verir)","yer":"Aden","yer_id":"Aden","kisiler":"Ali b. Sebe' b. Ebü's-Suûd","d":"Amca ve yeğen kolları arasındaki çekişmeyle geçen istikrarsız dönem, Ali b. Sebe'in hâkimiyeti ele geçirmesiyle bitti. Kardeşi ve halefi Muhammed b. Sebe' döneminde Zürey‘îler Aden ile birlikte Güney Arabistan'ın tamamında etkili oldu ve Fâtımî halifesince bölge dâîsi tayin edildi.","kaynak":"TDV: zureyiler (\"Bu istikrarsızlık dönemi, Ali b. Sebe’ b. Ebü’s-Suûd b. Zürey‘in hâkimiyeti ele geçirmesiyle sona erdi (533/1138).\")","taraflar":["zureyi"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1138-01-01","tur":"hukumdar","k":"hukumdar","b":"Hâtim b. Ahmed San‘a'da üçüncü Hemdânî sülâlesini kurdu","gun":"(TDV yıl verir)","yer":"San‘a","yer_id":"Sana","kisiler":"Hamîdüddevle Hâtim b. Ahmed","d":"Hâtim b. Humâs'ın ölümünden sonra çıkan taht kavgası, kabile meclisinin desteklediği Hâtim b. Ahmed'in tahta geçmesiyle sona erdi. Hemdânîlerin en önemli sultanı sayılan Hâtim, ilk yıllarını ülkenin kuzeyini denetim altına almaya harcadı.","kaynak":"TDV: hemdaniler (\"Bu şekilde Benî Kubeyb sülâlesi dönemi sona ermiş ve kurucusunun adından dolayı yine Benî Hâtim denilen üçüncü Hemdânî sülâlesi dönemi başlamış oldu.\")","taraflar":["hamdani-yemen"],"onem":1,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"odak_yer":["Şeyzer"],"t":"1138-04-29","tur":"kusatma","k":"kusatma","b":"Bizans İmparatoru Ioannes Komnenos Şeyzer'i kuşattı","gun":"29 Nisan - 21 Mayıs 1138","yer":"Şeyzer","kisiler":"Ioannes Komnenos, Sultan b. Ali","d":"Kuzey Suriye'yi denetim altına almak için sefere çıkan Bizans İmparatoru Ioannes Komnenos, Antakya'daki Haçlılarla birlikte Şeyzer'i üç hafta kuşattı. Münkızoğulları'nın sarp mevkideki kalesi direndi ve kuşatma başarısızlıkla sonuçlandı.","kaynak":"TDV: seyzer (\"Kuzey Suriye’yi kontrol altına almak için sefere çıkan Bizans İmparatoru Ioannes Komnenos tarafından yine başarısızlıkla sonuçlanan bir kuşatmaya mâruz kaldı (29 Nisan - 21 Mayıs 1138).\")","taraflar":["munkizogullari","bizans"],"onem":2,"dunya":2,"kapsam":"dis","etiket":["kusatma","konu-askeri"]},{"t":"1144-12-24","tur":"toprak-kazanc","k":"toprak-kazanc","b":"İmâdüddin Zengî Urfa'yı fethetti; Urfa Haçlı Kontluğu'nun merkezi düştü","gun":"24 Aralık 1144","yer":"Urfa","yer_id":"Urfa","kisiler":"İmâdüddin Zengî; II. Josselin; Zeynüddin Ali Küçük","d":"Urfa ile Antakya'daki Haçlı hükümdarlarının arasının açık olmasından ve Kont II. Josselin'in şehirden ayrılmasından yararlanan Musul-Halep hâkimi İmâdüddin Zengî Urfa'yı kuşattı. Dört hafta süren kuşatmadan sonra şehir alındı ve valiliğine Ali Küçük getirildi. Fetih, bölgede Türk hâkimiyetinin dönüm noktası oldu ve II. Haçlı Seferi'nin başlıca sebebi sayıldı.","kaynak":"TDV: sanliurfa (\"… surlar mancınıklarla dövüldü ve dört hafta kadar süren kuşatmanın ardından Türkler şehre girdi (26 Cemâziyelâhir 539 / 24 Aralık 1144).\")","taraflar":["zengi-musul","urfa-kontlugu","begteginli"],"onem":4,"dunya":4,"kapsam":"dis","etiket":["savas","toprak-kazanc","kusatma","konu-askeri"]},{"t":"1146-10-01","tur":"savas","k":"savas","b":"II. Josselin'in Urfa'yı geri alma girişimini Nûreddin Mahmud bastırdı","gun":"Ekim 1146 (gün bilinmiyor)","yer":"Urfa","yer_id":"Urfa","kisiler":"Nûreddin Mahmud Zengî; II. Josselin","d":"İmâdüddin Zengî'nin ölümünü fırsat bilen II. Josselin, şehirdeki isyanla Urfa'yı iç kale hariç kısa süre için yeniden ele geçirdi. Musul'dan gelen kuvvetlerden önce Urfa'ya ulaşan Nûreddin Mahmud isyanı bastırdı, Josselin kaçtı ve Urfa kesin olarak Nûreddin'in idaresine geçti.","kaynak":"TDV: zengiler (\"Fakat Urfa’ya daha önce ulaşan Nûreddin Mahmud isyanı bastırdı, II. Josselin şehri terkedip kaçtı.\"); ay: TDV sanliurfa \"II. Josselin 1146 Ekiminde şehri geri almaya çalıştı;\"","taraflar":["zengi-halep","urfa-kontlugu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","toprak-kazanc","konu-askeri"]},{"t":"1148-05-22","tur":"kusatma","k":"kusatma","b":"II. Haçlı Seferi ordusu Dımaşk'ı kuşattı ve çekildi","yer_id":"Şam","gun":"543 (1148) (TDV yıl verir)","yer":"Dımaşk","kisiler":"VII. Louis, III. Konrad, Muînüddin Üner, Mücîrüddin Abak","d":"Urfa'nın düşüşü üzerine düzenlenen II. Haçlı Seferi'nin Fransa ve Almanya kralları Kudüs Krallığı ile birlikte Dımaşk'ı kuşattı. Vezir Üner komşu hükümdarlardan yardım isterken Haçlı liderleri arasında ayrılık yarattı. Beş gün süren kuşatma yiyecek tükenince başarısız bitti; krallar ülkelerine döndü.","kaynak":"TDV: tugteginliler (\"Kalabalık bir Haçlı ordusu 543’te (1148) şehri kuşattı.\")","taraflar":["boriler","kudus-kralligi"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["kusatma","konu-askeri"]},{"odak_yer":["Halep"],"t":"1149-06-28","tur":"savas","k":"savas","b":"İnab Savaşı: Nûreddin Antakya ordusunu yendi, Raymond de Poitiers öldü","gun":"28 Haziran 1149","yer":"İnab Kalesi önü","kisiler":"Nûreddin Mahmud Zengî, Raymond de Poitiers","d":"Nûreddin, Anadolu Selçuklu Sultanı Mesud ile anlaşarak İnab Kalesi önünde Antakya birliklerini yenilgiye uğrattı. Prinkeps Raymond de Poitiers savaşta öldü, idareyi karısı Konstance üstlendi. Ertesi yıl Urfa kontu II. Josselin'in de esir düşmesiyle kuzeydeki Haçlı varlığı ciddi biçimde daraldı.","kaynak":"TDV: haclilar (\"Raimond bu savaşta öldü (28 Haziran 1149); şehrin idaresini karısı Konstance üstlendi.\")","taraflar":["antakya-prinkipsligi","zengi-halep"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1150-04-01","yer_id":"Şam","tur":"vassal","k":"vassal","b":"Dımaşk atabegi Abak, Nûreddin'in hâkimiyetini tanıdı","gun":"Zilhicce 544 / Nisan 1150 (gün bilinmiyor)","yer":"Dımaşk","kisiler":"Mücîrüddin Abak, Nûreddin Mahmud Zengî","d":"Vezir Üner'in ölümüyle yetkileri eline alan Abak'a karşı Dımaşk'ta isyan çıktı. Nûreddin şehri kuşattı ve Haçlıların müdahalesi ihtimaline karşı hâkimiyetinin tanınması şartıyla Abak'la anlaştı. 27 Temmuz 1151 antlaşması Abak'ı Nûreddin'in nâibi konumuna düşürdü; atabeglik fiilen Zengî tâbiiyetine girdi.","kaynak":"TDV: tugteginliler (\"Böylece Abak’ın atabegliği Nûreddin Mahmud’un tâbiiyetine girmiş oluyordu.\")","taraflar":["boriler","zengi-halep"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["vassal","kusatma","konu-siyasi"]},{"odak_yer":["Sana"],"t":"1150-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Hemdânî Hâtim b. Ahmed Sa‘de dışındaki kuzey Yemen'e hâkim oldu","gun":"(TDV yıl verir)","yer":"Kuzey Yemen","kisiler":"Hâtim b. Ahmed; Mütevekkil-Alellah Ahmed b. Süleyman","d":"On iki yıllık mücadeleden sonra Hâtim b. Ahmed kuzeyde hâkimiyet kurdu ve Zeydîlerin başşehri Sa‘de dışında kalan Yemen topraklarını ülkesine kattı. Zeydî İmam Mütevekkil-Alellah ile savaşlarında esir düşüp barış imzalamak zorunda kaldıysa da çatışmalar sürdü.","kaynak":"TDV: hemdaniler (\"545’te (1150) bölgede hâkimiyet kurmayı başardı.\")","taraflar":["hamdani-yemen","yemen-zeydi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","savas","konu-askeri"]},{"t":"1152-01-01","tur":"hukumdar","k":"hukumdar","b":"Trablus kontu II. Raymond Bâtınîlerce öldürüldü","gun":"1152 (TDV yıl verir)","yer":"Trablusşam","yer_id":"Trablusşam","kisiler":"II. Raymond, III. Raymond, Hodierna","d":"Trablus kontu II. Raymond Bâtınîler (Haşhaşîler) tarafından öldürüldü; idareyi karısı Hodierna, ardından oğlu III. Raymond üstlendi. Aynı dönemde Antakya'da da idare Konstance'ın elindeydi; Doğu'daki üç Haçlı devletinin sorumluluğu bir süre üç kadının eline kaldı.","kaynak":"TDV: haclilar (\"II. Raimond’un 1152’de Bâtınîler tarafından öldürülmesinden sonra yerine oğlu III. Raimond geçti (1152-1187).\")","taraflar":["trablus-kontlugu"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1153-08-19","yer_id":"Askalân","tur":"toprak-kayip","k":"toprak-kayip","b":"III. Baudouin Askalân'ı aldı; Fâtımîlerin Suriye'deki son kalesi düştü","gun":"19 Ağustos 1153","yer":"Askalân","kisiler":"III. Baudouin","d":"Kahire'deki vezirlik kavgaları ve Halife Zâfir'in öldürülmesinin yarattığı karışıklığı fırsat bilen Kudüs Kralı III. Baudouin, yedi ay süren kuşatmadan sonra Askalân'ı zaptetti. Bu, Fâtımîlerin Suriye'deki son kalesiydi ve Haçlıların son büyük başarısı sayılır. Kudüs Krallığı'nın gözü artık Mısır'a çevrildi.","kaynak":"TDV: kudus (\"Yedi ay süren kuşatmadan sonra 19 Ağustos 1153’te Askalân’ı zaptetmesi Haçlılar’ın son büyük başarısını teşkil eder.\")","taraflar":["kudus-kralligi","fatimi"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["kusatma","toprak-kayip","konu-askeri"]},{"t":"1154-04-25","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Nûreddin Mahmud Dımaşk'ı aldı; Halep ve Dımaşk tek elde birleşti","yer_id":"Şam","gun":"25 Nisan 1154","yer":"Dımaşk","kisiler":"Nûreddin Mahmud Zengî","d":"Babasının ölümünden beri başlıca hedefi Dımaşk olan Nûreddin Mahmud, Tuğteginliler'in (Dımaşk Atabegliği) elindeki şehri zaptetti. Halep ve Dımaşk'ı kendi hâkimiyetinde birleştiren Nûreddin bölgenin en güçlü hükümdarı oldu; Haçlı devletlerinin doğusunda tek bir İslâm cephesi oluştu.","kaynak":"TDV: zengiler (\"25 Nisan 1154’te Dımaşk’ı zapteden Nûreddin, Halep ve Dımaşk’ı kendi hâkimiyeti altında birleştirmek suretiyle bölgenin en güçlü hükümdarı oldu.\")","taraflar":["zengi-halep"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["toprak-kazanc","birlesme","konu-askeri"]},{"t":"1156-01-01","tur":"kusatma","k":"kusatma","b":"Ali b. Mehdî Necâhî veziri Sürûr'u öldürtüp Zebîd'i kuşattı","gun":"(TDV yıl verir)","yer":"Zebîd","yer_id":"Zebîd","kisiler":"Ali b. Mehdî; Sürûr el-Fâtikî","d":"Ümmü Fâtik Alem'in ölümünden sonra Ali b. Mehdî ve taraftarları dağlardan Zebîd ve Tihâme'ye karşı amansız bir mücadele başlattı. Necâhî devletini yeniden güçlendiren vezir Sürûr el-Fâtikî'yi bir suikastla ortadan kaldıran Ali b. Mehdî Zebîd'i kuşattı; şehir halkı Zeydî imamdan yardım istedi.","kaynak":"TDV: mehdiler--yemen (\"Ancak Zûcible’den döndüğünde Necâhî reislerinden Sürûr el-Fâtikî’yi ortadan kaldırmaya muvaffak oldu (551/1156); arkasından da Zebîd’i kuşattı.\")","taraflar":["necahi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["kusatma","savas","konu-askeri"]},{"t":"1157-01-15","tur":"kusatma","k":"kusatma","b":"Irak Selçuklu Sultanı Muhammed b. Mahmûd Bağdat'ı kuşattı, halife direndi","gun":"Ocak-Şubat 1157 (gün bilinmiyor)","yer":"Bağdat","yer_id":"Bağdat","kisiler":"Halife Muktefî-Liemrillâh; Sultan Muhammed b. Mahmûd; Ali Küçük","d":"Saltanatını onaylamayan ve rakibi Süleyman Şah adına hutbe okutan Halife Muktefî'ye karşı Irak Selçuklu Sultanı Muhammed b. Mahmûd Bağdat'ı kuşattı; Ali Küçük idaresindeki Musul ordusu da sultana katıldı. Hemedan'ın bir şehzade tarafından alındığı haberi üzerine kuşatma kaldırıldı; halifenin bağımsız tavrı sürdü.","kaynak":"TDV: zengiler (\"Zilhicce 551’de (Ocak-Şubat 1157) Selçuklu ordusu Bağdat’ı kuşattıktan kısa bir süre sonra Ali Küçük idaresindeki Musul ordusu da Bağdat’a ulaştı.\")","taraflar":["abbasi","irak-selcuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["kusatma","konu-askeri"]},{"t":"1158-01-01","tur":"hukumdar","k":"hukumdar","b":"Zebîdliler Zeydî yardımı karşılığında Necâhî emîri III. Fâtik'i öldürdü","gun":"(TDV yıl verir)","yer":"Zebîd","yer_id":"Zebîd","kisiler":"III. Fâtik b. Muhammed; Mütevekkil-Alellah Ahmed b. Süleyman","d":"Kuşatma altındaki Zebîdliler, Sa‘de'deki Zeydî İmam Mütevekkil-Alellah'tan yardım istedi. İmam, Necâhî emîri III. Fâtik'in öldürülmesi ve kendi hâkimiyetinin tanınması şartını koştu. Emîr öldürüldü, ancak beklenen Zeydî yardımı gelmedi ve şehir ertesi yıl Ali b. Mehdî'ye düştü.","kaynak":"TDV: necahiler (\"Bunun üzerine 553 (1158) yılında emîr öldürüldüyse de Mütevekkil-Alellah beklenen yardımı yapamadı\")","taraflar":["necahi","yemen-zeydi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["hukumdar","konu-siyasi"]},{"t":"1164-01-01","tur":"hukumdar","k":"hukumdar","b":"Abdünnebî b. Ali Mehdî yönetimini ele aldı","gun":"(TDV yıl verir)","yer":"Zebîd","yer_id":"Zebîd","kisiler":"Abdünnebî b. Ali b. Mehdî","d":"Ali b. Mehdî'nin ölümünden sonraki dönem kaynaklarda belirsizdir; yönetim bir süre Mehdî'de kaldıktan sonra Ali'nin oğlu Abdünnebî'ye geçti. Abdünnebî, vergi karşılığında barış yaptığı Zürey‘î Aden'i dışında Yemen'in hemen tamamını hükmü altına aldı.","kaynak":"TDV: mehdiler--yemen (\"Mehdî’den sonra yönetim 559 (1164) yılında Ali’nin oğlu Abdünnebî’nin eline geçti.\")","taraflar":["benu-mehdi-zebid"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","toprak-kazanc","konu-siyasi"]},{"odak_yer":["Musul"],"t":"1164-08-10","tur":"kusatma","k":"kusatma","b":"Nûreddin Mahmud, Musul ve Artuklu kuvvetleriyle Hârim'i Haçlılar'dan geri aldı","gun":"10 Ağustos 1164","yer":"Hârim","kisiler":"Nûreddin Mahmud Zengî; Zeynüddin Ali Küçük","d":"Nûreddin'in hastalığından yararlanan Haçlılar Hârim'i almış ve onu Hısnülekrâd önünde yenmişti. Cihad çağrısına Artuklular ve Ali Küçük kumandasındaki Musul ordusu katıldı; şiddetli bir kuşatmanın ardından Hârim geri alındı. Ertesi yıl Arkā ve Banyas gibi kaleler de ele geçirildi.","kaynak":"TDV: zengiler (\"Hârim önlerine gelen ordu şiddetli bir kuşatmanın ardından şehri ele geçirdi (19 Ramazan 559 / 10 Ağustos 1164).\")","taraflar":["zengi-halep","artuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["kusatma","toprak-kazanc","konu-askeri"]},{"t":"1166-01-01","tur":"kusatma","k":"kusatma","b":"Abdünnebî Taiz ve İb'i alıp Zürey‘î Aden'ini kuşattı","gun":"(TDV yıl verir)","yer":"Taiz, İb, Aden","yer_id":"Taiz","kisiler":"Abdünnebî; Hâtim b. Ali ez-Zürey‘î; Ali b. Hâtim el-Hemdânî","d":"Taiz ve İb şehirlerini alan Mehdî hükümdarı Abdünnebî, Güney Arabistan'ın son bağımsız limanı Aden'i kuşattı. Zor durumda kalan Zürey‘î hâkimi, kendisi gibi İsmâilî olan San‘a'daki Hemdânî sultanı Ali b. Hâtim'den yardım istedi.","kaynak":"TDV: mehdiler--yemen (\"Abdünnebî 561’de (1166) Taiz ve İb şehirlerini de aldıktan sonra Aden’i kuşattı.\")","taraflar":["benu-mehdi-zebid","zureyi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["kusatma","toprak-kazanc","konu-askeri"]},{"t":"1169-01-18","tur":"hukumdar","k":"hukumdar","b":"Şîrkûh Fâtımî veziri oldu; Mısır Nûreddin'in ordusuna geçti","gun":"17 Rebîülâhir 564 / 18 Ocak 1169","yer":"Kahire","yer_id":"Kahire","kisiler":"Esedüddin Şîrkûh, Âdıd-Lidînillâh, Şâver, Amaury, Selâhaddin","d":"Vezir Şâver'in Nûreddin ile Kudüs Kralı Amaury arasında taraf değiştiren siyaseti 1164'ten beri Mısır'ı üç seferin sahnesi yaptı. Haçlıların Mısır'ı işgal girişimi üzerine Halife Âdıd yardım istedi; Şîrkûh 7000 süvariyle geldi, Şâver öldürüldü ve Şîrkûh Fâtımî vezirliğine tayin edildi. İki ay sonra ölünce yeğeni Selâhaddin 26 Mart 1169'da hem vezir hem Nûreddin'in Mısır ordusu başkumandanı oldu.","kaynak":"TDV: fatimiler (\"Esedüddin Şîrkûh 17 Rebîülâhir 564 (18 Ocak 1169) tarihinde Fâtımî vezirliğine tayin edildi, fakat iki ay sonra vefat etti.\")","taraflar":["fatimi","zengi-halep"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["hukumdar","konu-siyasi"]},{"t":"1171-01-22","tur":"vassal","k":"vassal","b":"Nûreddin Mahmud Musul'a girdi; Musul Atabegliği ona tâbi oldu","gun":"22 Ocak 1171","yer":"Musul","yer_id":"Musul","kisiler":"Nûreddin Mahmud Zengî; II. Seyfeddin Gazi; II. İmâdüddin Zengî; Sâdeddin Gümüştegin","d":"Kutbüddin Mevdûd'un ölümünden sonra vasiyete aykırı olarak II. Seyfeddin Gazi'nin atabeg yapılması üzerine Nûreddin Mahmud Fırat'ı geçip Habur, Nusaybin, Rakka, Harran ve Sincar'ı aldı; Sincar'ı yeğeni II. İmâdüddin Zengî'ye iktâ etti (Sincar kolunun başlangıcı). 22 Ocak 1171'de Musul'a giren Nûreddin valiyi azletti; Musul Atabegliği ona tâbi oldu ve Irak'tan Mısır'a Haçlılar'a karşı tek cephe kuruldu.","kaynak":"TDV: zengiler (\"… Nûreddin Mahmud 13 Cemâziyelevvel 566’da (22 Ocak 1171) şehre girdi ve Abdülmesîh’i azledip Musul valiliğine kendi adamlarından Sâdeddin Gümüştegin’i getirdi.\")","taraflar":["zengi-halep","zengi-musul","begteginli"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["vassal","toprak-kazanc","konu-siyasi"]},{"t":"1173-01-01","tur":"ittifak","k":"ittifak","b":"Zürey‘î-Hemdânî ittifakı Abdünnebî'yi Aden kuşatmasını kaldırmaya zorladı","gun":"(TDV yıl verir)","yer":"Aden","yer_id":"Aden","kisiler":"Abdünnebî; Hâtim b. Ali ez-Zürey‘î; Ali b. Hâtim el-Hemdânî","d":"İki İsmâilî hanedanın, Aden Zürey‘îleri ile San‘a Hemdânîlerinin kurduğu ittifak Mehdî hükümdarı Abdünnebî'yi kuşatmayı kaldırıp Zebîd'e çekilmeye mecbur etti. Yemen'deki bu karışıklığı izleyen Selâhaddîn-i Eyyûbî aynı yıl kardeşi Turan Şah'ı bölgeye gönderdi.","kaynak":"TDV: mehdiler--yemen (\"Böylece oluşturulan Zürey‘î-Hemdânî ittifakı 569’da (1173-74) Abdünnebî’yi kuşatmayı kaldırarak Zebîd’e çekilmeye mecbur etti.\")","taraflar":["zureyi","hamdani-yemen","benu-mehdi-zebid"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["ittifak","kusatma","konu-askeri"]},{"t":"1174-05-15","tur":"hukumdar","k":"hukumdar","b":"Nûreddin Mahmud öldü; Halep'te oğlu el-Melikü's-Sâlih İsmâil'e geçildi","yer_id":"Halep","gun":"569 / 1174 (TDV yıl verir)","yer":"Dımaşk, Halep","kisiler":"Nûreddin Mahmud Zengî; el-Melikü's-Sâlih İsmâil; Sâdeddin Gümüştegin","d":"Haçlılar'a karşı yeni bir sefere hazırlanan Nûreddin Mahmud öldü. Musul'dan ayrılan Vali Gümüştegin Halep'te Nûreddin'in küçük oğlu el-Melikü's-Sâlih İsmâil'i tahta geçirip onu tahakküm altına aldı; Selâhaddîn-i Eyyûbî de Melikü's-Sâlih adına hutbe okutmakla birlikte Suriye'ye yöneldi. Nûreddin'in kurduğu birlik dağılmaya başladı.","kaynak":"TDV: zengiler (\"Diğer taraftan Musul’dan ayrılan Vali Gümüştegin, Halep’te Nûreddin Mahmud’un yerine oğlu el-Melikü’s-Sâlih İmâdüddin İsmâil’i geçirdi;\"); yıl: TDV sam--suriye \"Nûreddin Zengî’nin ölümünün (569/1174) ardından …\"","taraflar":["zengi-halep"],"onem":4,"dunya":3,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"odak_yer":["Halep","Musul"],"t":"1174-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"II. Seyfeddin Gazi el-Cezîre'deki eski Musul topraklarını geri aldı; Halep'e tâbiliği kopardı","gun":"1174 (TDV yıl verir)","yer":"Harran, Nusaybin, Habur, Urfa, Suruç, Rakka, Cizre","kisiler":"II. Seyfeddin Gazi; Muzafferüddin Kökböri","d":"Nûreddin'in ölüm haberini Suriye'ye giderken alan Musul Atabegi II. Seyfeddin Gazi, amcasının zaptettiği Harran, Nusaybin, Habur, Urfa, Serûc, Rakka ve Cezîre-i İbn Ömer'i yeniden Musul'a bağladı; Harran'ı Kökböri'ye iktâ etti. Böylece Musul'un Halep'e tâbiliği sona erdi.","kaynak":"TDV: begteginliler (\"II. Seyfeddin Gazi amcası Nûreddin Mahmud’un 1174 yılında ölmesi üzerine daha önce Musul’a bağlı olan el-Cezîre’deki toprakları geri aldı …\"); TDV zengiler (\"Harran, Nusaybin, Habur, Urfa, Serûc (Suruç), Rakka ve Cezîre-i İbn Ömer’i (Cizre) Musul’a bağladı.\")","taraflar":["zengi-musul","zengi-halep","begteginli"],"onem":3,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-siyasi"]},{"t":"1174-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Turan Şah Yemen'i fethetti: Zebîd ve San‘a Eyyûbîler'e geçti","yer_id":"Zebîd","gun":"(TDV yıl verir)","yer":"Zebîd; San‘a","kisiler":"Turan Şah; Selâhaddîn-i Eyyûbî; Abdünnebî; Ali b. Hâtim","d":"Yemen'i stratejik, siyasî ve mezhebî sebeplerle hedef seçen Selâhaddîn-i Eyyûbî ağabeyi Turan Şah'ı bölgeye gönderdi. Turan Şah kısa sürede Mehdîlerin başşehri Zebîd'i ve Hemdânîlerin merkezi San‘a'yı alarak iki hanedana son verdi; Zürey‘îlere karşı da ilerledi. Yemen bundan sonra Eyyûbî valileriyle yönetildi.","kaynak":"TDV: yemen (\"Turan Şah kısa süre içerisinde Hemdânîler, Mehdîler ve Zürey‘îler’e karşı başarı sağladı, onların elindeki bölgeleri Eyyûbî hâkimiyeti altına aldı.\")","taraflar":["eyyubi","zureyi"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["savas","toprak-kazanc","son","konu-askeri"]},{"t":"1174-01-01","yer_id":"Mekke","tur":"vassal","k":"vassal","b":"Mekke ve Medine Fâtımî nüfuzundan çıktı; hutbe Nûreddin Zengî adına okundu","gun":"(TDV yıl verir)","yer":"Mekke; Medine","kisiler":"Îsâ b. Füleyte; Turan Şah; Nûreddin Mahmud Zengî","d":"Turan Şah'ın Yemen seferinin ardından Mekke Emîri Îsâ b. Füleyte hutbeyi Abbâsî halifesiyle birlikte Nûreddin Mahmud Zengî adına okuttu; Medine'de de aynı yıl hutbe Fâtımîlerden çevrildi. Nûreddin'in aynı yıl ölümünden sonra Haremeyn Selâhaddîn-i Eyyûbî'nin nüfuzuna girdi ve Eyyûbî hâkimiyeti kesintilerle 1252'ye dek sürdü.","kaynak":"TDV: mekke (\"Turan Şah’ın Yemen’i ele geçirmesinden sonra 569’da (1174) Mekke Emîri Îsâ b. Füleyte hutbeyi Nûreddin Mahmûd Zengî adına okutmaya başladı\"); TDV: medine (\"Fâtımî hâkimiyetinden çıkan Medine’de hutbe 569 (1174) yılından itibaren Abbâsî halifesinin yanı sıra Nûreddin Mahmud Zengî adına okunmaya başlandı\")","taraflar":["mekke-serifligi","medine-emirligi","abbasi","zengi-halep"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["vassal","konu-siyasi"]},{"t":"1174-10-12","yer_id":"Şam","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Selâhaddin Suriye'ye yürüdü; Dımaşk, Humus ve Hama'yı aldı","gun":"12 Ekim 1174 (Mısır'dan hareket günü; Dımaşk'ın teslim günü TDV'de yok)","yer":"Dımaşk, Ba'lebek, Humus, Hama","kisiler":"Selâhaddîn-i Eyyûbî, el-Melikü's-Sâlih İsmâil, Sâdeddin Gümüştegin","d":"Nûreddin'in ölümünden sonra oğlu el-Melikü's-Sâlih İsmâil'in atabegliği için Halep ve Dımaşk emîrleri çekişti. Dımaşk emîrlerinin daveti üzerine Selâhaddin 12 Ekim 1174'te Mısır'dan hareket etti ve Dımaşk, Ba'lebek, Humus, Hama gibi merkezleri kolayca ele geçirdi. Halep direndi; 6 Mayıs 1175'te Abbâsî halifesinin taklidiyle Selâhaddin bağımsızlığını ilân etti.","kaynak":"TDV: eyyubiler (\"Selâhaddin, Dımaşk’tan gelen davet üzerine 12 Ekim 1174 tarihinde Mısır’dan Suriye’ye hareket etti.\")","taraflar":["eyyubi","zengi-halep"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri"]},{"odak_yer":["Halep","Musul"],"t":"1175-01-01","tur":"savas","k":"savas","b":"Halep-Musul ordusu Selâhaddin'e yenildi","gun":"1175 (TDV yıl verir)","yer":"Kuzey Suriye","kisiler":"İzzeddin Mesud; II. Seyfeddin Gazi; Kökböri; Selâhaddîn-i Eyyûbî","d":"II. Seyfeddin Gazi Sincar'ı kuşatırken Halep önlerindeki Selâhaddin'e karşı kardeşi İzzeddin Mesud'u gönderdi; yanında Kökböri'nin de bulunduğu birleşik Halep-Musul ordusu yenildi. Selâhaddin zaptettiği yerleri elinde tuttu, bağımsızlığını ilân etti ve halife tarafından onaylandı (6 Mayıs 1175).","kaynak":"TDV: zengiler (\"Ancak Halep-Musul ordusu Selâhaddîn-i Eyyûbî karşısında yenilgiye uğradı.\"); yıl: TDV begteginliler (\"… 1175 yılında yapılan savaşta Selâhaddin’e mağlûp oldu.\")","taraflar":["zengi-musul","zengi-halep","begteginli"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1180-03-30","tur":"hukumdar","k":"hukumdar","b":"Nâsır-Lidînillâh halife oldu; Abbâsî hilâfetinin ihya dönemi başladı","gun":"30 Mart 1180","yer":"Bağdat","yer_id":"Bağdat","kisiler":"Halife Nâsır-Lidînillâh","d":"Babası Müstazî'nin ölümüyle halife olan Nâsır-Lidînillâh, Büveyhî ve Selçuklu vesâyeti altında dünyevî gücünü yitirmiş hilâfetin hâkimiyetini siyasî, askerî, idarî ve fikrî alanlarda yeniden kurmaya girişti. 45 yıllık hilâfeti en uzun Abbâsî hilâfetidir; fütüvvet teşkilâtını kendine bağlayarak hilâfete eski itibarını kazandırdı.","kaynak":"TDV: nasir-lidinillah (\"Babasının ölümünün ardından 2 Zilkade 575 (30 Mart 1180) tarihinde hilâfet makamına geçti.\")","taraflar":["abbasi"],"onem":3,"dunya":2,"kapsam":"ic","etiket":["hukumdar","konu-siyasi","konu-dini"]},{"t":"1181-12-29","tur":"birlesme","k":"birlesme","b":"Musul Atabegi İzzeddin Mesud Halep'in idaresini ele geçirdi","gun":"29 Aralık 1181","yer":"Halep","yer_id":"Halep","kisiler":"İzzeddin Mes‘ûd b. Mevdûd; el-Melikü's-Sâlih İsmâil","d":"Hastalığı ilerleyen Halep hükümdarı el-Melikü's-Sâlih İsmâil topraklarını Musul Atabegliği'ne bıraktı. Selâhaddin Mısır'da bulunduğu için müdahale edemeden İzzeddin Mesud süratle Halep'e girdi. Ancak hânedan içi çekişme kısa sürede Halep'in Sincar karşılığında II. İmâdüddin Zengî'ye verilmesiyle sonuçlandı.","kaynak":"TDV: zengiler (\"… İzzeddin Mes‘ûd b. Mevdûd süratle hareket ederek şehrin idaresini ele geçirdi (20 Şâban 577 / 29 Aralık 1181).\")","taraflar":["zengi-musul","zengi-halep"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["birlesme","konu-siyasi"]},{"t":"1182-10-02","tur":"kusatma","k":"kusatma","b":"Selâhaddin Musul'u kuşattı, alamadı","gun":"Ekim 1182 (gün bilinmiyor)","yer":"Musul","yer_id":"Musul","kisiler":"Selâhaddîn-i Eyyûbî; İzzeddin Mesud","d":"Musul emîrlerinin bir kısmını hizmetine alan ve Hısnıkeyfâ Artuklu beyinin tâbiiyetini kazanan Selâhaddin Musul'u kuşattı. Kuşatma başarısız oldu, fakat Sincar'ın düşmesi ve Mardin Artukluları'nın da Selâhaddin'e bağlanması Musul Atabegliği'ni yalnız bıraktı.","kaynak":"TDV: zengiler (\"… durumunu iyice güçlendirdi ve Cemâziyelâhir 578’de (Ekim 1182) Musul’u kuşattı.\")","taraflar":["zengi-musul","artuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["kusatma","konu-askeri"]},{"t":"1183-06-11","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Selâhaddin Halep'i aldı","gun":"17 Safer 579 / 11 Haziran 1183","yer":"Halep","yer_id":"Halep","kisiler":"Selâhaddîn-i Eyyûbî, II. İmâdüddin Zengî","d":"el-Melikü's-Sâlih İsmâil'in ölümünden sonra Halep'i Musul Zengîleri aldı. I. Şark Seferi'nde el-Cezîre, Sincar ve Âmid'i alan Selâhaddin Halep'i kuşattı; II. İmâdüddin Zengî, Halep karşılığında Sincar, Habur, Nusaybin ve Serûc'u alarak şehri teslim etti. Halep'in zaptı Selâhaddin'in Nûreddin mirasını birleştirmesini tamamladı ve Kudüs Krallığı'na yönelmesinin yolunu açtı.","kaynak":"TDV: eyyubiler (\"Bu sefer esnasında el-Cezire bölgesini ve Sincar’ı, 4 Muharrem 579’da (29 Nisan 1183) Âmid’i (Diyarbakır), ardından 17 Safer 579’da (11 Haziran 1183) Halep’i aldı.\")","taraflar":["eyyubi"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["toprak-kazanc","antlasma","konu-askeri"]},{"t":"1186-03-03","tur":"vassal","k":"vassal","b":"Musul Atabegliği Selâhaddin'e tâbi oldu; el-Cezîre'de Selçuklu egemenliği hukuken bitti","gun":"3 Mart 1186","yer":"Musul","yer_id":"Musul","kisiler":"İzzeddin Mesud; Selâhaddîn-i Eyyûbî","d":"İkinci Musul kuşatmasından sonuç alamayan Selâhaddin, Ahlat'taki gelişmeler üzerine kuşatmayı kaldırdı; varılan anlaşmayla Musul Atabegliği ona tâbi oldu, hutbede Irak Selçuklu sultanının yerine Selâhaddin'in adı okundu ve Zap suyunun ötesindeki topraklar Eyyûbîler'e bırakıldı. el-Cezîre'de sözde kalan Selçuklu egemenliği hukuken de sona erdi.","kaynak":"TDV: zengiler (\"… ve Zap suyunun ötesindeki topraklar da kendisine bırakılacaktı (9 Zilhicce 581 / 3 Mart 1186).\")","taraflar":["zengi-musul"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["vassal","antlasma","toprak-kayip","konu-siyasi"]},{"odak_yer":["Kudüs"],"t":"1187-07-04","tur":"savas","k":"savas","b":"Hıttîn Savaşı: Selâhaddin Kudüs Krallığı ordusunu yok etti","gun":"24-25 Rebîülâhir 583 / 3-4 Temmuz 1187","yer":"Hıttîn (Taberiye yakını)","kisiler":"Selâhaddîn-i Eyyûbî, Guy de Lusignan, Renaud de Châtillon, III. Raymond","d":"Kerek hâkimi Renaud de Châtillon'un Kahire-Dımaşk kervanını vurması ve tazminat verilmemesi üzerine Selâhaddin Kudüs Krallığı'na sefer açtı. Hıttîn'de krallık ordusu yok edildi, Kral Guy esir düştü. Ardından Taberiye, Akkâ, Nablus, Yafa, Sayda, Beyrut, Cübeyl, Askalân ve Gazze birkaç hafta içinde alındı; bir yıl içinde Sûr dışındaki krallık toprakları müslümanlara geçti.","kaynak":"TDV: kudus (\"Selâhaddin, 4 Temmuz 1187’de Hittîn mevkiinde yapılan savaşta Kudüs krallık ordusunu yok etti.\")","taraflar":["eyyubi","kudus-kralligi","trablus-kontlugu"],"onem":5,"dunya":5,"kapsam":"dis","etiket":["savas","toprak-kazanc","konu-askeri"]},{"t":"1187-10-02","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Selâhaddin Kudüs'e girdi","gun":"27 Receb 583 / 2 Ekim 1187","yer":"Kudüs","yer_id":"Kudüs","kisiler":"Selâhaddîn-i Eyyûbî, Balian d'Ibelin","d":"20 Eylül'de şehir önüne gelen Selâhaddin surlarda gedik açtırdı; savunmayı yöneten Balian d'Ibelin 30 Eylül'de teslim şartlarını konuştu. Halkın küçük bir fidyeyle şehri terketmesine izin verildi ve Mi'rac kandiline denk gelen 2 Ekim Cuma günü Selâhaddin Kudüs'e girdi. 88 yıllık Haçlı hâkimiyeti sona erdi; krallık Sûr ve sonra Akkâ merkezli bir kıyı devletine dönüştü. Kerek de 1188'de alındı.","kaynak":"TDV: kudus (\"Mi‘rac kandiline denk düşen 27 Receb 583 (2 Ekim 1187) Cuma günü Selâhaddin Kudüs’e girdi.\")","taraflar":["eyyubi","kudus-kralligi"],"onem":5,"dunya":5,"kapsam":"dis","etiket":["kusatma","toprak-kazanc","konu-askeri"]},{"t":"1190-01-01","tur":"hukumdar","k":"hukumdar","b":"Muzafferüddin Kökböri Erbil'e hâkim oldu","gun":"1190 (TDV yıl verir)","yer":"Erbil","yer_id":"Erbil","kisiler":"Muzafferüddin Kökböri; Zeynüddin Yûsuf","d":"Erbil beyi Zeynüddin Yûsuf Akkâ savunmasında hastalanıp ölünce Erbil halkı Musul'daki Emîr Kaymaz'ı davet etti, ancak o Selâhaddin'den çekindiği için karışmadı. Urfa ve Harran emîri olan kardeşi Kökböri Erbil'e gelerek şehre hâkim oldu; beyliğin en parlak dönemi başladı.","kaynak":"TDV: begteginliler (\"Kökböri şehre gelerek Erbil’e hâkim oldu (1190).\")","taraflar":["begteginli"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1191-07-11","tur":"toprak-kayip","k":"toprak-kayip","b":"III. Haçlı Seferi: Akkâ garnizonu şehri Haçlılara teslim etti","gun":"11 Temmuz 1191","yer":"Akkâ","yer_id":"Akkâ","kisiler":"Richard (Aslan Yürekli), Philippe Auguste, Selâhaddîn-i Eyyûbî","d":"Hıttîn ve Kudüs'ün kaybı Avrupa'da III. Haçlı Seferi'ni doğurdu. Fransa kralı Philippe 20 Nisan, İngiltere kralı Richard 8 Haziran 1191'de Akkâ kuşatmasına katıldı. Şiddetli hücumlar karşısında müslüman garnizon Selâhaddin'in izni olmadan şehri teslim etti. Akkâ, Kudüs Krallığı'nın yeni merkezi oldu ve 1291'e kadar Haçlı elinde kaldı.","kaynak":"TDV: haclilar (\"Bütün Haçlı kuvvetlerinin şiddetli hücumu üzerine Akkâ’nın müslüman garnizonu 11 Temmuz 1191’de Selâhaddin’in izni olmadan şehri Haçlılar’a teslime mecbur kaldı.\")","taraflar":["kudus-kralligi","eyyubi"],"onem":4,"dunya":4,"kapsam":"dis","etiket":["kusatma","toprak-kazanc","konu-askeri"]},{"odak_yer":["Yafa"],"t":"1192-09-01","tur":"antlasma","k":"antlasma","b":"Selâhaddin ile Richard arasında barış: Sûr-Yafa kıyısı Haçlılarda kaldı","gun":"21 Şâban 588 / 1 Eylül 1192","kisiler":"Selâhaddîn-i Eyyûbî, Richard (Aslan Yürekli), el-Melikü'l-Âdil","d":"Kudüs'ü geri almak için beş yıl süren mücadele bir barış antlaşmasıyla sona erdi. Sûr ile Yafa arasındaki sahil şeridi Haçlılara bırakıldı; Kudüs ve fethedilen öbür topraklar Selâhaddin'de kaldı, Askalân müslümanlarda kalacak şekilde yıkıldı. Hıristiyan hacılar Kudüs'ü serbestçe ziyaret edebilecek, iki taraf birbirinin ülkesinde ticaret yapabilecekti.","kaynak":"TDV: eyyubiler (\"21 Şâban 588’de (1 Eylül 1192) üç yıl sekiz ay süreli, karada ve denizde geçerli bir antlaşma imzalandı.\")","taraflar":["eyyubi","kudus-kralligi"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["antlasma","konu-siyasi"]},{"t":"1193-01-01","tur":"isyan","k":"isyan","b":"Selâhaddin'in ölümü üzerine Kökböri Eyyûbîler'e karşı bağımsızlığını ilân etti","gun":"1193 (TDV yıl verir)","yer":"Erbil","yer_id":"Erbil","kisiler":"Muzafferüddin Kökböri","d":"Selâhaddîn-i Eyyûbî'nin ölümüyle Kökböri Eyyûbî Devleti'ne karşı bağımsızlığını ilân etti. Bundan sonra Erbil, Musul Atabegliği ve Eyyûbîler'in güç kazanmasını önlemek için değişen ittifaklar kurarak kendi başına bir güç olarak hareket etti.","kaynak":"TDV: begteginliler (\"Selâhaddîn-i Eyyûbî’nin 1193 yılında ölümü üzerine Kökböri Eyyûbî Devleti’ne karşı bağımsızlığını ilân etti.\")","taraflar":["begteginli"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["isyan","konu-siyasi"]},{"t":"1193-03-04","tur":"bolunme","k":"bolunme","b":"Selâhaddin Dımaşk'ta öldü; Eyyûbî ülkesi oğulları ve kardeşi arasında bölündü","yer_id":"Şam","gun":"27 Safer 589 / 4 Mart 1193","yer":"Dımaşk","kisiler":"Selâhaddîn-i Eyyûbî, el-Melikü'l-Efdal Ali, el-Melikü'l-Azîz Osman, el-Melikü'z-Zâhir Gāzî, el-Melikü'l-Âdil","d":"Selâhaddin öldüğünde devletin sınırları Trablusgarp'tan Hemedan ve Ahlat'a, Yemen'den Malatya'ya uzanıyordu. Dımaşk'ta veliaht el-Melikü'l-Efdal, Kahire'de el-Melikü'l-Azîz, Halep'te el-Melikü'z-Zâhir, Ürdün ve el-Cezîre'de kardeşi el-Melikü'l-Âdil, Hama, Humus ve Ba'lebek'te yeğenleri hüküm sürüyordu. Büyük sultan Efdal'e karşı Azîz ve Âdil birleşip 1196'da Dımaşk'ı aldılar; birlik ancak Âdil'le yeniden kurulabildi.","kaynak":"TDV: eyyubiler (\"Selâhaddin 27 Safer 589 (4 Mart 1193) tarihinde Dımaşk’ta vefat etti.\")","taraflar":["eyyubi","eyyubi-halep","eyyubi-hama"],"onem":4,"dunya":3,"kapsam":"ic","etiket":["bolunme","hukumdar","konu-siyasi"]},{"odak_yer":["Kûfe"],"t":"1195-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Irak Selçukluları'nın çöküşünden sonra halife Hûzistan'ı ve bazı İran eyaletlerini aldı","gun":"591 / 1195 (TDV yıl verir)","yer":"Hûzistan","kisiler":"Halife Nâsır-Lidînillâh; Vezir İbnü'l-Kassâb; Hârizmşah Alâeddin Tekiş","d":"Irak Selçuklu Sultanı II. Tuğrul'un 1194'te Hârizmşah Tekiş'e karşı savaşta ölmesiyle Irak Selçukluları tarihe karıştı ve halife en çekindiği rakibinden kurtuldu. Nâsır'ın veziri İbnü'l-Kassâb Hûzistan ile bazı İran eyaletlerini ele geçirdi; ertesi yıl Hârizmşah bu yerleri geri aldı, yalnız Hûzistan halifede kaldı.","kaynak":"TDV: nasir-lidinillah (\"Veziri İbnü’l-Kassâb bu amaçla Hûzistan ile bazı İran eyaletlerini ele geçirdi (591/1195).\")","taraflar":["abbasi"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri","konu-siyasi"]},{"t":"1200-05-13","tur":"hukumdar","k":"hukumdar","b":"Katâde b. İdrîs Mekke'yi ele geçirdi; Hevâşim devri bitti, Benî Katâde başladı","gun":"13 Mayıs 1200 (27 Receb 596)","yer":"Mekke","yer_id":"Mekke","kisiler":"Katâde b. İdrîs","d":"Yenbu‘ ve çevresine hâkim olan Hasenî şerif Katâde b. İdrîs, kendisini destekleyen kabilelerle Mekke'yi alarak 1063'ten beri süren Benî Hâşim (Hevâşim) emirliğine son verdi. Mekke, 1924'e kadar Katâde'nin soyundan gelen emîrlerce yönetildi.","kaynak":"TDV: mekke (\"Katâde b. İdrîs’in kendisini destekleyen kabilelerle birlikte şehri ele geçirmesine kadar sürdü (27 Receb 596 / 13 Mayıs 1200)\")","taraflar":["mekke-serifligi"],"onem":3,"dunya":2,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1201-01-01","tur":"bolunme","k":"bolunme","b":"Âdil'in büyük sultanlığı kabul edildi; Dımaşk, Mısır ve el-Cezîre oğullarına paylaştırıldı","gun":"1201 (TDV yıl verir)","yer":"Kahire, Dımaşk, el-Cezîre, Meyyâfârikîn","yer_id":"Kahire","kisiler":"el-Melikü'l-Âdil, el-Melikü'l-Kâmil, el-Melikü'l-Muazzam, el-Melikü'l-Eşref Mûsâ, el-Melikü'l-Evhad","d":"26 Ocak 1200'de Kahire'ye giren el-Melikü'l-Âdil kısa sürede kendini büyük sultan ilân etti. Selâhaddin'in oğullarının 1201'deki başarısız girişiminden sonra yapılan antlaşmayla Dımaşk el-Melikü'l-Muazzam'a, Mısır el-Melikü'l-Kâmil'e, el-Cezîre el-Melikü'l-Eşref Mûsâ'ya verildi. Meyyâfârikîn kolu 596 (1200)'de el-Melikü'l-Evhad Necmeddin Eyyûb'a geçmişti (şehir 581/1185'te Selâhaddin'ce alınmıştı), 607 (1210)'de Eşref'e geçti. Dımaşk, el-Cezîre-Meyyâfârikîn ve (Âdil zamanında kurulan) Kerek kolları bu paylaşımdan doğdu; yalnız Halep bu denetimin dışında kaldı.","kaynak":"TDV: eyyubiler (\"Âdil’in üçüncü oğlu el-Melikü’l-Eşref Mûsâ’ya ise el-Cezîre bölgesi verildi.\")","taraflar":["eyyubi"],"onem":3,"dunya":2,"kapsam":"ic","etiket":["bolunme","hukumdar","konu-siyasi"]},{"t":"1203-01-01","tur":"savas","k":"savas","b":"Haçlılar Trablus'tan Humus ve Hama beyliklerine akın yaptı","gun":"1203 (TDV yıl verir)","yer":"Humus, Hama","yer_id":"Humus","kisiler":"II. Amaury","d":"IV. Haçlı Seferi'nin öncülerinden Felemenk ve Fransız gruplar Akkâ'ya gelip Kral II. Amaury'yi müslümanlara karşı sefere ikna edemeyince Trablus Kontluğu'na geçtiler ve Humus ile Hama Eyyûbî beyliklerinin topraklarına akınlar düzenlediler. el-Melikü'l-Âdil 1207'de Trablus Kontluğu'nu antlaşmaya mecbur etti.","kaynak":"TDV: eyyubiler (\"Onun bu teklifi kabul etmemesi üzerine Trablus Kontluğu’na gelerek Humus, Hama beylikleri topraklarına akınlar yaptılar.\")","taraflar":["eyyubi-hama","trablus-kontlugu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"odak_yer":["Musul","Erbil"],"t":"1204-09-01","tur":"savas","k":"savas","b":"Kefr-Zemmar Savaşı: Eyyûbî-Erbil-Artuklu ittifakı Musul atabegini ağır yenilgiye uğrattı","gun":"Eylül 1204 (gün bilinmiyor)","yer":"Kefr-Zemmar (Musul yakını)","kisiler":"Nûreddin Arslanşah; Muzafferüddin Kökböri; Muizzüddin Sencer Şah; el-Melikü'l-Âdil'in oğulları","d":"Musul Atabegi Nûreddin Arslanşah'ın Sincar'a bağlı Tel A‘fer'i alması, aleyhinde el-Melikü'l-Âdil'in oğulları, Hısnıkeyfâ Artuklu beyi, Cizre'deki Zengî Sencer Şah ve Kökböri'den oluşan geniş bir ittifak doğurdu. Kefr-Zemmar'da yenilen atabeg kuvvetlerinin neredeyse tamamını kaybetti ve Tel A‘fer'i geri vermek şartıyla el-Âdil ile anlaşmak zorunda kaldı.","kaynak":"TDV: zengiler (\"Atabeg elindeki kuvvetlerin neredeyse tamamını kaybetti ve büyük zorluklarla Musul’a dönebildi (Muharrem 601 / Eylül 1204).\")","taraflar":["zengi-musul","begteginli","artuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1207-01-01","tur":"antlasma","k":"antlasma","b":"el-Melikü'l-Âdil Trablus Kontluğu'nu antlaşmaya zorladı","gun":"1207 (TDV yıl verir)","yer":"Trablusşam","yer_id":"Trablusşam","kisiler":"el-Melikü'l-Âdil","d":"Haçlıların Humus ve Hama beyliklerine yaptığı akınlardan sonra el-Melikü'l-Âdil Trablus Kontluğu üzerine yürüyerek onu antlaşmaya mecbur etti. Akkâ'daki Haçlıları denetlemek için şehrin ovasına hâkim Tûr dağında müstahkem bir kale yaptırdı.","kaynak":"TDV: eyyubiler (\"el-Melikü’l-Âdil 1207 yılında Trablus Kontluğu’nu yola getirerek antlaşmaya mecbur etti.\")","taraflar":["trablus-kontlugu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["antlasma","konu-siyasi"]},{"t":"1209-01-01","tur":"ittifak","k":"ittifak","b":"Halep'in Zâhir Gāzî'si, Musul, Erbil ve Anadolu Selçuklu Âdil'e karşı ittifak kurdu","gun":"1209 (TDV yıl verir)","yer":"Sincar, Halep","yer_id":"Sincar","kisiler":"el-Melikü'z-Zâhir Gāzî, Kökböri, Arslanşah, I. Gıyâseddin Keyhusrev, el-Melikü'l-Âdil","d":"el-Melikü'l-Âdil'in Habur ve Nusaybin'i alıp Sincar'ı kuşatması üzerine Erbil hâkimi Kökböri, Musul sahibi Arslanşah, Halep sahibi el-Melikü'z-Zâhir Gāzî ve Anadolu Selçuklu Sultanı I. Gıyâseddin Keyhusrev Âdil'e karşı ittifak kurdu. Halep kolu Âdil soyunun merkezî sultanlığından bağımsız kalmayı sürdürdü.","kaynak":"TDV: eyyubiler (\"el-Melikü’l-Âdil’in Habur ve Nusaybin’i ele geçirip Sincar’ı kuşatması üzerine (1209)\")","taraflar":["eyyubi-halep","selcuklu"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["ittifak","konu-siyasi"]},{"t":"1210-01-01","tur":"vassal","k":"vassal","b":"Kökböri Anadolu Selçuklu Sultanı İzzeddin Keykâvus'a tâbi oldu","gun":"1210 (TDV yıl verir)","yer":"Erbil","yer_id":"Erbil","kisiler":"Muzafferüddin Kökböri; I. İzzeddin Keykâvus; el-Melikü'l-Âdil","d":"el-Melikü'l-Âdil'in Sincar'ı ele geçirmesini önlemek isteyen Kökböri Anadolu Selçuklu sultanına tâbi olarak Eyyûbîler'e karşı ittifak kurdu. Halifenin de araya girmesiyle el-Âdil Sincar'ı almaktan vazgeçti; Kökböri kızlarını Musul atabeginin oğullarıyla evlendirerek Musul ile ittifakını pekiştirdi.","kaynak":"TDV: begteginliler (\"… 1210 yılında Anadolu Selçuklu Sultanı I. İzzeddin Keykâvus’a tâbi oldu.\")","taraflar":["begteginli","selcuklu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["vassal","ittifak","konu-siyasi"]},{"t":"1216-10-09","tur":"hukumdar","k":"hukumdar","b":"Halep'te el-Melikü'l-Azîz Gıyâseddin tahta geçti","gun":"613 (1216) (TDV yıl verir)","yer":"Halep","yer_id":"Halep","kisiler":"el-Melikü'z-Zâhir Gāzî, el-Melikü'l-Azîz Gıyâseddin","d":"Halep'in en parlak dönemini yaşattığı kabul edilen el-Melikü'z-Zâhir Gāzî'nin ölümüyle yerine oğlu el-Melikü'l-Azîz Gıyâseddin geçti. Gāzî devrinde Halep'te ticaret canlanmış, birçok mimari eser yapılmış ve şehir yeniden bir ilim merkezi olmuştu.","kaynak":"TDV: eyyubiler (\"el-Melikü’l-Azîz Gıyâseddin 613 (1216)\")","taraflar":["eyyubi-halep"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1218-03-30","tur":"hukumdar","k":"hukumdar","b":"Musul Atabegi II. İzzeddin Mesud zehirlenerek öldü; Bedreddin Lü'lü' nâib olarak yönetimi tekeline aldı","gun":"615 / 1218 (TDV yıl verir)","yer":"Musul","yer_id":"Musul","kisiler":"II. İzzeddin Mesud; II. Nûreddin Arslanşah; Bedreddin Lü'lü'","d":"Bedreddin Lü'lü'ün tahakkümü altında geçen II. İzzeddin Mesud'un atabegliği zehirlenerek öldürülmesiyle sona erdi. Lü'lü' on yaşındaki II. Nûreddin Arslanşah'ı tahta çıkarıp halifenin onayını aldı ve atabeg-nâib olarak devlet mekanizmasını tamamen tekeline aldı; Zengî atabegleri artık yalnız adda kaldı.","kaynak":"TDV: zengiler (\"Fakat Bedreddin Lü’lü’ün tahakkümü altında geçen devri zehirlenerek öldürülmesiyle son buldu (615/1218).\")","taraflar":["zengi-musul"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"odak_yer":["Musul"],"t":"1219-09-01","tur":"savas","k":"savas","b":"Zap Suyu Savaşı: Kökböri ve III. İmâdüddin Zengî Musul ordusunu yendi","gun":"Eylül 1219 (gün bilinmiyor)","yer":"Zap Suyu","kisiler":"Muzafferüddin Kökböri; III. İmâdüddin Zengî; Bedreddin Lü'lü'; Aybek","d":"Küçük yaştaki Nâsırüddin Mahmud'un Musul atabegi yapılmasından yararlanan Kökböri ve damadı III. İmâdüddin Zengî Musul çevresini yağmaladı. Lü'lü', el-Melikü'l-Eşref'in Nusaybin'deki ordusundan yardım aldıysa da Zap Suyu kıyısındaki muharebe Musul ordusunun yenilgisiyle bitti; Kevâşe Kalesi de Zengî'nin eline geçti.","kaynak":"TDV: begteginliler (\"İki ordu Zap Suyu kenarında Eylül 1219’da karşılaştı ve muharebe Musul ordusunun mağlûbiyetiyle sonuçlandı.\")","taraflar":["begteginli","zengi-musul"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1219-11-05","tur":"toprak-kayip","k":"toprak-kayip","b":"V. Haçlı Seferi Dimyat'ı ele geçirdi","gun":"5 Kasım 1219","yer":"Dimyat","yer_id":"Dimyat","kisiler":"el-Melikü'l-Kâmil, Pelagius, Jean de Brienne","d":"Mısır'ı ele geçirmeyi hedefleyen V. Haçlı Seferi 27 Mayıs 1218'de Akkâ'dan Dimyat'a hareket etti; bu sırada el-Melikü'l-Âdil öldü, yerine el-Melikü'l-Kâmil geçti. Kâmil'in Kerek dışındaki eski krallık topraklarını verme teklifini papa elçisi Pelagius reddetti. Haçlılar Dimyat'ı aldı ve şehrin idaresini Kudüs Kralı Jean de Brienne'e verdi.","kaynak":"TDV: haclilar (\"Nihayet Haçlılar 5 Kasım 1219’da Dimyat’ı ele geçirdiler.\")","taraflar":["kudus-kralligi"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["kusatma","toprak-kayip","konu-askeri"]},{"t":"1220-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"el-Melikü'l-Eşref Sincar'ı aldı; Zengîler'in Sincar kolu sona erdi","gun":"Temmuz 1220 (gün bilinmiyor)","yer":"Sincar","yer_id":"Sincar","kisiler":"el-Melikü'l-Eşref Mûsâ","d":"Kökböri ve Anadolu Selçuklu Sultanı I. Keykâvus'un ittifakı Keykâvus'un ölümüyle zayıflayınca Eyyûbî el-Melikü'l-Eşref Sincar'ı ele geçirip Zengîler'in 1170'ten beri süren Sincar koluna son verdi. Ardından Musul'a gelerek Zap kıyısında anlaşma dayattı.","kaynak":"TDV: zengiler (\"el-Melikü’l-Eşref, Sincar’ı ele geçirip atabegliğin bu koluna da son verdi (Cemâziyelevvel 617 / Temmuz 1220).\")","taraflar":["zengi-musul"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","konu-askeri"]},{"t":"1221-08-29","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Haçlılar Dimyat'ı boşalttı; V. Haçlı Seferi sona erdi","gun":"29 Ağustos 1221","yer":"Dimyat","yer_id":"Dimyat","kisiler":"el-Melikü'l-Kâmil, el-Melikü'l-Muazzam Îsâ, el-Melikü'l-Eşref Mûsâ","d":"Kâmil'in kardeşleri Dımaşk sahibi el-Melikü'l-Muazzam ve el-Cezîre sahibi el-Melikü'l-Eşref yardıma gelince Haçlılar çok zor durumda kaldı. Dimyat'ı ve işgal ettikleri yerleri boşaltmaya razı olarak barış istediler. Eyyûbî kardeşlerin bu dayanışması kısa sürdü; zaferden sonra aralarındaki âhenk bozuldu.","kaynak":"TDV: eyyubiler (\"Tekliflerinin kabul edilmesi üzerine de 29 Ağustos 1221 tarihinde Dimyat’ı boşalttılar.\")","taraflar":["eyyubi"],"onem":3,"dunya":3,"kapsam":"dis","etiket":["antlasma","toprak-kazanc","konu-askeri"]},{"t":"1224-07-02","tur":"kusatma","k":"kusatma","b":"Kökböri Musul'u kuşattı; Eyyûbî müttefiklerinin ayrılmasıyla şehir kurtuldu","gun":"2 Temmuz 1224","yer":"Musul","yer_id":"Musul","kisiler":"Muzafferüddin Kökböri; Bedreddin Lü'lü'; el-Melikü'l-Eşref","d":"Musul atabegine ve hâmisi el-Melikü'l-Eşref'e karşı bazı Eyyûbî melikleriyle ittifak kuran Kökböri Musul'u kuşattı. Şehir düşmek üzereyken ittifakın Eyyûbî kanadı el-Eşref ile anlaştı ve Musul kurtuldu; ancak savaş Musul yöresinde büyük kıtlık ve pahalılığa yol açtı.","kaynak":"TDV: zengiler (\"Bu çerçevede Kökböri’nin 13 Cemâziyelâhir 621’de (2 Temmuz 1224) kuşattığı Musul düşmek üzereyken ittifakın Eyyûbî kanadı el-Melikü’l-Eşref ile anlaştı.\")","taraflar":["begteginli","zengi-musul"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["kusatma","konu-askeri"]},{"t":"1225-01-13","tur":"savas","k":"savas","b":"Celâleddin Hârizmşah Bağdat'a yaklaştı; halifenin ordusunu yendi","yer_id":"Bağdat","gun":"622 / 1225 (TDV yıl verir)","yer":"Irak (Bağdat yakınları)","kisiler":"Celâleddin Hârizmşah; Halife Nâsır-Lidînillâh; Emîr Kuştemir","d":"Moğollar önünden batıya çekilen Celâleddin Hârizmşah ordusuyla Bağdat'ın 200 km yakınına kadar geldi. Halifenin Emîr Kuştemir idaresinde gönderdiği ordu Kökböri'nin kuvvetlerini beklemeden savaşa girip yenildi ve Bağdat'a güçlükle kaçtı. Bu yenilgiden sonra Kökböri Celâleddin'le anlaşarak Eyyûbîler'e karşı ittifaka katıldı.","kaynak":"TDV: nasir-lidinillah (\"622’de (1225) ordusuyla Bağdat’ın 200 km. yakınına kadar gelen Celâleddin halifeye ve Moğollar’a karşı yaptığı savaşları cihad olarak ilân etti.\"); yenilgi: TDV begteginliler (\"Emîr Kuştemir Kökböri’yi beklemeden Celâleddin ile savaşa girdi ve yenilerek Bağdat’a güçlükle kaçabildi.\")","taraflar":["abbasi","begteginli"],"onem":2,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"odak_yer":["Kahire"],"t":"1229-01-01","tur":"kurulus","k":"kurulus","b":"Yemen Eyyûbîlerinin sonu: Nûreddin Ömer b. Resûl yönetimi atabeg olarak devraldı","gun":"(TDV yıl verir)","yer":"Yemen","kisiler":"Nûreddin Ömer b. Ali b. Resûl; el-Melikü'l-Mes‘ûd Atsız","d":"Yemen Eyyûbîlerinin son hükümdarı el-Melikü'l-Mes‘ûd Atsız'ın ölümünden sonra, Eyyûbîlerin Mekke valisi olan Nûreddin Ömer b. Ali Yemen'i atabeg sıfatıyla idaresine aldı. Başlangıçta Mısır Eyyûbî Sultanı el-Melikü'l-Kâmil'in tâbiiyetinde kalan Resûlî yönetimi böyle doğdu.","kaynak":"TDV: resuliler (\"Bunlardan Mekke Valisi Nûreddin Ömer b. Ali, Yemen Eyyûbîleri’nin son hükümdarı el-Melikü’l-Mes‘ûd Selâhaddin Atsız’ın ölümünden (626/1229) sonra Yemen’i atabeg sıfatıyla idaresi altına aldı.\")","taraflar":["eyyubi"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["kurulus","vassal","konu-siyasi"]},{"t":"1229-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Lahsâ Uyûnîler'den Usfûr b. Râşid'in Ukaylî bedevîlerine geçti (yaklaşık)","gun":"c. 1229 (yaklaşık; gün ve kesin yıl bilinmiyor)","yer":"Lahsâ (Ahsâ)","yer_id":"Lahsa","kisiler":"Usfûr b. Râşid b. Umeyre; Ebü'l-Kāsım Mes‘ûd b. Muhammed (son Uyûnî emîri, Lahsâ)","d":"Hanedan içi bölünmelerle zayıflayan Uyûnîler, destek için giderek Ukaylî bedevîlerine bağımlı hale gelmişti. Lahsâ'nın ileri gelenleri son Uyûnî emîrine bağlılığı bırakıp Usfûr b. Râşid'e yöneldi; bir kuşatma ve ipotek hilesiyle Uyûnî ailesinin mülkleri bedevîlere geçti. Tarihçiler Lahsâ'nın Ukaylî (Usfûrî) hâkimiyetine girişini yaklaşık 1229'a yerleştirir.","kaynak":"akademik: Alwazzan 2015, §4.3 (\"The Fall of the ʿUyūnid Emirate in al-Aḥsāʾ to the ʿUqaylids in c.1229 CE.\") — TDV'de bulunamadı","taraflar":["uyuni"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","toprak-kayip","konu-siyasi"]},{"t":"1229-02-24","tur":"antlasma","k":"antlasma","b":"Kâmil-II. Friedrich antlaşması: Kudüs Haçlılara bırakıldı","gun":"24 Şubat 1229","yer":"Yafa","yer_id":"Yafa","kisiler":"el-Melikü'l-Kâmil, II. Friedrich","d":"Kardeşleriyle arası açılan el-Melikü'l-Kâmil, Alman İmparatoru II. Friedrich ile uzun müzakerelerden sonra Kudüs'ün Haçlılara bırakılmasına razı oldu. Çevredeki arazi ve Harem-i şerif müslümanlarda kalacak, Frenkler Kudüs'ü tahkim etmeyecekti; haclilar maddesine göre Beytülahm, Nâsıra ve Celîle'nin bir kısmı da verildi. Friedrich 17 Mart 1229'da Kudüs'e girdi; Dımaşk'ta mâtem ilân edildi.","kaynak":"TDV: eyyubiler (\"iki tarafın mukaddes yerlerinin kendi yönetimlerine terkedilmesi ve Frenkler’in Kudüs’ü tahkim etmeyip sadece sivil maksatlarla kullanmaları şartlarıyla bir antlaşma yaptı (24 Şubat 1229).\")","taraflar":["eyyubi","kudus-kralligi"],"onem":4,"dunya":4,"kapsam":"dis","etiket":["antlasma","toprak-kayip","konu-siyasi"]},{"t":"1233-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Uyûnîler Katîf'i Ukaylîler'e kaybetti (yaklaşık)","gun":"c. 1233 (yaklaşık; gün bilinmiyor)","yer":"Katîf","yer_id":"Katîf","kisiler":"Muhammed b. Muhammed (Muhammed b. Ebû Mâcid)","d":"Yeğeni Mansûr'u öldürerek Katîf'i ve Uvâl adasını ele geçiren son Uyûnî emîri Muhammed b. Muhammed, Katîf'te yalnız üç yıl beş ay hüküm sürdü. Salgurlu saldırılarını iki kez püskürttükten sonra Katîf'i belirsiz koşullarda, Vassâf'ın işaretine göre Ukaylî bedevîlerine kaptırdı; elinde yalnız Uvâl kaldı.","kaynak":"akademik: Alwazzan 2015, §4.4 (\"The Fall of the ʿUyūnid Emirate in al-Qaṭīf to the ʿUqaylids (c.1233 CE) and in Uwāl to the Salghūrids (1236 CE).\") — TDV'de bulunamadı","taraflar":["uyuni","usfuri"],"onem":1,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","konu-siyasi"]},{"odak_yer":["Kûfe"],"t":"1235-01-01","tur":"bolunme","k":"bolunme","b":"Nûreddin Ömer el-Melikü'l-Mansûr unvanıyla bağımsızlığını ilân etti","gun":"(TDV yıl verir)","yer":"Yemen","kisiler":"el-Melikü'l-Mansûr Nûreddin Ömer","d":"Durumunu sağlamlaştıran Nûreddin Ömer, Mısır Eyyûbîlerine tâbiiyeti bırakıp el-Melikü'l-Mansûr unvanıyla bağımsız sultanlığını ilân etti. Hükümdarlığı Abbâsî Halifesi Müstansır-Billâh tarafından da tanındı.","kaynak":"TDV: resuliler (\"durumunu sağlamlaştırınca el-Melikü’l-Mansûr unvanıyla bağımsızlığını ilân etti (632/1235), hükümdarlığı Abbâsî Halifesi Müstansır-Billâh tarafından da kabul gördü\")","taraflar":["resuli","eyyubi","abbasi"],"onem":3,"dunya":1,"kapsam":"dis","etiket":["bolunme","konu-siyasi"]},{"odak_yer":["Şiraz"],"t":"1236-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Fars Atabegi Ebû Bekir Uvâl'i (Bahreyn) aldı; Uyûnî emirliği sona erdi","gun":"Ağustos 1236 (gün bilinmiyor; Vassâf: 3 Zilhicce 633)","yer":"Uvâl (Bahreyn adası)","kisiler":"Ebû Bekir b. Sa‘d (Salgurlu atabegi); Muhammed b. Muhammed","d":"Kîş adasını 1230'da ele geçiren Fars Salgurlu Atabegi Ebû Bekir, Basra körfezindeki hâkimiyetini Arabistan kıyılarına yaydı. Uvâl adasına yaptığı çıkarmada son Uyûnî emîrini yenip çıkardı (bir rivayete göre öldürdü); böylece 1076'dan beri süren Uyûnî emirliği sona erdi.","kaynak":"akademik: Alwazzan 2015, s. 129 (\"Vaṣṣāf writes that on the third of Dhū al-Ḥijja 633 [August 1236 CE], Abū Bakr invaded Uwāl and expelled the last ʿUyūnid emir.\") — TDV salgurlular Kays 627/1230'u verir, Uvâl'i anmaz","taraflar":["salgurlu"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","son","konu-askeri"]},{"t":"1236-11-02","tur":"hukumdar","k":"hukumdar","b":"Halep'te II. el-Melikü'n-Nâsır Selâhaddin Yûsuf tahta geçti","gun":"634 (1237) (TDV yıl verir)","yer":"Halep","yer_id":"Halep","kisiler":"II. el-Melikü'n-Nâsır Selâhaddin Yûsuf","d":"el-Melikü'l-Azîz'in ölümüyle Halep'te oğlu II. el-Melikü'n-Nâsır Selâhaddin Yûsuf başa geçti. Yûsuf, Mısır'daki merkezle bağlarını koparmış Halep'i 1260'a kadar yönetti; Humus'u 646/1248'de aldı, 1250'de Dımaşk'a da hâkim olarak Suriye Eyyûbîlerinin son büyük hükümdarı oldu.","kaynak":"TDV: eyyubiler (\"II. el-Melikü’n-Nâsır Selâhaddin Yûsuf 634-658 (1237-1260)\")","taraflar":["eyyubi-halep"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1244-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Salgurlu Atabegi Ebû Bekir Katîf'i alıp Ukaylî emîrini öldürdü","yer_id":"Katîf","gun":"İlkbahar 1244 (gün bilinmiyor)","yer":"Katîf; Târût","kisiler":"Ebû Bekir b. Sa‘d; Ebû Âsım b. Sirhân","d":"Fars Atabegi Ebû Bekir deniz seferiyle Katîf'i ve limanı Târût'u işgal etti; Usfûr'un akrabası olan Ukaylî emîri Ebû Âsım b. Sirhân öldürüldü. Ukaylîler ardından Katîf'e sık baskınlar düzenledi ve Salgurlular onlara hurma ve altınla haraç ödemek zorunda kaldı.","kaynak":"akademik: Alwazzan 2015, s. 138 (\"In order to subjugate al-Qaṭīf, the Atābeg launched a maritime expedition and its seaport of Tārūt in the spring of 1244 CE.\") — TDV'de bulunamadı","taraflar":["usfuri","salgurlu"],"onem":1,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","savas","konu-askeri"]},{"t":"1244-07-11","tur":"toprak-kayip","k":"toprak-kayip","b":"Hârizmliler Kudüs'e girdi; şehir Haçlıların elinden kesin olarak çıktı","gun":"11 Temmuz 1244","yer":"Kudüs","yer_id":"Kudüs","kisiler":"el-Melikü's-Sâlih Necmeddin Eyyûb, el-Melikü'n-Nâsır Dâvûd","d":"Mısır sultanı el-Melikü's-Sâlih Necmeddin Eyyûb'un Suriye Eyyûbîlerine karşı çağırdığı Hârizmli atlı birlikler Dımaşk yöresini yakıp yıktıktan sonra Kudüs'e girdi. Kerek hâkimi Dâvûd'un aracılığıyla Yafa'ya çekilmeye izin alan hıristiyan halk ve garnizon yolda pusuya düşürüldü. Haçlıların 1099'dan beri (1187-1229 arası hariç) tuttuğu Kudüs bir daha Haçlı eline geçmedi.","kaynak":"TDV: kudus (\"Hârizmliler, Dımaşk civarında dehşet saçarak bütün bölgeyi yakıp yıktıktan sonra 11 Temmuz 1244’te Kudüs’e girdiler.\")","taraflar":["kudus-kralligi"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["isgal","toprak-kayip","konu-askeri"]},{"t":"1244-10-20","tur":"savas","k":"savas","b":"Gazze Savaşı: Mısır sultanı Sâlih, Suriye Eyyûbîleri ve Haçlı müttefiklerini yendi","yer_id":"Gazze","gun":"16 Cemâziyelevvel 642 / 20 Ekim 1244","yer":"Gazze yakını","kisiler":"el-Melikü's-Sâlih Necmeddin Eyyûb, el-Melikü's-Sâlih İmâdüddin İsmâil, el-Melikü'n-Nâsır Dâvûd","d":"Kâmil'in 1238'deki ölümünden sonra Eyyûbî merkezinin otoritesi çöktü: 1243'e dek Kerek ve Dımaşk dahil doğuda Mısır sultanının hükmü geçmiyor, yalnız el-Cezîre, Âmid ve Hama'da onun adına hutbe okunuyordu; Halep merkezle ilişkisini kesmiş, Halep, Humus ve Dımaşk Kösedağ'a (1243) kadar daha çok Anadolu Selçuklularına tâbi kalmıştı. Dımaşk sahibi İmâdüddin İsmâil Haçlılara Kudüs, Askalân, Sayda, Taberiye, Safed ve Kevkeb'i vererek onlarla ittifak kurdu. Mısır sultanı el-Melikü's-Sâlih Necmeddin Eyyûb Hârizmlilerin desteğiyle Gazze yakınında bu ittifakı ağır bir yenilgiye uğrattı ve Kudüs'ü geri aldı; 1245'te Dımaşk da Mısır'a bağlandı.","kaynak":"TDV: eyyubiler (\"16 Cemâziyelevvel 642 (20 Ekim 1244) tarihinde Gazze yakınında meydana gelen savaşta\")","taraflar":["eyyubi","kudus-kralligi"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"odak_yer":["Sana"],"t":"1247-01-01","tur":"savas","k":"savas","b":"Nûreddin Ömer, Zeydî imamla birleşen yeğeni Esedüddin Muhammed'i yendi","gun":"(TDV yıl verir)","yer":"Yemen","kisiler":"el-Melikü'l-Mansûr Nûreddin Ömer; Esedüddin Muhammed","d":"Resûlî sultanı Nûreddin Ömer'e karşı yeğeni Esedüddin Muhammed, Zeydî imamla birleşerek ayaklandı. Sultan isyanı bastırdı; Esedüddin sonraki dönemde de defalarca baş kaldırdı.","kaynak":"TDV: resuliler (\"Nûreddin Ömer, 645 (1247) yılında Zeydî imamıyla birleşerek yönetime baş kaldıran yeğeni Esedüddin Muhammed’i yendi.\")","taraflar":["resuli","yemen-zeydi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","isyan","konu-askeri"]},{"t":"1248-04-26","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Halep Eyyûbîsi el-Melikü'n-Nâsır Yûsuf Humus'u ele geçirdi","gun":"646 (1248) (TDV yıl verir)","yer":"Humus","yer_id":"Humus","kisiler":"II. el-Melikü'n-Nâsır Selâhaddin Yûsuf","d":"Halep sahibi el-Melikü'n-Nâsır Yûsuf, Şîrkûh soyunun yönettiği Humus'u ele geçirdi. Humus'taki Şîrkûh ailesinin yönetimi bazı aralıklarla 661/1263'e kadar sürdü.","kaynak":"TDV: humus--suriye (\"Daha sonra Halep Eyyûbî Emîri el-Melikü’n-Nâsır Yûsuf Humus’u ele geçirdi (646/1248).\")","taraflar":["eyyubi-halep"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri"]},{"t":"1249-06-08","tur":"toprak-kayip","k":"toprak-kayip","b":"VII. Haçlı Seferi: IX. Louis Dimyat'ı ele geçirdi","gun":"8 Haziran 1249","yer":"Dimyat","yer_id":"Dimyat","kisiler":"IX. Louis (Saint Louis), el-Melikü's-Sâlih Necmeddin Eyyûb","d":"Fransa Kralı IX. Louis'nin yönettiği VII. Haçlı Seferi Ağustos 1248'de yola çıktı ve Dimyat'ı ele geçirdi. el-Melikü's-Sâlih Necmeddin Eyyûb mücadeleyi sürdürdü ama 23 Kasım 1249'da öldü; karısı Şecerüddür ölümü gizleyip Hısnıkeyfâ'daki oğlu Turan Şah'ı Mansûre'ye çağırdı.","kaynak":"TDV: eyyubiler (\"Bu Haçlı seferinin lideri IX. Saint Louis, Ağustos 1248’de Fransa’dan doğuya hareket etti ve 8 Haziran 1249’da Dimyat’ı ele geçirdi.\")","taraflar":["eyyubi"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["kusatma","toprak-kayip","konu-askeri"]},{"t":"1250-04-05","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Halep'in el-Melikü'n-Nâsır Yûsuf'u Dımaşk'a hâkim oldu","yer_id":"Şam","gun":"648 (1250) (TDV yıl verir)","yer":"Dımaşk","kisiler":"II. el-Melikü'n-Nâsır Selâhaddin Yûsuf","d":"el-Melikü's-Sâlih Eyyûb'un ölümü ve Mısır'da Memlük hâkimiyetinin kurulması sırasında Halep hâkimi el-Melikü'n-Nâsır Yûsuf, şehir halkının da çağrısıyla Dımaşk'ta hâkimiyet kurdu. Dımaşk, Hama, Humus ve Kerek Eyyûbîleri Memlüklere karşı onun etrafında birleşti.","kaynak":"TDV: sam--suriye (\"Eyyûbîler’den Halep hâkimi el-Melikü’n-Nâsır Yûsuf şehir halkının da çağrısıyla Dımaşk’ta hâkimiyeti sağladı (648/1250).\")","taraflar":["eyyubi-halep"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","konu-siyasi"]},{"odak_yer":["Taiz"],"t":"1250-01-01","tur":"hukumdar","k":"hukumdar","b":"Nûreddin Ömer suikastla öldürüldü; I. Yûsuf (el-Melikü'l-Muzaffer) tahta geçti","gun":"Şubat 1250 (Zilkade 647; gün bilinmiyor)","yer":"Cened","kisiler":"Nûreddin Ömer; el-Melikü'l-Muzaffer I. Yûsuf","d":"Kurduğu devlet Mekke ile Hadramut arasında tanınırken Nûreddin Ömer Cened'de kendi memlüklerinin suikastına kurban gitti. Rakiplerini bertaraf eden oğlu el-Melikü'l-Muzaffer I. Yûsuf, iktidar mücadelesi sırasında elden çıkan Zebîd, Tihâme, Aden ve Mekke'yi yeniden hâkimiyeti altına aldı.","kaynak":"TDV: resuliler (\"Cened’de kendi memlüklerinin suikastına uğradığında (Zilkade 647 / Şubat 1250) kurduğu devletin hâkimiyeti Mekke ile Hadramut arasındaki bölgede tanınıyordu.\")","taraflar":["resuli"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1250-05-07","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Mansûre zaferinden sonra Dimyat müslümanlara teslim edildi","gun":"7 Mayıs 1250","yer":"Dimyat, Mansûre","yer_id":"Dimyat","kisiler":"Turan Şah, IX. Louis, Baybars el-Bundukdârî, Şecerüddür","d":"Mart başından 7 Nisan 1250'ye kadar süren savaşlarda Haçlılar kesin yenilgiye uğradı ve IX. Louis maiyetiyle esir alındı. Dimyat'ın iadesi ve ağır bir fidye karşılığında kralın serbest bırakılması kararlaştırıldı. Arada 30 Nisan'da Turan Şah memlükler tarafından öldürülmüş, Mısır'da Eyyûbî devri sona ermişti; Dimyat 7 Mayıs'ta yeni yönetime teslim edildi.","kaynak":"TDV: eyyubiler (\"7 Mayıs 1250’de Dimyat müslümanlara teslim edildi.\")","taraflar":["memluk"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["antlasma","toprak-kazanc","konu-askeri"]},{"t":"1251-01-30","tur":"savas","k":"savas","b":"Suriye Eyyûbîleri Kahire önünde Memlüklere yenildi","yer_id":"Kahire","gun":"30 Ocak 1251","yer":"Kahire önü (Abbâse)","kisiler":"II. el-Melikü'n-Nâsır Selâhaddin Yûsuf, Aktay, İzzeddin Aybeg","d":"Mısır'da Memlük devrinin başlamasını kabul etmeyen Dımaşk-Hama-Humus-Kerek Eyyûbîleri, Halep'in el-Melikü'n-Nâsır Yûsuf'u etrafında birleşip Kahire önlerine geldi. Eyyûbîler yenildi, Aktay kumandasındaki Memlükler Şeria nehrine kadar Filistin'i geri aldı. Abbâsî halifesinin aracılığıyla Şeria ve Nablus'a kadar olan toprakların Memlüklerde, kuzey ve doğusunun Eyyûbîlerde kalması kararlaştırıldı.","kaynak":"TDV: eyyubiler (\"Selâhaddin Yûsuf ordusuyla 30 Ocak 1251’de Kahire önlerine geldi.\")","taraflar":["eyyubi-halep","eyyubi-hama","memluk"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","antlasma","konu-askeri"]},{"t":"1254-01-01","tur":"hukumdar","k":"hukumdar","b":"Ebû Nümey Muhammed b. Hasan Mekke emîri oldu","gun":"(TDV yıl verir)","yer":"Mekke","yer_id":"Mekke","kisiler":"Ebû Nümey Muhammed b. Hasan","d":"Eyyûbîlerin Mekke'deki nüfuzu 1252'de sona ermişti. 1301'e kadar emirlik yapan Ebû Nümey, sonradan Memlük sultanlarına bağlılığını sürdürerek şerif ailesi içindeki muhalefeti bastırdı ve Benî Katâde'nin Mekke'deki hükümranlığını sağlamlaştırdı.","kaynak":"TDV: mekke (\"1254-1301 yılları arasında Mekke emîri olan Ebû Nümey Muhammed b. Hasan, Memlük sultanlarına bağlılığını sürdürerek\")","taraflar":["mekke-serifligi"],"onem":2,"dunya":1,"kapsam":"ic","etiket":["hukumdar","konu-siyasi"]},{"t":"1256-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Salgurlu atabegi Katîf'in yönetimini Usfûr b. Râşid'e bıraktı","gun":"(yıl verilir)","yer":"Katîf","yer_id":"Katîf","kisiler":"Usfûr b. Râşid b. Umeyre; Mâni‘ b. Ali","d":"Vassâf'a göre Fars atabegi 654 yılında Katîf'in idaresini Usfûr b. Râşid ile Mâni‘ b. Ali'ye verdi. Başka kaynaklar bu devri anmaz ve Katîf'i sonraki dönemde yine İran merkezli güçlerin elinde gösterir; devir kısa süreli olmuş olabilir.","kaynak":"akademik: Alwazzan 2015, s. 139 (\"Vaṣṣāf (1328 CE) writes that ‘in 654 [A.H.] [1256 CE] [the Atābeg] gave the rule there\") — TDV'de bulunamadı","taraflar":["usfuri","salgurlu"],"onem":1,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-siyasi"]},{"t":"1257-04-09","tur":"ittifak","k":"ittifak","b":"Memlük Sultanı Aybeg, Lü'lü'ün kızıyla nişanlandığı için öldürüldü","gun":"9 Nisan 1257","yer":"Kahire","yer_id":"Kahire","kisiler":"İzzeddin Aybeg; Şecerüddür; Bedreddin Lü'lü'","d":"İlk Memlük hükümdarı İzzeddin Aybeg hâkimiyetini genişletmek için Musul hükümdarı Bedreddin Lü'lü'ün kızıyla nişanlandı. Bu siyasî evlilik girişimi karısı Şecerüddür'ü öfkelendirdi ve Aybeg onun emriyle düzenlenen suikastle öldürüldü; Musul-Mısır ittifakı gerçekleşmedi.","kaynak":"TDV: memlukler (\"Bu arada siyasî bir evliliğe niyetlenmesi ve Musul Emîri Bedreddin Lü’lü’ün kızıyla nişanlanması yüzünden hanımı Şecerüddürr’ün emriyle bir suikast sonucunda öldürüldü (22 Rebîülevvel 655 / 9 Nisan 1257).\")","taraflar":["lului","memluk"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["ittifak","hukumdar","konu-siyasi"]},{"t":"1258-01-22","tur":"kusatma","k":"kusatma","b":"Hülâgû Bağdat'ı kuşattı","gun":"22 Ocak 1258","yer":"Bağdat","yer_id":"Bağdat","kisiler":"Hülâgû; Baycu Noyan; Halife Müsta‘sım-Billâh","d":"Halifeye bölge devletlerinden yardım ulaşmasını engelleyen tedbirleri aldıktan sonra Hemedan'dan yürüyen Hülâgû'nun Baycu Noyan kumandasındaki sağ kanadı 17 Ocak 1258'de Enbâr yakınında Abbâsî kuvvetlerini bozguna uğrattı. Moğollar başka engelle karşılaşmadan Bağdat önlerine inip şehri kuşattı; kuşatma 10 Şubat'ta halifenin teslimiyle bitti.","kaynak":"TDV: mustasim-billah (\"… Moğollar başka bir engelle karşılaşmadan Bağdat önlerine indiler ve şehri kuşattılar (15 Muharrem 656 / 22 Ocak 1258).\")","taraflar":["abbasi","ilhanli"],"onem":5,"dunya":5,"kapsam":"dis","etiket":["kusatma","savas","konu-askeri"]},{"t":"1260-03-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Ketboğa Noyan Dımaşk'ı teslim aldı","yer_id":"Şam","gun":"Rebîülevvel 658 / Mart 1260 (gün bilinmiyor)","yer":"Dımaşk","kisiler":"Ketboğa Noyan, Hülâgû, II. el-Melikü'n-Nâsır Selâhaddin Yûsuf","d":"Bağdat'ın 1258'de düşüşünden sonra Hülâgû Suriye'ye yürüdü; Halep'i yakıp yıktıktan sonra kumandanı Ketboğa Noyan Dımaşk'ı teslim aldı. Halep, Humus ve Hama ile birlikte Dımaşk da Moğolların eline geçti; Eyyûbîlerin Dımaşk'taki hâkimiyeti sona erdi.","kaynak":"TDV: sam--suriye (\"gibi Dımaşk da Moğollar’ın eline geçti (Rebîülevvel 658 / Mart 1260).\")","taraflar":["eyyubi-halep","ilhanli"],"onem":4,"dunya":3,"kapsam":"dis","etiket":["isgal","toprak-kayip","konu-askeri"]},{"odak_yer":["Tebriz"],"t":"1260-01-01","tur":"toprak-kayip","k":"toprak-kayip","b":"Hülâgû Meyyâfârikîn'i aldı; el-Cezîre Eyyûbî kolu sona erdi","gun":"658 (1260) (TDV yıl verir) — eyyubiler 1259 der","yer":"Meyyâfârikîn (Silvan)","kisiler":"Hülâgû, el-Melikü'l-Kâmil Nâsırüddin","d":"Hülâgû'nun Suriye seferiyle eşzamanlı olarak bir Moğol şehzadesi Meyyâfârikîn'i kuşattı. Son Eyyûbî hükümdarı el-Melikü'l-Kâmil Nâsırüddin şehri büyük bir cesaretle savundu, ama baş gösteren kıtlık yüzünden teslim olmak zorunda kaldı ve işkenceyle öldürüldü. 581/1185'ten beri Eyyûbî elinde olan şehir İlhanlılara geçti; Hısnıkeyfâ dışındaki el-Cezîre Eyyûbîleri tarihe karıştı.","kaynak":"TDV: meyyafarikin (\"Son Eyyûbî hükümdarı el-Melikü’l-Kâmil Nâsırüddin şehri büyük bir cesaretle savunduysa da baş gösteren kıtlık sebebiyle teslim olmak zorunda kaldı ve işkenceyle öldürüldü.\")","taraflar":["ilhanli"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["kusatma","toprak-kayip","konu-askeri"]},{"odak_yer":["Kahire"],"t":"1260-09-03","tur":"savas","k":"savas","b":"Aynicâlût Savaşı: Memlükler Moğolları yendi","gun":"3 Eylül 1260","yer":"Aynicâlût","kisiler":"Kutuz, Baybars, Ketboğa Noyan","d":"Dımaşk'ı alan Hülâgû'nun Mısır'ı tehdit etmesi üzerine Memlük Sultanı Kutuz savaşmaya karar verdi. 3 Eylül'de Aynicâlût'ta ve 6 Eylül'de Beysân yakınında yapılan iki savaş Memlüklerin kesin zaferiyle sonuçlandı; Moğollar Fırat'ın doğusuna çekildi. Yenilgiyi öğrenen Hülâgû yanındaki Halep sultanı el-Melikü'n-Nâsır Yûsuf'u öldürttü.","kaynak":"TDV: eyyubiler (\"Memlükler’le Moğollar arasında 3 Eylül 1260’ta Aynicâlût’ta, 6 Eylül 1260’ta Beysân yakınlarında yapılan iki savaş Memlükler’in kesin zaferiyle sonuçlandı.\")","taraflar":["memluk","ilhanli"],"onem":5,"dunya":5,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1260-12-10","tur":"savas","k":"savas","b":"I. Humus Savaşı: Humus, Hama ve Halep Eyyûbî kuvvetleri Moğolları bozdu","gun":"5 Muharrem 659 / 10 Aralık 1260","yer":"Humus (Hâlid b. Velîd türbesi yakını)","yer_id":"Humus","kisiler":"el-Melikü'l-Eşref Mûsâ (Humus), el-Melikü'l-Mansûr (Hama)","d":"Aynicâlût'tan sonra Halep'i yeniden yağmalayan Moğollar Humus'a ilerledi. Hâlid b. Velîd'in kabri civarındaki I. Humus Savaşı'nda Humus, Hama ve Halep askerlerinden oluşan Eyyûbî müttefik kuvvetleri karşısında bozguna uğradılar.","kaynak":"TDV: humus--suriye (\"(5 Muharrem 659/10 Aralık 1260)\")","taraflar":["eyyubi-hama","ilhanli"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"t":"1263-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Baybars Kerek ve Humus'taki Eyyûbî hâkimiyetine son verdi","yer_id":"Humus","gun":"661 (1263) (TDV yıl verir)","yer":"Kerek, Humus","kisiler":"Baybars, el-Melikü'l-Eşref Mûsâ","d":"Aynicâlût'tan sonra sultan olan Baybars, el-Melikü'n-Nâsır Dâvûd'un yarı bağımsız bir emirlik merkezi yaptığı Kerek'i Memlüklere bağlayıp tahkim etti. Humus'ta Şîrkûh soyunun yönetimi el-Melikü'l-Eşref Mûsâ'nın ölümüyle sona erdi ve şehir Hama ile Dımaşk'a bağlı bir idarî bölge oldu. Eyyûbîlerin elinde yalnız Hama ve Hısnıkeyfâ beylikleri kaldı.","kaynak":"TDV: eyyubiler (\"Aynicâlût Savaşı’ndan sonra sultan olan Baybars 661 (1263) yılında Kerek ve Humus’taki Eyyûbî hâkimiyetine son verdi.\")","taraflar":["memluk"],"onem":3,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","konu-siyasi"]},{"odak_yer":["Sana"],"t":"1278-01-01","tur":"savas","k":"savas","b":"I. Yûsuf Zeydîlere karşı başarı kazandı","gun":"(TDV yıl verir)","yer":"Kuzey Yemen","kisiler":"el-Melikü'l-Muzaffer I. Yûsuf","d":"Amcazadesi Esedüddin Muhammed'in ölümünden sonra Zeydî imam ve şeriflerin isyanlarıyla uğraşan Resûlî Sultanı I. Yûsuf, Zeydîlere karşı başarı sağladı. Bu zafer güneydoğuya, Zafâr ve Hadramut'a yönelik genişlemenin önünü açtı.","kaynak":"TDV: resuliler (\"676’da (1278) Zeydîler’e karşı başarı sağlayarak 678’de (1279) Zafâr’ı, ertesi yıl da Şibâm ve Hadramut’u topraklarına kattı.\")","taraflar":["resuli","yemen-zeydi"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["savas","konu-askeri"]},{"odak_yer":["Hadramut"],"t":"1279-01-01","tur":"toprak-kazanc","k":"toprak-kazanc","b":"Resûlîler Zafâr'ı aldı (ertesi yıl Şibâm ve Hadramut)","gun":"(TDV yıl verir)","yer":"Zafâr","kisiler":"el-Melikü'l-Muzaffer I. Yûsuf","d":"I. Yûsuf, Zeydîlere karşı kazandığı başarının ardından Arabistan'ın güney kıyısındaki Zafâr'ı ele geçirdi. TDV'ye göre ertesi yıl Şibâm ve Hadramut da Resûlî topraklarına katıldı.","kaynak":"TDV: resuliler (\"676’da (1278) Zeydîler’e karşı başarı sağlayarak 678’de (1279) Zafâr’ı, ertesi yıl da Şibâm ve Hadramut’u topraklarına kattı.\")","taraflar":["resuli"],"onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri"]}];

