window.KRONOLOJI_COK_ONCE1281_IRAN = [{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1000-01-01","k":"olay","tur":"hanedan","b":"Müntasır Buhara'yı geri alıp Sâmânî tahtına çıktı","gun":"390 h. (1000); gün bilinmiyor","yer":"Buhara","yer_id":"Buhara","kisiler":"İsmâil b. Nûh el-Müntasır","d":"Karahanlılar'ın 999'da Özkent'e sürdüğü Sâmânî ailesinden İsmâil b. Nûh hapisten kaçtı ve Buhara'yı yeniden ele geçirdi. Müntasır lakabıyla tahta çıkan son Sâmânî emîri, Karahanlılar ve Gazneliler'e karşı devleti diriltmeye çalıştı.","kaynak":"TDV: samaniler (SÂMÂNÎLER)","taraflar":["samani","karahanli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1001-01-01","k":"antlasma","tur":"antlasma","b":"Gazneli-Karahanlı antlaşması: Ceyhun sınır oldu","gun":"391 h. (1001); gün bilinmiyor","yer":"Ceyhun (Amuderya)","odak_yer":["Belh","Buhara"],"kisiler":"Sultan Mahmud, İlig Han Nasr b. Ali","d":"Karahanlı Nasr b. Ali Buhara'yı aldıktan sonra Mahmud ile dostluk mektuplaştı ve Sâmânî mirası Ceyhun nehri sınır olmak üzere paylaşıldı: Mâverâünnehir Karahanlılar'a, Horasan Gazneliler'e kaldı.","kaynak":"TDV: mahmud-i-gaznevi (MAHMÛD-ı GAZNEVÎ)","taraflar":["gazneli","karahanli"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","t":"1001-01-01","k":"hanedan","tur":"hanedan","b":"Revvâdî Memlân öldü, oğlu Ebû Nasr Hüseyin geçti","gun":"391/1001 (gün bilinmiyor)","yer":"Tebriz","yer_id":"Tebriz","kisiler":"Memlân, Ebû Nasr Hüseyin","d":"998'de Ermeni-Gürcü ordularına ağır yenilen Revvâdî emîri Memlân öldü. Yerine oğlu Ebû Nasr Hüseyin geçti; onun dönemi hakkında kaynaklarda bilgi yoktur.","kaynak":"TDV: revvadiler (REVVÂDÎLER)","taraflar":["revvadi"],"etiket":["hanedan-degisimi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1006-01-01","k":"hanedan","tur":"hanedan","b":"Bâvendî İspehbed III. Şehriyâr Kābûs'a isyan edip öldürüldü","gun":"1006 (gün bilinmiyor)","yer":"Taberistan","odak_yer":["Âmül","Sârî"],"kisiler":"III. Şehriyâr, Kābûs b. Veşmgîr","d":"Daha önce müttefiki olduğu Ziyârî Kābûs'a karşı ayaklanan Keyûsiyye kolundan İspehbed III. Şehriyâr yakalanarak öldürüldü; yerine III. Rüstem geçti.","kaynak":"TDV: bavendiler (BÂVENDÎLER)","taraflar":["bavendi","ziyari"],"etiket":["hanedan-degisimi","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1006-01-01","yer_id":"Bulgar (Bolgar)","k":"antlasma","tur":"antlasma","b":"İdil Bulgarları ile Kiev Rus Knezliği ticaret antlaşması yaptı","gun":"1006 (gün/ay bilinmiyor)","yer":"Bulgar","odak_yer":["Bulgar"],"d":"964 ve 985'teki Kiev Rus saldırılarını savuşturan İdil Bulgarları 1006'da Ruslarla bir ticaret antlaşması imzaladılar; Bulgar şehri Arap, İran, Rus ve İskandinav tüccarlarının buluştuğu büyük bir pazar oldu.","kaynak":"TDV: idil-bulgar-hanligi (İDİL BULGAR HANLIĞI)","taraflar":["idil-bulgar"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1007-01-01","k":"savas","tur":"savas","b":"Belh Savaşı: Mahmud birleşik Karahanlı ordusunu yendi","gun":"Rebîülevvel 398 / Aralık 1007 (gün bilinmiyor)","yer":"Belh","yer_id":"Belh","kisiler":"Sultan Mahmud, İlig Han Nasr, Yûsuf Kadır Han","d":"Horasan'dan vazgeçmeyen Nasr b. Ali, Hoten hâkimi Yûsuf Kadır Han'dan yardım aldı. Mahmud birleşik Karahanlı ordusunu Belh civarında yendi; Karahanlılar'ın Horasan'a son teşebbüsü de böylece başarısız kaldı.","kaynak":"TDV: mahmud-i-gaznevi (MAHMÛD-ı GAZNEVÎ)","taraflar":["gazneli","karahanli"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Gazne"],"t":"1010-01-01","k":"savas","tur":"savas","b":"Mahmud'un Gur seferi: Muhammed b. Sûrî esir alındı","gun":"1010 (gün bilinmiyor)","yer":"Âhengerân (Gur)","kisiler":"Sultan Mahmud, Muhammed b. Sûrî, Ebû Ali","d":"Gazneli topraklarına akın eden Gur reislerini cezalandırmak için Mahmud sefere çıktı. Âhengerân reisi Muhammed b. Sûrî yenilip esir alındı, yerine oğlu Ebû Ali reis yapıldı; Gur, Gazneli tâbiiyetine girdi.","kaynak":"TDV: gurlular (GURLULAR)","taraflar":["gazneli","gurlu"],"etiket":["konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Kirmanşah"],"t":"1010-01-01","k":"hanedan","tur":"hanedan","b":"Ebü'l-Feth öldü; Ebü'ş-Şevk Fâris Annâzî başına geçti","gun":"1010 (gün bilinmiyor)","yer":"Hulvân","kisiler":"Ebü'l-Feth Muhammed, Ebü'ş-Şevk Fâris, Mühelhil, Sürhâb","d":"Hânedanın kurucusu Hulvân'da öldü; yerine oğlu Hüsâmüddevle Ebü'ş-Şevk geçti. Kardeşlerinden Mühelhil Şehrizor'da, Sürhâb Bendenîcîn'de bağımsız hüküm sürdü.","kaynak":"TDV: annaziler (ANNÂZÎLER)","taraflar":["annazi"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","odak_yer":["Balasagun"],"t":"1012-01-01","k":"hanedan","tur":"hanedan","b":"İlig Han Nasr öldü, Arslan İlig Mansûr yerine geçti","gun":"403 h. (1012-13); gün bilinmiyor","yer":"Özkent","kisiler":"İlig Han Nasr, Arslan İlig Han Mansûr","d":"Buhara fatihi İlig Han Nasr, ağabeyi Togan Han Ahmed'e karşı giriştiği bağımsızlık mücadelesinin ortasında öldü. Yerine geçen kardeşi Mansûr kısa sürede Talas, Şâş, Fergana ve Buhara'yı alarak kendini büyük kağan ilân etti.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["karahanli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1012-01-01","k":"hanedan","tur":"hanedan","b":"Kābûs tahttan indirildi, oğlu Menûçihr Ziyârî tahtına çıktı","gun":"402/1012 (gün bilinmiyor)","yer":"Cürcân","odak_yer":["Esterâbâd"],"kisiler":"Kābûs b. Veşmgîr, Menûçihr","d":"Zalimane davranışları yüzünden ordu tarafından tahttan uzaklaştırılan Kābûs öldürüldü, yerine oğlu Menûçihr getirildi. Menûçihr, kardeşini destekleyen Gazneli Mahmud'a tâbi oldu.","kaynak":"TDV: ziyariler (ZİYÂRÎLER)","taraflar":["ziyari","gazneli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1016-01-01","k":"savas","tur":"savas","b":"Karahanlılar Hıtay ilerleyişini Balasagun'da durdurdu","gun":"1016 (gün bilinmiyor)","yer":"Balasagun","yer_id":"Balasagun (Ak-Beşim)","d":"1009'dan beri batıya yönelen Hıtaylar (Liao) Balasagun yakınında Karahanlılar'a yenildi; batıya ilerleyişleri bir yüzyıl gecikti.","kaynak":"TDV: karahitaylar (KARAHITAYLAR)","taraflar":["karahanli"],"etiket":["konu-askeri"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1017-05-30","k":"fetih","tur":"fetih","b":"Mahmud Hârizm'i ilhak etti, Me'mûnîler sona erdi","gun":"408 h. (1017) — hicrî yılın ilk günü (Jülyen 1017-05-30); gün kaynaktan alınmadı","yer":"Gürgenç (Hârizm)","yer_id":"Köhne Ürgenç (Gürgenç)","kisiler":"Sultan Mahmud, Hârizmşah Ebü'l-Hâris Muhammed","d":"Gazneli tâbiiyetini kabul eden Hârizmşah Me'mûn'u kumandanları öldürünce Mahmud intikam bahanesiyle Hârizm'e yürüdü, başşehir Gürgenç'e girdi ve Me'mûnî hânedanına son verdi. Bölgeye Altuntaş el-Hâcib Hârizmşah unvanıyla vali atandı.","kaynak":"TDV: mahmud-i-gaznevi (MAHMÛD-ı GAZNEVÎ)","taraflar":["memuni-harezm","gazneli"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","odak_yer":["Gazne"],"t":"1018-12-20","k":"fetih","tur":"fetih","b":"Kannevc'in fethi","gun":"8 Şâban 409 / 20 Aralık 1018","yer":"Kannevc (Kanauj)","kisiler":"Sultan Mahmud","d":"Mahmud on ikinci Hint seferinde Sarsâva ve Mathûrâ'yı aldıktan sonra asıl hedefi olan Gangetik ovadaki Kannevc'i fethetti. Sefere Mâverâünnehir'den 20.000 gazi katılmıştı.","kaynak":"TDV: mahmud-i-gaznevi (MAHMÛD-ı GAZNEVÎ)","taraflar":["gazneli"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1023-01-01","k":"fetih","tur":"fetih","b":"Kâkûyî Alâüddevle Hemedan'ı Büveyhîlerden aldı","gun":"414/1023-24 (gün bilinmiyor)","yer":"Hemedan","yer_id":"Hemedan","kisiler":"Alâüddevle Muhammed, Semâüddevle","d":"İsfahan'daki Alâüddevle Muhammed, Burûcird hâkiminin kendisine sığınmasını bahane ederek Hemedan'a yürüdü ve Büveyhî Semâüddevle'nin buradaki hâkimiyetine son verdi.","kaynak":"TDV: kakuyiler (KÂKÛYÎLER)","taraflar":["kakuyi","buveyhi"],"etiket":["toprak-kazanc","toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1026-01-01","k":"hanedan","tur":"hanedan","b":"Ali Tegin Mâverâünnehir'in müstakil hükümdarı oldu","gun":"417 h. (1026); gün bilinmiyor","yer":"Buhara-Semerkant","odak_yer":["Buhara","Semerkant"],"kisiler":"Ali Tegin","d":"Mahmud'un çekilmesinden sonra Buhara ve Semerkant'a yeniden hâkim olan Ali Tegin, Mâverâünnehir'in bağımsız hükümdarı oldu; 1032'de Tamgaç Buğra Kara Hakan unvanıyla bağımsızlığını ilân etti.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["karahanli"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1026-01-08","k":"savas","tur":"savas","b":"Gazneli Mahmud Somnat Kalesi'ni fethetti","gun":"16 Zilkade 416 / 8 Ocak 1026","yer":"Somnat (Sûmenât), Kathiavar","yer_kon":[20.888,70.401],"kisiler":"Sultan Mahmud","d":"Mahmud'un Hindistan'a düzenlediği seferlerin en önemlisi sayılan Sûmenât seferinde Ekim 1025'te Gazne'den yola çıkan ordu, 8 Ocak 1026'da Kathiavar yarımadasındaki Somnat Kalesi'ni aldı ve tapınaktaki büyük put sökülerek parçalandı. Zaferin yankısı bütün İslâm âlemine yayıldı.","kaynak":"TDV: mahmud-i-gaznevi (MAHMÛD-ı GAZNEVÎ): \"Gazneli ordusu 16 Zilkade 416’da (8 Ocak 1026) Somnât Kalesi’ni fethetti.\" · TDV: gazneliler (GAZNELİLER)","taraflar":["gazneli"],"etiket":["konu-askeri"],"kapsam_genis":true,"odak_yer":["Cûnâgadh","Diu"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","odak_yer":["Isfahan"],"t":"1029-01-01","k":"fetih","tur":"fetih","b":"Gazneli Mahmud Rey'i aldı, Büveyhî Cibâl koluna son verdi","gun":"420/1029 (gün bilinmiyor)","yer":"Rey","kisiler":"Gazneli Mahmud, Mecdüddevle","d":"Ömrünün son yıllarında batıya yönelen Gazneli Mahmud Rey şehrine hâkim oldu. Büveyhîlerin Cibâl (Rey) kolu sona erdi; Kâkûyî Alâüddevle de İsfahan'ı boşaltıp Hûzistan'a kaçtı.","kaynak":"TDV: buveyhiler (BÜVEYHÎLER)","taraflar":["kakuyi"],"etiket":["toprak-kazanc","toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1029-01-01","k":"olay","tur":"siyasi","b":"Menûçihr Gazneli Mahmud'a 500.000 dinar ödedi ve öldü","gun":"420/1029 (gün bilinmiyor)","yer":"Cürcân / Taberistan","odak_yer":["Esterâbâd","Âmül"],"kisiler":"Menûçihr, Gazneli Mahmud, Enûşirvân","d":"Rey seferine çıkan Gazneli Mahmud'a düşmanca tavır takınan Menûçihr'in ülkesi Gazneli hâkimiyetine alındı. Tahtta kalmak için 500.000 dinar ödeyen Menûçihr kısa süre sonra öldü; yerine Enûşirvân geçti.","kaynak":"TDV: ziyariler (ZİYÂRÎLER)","taraflar":["ziyari","gazneli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1029-01-01","k":"olay","tur":"sosyal","b":"Azerbaycan'a ilk Oğuz göçü; 2000 çadır Vehsûdân'ın ordusuna katıldı","gun":"420/1029 (gün bilinmiyor)","yer":"Azerbaycan","odak_yer":["Tebriz","Erdebil"],"kisiler":"Ebû Mansûr Vehsûdân","d":"Revvâdî Vehsûdân döneminde bölgeye ilk Oğuz muhacereti başladı; gelen 2000 çadırlık Oğuz halkı Revvâdî ordusuna katıldı.","kaynak":"TDV: revvadiler (REVVÂDÎLER)","taraflar":["revvadi"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1029-01-01","k":"savas","tur":"savas","b":"Gazneli Mesud Târum Sellârı İbrâhim'i ele geçirip vergiye bağladı","gun":"420/1029 (gün bilinmiyor)","yer":"Kazvin / Sercihan","yer_id":"Kazvin","kisiler":"Gazneli Mesud, Sellâr İbrâhim b. Merzübân","d":"Gazneli ordusunu Kazvin'den çıkaran Sellâr İbrâhim'e karşı Rey'deki Mesud yürüdü; ilk karşılaşmada başarısız olsa da sonraki saldırıda onu yakalayıp vergiye bağladı.","kaynak":"TDV: musafiriler (MÜSÂFİRÎLER)","taraflar":["gazneli","musafiri"],"etiket":["konu-askeri","toprak-kayip"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1030-01-01","k":"fetih","tur":"fetih","b":"Kâkûyî Alâüddevle Yezd'i ele geçirip adına para bastırdı","gun":"421/1030 (gün bilinmiyor)","yer":"Yezd","yer_id":"Yezd","kisiler":"Alâüddevle Muhammed","d":"Gazneli ordusu çekilince eski topraklarına dönen Alâüddevle sınırlarını doğuda Yezd'e doğru genişletti ve kendi adına sikke bastırdı.","kaynak":"TDV: yezd (YEZD)","taraflar":["kakuyi"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1030-04-30","k":"hanedan","tur":"hanedan","b":"Sultan Mahmud Gazne'de öldü","gun":"23 Rebîülâhir 421 / 30 Nisan 1030","yer":"Gazne","yer_id":"Gazne","kisiler":"Sultan Mahmud, Mesud, Muhammed","d":"Gazneli Devleti'ni Azerbaycan'dan Yukarı Ganj'a, Hârizm'den Hint Okyanusu'na uzanan imparatorluğa çeviren Mahmud öldü. Ardından oğulları arasında taht mücadelesi başladı ve Mesud kardeşi Muhammed'i yenerek tahta çıktı.","kaynak":"TDV: mahmud-i-gaznevi (MAHMÛD-ı GAZNEVÎ)","taraflar":["gazneli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1032-01-01","k":"hanedan","tur":"hanedan","b":"Yûsuf Kadır Han Kâşgar'da öldü","gun":"Muharrem 424 / Aralık 1032 (gün bilinmiyor)","yer":"Kâşgar","yer_id":"Kaşgar","kisiler":"Yûsuf Kadır Han, Arslan Han Süleyman, Buğra Han Muhammed","d":"Büyük kağanlık iddiasındaki Yûsuf Kadır Han öldü; yönetimi oğulları Arslan Han Süleyman ile Buğra Han Muhammed üstlendi. Süleyman'ın saltanatı TDV'de Doğu Karahanlılar'ın başlangıcı sayılır.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["karahanli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1033-01-01","yer_id":"Isfahan","k":"antlasma","tur":"antlasma","b":"Gazneli Mesud Alâüddevle'yi vergili İsfahan emîri olarak tanıdı","gun":"424/1033 (gün bilinmiyor)","yer":"İsfahan","odak_yer":["Isfahan"],"kisiler":"Gazneli Mesud, Alâüddevle Muhammed","d":"Sultan Mesud, Alâüddevle'nin vergi ödemesi şartıyla İsfahan emîrliğini kabul etti. Alâüddevle ertesi yıl yeniden isyan etti.","kaynak":"TDV: kakuyiler (KÂKÛYÎLER)","taraflar":["gazneli","kakuyi"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":2,"bolge_onem":4,"puan_s":"v2","odak_yer":["Gazne"],"t":"1035-01-01","k":"savas","tur":"savas","b":"Hisâr-ı Tâk'ta Gazneli ordusu Selçuklular'a yenildi","gun":"426 h. (1035); gün bilinmiyor","yer":"Hisâr-ı Tâk (Horasan)","kisiler":"Sultan Mesud, Hâcib Beg Toğdı","d":"1035 ilkbaharında Horasan'a göçüp Merv-Serahs-Ferâve arasına yerleşen Selçuklular'a karşı Mesud'un gönderdiği ordu ağır bir yenilgiye uğradı. 1037 ve 1038 yenilgileriyle Gazneliler'in Horasan hâkimiyeti sarsıldı.","kaynak":"TDV: gazneliler (GAZNELİLER)","taraflar":["gazneli"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1035-01-01","k":"savas","tur":"savas","b":"Gazneli Mesud'un Hazar seferi: Cürcân ve Taberistan işgal edildi","gun":"426/1035 (gün bilinmiyor)","yer":"Cürcân, Taberistan","odak_yer":["Esterâbâd","Âmül"],"kisiler":"Gazneli Mesud, Ebû Kâlîcâr, Enûşirvân","d":"Vergiyi düzenli ödemeyen Ziyârî yönetimine karşı Sultan Mesud Hazar kıyılarına sefer yaptı; Gazneli ordusu Cürcân ve Taberistan'ı ele geçirdi. Kaçan Ebû Kâlîcâr sonunda af diledi ve vergi ödemeye söz verdi.","kaynak":"TDV: ziyariler (ZİYÂRÎLER)","taraflar":["gazneli","ziyari"],"etiket":["konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1036-01-01","yer_id":"Isfahan","k":"antlasma","tur":"antlasma","b":"Alâüddevle Gazneli Mesud'la barıştı, İsfahan'a döndü","gun":"Safer 428 / Aralık 1036 (gün bilinmiyor)","yer":"İsfahan","odak_yer":["Isfahan"],"kisiler":"Alâüddevle Muhammed, Gazneli Mesud","d":"Gazneli ordusunun İsfahan'ı aldığı yenilgiden sonra Hûzistan'dan dönen Alâüddevle, şehri geri alamayınca barış istedi. Sultan Mesud İsfahan'daki eski mevkiini ona geri verdi.","kaynak":"TDV: kakuyiler (KÂKÛYÎLER)","taraflar":["kakuyi","gazneli"],"etiket":["toprak-kazanc","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Isfahan"],"t":"1038-01-01","k":"fetih","tur":"fetih","b":"Alâüddevle Rey'i geçici olarak ele geçirdi","gun":"Cemâziyelevvel 429 / Şubat 1038 (gün bilinmiyor)","yer":"Rey","kisiler":"Alâüddevle Muhammed","d":"Irak Oğuzlarının Azerbaycan'a gitmesiyle boşalan Rey'i Alâüddevle ele geçirdi, ancak kısa süre sonra şehri terk edip İsfahan'ı surlarla tahkim etti.","kaynak":"TDV: kakuyiler (KÂKÛYÎLER)","taraflar":["kakuyi"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1038-01-01","k":"isgal","tur":"isgal","b":"Ebü'ş-Şevk Karmîsîn, Hulencân ve Erenbe'yi işgal etti","gun":"430/1038-39 (gün bilinmiyor)","yer":"Karmîsîn (Kirmanşah)","yer_id":"Kirmanşah","kisiler":"Ebü'ş-Şevk Fâris","d":"Oğuzları durdurup Ukaylîlerden Dakūkā'yı alan Ebü'ş-Şevk, ardından Karmîsîn ile Hulencân ve Erenbe kalelerini yeniden işgal etti.","kaynak":"TDV: annaziler (ANNÂZÎLER)","taraflar":["annazi"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1041-01-01","k":"hanedan","tur":"hanedan","b":"Alâüddevle Muhammed öldü; Ferâmurz İsfahan tahtına geçti","gun":"Muharrem 433 / Eylül 1041 (gün bilinmiyor)","yer":"İsfahan","yer_id":"Isfahan","kisiler":"Alâüddevle Muhammed, Ebû Mansûr Ferâmurz, Ebû Kâlîcâr Gerşâsb","d":"Annâzîlerden Dînever'i barış yoluyla alıp dönerken Alâüddevle öldü. İsfahan'da büyük oğlu Ferâmurz, Nihâvend'de ona bağlı olarak Gerşâsb yönetime geçti.","kaynak":"TDV: kakuyiler (KÂKÛYÎLER)","taraflar":["kakuyi","annazi"],"etiket":["hanedan-degisimi","toprak-kazanc"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1041-01-01","k":"olay","tur":"askeri","b":"Vehsûdân Oğuz liderlerini ziyafette öldürttü","gun":"432/1041 (gün bilinmiyor)","yer":"Tebriz / Urmiye","yer_id":"Tebriz","odak_yer":["Tebriz","Urmiye"],"kisiler":"Vehsûdân","d":"1038'deki ikinci Oğuz göçünden sonra bölgede kalan Oğuz liderleri Vehsûdân'ın ziyafetinde öldürüldü. Urmiye'deki Oğuzlar bunun üzerine Musul'a göçtü.","kaynak":"TDV: revvadiler (REVVÂDÎLER)","taraflar":["revvadi"],"etiket":["konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Nîşâbur"],"t":"1042-01-01","k":"antlasma","tur":"antlasma","b":"Târum Sellârı Tuğrul Bey'i metbû tanıdı","gun":"434/1042-43 (gün bilinmiyor)","yer":"Târum","kisiler":"Tuğrul Bey","d":"Selçukluların Rey'e ve Cibâl vilâyetlerine hâkim olması üzerine Târum'daki Müsâfirî hükümdarı Tuğrul Bey'e bağlanıp vergi vermeyi kabul etti.","kaynak":"TDV: musafiriler (MÜSÂFİRÎLER)","taraflar":["buyuk-selcuklu","musafiri"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Nîşâbur"],"t":"1046-01-01","k":"hanedan","tur":"hanedan","b":"Ebü'ş-Şevk Sîrvân Kalesi'nde öldü; Selçuklu baskısı arttı","gun":"Ramazan 437 / Nisan 1046 (gün bilinmiyor)","yer":"Sîrvân Kalesi","kisiler":"Ebü'ş-Şevk Fâris, İbrâhim Yinal, Mühelhil","d":"İbrâhim Yinal'ın ordusu Hulvân ve Mâhîdeşt'i alırken Dînever'den kaçıp Sîrvân'a sığınan Ebü'ş-Şevk öldü; Annâzîler Mühelhil'in çevresinde toplandı.","kaynak":"TDV: annaziler (ANNÂZÎLER)","taraflar":["annazi","buyuk-selcuklu"],"etiket":["hanedan-degisimi","toprak-kayip"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1047-01-01","k":"fetih","tur":"fetih","b":"Kinkever Kalesi Selçuklulara teslim oldu; Gerşâsb bütün topraklarını kaybetti","gun":"439/1047 (gün bilinmiyor)","yer":"Kinkever / Hemedan","odak_yer":["Hemedan"],"kisiler":"Ebû Kâlîcâr Gerşâsb, İbrâhim Yinal","d":"İbrâhim Yinal'ın seferleriyle Hemedan kesin olarak Selçuklulara bağlandı, ardından Kinkever Kalesi de teslim oldu. Kâkûyî Gerşâsb Büveyhî Hûzistan'ına sürgüne gitti.","kaynak":"TDV: kakuyiler (KÂKÛYÎLER)","taraflar":["buyuk-selcuklu","kakuyi"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Nîşâbur"],"t":"1047-01-01","k":"fetih","tur":"fetih","b":"İbrâhim Yinal Sürhâb'ın Annâzî topraklarını ele geçirdi","gun":"Aralık 1047 (gün bilinmiyor)","yer":"Bendenîcîn / Diz-i Mâhkî","kisiler":"İbrâhim Yinal, Sürhâb","d":"Selçuklu komutanı İbrâhim Yinal gönderdiği kuvvetlerle Annâzî Sürhâb'ın topraklarını aldı; Annâzîlerin önemli kalesi Sîrvân da kuşatmadan sonra düştü.","kaynak":"TDV: annaziler (ANNÂZÎLER)","taraflar":["buyuk-selcuklu","annazi"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1048-01-01","k":"fetih","tur":"fetih","b":"Kavurd Kirman'daki Büveyhî hâkimiyetine son verdi","gun":"1048 (gün bilinmiyor)","yer":"Kirman","yer_id":"Kirman","kisiler":"Kavurd, Ebû Kâlîcâr","d":"Dandanakan'dan sonra Kirman payı kendisine verilen Çağrı Bey'in oğlu Kavurd bölgeye yürüdü ve Büveyhî hâkimiyetini bitirdi. Aynı yıl Ebû Kâlîcâr öldü; Kirman Selçuklularının temeli atıldı.","kaynak":"TDV: buveyhiler (BÜVEYHÎLER)","taraflar":["buyuk-selcuklu"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1049-01-01","k":"hanedan","tur":"hanedan","b":"Keykâvus b. İskender Ziyârî tahtına geçti","gun":"441/1049 (gün bilinmiyor; 435/1043-44 de olabilir)","yer":"Cürcân","odak_yer":["Esterâbâd"],"kisiler":"Keykâvus b. İskender, Enûşirvân","d":"Enûşirvân'ın ölümünün ardından Kâbûsnâme'nin yazarı Keykâvus b. İskender hükümdar oldu. Ziyârîler bu dönemde Selçuklulara tâbi olarak varlıklarını sürdürdü.","kaynak":"TDV: ziyariler (ZİYÂRÎLER)","taraflar":["ziyari"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1051-01-01","k":"fetih","tur":"fetih","b":"Tuğrul Bey İsfahan'ı aldı","gun":"443/1051 (gün bilinmiyor)","yer":"İsfahan","yer_id":"Isfahan","kisiler":"Tuğrul Bey","d":"Daha önce vergiye bağlanan İsfahan, Tuğrul Bey tarafından doğrudan ülkeye katıldı. Şehir sonraki dönemde Selçuklu başkentlerinden biri oldu.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1054-01-01","k":"antlasma","tur":"antlasma","b":"Revvâdî Vehsûdân Tuğrul Bey'e itaat etti","gun":"446/1054 (gün bilinmiyor)","yer":"Azerbaycan","odak_yer":["Tebriz"],"kisiler":"Tuğrul Bey, Vehsûdân","d":"Azerbaycan'a gelen Selçuklu Sultanı Tuğrul Bey'e itaat arz eden mahallî hükümdarlar arasında Revvâdî Vehsûdân da vardı.","kaynak":"TDV: revvadiler (REVVÂDÎLER)","taraflar":["buyuk-selcuklu","revvadi"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1056-01-01","k":"hanedan","tur":"hanedan","b":"Arslan Han Süleyman kardeşi Muhammed'e esir düştü","gun":"448 h. (1056); gün bilinmiyor","odak_yer":["Kaşgar","Balasagun"],"kisiler":"Arslan Han Süleyman, Buğra Han Muhammed","d":"Büyük kağan Süleyman, kardeşi Muhammed'in topraklarına sefer düzenlerken esir düşüp hapsedildi. Muhammed kendini büyük kağan ilân etti.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["dogu-karahanli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1056-01-01","k":"hanedan","tur":"hanedan","b":"Şebânkâre emîri Fazlûye Fars'taki Büveyhî hâkimiyetine son verdi","gun":"1056 (gün bilinmiyor)","yer":"Şîraz","yer_id":"Şiraz","kisiler":"Fazlûye, Ebû Mansûr Fülâd Sütûn","d":"Şîraz'da Tuğrul Bey adına hutbe okutan son Büveyhî Fülâd Sütûn, Şebânkâre emîrlerinden Fazlûye'ye yenilip öldürüldü. Fars Şebânkâre emirinin eline geçti.","kaynak":"TDV: buveyhiler (BÜVEYHÎLER)","taraflar":["buveyhi"],"etiket":["toprak-kayip","yikilis","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1059-01-01","k":"antlasma","tur":"antlasma","b":"Çağrı Bey ile Gazneli İbrâhim arasında barış","gun":"451/1059 (gün bilinmiyor)","yer":"Horasan / Tohâristan","odak_yer":["Belh","Termez","Gazne"],"kisiler":"Çağrı Bey; Gazneli İbrâhim","d":"Uzun Gazneli mücadelesinde Belh, Tohâristan, Tirmiz ve çevresini ülkesine katan Çağrı Bey, Gazneli hükümdarı İbrâhim ile barış imzaladı. Taraflar ellerindeki yerleri koruyacak, birbirlerine saldırmayacaktı; doğu sınırı böylece belirlendi.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu","gazneli"],"etiket":["toprak-kazanc","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","odak_yer":["Balasagun"],"t":"1059-01-01","k":"hanedan","tur":"hanedan","b":"İbrâhim b. Muhammed öldürüldü, Tuğrul Karahan Mahmud büyük kağan oldu","gun":"451 h. (1059); gün bilinmiyor","yer":"Barsgan","kisiler":"İbrâhim b. Muhammed, Yinal Tegin, Tuğrul Karahan Mahmud","d":"Doğu Karahanlı kağanı İbrâhim b. Muhammed, Barsgan hâkimi Yinal Tegin'e yenilip öldürüldü. Bu karışıklıkta Batı Karahanlı Böri Tegin İbrâhim Fergana ve Şâş'ı aldı.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["dogu-karahanli","bati-karahanli"],"etiket":["hanedan-degisimi","toprak-kayip"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1060-01-01","k":"savas","tur":"savas","b":"Tuğrul Bey Tebriz kuşatmasında başarısız oldu","gun":"452/1060 (gün bilinmiyor)","yer":"Tebriz","yer_id":"Tebriz","kisiler":"Tuğrul Bey, Ebû Nasr Memlân","d":"1059'da Selçuklulara baş kaldıran Vehsûdân'ın oğlu Ebû Nasr Memlân'a karşı Tuğrul Bey Tebriz'i kuşattı, fakat şehri alamadı.","kaynak":"TDV: revvadiler (REVVÂDÎLER)","taraflar":["buyuk-selcuklu","revvadi"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1062-01-01","k":"fetih","tur":"fetih","b":"Şîraz Kavurd Bey'e teslim edildi","gun":"454/1062 (gün bilinmiyor)","yer":"Şîraz","yer_id":"Şiraz","kisiler":"Kavurd Bey","d":"Kirman'da tutunan Kavurd Bey'e Şîraz ve çevresi Türk askerleri ve Deylemliler tarafından teslim edildi. Kavurd Bey Şebânkâre emîri Fazlûye'yi yenerek Fars'taki durumunu sağlamlaştırdı ve hutbeyi amcası Tuğrul Bey adına okuttu.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["kirman-selcuklu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","odak_yer":["Nîşâbur"],"t":"1063-09-04","k":"hanedan","tur":"hanedan","b":"Tuğrul Bey öldü; Alparslan tahtı ele geçirdi","gun":"4 Eylül 1063","yer":"Rey","kisiler":"Tuğrul Bey; Alparslan; Kutalmış; Süleyman","d":"Çocuğu olmayan Tuğrul Bey Rey'de öldü. Vezir Kündürî'nin tahta çıkardığı Süleyman'ı ve saltanat iddia eden Kutalmış'ı saf dışı bırakan Alparslan, babası Çağrı Bey'in ve amcasının topraklarını birleştirerek Ceyhun'dan Dicle'ye uzanan ülkenin tek hükümdarı oldu.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1066-01-01","k":"hanedan","tur":"hanedan","b":"Gazneli İbrâhim Emîr Muhammed'i Gur'un başına getirdi","gun":"458 h. (1066); gün bilinmiyor","yer":"Gur","odak_yer":["Herat","Kâbil"],"kisiler":"Sultan İbrâhim, Abbas, Emîr Muhammed","d":"Haracı göndermeyen Gur reisi Abbas'a karşı sefere çıkan Gazneli Sultan İbrâhim, Abbas'ın oğlu Emîr Muhammed'i Gurlular'ın idaresine getirdi. Emîr Muhammed Gazne sarayına bağlı kaldı.","kaynak":"TDV: gurlular (GURLULAR)","taraflar":["gazneli","gurlu"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1067-01-01","yer_id":"Kirman","k":"savas","tur":"savas","b":"Alparslan Kirman'a yürüdü; Kavurd Bey itaat etti","gun":"459/1067 (gün bilinmiyor)","yer":"Kirman / Cîruft","odak_yer":["Kirman","Cîruft"],"kisiler":"Sultan Alparslan; Kavurd Bey","d":"Saltanat iddiasına kalkışan Kavurd Bey'in üzerine Alparslan Kirman'a yürüdü. Öncü kuvvetinin yenildiğini gören Kavurd Cîruft'a kaçıp af diledi; Alparslan onu bağışlayıp ülkesini geri verdi.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["kirman-selcuklu","buyuk-selcuklu"],"etiket":["konu-askeri","konu-siyasi"]},{"onem":5,"dunya":4,"bolge_onem":5,"puan_s":"v2","odak_yer":["Karabiga"],"t":"1071-08-26","k":"savas","tur":"savas","b":"Malazgirt Savaşı","gun":"26 Ağustos 1071","yer":"Malazgirt","kisiler":"Sultan Alparslan; İmparator Romanos Diogenes","d":"Mısır seferine giden Alparslan, Romanos Diogenes'in büyük bir orduyla yürüdüğünü öğrenince geri döndü ve Malazgirt ovasında Bizans ordusunu ağır bir yenilgiye uğrattı. Zafer Anadolu'nun Türkler tarafından fethinin yolunu açtı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu","bizans"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1072-01-01","k":"fetih","tur":"fetih","b":"II. Nasr Alparslan'ın ölümü üzerine Tirmiz ve Belh'i aldı","gun":"Rebîülâhir 465 / Aralık 1072 (gün bilinmiyor)","yer":"Tirmiz","yer_id":"Termez","kisiler":"Şemsülmülk II. Nasr b. İbrâhim","d":"Alparslan'ın Mâverâünnehir seferinde ölmesi üzerine Batı Karahanlı II. Nasr Selçuklular'dan Tirmiz'i, ardından Belh'i aldı.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["bati-karahanli","buyuk-selcuklu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1072-11-24","k":"hanedan","tur":"hanedan","b":"Alparslan öldürüldü; Melikşah tahta geçti","gun":"24 Kasım 1072","yer":"Ceyhun kıyısı","odak_yer":["Termez","Buhara"],"kisiler":"Sultan Alparslan; Melikşah","d":"Mâverâünnehir seferindeki Alparslan Ceyhun kıyısında bir suikaste kurban gitti. Yerine veliaht tayin ettiği oğlu Melikşah geçti; genç sultanın tahta çıkışını fırsat bilen Karahanlılar ve Gazneliler Selçuklu topraklarına saldırdı, Kavurd Bey ise saltanat iddiasıyla ayaklandı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1073-01-01","k":"savas","tur":"savas","b":"Kavurd Bey Melikşah'a yenilip öldürüldü","gun":"Şâban 465 / Nisan 1073 (gün bilinmiyor)","yer":"Hemedan yöresi","yer_id":"Hemedan","kisiler":"Kavurd Bey; Sultan Melikşah; Nizâmülmülk","d":"Alparslan'ın ölümü üzerine saltanat iddiasıyla Hemedan'a yürüyen Kavurd Bey, Türkmen boylarını kendi tarafına çeken Melikşah ve Nizâmülmülk karşısında yenildi, Hemedan dağlarında yakalanıp öldürüldü. Kirman'da yerine oğlu Kirmanşah geçti.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["kirman-selcuklu","buyuk-selcuklu"],"etiket":["hanedan-degisimi","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1074-01-01","yer_id":"Semerkant","k":"antlasma","tur":"antlasma","b":"Melikşah ile barış: Mâverâünnehir'de Selçuklu hâkimiyeti tanındı","gun":"466 h. (1074); gün bilinmiyor","yer":"Semerkant","odak_yer":["Semerkant"],"kisiler":"Melikşah, II. Nasr, Nizâmülmülk","d":"Tirmiz'i geri alıp Semerkant'a yürüyen Melikşah karşısında II. Nasr barış istedi. Nizâmülmülk'ün aracılığıyla yapılan barışla Batı Karahanlılar Selçuklu hâkimiyetini tanıdı; iki hânedan evliliklerle bağlandı.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["bati-karahanli","buyuk-selcuklu"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1078-01-01","k":"savas","tur":"savas","b":"Kıpçaklar Peçeneklerle birlikte Edirne'yi kuşattı","gun":"1078 (gün/ay bilinmiyor)","yer":"Edirne","yer_id":"Edirne","d":"Bizans'a isyan eden Peçeneklerle birleşen Kıpçaklar Edirne'yi muhasara ettiler. Bu tarihten sonra 1083-1096 ve 1109-1114 yıllarında Bizans topraklarına akınlar düzenlediler.","kaynak":"TDV: kipcaklar (KIPÇAKLAR)","taraflar":["kipcak","bizans"],"etiket":["konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1079-01-01","k":"olay","tur":"siyasi","b":"Melikşah'ın Kirman seferi; Sultan Şah itaat etti","gun":"472 başı / Temmuz 1079 (gün bilinmiyor)","yer":"Berdesîr","odak_yer":["Kirman"],"kisiler":"Sultan Melikşah; Sultan Şah","d":"Melikşah'ın Kirman üzerine yürüdüğünü öğrenen Kirman meliki Sultan Şah, Berdesîr'den çıkıp sultanı karşıladı ve itaatini bildirdi. Memnun kalan Melikşah onu kızıyla evlendirip Kirman'dan ayrıldı; Kirman kolu Büyük Selçuklu tâbiliğinde yaşamaya devam etti.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["kirman-selcuklu","buyuk-selcuklu"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","odak_yer":["Alamut"],"t":"1091-01-01","k":"savas","tur":"savas","b":"Melikşah'ın Alamut kuşatması sonuçsuz kaldı","gun":"484/1091 (gün bilinmiyor)","yer":"Alamut","kisiler":"Sultan Melikşah, Yoruntaş, Hasan Sabbâh","d":"Melikşah'ın emriyle Alamut'u kuşatan Yoruntaş'ın ölümü harekâtı sonuçsuz bıraktı. Ardından Nizâmülmülk'ün bir fidâîce öldürülmesi ve Melikşah'ın ölümü (1092) yeni seferi de durdurdu.","kaynak":"TDV: hasan-sabbah (HASAN SABBÂH)","taraflar":["buyuk-selcuklu","alamut-nizari"],"etiket":["konu-askeri"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1091-01-01","k":"savas","tur":"savas","b":"Kıpçaklar Macaristan'a, ertesi yıl Lehistan'a girdi","gun":"1091 (gün/ay bilinmiyor)","yer":"Macaristan","odak_yer":["Aquincum-Óbuda-Pest"],"d":"Batıya yayılan Kıpçaklar 1091'de Macaristan'a, 1092'de Lehistan'a akın ettiler; 1093'te Bizans topraklarında göründüler.","kaynak":"TDV: kipcaklar (KIPÇAKLAR)","taraflar":["kipcak","macaristan"],"etiket":["konu-askeri"]},{"onem":5,"dunya":3,"bolge_onem":5,"puan_s":"v2","t":"1092-11-19","k":"hanedan","tur":"hanedan","b":"Melikşah öldü; taht kavgaları başladı","gun":"19 Kasım 1092","yer":"Bağdat","yer_id":"Bağdat","kisiler":"Sultan Melikşah; Berkyaruk; Terken Hatun; Mahmud","d":"Vezir Nizâmülmülk'ün Bâtınîler tarafından öldürülmesinden yaklaşık bir ay sonra Melikşah Bağdat'ta öldü. Onun döneminde ülke Kâşgar'dan Ege adalarına, Kafkasya'dan Yemen'e uzanmıştı. Ölümünün ardından Berkyaruk ile Terken Hatun'un oğlu Mahmud arasında saltanat mücadelesi başladı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","odak_yer":["Alamut (Alamut Kalesi, Kazvin vilayeti)"],"t":"1094-01-01","k":"olay","tur":"siyasi","b":"Nizârî-Müsta'lî ayrılığı: Hasan Sabbâh Fâtımîlerle ilişkiyi kesti","gun":"487/1094 (gün bilinmiyor)","yer":"Alamut","kisiler":"Hasan Sabbâh, Müsta'lî-Billâh, Nizâr","d":"Fâtımî Halifesi Müstansır'ın ölümüyle tahta Müsta'lî geçirilince Hasan Sabbâh isyan edip Nizâr adına hutbe okuttu. Doğu İsmâilîleri Nizârî adıyla Kahire'den koptu.","kaynak":"TDV: hasan-sabbah (HASAN SABBÂH)","taraflar":["alamut-nizari"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","odak_yer":["Nîşâbur"],"t":"1095-02-26","k":"savas","tur":"savas","b":"Tutuş Berkyaruk'a yenilip öldü; Suriye Selçukluları ikiye bölündü","gun":"26 Şubat 1095","yer":"Rey yakını","kisiler":"Tutuş; Berkyaruk; Rıdvân; Dukak","d":"Melikşah'ın ölümünden sonra Musul, Halep ve Diyarbekir'i ele geçiren Tutuş, Büyük Selçuklu tahtı için Berkyaruk'la savaştı; askerlerinin bir kısmı karşı tarafa geçince yenildi ve öldü. Ülkesi oğulları arasında paylaşıldı: Rıdvân Halep'te, Dukak Dımaşk'ta hüküm sürmeye başladı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu"],"etiket":["hanedan-degisimi","toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1095-06-25","k":"hanedan","tur":"hanedan","b":"Ahmed b. Hızır zındıklık suçlamasıyla idam edildi","gun":"18 Cemâziyelâhir 488 / 25 Haziran 1095","yer":"Semerkant","yer_id":"Semerkant","kisiler":"Ahmed Han b. Hızır, I. Mesud b. Muhammed","d":"Melikşah'ın tâbi olarak tahtına iade ettiği Ahmed Han, ulemânın İsmâilîlik ithamıyla yargılanıp idam edildi. Yerine amcazadesi Kılıç Tamgaç Han I. Mesud getirildi.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["bati-karahanli"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1097-08-28","k":"olay","tur":"siyasi","b":"Rıdvân Halep'te Fâtımî halifesi adına hutbe okuttu","gun":"28 Ağustos 1097","yer":"Halep","yer_id":"Halep","kisiler":"Melik Rıdvân","d":"Fâtımîlerin desteğini sağlamak isteyen Halep meliki Rıdvân, hutbeyi Fâtımî halifesi adına okuttu; bir Selçuklu melikinin Fâtımî halifesini metbû tanıdığı ilk durumdu. Sünnî dünyanın tepkisi üzerine dört hafta sonra, 22 Eylül 1097'de, hutbe yeniden Abbâsî halifesi ve Selçuklu sultanı adına okunmaya başladı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["suriye-selcuklu"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Şehrizor"],"t":"1101-01-01","k":"savas","tur":"savas","b":"Salgurlu Türkmenleri Annâzî ülkesini Dakūkā ve Şehrizor dışında ele geçirdi","gun":"495/1101-1102 (gün bilinmiyor)","yer":"Huftîzgān","kisiler":"Sürhâb b. Bedr, Karabuli","d":"Huftîzgān Kalesi'ni alan Sürhâb b. Bedr, Salgurlu Türkmenlerinden Karabuli'ye yenilip dağa kaçtı; Türkmenler Dakūkā ve Şehrizor dışında bütün ülkesini ele geçirdi.","kaynak":"TDV: annaziler (ANNÂZÎLER)","taraflar":["annazi"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1102-05-22","k":"hanedan","tur":"hanedan","b":"Sencer Hârun Tegin'i idam edip Arslan Han Muhammed'i Semerkant'a atadı","gun":"2 Şâban 495 / 22 Mayıs 1102","yer":"Tirmiz-Semerkant","odak_yer":["Termez","Semerkant"],"kisiler":"Sultan Sencer, Hârun Tegin, Arslan Han II. Muhammed","d":"Mâverâünnehir'i istilâ edip Tirmiz'i alan Hârun Tegin, Sencer'e esir düşüp idam edildi. Sencer yeğeni ve damadı II. Muhammed'i Arslan Han unvanıyla Batı Karahanlı tahtına oturttu; sikkelerde Sencer'in adı metbû olarak geçti.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["buyuk-selcuklu","bati-karahanli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1104-01-01","k":"hanedan","tur":"hanedan","b":"Berkyaruk öldü; Muhammed Tapar ülkeyi yeniden birleştirdi","gun":"Rebîülâhir 498 / Aralık 1104 (gün bilinmiyor)","yer":"İsfahan","yer_id":"Isfahan","kisiler":"Berkyaruk; Muhammed Tapar","d":"On iki yıl süren taht mücadelesi Haçlıların ilerlemesine ve Bâtınîlerin güçlenmesine yol açmıştı. Berkyaruk'un ölümünden sonra onun küçük oğlu Melikşah'ı bertaraf eden Muhammed Tapar, bölünmüş Selçuklu ülkesini yeniden tek elde topladı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1104-06-06","k":"yikilis","tur":"yikilis","b":"Dımaşk Selçuklu melikliği sona erdi; Börîler dönemi başladı","gun":"Safer 498 / Ekim-Kasım 1104 (gün bilinmiyor)","yer":"Dımaşk","yer_id":"Şam","kisiler":"Atabeg Tuğtegin; Ertaş (Bektaş); II. Tutuş","d":"Dukak'ın 6 Haziran 1104'te ölümünden sonra atabeg Tuğtegin önce küçük II. Tutuş'u, sonra Ertaş'ı tahta oturttu. Tuğtegin'den korkan Ertaş'ın şehirden kaçmasıyla Dımaşk Selçuklu melikliği bitti; şehirde Börîler (Dımaşk Atabegleri) hüküm sürmeye başladı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["suriye-selcuklu"],"etiket":["toprak-kayip","hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1117-01-01","k":"olay","tur":"siyasi","b":"Muhammed Tapar Gaznelileri tâbi kıldı","gun":"511/1117 (gün bilinmiyor)","yer":"Gazne","yer_id":"Gazne","kisiler":"Muhammed Tapar; Behram Şah","d":"Gazneli hânedanındaki taht kavgalarına müdahale eden Muhammed Tapar, Behram Şah'ın sultan ilân edilmesini sağladı. Böylece Gazneli Devleti Büyük Selçuklulara tâbi oldu.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu","gazneli"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1117-01-01","k":"hanedan","tur":"hanedan","b":"Behram Şah Sencer'in desteğiyle Gazne tahtına çıktı","gun":"511 h. (1117); gün bilinmiyor","yer":"Gazne","yer_id":"Gazne","kisiler":"Behram Şah, Arslanşah, Sencer","d":"III. Mesud'un ölümünden sonraki taht kavgasında Behram Şah, Horasan meliki Sencer'in yardımıyla kardeşi Arslanşah'ı devirip tahta geçti. Gazneliler bundan sonra Selçuklular'a vergi veren tâbi konumuna düştü.","kaynak":"TDV: gazneliler (GAZNELİLER)","taraflar":["gazneli","buyuk-selcuklu"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Alamut"],"t":"1117-07-13","k":"savas","tur":"savas","b":"Sultan Muhammed Tapar'ın büyük Alamut kuşatması","gun":"11 Rebîülevvel 511 / 13 Temmuz 1117","yer":"Alamut","kisiler":"Muhammed Tapar, Anuş Tegin Şîrgîr, Hasan Sabbâh","d":"Anuş Tegin Şîrgîr komutasındaki Selçuklu ordusu Alamut'u Nisan 1118'e kadar kuşatıp Nizârîleri açlığa düşürdü. Kale düşmek üzereyken Sultan Muhammed Tapar'ın ölüm haberi geldi ve kuşatma kaldırıldı.","kaynak":"TDV: hasan-sabbah (HASAN SABBÂH)","taraflar":["buyuk-selcuklu","alamut-nizari"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1118-01-01","k":"olay","tur":"askeri","b":"Gürcü kralı Kıpçaklardan 40.000 kişilik atlı ordu kurdu","gun":"1118 (gün/ay bilinmiyor)","yer":"Gürcistan","odak_yer":["Tiflis"],"kisiler":"Kral II. David, Başbuğ Atrak","d":"Başbuğ Atrak'ın kızının II. David ile evlenmesinden sonra Kıpçaklar Gürcistan'a geldi; kral Çoruh ve Kür dolaylarına yerleşen Kıpçaklardan büyük bir atlı ordu kurdu. Atrak 1125'te yurduna döndü, Kıpçakların çoğu Gürcistan'da kaldı.","kaynak":"TDV: kipcaklar (KIPÇAKLAR)","taraflar":["kipcak","gurcistan"],"etiket":["konu-askeri","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1119-09-10","k":"savas","tur":"savas","b":"Sâve Savaşı: Sencer yeğeni Mahmud'u yendi","gun":"10 Eylül 1119","yer":"Sâve","yer_id":"Sâve","kisiler":"Sultan Sencer; Sultan Mahmud","d":"Muhammed Tapar'ın ölümünden sonra oğlu Mahmud'un sultanlığını tanımayan Horasan meliki Sencer, Sâve'de onu yendi. Sencer Mahmud'u kendine tâbi kıldı; Mâzenderan, Taberistan, Kūmis, Damgan ve Rey bölgelerini kendi ülkesine kattı, Kasım 1119 antlaşmasıyla Irak Selçuklu kolu tâbi melikliğe dönüştü.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu","irak-selcuklu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","t":"1120-01-01","yer_id":"Merâga","k":"olay","tur":"siyasi","b":"Aksungur el-Ahmedîlî Merâga'ya gönderildi","gun":"1120 (gün bilinmiyor)","yer":"Merâga","odak_yer":["Merâga"],"kisiler":"Aksungur el-Ahmedîlî, Sultan Mahmud","d":"Sultan Mahmud, kardeşi Mesud'un atabegi Porsukī'nin Merâga'ya atandığını duyunca Bağdat'taki Aksungur el-Ahmedîlî'yi derhal Merâga'ya gönderdi.","kaynak":"TDV: ahmedililer (AHMEDÎLÎLER)","taraflar":["irak-selcuklu","ahmedili"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1121-01-01","k":"savas","tur":"savas","b":"Gürcüler Selçuklu ordusunu yenip Tiflis'i aldı","gun":"515/1121 (gün bilinmiyor)","yer":"Tiflis","yer_id":"Tiflis","kisiler":"Arrân Meliki Tuğrul; Atabeg Gündoğdu; Artuklu İlgazi","d":"Sultan Mahmud'un zayıflığından yararlanan Gürcüler Kıpçaklarla ittifak ederek İslâm topraklarına akınlara başladı. Arrân meliki Tuğrul, Artuklu İlgazi ve Dübeys b. Sadaka'nın bulunduğu Türk ordusunu yenip Tiflis'i ele geçirdiler.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["irak-selcuklu","artuklu"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1128-01-01","k":"savas","tur":"savas","b":"Doğu Karahanlı Arslan Han Ahmed ilk Karahıtay akınını yendi","gun":"1128 (gün bilinmiyor)","yer":"Balasagun-Kâşgar","odak_yer":["Balasagun","Kaşgar"],"kisiler":"Arslan Han Ahmed b. Hasan, Yeh-lü Ta-şi","d":"Yeh-lü Ta-şi komutasındaki Karahıtay ordusu Balasagun, Hoten ve Kâşgar bölgesine ilk girdiğinde Doğu Karahanlı hükümdarı Ahmed tarafından yenildi.","kaynak":"TDV: karahitaylar (KARAHITAYLAR)","taraflar":["dogu-karahanli"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1130-01-01","k":"savas","tur":"savas","b":"Sencer Semerkant'ı alıp Arslan Han Muhammed'i esir etti","gun":"524 h. (1130); gün bilinmiyor","yer":"Semerkant","yer_id":"Semerkant","kisiler":"Sultan Sencer, Arslan Han II. Muhammed, II. Ahmed","d":"Arslan Han Muhammed ve oğlu II. Ahmed ile ihtilâfa düşen Sencer Semerkant'ı zaptedip yönetime el koydu; Muhammed Merv'de esir olarak öldü.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["buyuk-selcuklu","bati-karahanli"],"etiket":["konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Dînever"],"t":"1132-01-01","k":"savas","tur":"savas","b":"Dînever Savaşı'na Bâvendî kuvvetleri de katıldı","gun":"1132 (gün bilinmiyor)","yer":"Dînever","kisiler":"Sultan Sencer, Mesud, II. Tuğrul, Alâüddevle Ali","d":"Sencer'in II. Tuğrul'u Irak Selçuklu tahtına çıkarmak için Mesud'la yaptığı Dînever Savaşı'nda Bâvendî Alâüddevle Ali'nin kuvvetleri de yer aldı.","kaynak":"TDV: bavendiler (BÂVENDÎLER)","taraflar":["buyuk-selcuklu","irak-selcuklu","bavendi"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1132-01-01","k":"savas","tur":"savas","b":"Aksungur Hemedan önünde yenildi; Tuğrul Merâga ve Tebriz'i aldı","gun":"1132 (gün bilinmiyor)","yer":"Hemedan, Merâga, Tebriz","yer_id":"Hemedan","odak_yer":["Hemedan","Merâga","Tebriz"],"kisiler":"Aksungur el-Ahmedîlî, Sultan Dâvud, II. Tuğrul (Selçuklu)","d":"Şehzade Dâvud'la Azerbaycan'a hâkim olan Aksungur Hemedan'daki Tuğrul'a yürüdü, ancak yenildi. Tuğrul Merâga ve Tebriz'i ele geçirdi; Aksungur Dâvud ile Bağdat'a kaçtı.","kaynak":"TDV: ahmedililer (AHMEDÎLÎLER)","taraflar":["irak-selcuklu","ahmedili"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","odak_yer":["Dînever"],"t":"1132-05-25","k":"savas","tur":"savas","b":"Dînever Savaşı: Sencer yeğenlerini yendi, Tuğrul'u tahta çıkardı","gun":"25 Mayıs 1132","yer":"Dînever","kisiler":"Sultan Sencer; Mesud; Selçuk Şah; I. Tuğrul","d":"Mahmud'un ölümünden sonra halife ile ittifak kuran Mesud ve Selçuk Şah, amcaları Sencer'e karşı çıktı. Sencer onları Dînever yakınında bozguna uğrattı; Mesud'a Arrân'ı verip kardeşi Tuğrul'u Irak Selçuklu tahtına geçirdi ve Horasan'a döndü.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["buyuk-selcuklu","irak-selcuklu"],"etiket":["hanedan-degisimi","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Merâga"],"t":"1133-01-01","k":"hanedan","tur":"hanedan","b":"Aksungur el-Ahmedîlî Bâtınîlerce öldürüldü","gun":"527/1133 (gün bilinmiyor)","yer":"Karategin çayırı","kisiler":"Aksungur el-Ahmedîlî, Arslanapa","d":"Tuğrul'u yenip Hemedan'ı alan Aksungur kısa süre sonra Bâtınî fedaileri tarafından öldürüldü. Yerine oğlu Arslanapa (II. Aksungur) geçti.","kaynak":"TDV: ahmedililer (AHMEDÎLÎLER)","taraflar":["ahmedili","alamut-nizari"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1134-01-01","k":"hanedan","tur":"hanedan","b":"Mesud Irak Selçuklu tahtına geçti","gun":"Muharrem 529 / Kasım 1134 (gün bilinmiyor)","yer":"Hemedan","yer_id":"Hemedan","kisiler":"Sultan Mesud; I. Tuğrul","d":"Mücadeleyi sürdüren Mesud, kardeşi Tuğrul'un ölümü üzerine Irak Selçuklu tahtına geçti. Ardından kendisine karşı yürüyen Halife Müsterşid'i esir aldı; halife kısa süre sonra Bâtınîlerce öldürüldü.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["irak-selcuklu"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1137-01-01","k":"savas","tur":"savas","b":"Hucend yenilgisi: Karahıtaylar Batı Karahanlı II. Mahmud'u yendi","gun":"Ramazan 531 / Haziran 1137 (gün bilinmiyor)","yer":"Hucend","yer_id":"Hucend","kisiler":"II. Mahmud Han, Yeh-lü Ta-şi","d":"Sencer'in tayin ettiği Batı Karahanlı hükümdarı II. Mahmud, Hucend yakınında Karahıtaylar'a yenilerek Semerkant'a kaçtı. Mâverâünnehir halkını büyük endişeye düşüren yenilgi Katvân'ın habercisi oldu.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["karahitay","bati-karahanli"],"etiket":["konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":5,"puan_s":"v2","t":"1141-09-09","k":"savas","tur":"savas","b":"Katvân Savaşı","gun":"5 Safer 536 / 9 Eylül 1141","yer":"Katvân sahrası (Semerkant yakını)","odak_yer":["Semerkant"],"kisiler":"Yeh-lü Ta-şi (Gürhan), Sultan Sencer, II. Mahmud Han","d":"Karluklar'ı koruyan Gürhan Yeh-lü Ta-şi, Semerkant yakınındaki Katvân sahrasında Sencer ve Batı Karahanlı II. Mahmud'u ağır bir yenilgiye uğrattı. Sencer 30.000 kayıp verip Tirmiz'e kaçtı; Ceyhun'a kadar bütün Mâverâünnehir Karahıtaylar'a geçti, Hârizm yıllık 30.000 dinar vergiye bağlandı.","kaynak":"TDV: karahitaylar (KARAHITAYLAR)","taraflar":["karahitay","buyuk-selcuklu","bati-karahanli"],"etiket":["toprak-kazanc","toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1142-01-01","k":"hanedan","tur":"hanedan","b":"Muhammed Şah babası I. Arslanşah'ı hapsederek tahta geçti","gun":"Safer 537 / Eylül 1142 (gün bilinmiyor)","yer":"Berdesîr","yer_id":"Kirman","kisiler":"I. Arslanşah; I. Muhammed Şah","d":"Kırk iki yıl Kirman'ı yöneten, Fars'ı zapteden ve Yezd'i ülkesine katan I. Arslanşah, oğlu Muhammed tarafından hapsedildi. Muhammed Şah tahta geçti.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["kirman-selcuklu"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1150-01-01","k":"savas","tur":"savas","b":"Gurlular Gazne'yi yaktı","gun":"545 h. (1150-51); gün bilinmiyor","yer":"Gazne","yer_id":"Gazne","kisiler":"Alâeddin Hüseyin Cihânsûz, Behram Şah","d":"Kardeşlerinin öldürülmesinin intikamını almak için Gazne'ye yürüyen Gurlu Alâeddin Hüseyin, Behram Şah'ı Sîstan'a kaçırdı ve şehri yedi gün yakıp yıktı; 'Cihânsûz' lakabı buradan gelir. Behram Şah 1152'de Gazne'ye döndüyse de Gazneliler çöküşe girdi.","kaynak":"TDV: gazneliler (GAZNELİLER)","taraflar":["gurlu","gazneli"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1152-01-01","k":"savas","tur":"savas","b":"Sencer Gurlu Alâeddin Hüseyin'i yenip esir aldı","gun":"547 h. (1152); gün bilinmiyor","odak_yer":["Herat"],"kisiler":"Sultan Sencer, Alâeddin Hüseyin Cihânsûz","d":"Vergiyi kesip bağımsızlık ilân eden Alâeddin Hüseyin'e karşı Sencer sefere çıktı. Gurlu ordusundaki Türk askerlerinin Sencer'e geçmesiyle Gurlular yenildi; esir alınan Alâeddin affedilip Selçuklu tâbii olarak Gur'a gönderildi.","kaynak":"TDV: sencer (SENCER)","taraflar":["buyuk-selcuklu","gurlu"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1152-10-02","k":"hanedan","tur":"hanedan","b":"Sultan Mesud öldü","gun":"2 Ekim 1152","yer":"Hemedan","yer_id":"Hemedan","kisiler":"Sultan Mesud; III. Melikşah","d":"Emîrleri tahakkümden kurtardıktan sonra güçlü bir hükümdar olarak saltanat süren Mesud öldü. İbnü'l-Esîr onu son büyük Selçuklu hükümdarı sayar; ardından tahta çıkarılan sultanlar kabiliyetsiz kaldı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["irak-selcuklu"],"etiket":["hanedan-degisimi"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1153-01-01","k":"savas","tur":"savas","b":"Sencer Oğuzlara yenilip esir düştü","gun":"Muharrem 548 / Nisan 1153 (gün bilinmiyor)","yer":"Belh yöresi","yer_id":"Belh","kisiler":"Sultan Sencer; Emîr Kamaç; Müeyyed Ay-aba","d":"Belh valisinin tahsildarının öldürülmesiyle başlayan anlaşmazlıkta Oğuzları cezalandırmak isteyen Sencer savaşı kaybetti ve esir düştü. Oğuzlar onu Merv'e götürüp şeklen hükümdar tanımaya devam ettiler; Sencer ancak Nisan 1156'da kurtarılabildi.","kaynak":"TDV: sencer (SENCER)","taraflar":["buyuk-selcuklu"],"etiket":["konu-askeri","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1157-01-01","k":"savas","tur":"savas","b":"Şah Gazi Rüstem Alamut'u tahrip etti, Cürcân ve Kūmis'i aldı","gun":"1157 (gün bilinmiyor)","yer":"Alamut, Cürcân, Kūmis","odak_yer":["Kazvin","Esterâbâd","Dâmgan"],"kisiler":"Şah Gazi Rüstem","d":"Büyük Selçuklu'nun çözülmesiyle bağımsız siyaset izleyen Bâvendî Şah Gazi Rüstem, Alamut İsmâilîlerine sefer düzenleyip kaleyi tahrip etti; Cürcân ve Kūmis'i ele geçirdi. Alamut kalesi ise düşmedi.","kaynak":"TDV: bavendiler (BÂVENDÎLER)","taraflar":["bavendi","alamut-nizari"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1158-01-01","k":"hanedan","tur":"hanedan","b":"II. İbrâhim Karluk isyanında öldü","gun":"553 h. (1158); gün bilinmiyor","yer":"Mâverâünnehir","odak_yer":["Semerkant","Buhara"],"kisiler":"II. İbrâhim b. Ahmed","d":"Karahıtay Gürhanı'nın İlig-i Türkmen unvanı verdiği Kâşgar hükümdarı II. İbrâhim, isyan eden Karluk Türkmenleri'ne karşı Mâverâünnehir'e gönderildi ve muhtemelen orada öldü.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["dogu-karahanli","karahitay"],"etiket":["hanedan-degisimi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1158-01-01","k":"hanedan","tur":"hanedan","b":"Bâdüsbânî Şehrîveş öldü, Keykâvus geçti; Bâvendîlerle savaş başladı","gun":"553/1158 (gün bilinmiyor)","yer":"Rûyân","odak_yer":["Âmül"],"kisiler":"Şehrîveş b. Hezâresb, Keykâvus, Şah Gazi Rüstem","d":"Şehrîveş'in ölümüyle kardeşi Keykâvus Rûyân'ın başına geçti. Keykâvus ile Bâvendî Şah Gazi Rüstem arasında şiddetli savaşlar çıktı.","kaynak":"TDV: badusbaniler (BÂDÜSBÂNÎLER)","taraflar":["badusbani","bavendi"],"etiket":["hanedan-degisimi","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1161-01-01","k":"hanedan","tur":"hanedan","b":"Arslanşah tahta çıktı; İldeniz atabegliği başladı","gun":"556/1161 (gün bilinmiyor)","yer":"Hemedan","yer_id":"Hemedan","kisiler":"Arslanşah; Şemseddin İldeniz","d":"Kabiliyetsiz Süleyman Şah yerine emîrler, Arrân ve Azerbaycan'da bulunan İldeniz'in yanındaki Arslanşah'ı tahta çıkardı. İldeniz onun atabegi oldu; böylece Irak Selçuklularında fiilî gücün atabeglere geçtiği dönem başladı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["irak-selcuklu"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1161-01-01","k":"savas","tur":"savas","b":"Ahmedîlî Arslanapa Sefîdrûd'da İldenizli Pehlivan'ı bozguna uğrattı","gun":"1161 (gün bilinmiyor)","yer":"Sefîdrûd (Kızılözen)","odak_yer":["Zencan"],"kisiler":"Arslanapa, Pehlivan, İldeniz","d":"İldeniz'in Sultan Arslanşah'a itaat talebini reddeden Merâga hâkimi Arslanapa, Ahlatşahların desteğiyle İldeniz'in oğlu Pehlivan'ı Sefîdrûd'da ağır bir yenilgiye uğrattı.","kaynak":"TDV: ahmedililer (AHMEDÎLÎLER)","taraflar":["ahmedili","ildenizli"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1164-01-01","k":"hanedan","tur":"hanedan","b":"II. Mahmud'un ölümüyle İbrâhim soyu sona erdi, iktidar Ali Tegin ailesine geçti","gun":"559 h. (1164); gün bilinmiyor","yer":"Horasan","odak_yer":["Semerkant"],"kisiler":"II. Mahmud Han, Müeyyed Ay-aba","d":"Sencer'den sonra Horasan'da Oğuzlar'ın başına geçen II. Mahmud ile oğlu Muhammed, Müeyyed Ay-aba'nın esiri olarak hapiste öldü. Batı Karahanlı tahtı Semerkant'ta Ali Tegin (Hasanî) kolunda devam etti.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["bati-karahanli"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Alamut (Alamut Kalesi, Kazvin vilayeti)"],"t":"1164-08-08","k":"olay","tur":"din","b":"Hasan Alâ Zikrihisselâm 'kıyamet'i ilân etti","gun":"17 Ramazan 559 / 8 Ağustos 1164","yer":"Alamut","kisiler":"Hasan Alâ Zikrihisselâm","d":"Dördüncü Alamut hâkimi Hasan, Nizâr soyundan imam olduğunu ve kıyamet devrinin başladığını ilân ederek şer'î yükümlülükleri kaldırdı. 1166'da öldürüldü.","kaynak":"TDV: nizariyye (NİZÂRİYYE)","taraflar":["alamut-nizari"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1168-01-01","k":"savas","tur":"savas","b":"Pehlivan Arslanapa'yı Merâga'da kuşatıp Selçuklu tâbiiyetine aldı","gun":"563/1167-68 (gün bilinmiyor)","yer":"Merâga","yer_id":"Merâga","kisiler":"Pehlivan, Arslanapa","d":"Halifenin Arslanapa'nın yanındaki şehzade Dâvud adına hutbe okutması üzerine İldeniz, Pehlivan'ı büyük bir orduyla gönderdi; yenilen Arslanapa Merâga'ya kaçtı, kuşatma anlaşmayla bitti.","kaynak":"TDV: ildenizliler (İLDENİZLİLER)","taraflar":["ildenizli","ahmedili"],"etiket":["konu-askeri","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1169-01-01","k":"fetih","tur":"fetih","b":"Zengî Fars'ı Afşar Şümle'den geri aldı","gun":"564/1169 (gün bilinmiyor)","yer":"Fars","odak_yer":["Şiraz"],"kisiler":"Muzafferüddin Zengî, Şümle","d":"Zengî'nin kötü yönetiminden bıkan halkın davetiyle Fars'a giren Hûzistan hâkimi Afşar Şümle de halka zulmedince Zengî Fars'ı yeniden ele geçirdi.","kaynak":"TDV: salgurlular (SALGURLULAR)","taraflar":["salgurlu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1170-01-01","k":"hanedan","tur":"hanedan","b":"Tuğrul Şah öldü; oğulları arasında yedi yıllık taht kavgası","gun":"565/1170 (gün bilinmiyor)","yer":"Kirman","yer_id":"Kirman","kisiler":"Tuğrul Şah; Behram Şah; II. Arslanşah; Türkân Şah; II. Turan Şah","d":"Tuğrul Şah'ın ölümüyle dört oğlu arasında yedi yıl süren saltanat mücadelesi başladı. Kirman harap oldu ve Kirman Selçuklularının fetret devri açıldı.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["kirman-selcuklu"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1173-01-01","k":"hanedan","tur":"hanedan","b":"Tekiş Karahıtay yardımıyla Hârizm tahtına çıktı","gun":"568 h. (1173); gün bilinmiyor","yer":"Gürgenç","yer_id":"Köhne Ürgenç (Gürgenç)","kisiler":"Alâeddin Tekiş, Sultan Şah, Fu-ma","d":"İlarslan'ın ölümüyle başlayan taht kavgasında Tekiş, vergileri fazlasıyla ödeme vaadiyle Karahıtaylar'dan yardım istedi. Gürhan Çieng-tien'in kocası Fu-ma'nın ordusu Tekiş'i Hârizm'e getirdi, Sultan Şah kaçtı ve Tekiş tahta çıktı.","kaynak":"TDV: karahitaylar (KARAHITAYLAR)","taraflar":["karahitay","harizmsah"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1173-01-01","k":"savas","tur":"savas","b":"Bâvendî Alâüddevle Hasan Horasan ordusunu yendi, sonra öldürüldü","gun":"1173 (gün bilinmiyor)","yer":"Taberistan","odak_yer":["Âmül","Sârî"],"kisiler":"Alâüddevle Hasan, Müeyyed Ay-aba, Sultan Şah","d":"Müeyyed Ay-aba ile Harizmşah şehzadesi Sultan Şah Taberistan'ı istilâ edip Sârî ve Temîşe'yi yağmaladı. Alâüddevle Hasan bu orduyu dağlarda yendi, fakat aynı yıl gulâmlarınca öldürüldü; yerine Erdeşîr geçti.","kaynak":"TDV: bavendiler (BÂVENDÎLER)","taraflar":["bavendi"],"etiket":["hanedan-degisimi","konu-askeri"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1175-01-01","k":"fetih","tur":"fetih","b":"Muizzüddin Mültan ve Yukarı Sind'i aldı","gun":"571 h. (1175-76); gün bilinmiyor","yer":"Mültan","yer_id":"Multan","kisiler":"Muizzüddin (Şehâbeddin) Muhammed","d":"Gazne'yi üs edinen Muizzüddin Muhammed Hindistan fetihlerine Mültan ve Yukarı Sind'deki Karmatî emirliğini alarak başladı.","kaynak":"TDV: gurlular (GURLULAR)","taraflar":["gurlu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1175-01-01","k":"hanedan","tur":"hanedan","b":"Atabeg İldeniz öldü; Pehlivan atabeg oldu, Kızılarslan Azerbaycan'a getirildi","gun":"571/1175 (gün bilinmiyor)","yer":"Nahcıvan","yer_id":"Nahçıvan","kisiler":"İldeniz, Cihan Pehlivan, Kızılarslan","d":"İldeniz'in ölümüyle oğlu Pehlivan Nahcıvan'a gelerek kendini atabeg ilân etti ve kardeşi Kızılarslan'ı Azerbaycan'ın başına getirdi. Arslanapa'nın ölümünden sonra Tebriz de barışla İldenizlilere geçti.","kaynak":"TDV: ildenizliler (İLDENİZLİLER)","taraflar":["ildenizli","irak-selcuklu"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1177-01-01","k":"hanedan","tur":"hanedan","b":"Irak Selçuklu Sultanı Arslanşah öldü; Pehlivan II. Tuğrul'u tahta çıkardı","gun":"Receb 572 / Ocak 1177 (gün bilinmiyor)","yer":"Hemedan","yer_id":"Hemedan","kisiler":"Arslanşah, Cihan Pehlivan, II. Tuğrul","d":"Atabeglerin baskısından kurtulmaya çalışan Sultan Arslanşah öldü (Pehlivan tarafından öldürüldüğü de rivayet edilir). Pehlivan yanında tuttuğu Tuğrul'u sultan yaptı.","kaynak":"TDV: ildenizliler (İLDENİZLİLER)","taraflar":["irak-selcuklu","ildenizli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1179-01-01","k":"savas","tur":"savas","b":"Oğuzlar Kirman-Fars kuvvetlerini yendi","gun":"575/1179 (gün bilinmiyor)","yer":"Kirman / Cîruft","yer_id":"Kirman","odak_yer":["Kirman","Cîruft"],"kisiler":"II. Turan Şah; Salgurlu Tekele","d":"Sencer'i esir alan Oğuzlardan kalabalık bir grup Kirman'a girmişti. II. Turan Şah'ın Salgurlu Tekele ile birlikte onları çıkarma girişimi Oğuzların zaferiyle bitti; Oğuzlar Cîruft'u yağmaladı ve ülkede kalıcı bir güç oldular.","kaynak":"TDV: selcuklular (SELÇUKLULAR)","taraflar":["kirman-selcuklu"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1183-01-01","k":"savas","tur":"savas","b":"Vladimir Knezi Vsevolod İdil Bulgar topraklarına ordu gönderdi","gun":"1183; ikinci sefer 1205 (gün/ay bilinmiyor)","yer":"İdil Bulgar ülkesi","odak_yer":["Bulgar"],"kisiler":"Rus Prensi Vsevolod, Yuri","d":"Kürk ticareti yüzünden Ruslarla uzun süren mücadelede Prens Vsevolod 1183 ve 1205'te İdil Bulgar topraklarına ordular gönderdi; oğlu Yuri 1221'de sınırda Nijni Novgorod kalesini kurdurdu.","kaynak":"TDV: idil-bulgar-hanligi (İDİL BULGAR HANLIĞI)","taraflar":["idil-bulgar"],"etiket":["konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1185-01-01","k":"savas","tur":"savas","b":"Bâvendî Erdeşîr Bâdüsbânî Hezâresb'i yendi; Rûyân'a kendi adayını atadı","gun":"tahminî 581/1185","yer":"Rûyân","odak_yer":["Âmül"],"kisiler":"Hezâresb b. Şehrîveş, Hüsâmüddevle Erdeşîr","d":"Bâvendî Şah Erdeşîr'e yenilen Hezâresb, Hemedan'daki Irak Selçuklu Sultanı Tuğrul'a sığındı ve ülkesine dönemeden öldü. Erdeşîr Rûyân'a Keykâvus'un torunu Zerrînkemer'i hükümdar tayin etti.","kaynak":"TDV: badusbaniler (BÂDÜSBÂNÎLER)","taraflar":["bavendi","badusbani"],"etiket":["konu-askeri","konu-siyasi"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1185-01-01","k":"savas","tur":"savas","b":"Kayalı ırmağında İgor Svyatoslaviç'in ordusu imha edildi","gun":"1185 (gün/ay bilinmiyor)","yer":"Aşağı Don, Kayalı ırmağı","odak_yer":["Donets bozkırı","Azak"],"kisiler":"Novgorod-Seversk Knezi İgor Svyatoslaviç","d":"1184'te güney Rus knezliklerine yenilen Kıpçaklar, ertesi yıl üzerlerine yürüyen Novgorod-Seversk Knezi İgor'u Aşağı Don'da kuşatıp ordusunu imha ettiler. Olay 'İgor Bölüğü Destanı'na konu oldu.","kaynak":"TDV: kipcaklar (KIPÇAKLAR)","taraflar":["kipcak"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1186-01-01","k":"hanedan","tur":"hanedan","b":"Atabeg Pehlivan öldü; Kızılarslan atabeg oldu","gun":"Zilhicce 581 / Mart 1186 (gün bilinmiyor)","yer":"Hemedan","yer_id":"Hemedan","kisiler":"Cihan Pehlivan, Kızılarslan, II. Tuğrul","d":"Selâhaddîn'e karşı savaş hazırlığındayken hastalanan Pehlivan öldü. Sultan II. Tuğrul atabeglerden kurtulamadı ve Kızılarslan'ı Hemedan'a davet ederek eski düzeni sürdürmek zorunda kaldı.","kaynak":"TDV: ildenizliler (İLDENİZLİLER)","taraflar":["ildenizli","irak-selcuklu"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1190-01-01","k":"hanedan","tur":"hanedan","b":"Kızılarslan II. Tuğrul'u hapsetti ve kendini sultan ilân etti","gun":"Şevval 586 / Kasım 1190 (gün bilinmiyor)","yer":"Hemedan / Azerbaycan","yer_id":"Hemedan","kisiler":"Kızılarslan, II. Tuğrul","d":"Uzun mücadeleden sonra yenilen II. Tuğrul oğluyla birlikte Azerbaycan'da bir kaleye kapatıldı. Kızılarslan halifenin teşvikiyle Selçuklu tahtına kendisi çıktı.","kaynak":"TDV: ildenizliler (İLDENİZLİLER)","taraflar":["ildenizli","irak-selcuklu"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","odak_yer":["Multan"],"t":"1191-01-01","k":"savas","tur":"savas","b":"Birinci Tarain Savaşı: Muizzüddin Prithivi Raj'a yenildi","gun":"1191 (gün bilinmiyor)","yer":"Tarain ovası","kisiler":"Muizzüddin Muhammed, Prithivi Raj","d":"Tabarhinda Kalesi'nin Gurlular'ca alınması üzerine Ecmîr hükümdarı Prithivi Raj büyük bir orduyla geldi. Tarain ovasındaki savaşta subayları kaçan Muizzüddin yaralanarak geri çekildi.","kaynak":"TDV: gurlular (GURLULAR)","taraflar":["gurlu"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1191-01-01","k":"hanedan","tur":"hanedan","b":"Kızılarslan çadırında öldürüldü; Azerbaycan atabegliği bölündü","gun":"Şâban 587 / Eylül 1191 (gün bilinmiyor)","yer":"Hemedan","yer_id":"Hemedan","kisiler":"Kızılarslan, İnanç Hatun, Ebû Bekir, Kutluğ İnanç","d":"İnanç Hatun ile iş birliği yapan emîrler Kızılarslan'ı uykusunda öldürttü. Yeğeni Ebû Bekir Azerbaycan'da atabegliğini ilân etti, İnanç Hatun'un oğulları ise onu tanımadı.","kaynak":"TDV: ildenizliler (İLDENİZLİLER)","taraflar":["ildenizli"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","odak_yer":["Multan"],"t":"1192-01-01","k":"savas","tur":"savas","b":"İkinci Tarain Savaşı: Prithivi Raj yenilip öldürüldü","gun":"1192 (gün bilinmiyor)","yer":"Tarain ovası","kisiler":"Muizzüddin Muhammed, Prithivi Raj","d":"Ordusunu yeniden düzenleyen Muizzüddin farklı bir taktikle Prithivi Raj'ı yendi; raca yakalanıp öldürüldü. Bu zaferle Gurlu hâkimiyeti Sind'den Bengal körfezine kadar yayıldı.","kaynak":"TDV: gurlular (GURLULAR)","taraflar":["gurlu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1198-01-01","k":"savas","tur":"savas","b":"Karahıtaylar Belh için Gurlular'a yenildi","gun":"1198 (gün bilinmiyor)","yer":"Belh-Cûzcân","odak_yer":["Belh"],"kisiler":"Bahâeddin Sâm, Tayangu","d":"Gurlu Bahâeddin Sâm'ın Karahıtay tâbii bir Türk beyinden Belh'i alması üzerine Tayangu komutasındaki Karahıtay ordusu Ceyhun'u geçip Cûzcân'ı yağmaladı, fakat Gurlu ordusuna yenilip 12.000 kayıp verdi.","kaynak":"TDV: karahitaylar (KARAHITAYLAR)","taraflar":["gurlu","karahitay"],"etiket":["toprak-kazanc","toprak-kayip","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Alamut"],"t":"1198-01-01","k":"savas","tur":"savas","b":"Harizmşah Tekiş'in Alamut kuşatması başarısız oldu","gun":"595/1198-99 (gün bilinmiyor)","yer":"Alamut","kisiler":"Alâeddin Tekiş","d":"Harizmşah Tekiş de Alamut'u kuşattı, fakat kale düşmedi.","kaynak":"TDV: alamut (ALAMUT)","taraflar":["harizmsah","alamut-nizari"],"etiket":["konu-askeri"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1200-08-03","k":"hanedan","tur":"hanedan","b":"Alâeddin Muhammed Gürgenç'te hârizmşah ilân edildi","gun":"20 Şevval 596 / 3 Ağustos 1200","yer":"Gürgenç","yer_id":"Köhne Ürgenç (Gürgenç)","kisiler":"Alâeddin Muhammed b. Tekiş","d":"Tekiş'in ölümü üzerine Horasan valisi Muhammed, Gürgenç'te toplanan devlet adamları ve kumandanlarca Alâeddin unvanıyla hârizmşah ilân edildi.","kaynak":"TDV: muhammed-b-tekis (MUHAMMED b. TEKİŞ)","taraflar":["harizmsah"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","odak_yer":["Multan"],"t":"1204-01-01","k":"savas","tur":"savas","b":"Endhûd: Karahıtaylar Muizzüddin'i kuşattı","gun":"1204 (gün bilinmiyor)","yer":"Endhûd (Endhûy) Kalesi","kisiler":"Muizzüddin Muhammed, Tayangu, Semerkant Sultanı Osman","d":"Hârizm'i kuşatan Muizzüddin, Hârizmşah'a yardıma gelen Karahıtay ordusu karşısında çekilirken Endhûd Kalesi'ne sıkıştı. Karahanlı Osman'ın aracılığıyla hazine ve filler karşılığında barış yapıldı ve sultan Gazne'ye döndü.","kaynak":"TDV: gurlular (GURLULAR)","taraflar":["karahitay","gurlu","bati-karahanli"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1204-01-01","k":"fetih","tur":"fetih","b":"Alâeddin Muhammed Nîşâbur, Merv ve Serahs'ı Gurlular'dan aldı","gun":"1204 (gün bilinmiyor)","yer":"Horasan","odak_yer":["Nîşâbur","Merv","Serahs"],"kisiler":"Alâeddin Muhammed b. Tekiş","d":"Tekiş'in ölümünden sonra Gurlular'ın ele geçirdiği Horasan şehirlerini Alâeddin Muhammed geri aldı; bunun üzerine Muizzüddin Hârizm'e yürüdü.","kaynak":"TDV: harizmsahlar (HÂRİZMŞAHLAR)","taraflar":["harizmsah","gurlu"],"etiket":["toprak-kazanc","toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1204-01-01","k":"fetih","tur":"fetih","b":"Salgurlu Sa'd Kirman'da hâkimiyet kurdu ve İsfahan'ı aldı","gun":"600/1204 (gün bilinmiyor)","yer":"Berdesîr, İsfahan","odak_yer":["Isfahan"],"kisiler":"Sa'd b. Zengî","d":"Berdesîr'i işgal eden Oğuzlar şehri Salgurlu ordusuna teslim etti; Kirman'da Salgurlu hâkimiyetinin temeli atıldı. Sa'd aynı yıl direnişsiz İsfahan'ı da alarak İldenizlilerle karşı karşıya geldi.","kaynak":"TDV: salgurlular (SALGURLULAR)","taraflar":["salgurlu","ildenizli"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1205-01-01","k":"antlasma","tur":"antlasma","b":"Gurlu-Hârizmşah antlaşması: Herat dışında Horasan Hârizmşahlar'a geçti","gun":"Cemâziyelevvel 601 / Ocak 1205 (gün bilinmiyor)","yer":"Horasan","odak_yer":["Nîşâbur","Merv","Herat"],"kisiler":"Alâeddin Muhammed b. Tekiş, Muizzüddin Muhammed","d":"Uzun mücadelenin sonunda Hârizmşah Alâeddin Muhammed ile Gurlu Muizzüddin arasında imzalanan antlaşmayla Herat hariç bütün Horasan Hârizmşahlar'a bırakıldı.","kaynak":"TDV: muhammed-b-tekis (MUHAMMED b. TEKİŞ)","taraflar":["harizmsah","gurlu"],"etiket":["toprak-kazanc","toprak-kayip","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1205-01-01","k":"hanedan","tur":"hanedan","b":"Doğu Karahanlı Ebü'l-Muzaffer Yûsuf öldü","gun":"Receb 601 / Mart 1205 (gün bilinmiyor)","yer":"Kâşgar","yer_id":"Kaşgar","kisiler":"Ebü'l-Muzaffer Yûsuf b. Muhammed","d":"Karahıtay tâbii Doğu Karahanlı hükümdarı Ebü'l-Muzaffer Yûsuf öldü ve Kâşgar'daki hükümdarlar mezarlığına gömüldü; oğlu III. Muhammed Karahıtaylar'ca tutuldu.","kaynak":"TDV: karahanlilar (KARAHANLILAR)","taraflar":["dogu-karahanli"],"etiket":["hanedan-degisimi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1205-01-01","yer_id":"Merâga","k":"antlasma","tur":"antlasma","b":"Ahmedîlî Alâeddin Merâga'yı İldenizli Ebû Bekir'e bıraktı","gun":"602/1205-1206 (gün bilinmiyor)","yer":"Merâga, Urmiye, Uşnu","odak_yer":["Merâga","Urmiye"],"kisiler":"Alâeddin Körpearslan, Ebû Bekir","d":"Erbil hâkimi Kökböri ile ittifak kuran Alâeddin'e karşı İldenizli Ebû Bekir Merâga'ya yürüdü; Alâeddin Urmiye ve Uşnu karşılığında şehri terk etti.","kaynak":"TDV: ahmedililer (AHMEDÎLÎLER)","taraflar":["ildenizli","ahmedili"],"etiket":["toprak-kayip","toprak-kazanc","konu-siyasi"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1209-01-01","k":"olay","tur":"tabiiyet","b":"Uygur İdikut Barçuk Karahıtaylar'dan ayrılıp Cengiz Han'a bağlandı","gun":"1209 (gün bilinmiyor)","yer":"Beşbalık-Turfan","odak_yer":["Turfan"],"kisiler":"İdikut Barçuk, Cengiz Han","d":"Karahıtaylar'ın tâbii Uygur hükümdarı İdikut Barçuk, Cengiz Han'ın hâkimiyetini tanıdı; Karahıtay devletinin doğu kanadı Moğollar'a geçti.","kaynak":"TDV: karahitaylar (KARAHITAYLAR)","taraflar":["karahitay"],"etiket":["toprak-kayip","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1209-01-09","k":"olay","tur":"taht","b":"Atabeg Sa'd Kirman'ın başşehri Berdesîr'de Kavurd'un tahtına oturdu","gun":"1 Receb 605 / 9 Ocak 1209","yer":"Berdesîr (Kirman)","yer_id":"Kirman","kisiler":"Sa'd b. Zengî","d":"Sa'd b. Zengî Kirman'ın merkezine giderek eski Kirman Selçuklu tahtına oturdu, beş aya yakın kalıp bölgenin büyük kısmını itaat altına aldı.","kaynak":"TDV: salgurlular (SALGURLULAR)","taraflar":["salgurlu"],"etiket":["toprak-kazanc","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1210-01-01","k":"hanedan","tur":"hanedan","b":"İldenizli Ebû Bekir öldü; kardeşi Özbek geçti","gun":"607/1210 (gün bilinmiyor)","yer":"Tebriz","yer_id":"Tebriz","kisiler":"Ebû Bekir, Özbek","d":"Gürcüler karşısında âciz kalıp bir Gürcü prensesiyle evlenen Ebû Bekir aynı yıl öldü. Arrân-Azerbaycan tahtına kardeşi Özbek geçti.","kaynak":"TDV: ildenizliler (İLDENİZLİLER)","taraflar":["ildenizli","gurcistan"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1213-01-01","k":"fetih","tur":"fetih","b":"Kirman Salgurlulardan Harizmşahlara geçti","gun":"610/1213 (gün bilinmiyor)","yer":"Kirman","yer_id":"Kirman","kisiler":"Sa'd b. Zengî","d":"Salgurluların ihmal ettiği Kirman Harizmşahların eline geçti; Harizmşah akıncıları Fars'ta Şîraz'a kadar ilerledi.","kaynak":"TDV: salgurlular (SALGURLULAR)","taraflar":["harizmsah","salgurlu"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1215-01-01","k":"fetih","tur":"fetih","b":"Alâeddin Muhammed Kıpçaklar'dan Sığnak'ı aldı","gun":"612 h. (1215); gün bilinmiyor","yer":"Sığnak","yer_id":"Sığnak (Sunak Kurgan)","kisiler":"Alâeddin Muhammed b. Tekiş","d":"Kıpçak bozkırlarına başarılı seferler yapan Alâeddin Muhammed Siriderya boyundaki Sığnak'ı topraklarına kattı; aynı yıl Gazne'yi de alarak devletini en geniş sınırlarına ulaştırdı.","kaynak":"TDV: muhammed-b-tekis (MUHAMMED b. TEKİŞ)","taraflar":["harizmsah"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","odak_yer":["Semerkant"],"t":"1217-01-01","k":"antlasma","tur":"antlasma","b":"Sa'd b. Zengî Rey yakınında Harizmşah'a esir düştü; ağır şartlı antlaşma","gun":"614/1217 (gün bilinmiyor)","yer":"Rey civarı","kisiler":"Sa'd b. Zengî, Alâeddin Muhammed Harizmşah","d":"Irâk-ı Acem'e hâkim olmak isteyen Sa'd Harizmşah Alâeddin Muhammed'e yenilip esir düştü. Affedilen Sa'd; Eşkenvan ve İstahr kalelerini bırakmayı, gelirin üçte birini haraç vermeyi ve Harizmşah adına hutbe okutmayı kabul etti.","kaynak":"TDV: salgurlular (SALGURLULAR)","taraflar":["harizmsah","salgurlu"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1218-01-01","k":"fetih","tur":"fetih","b":"Cebe Noyan Güçlüg'ün elindeki Karahıtay topraklarını aldı","gun":"1218 (gün/ay bilinmiyor)","yer":"Karahıtay ülkesi (Balasagun-Kâşgar)","odak_yer":["Balasagun","Kaşgar"],"kisiler":"Cebe Noyan, Nayman Güçlüg","d":"Nayman Tayang Han'ın oğlu Güçlüg Karahıtay Gürhanını devirip ülkeye hâkim olmuştu. Cengiz Han'ın kumandanı Cebe Noyan 1218'de bu toprakları ele geçirdi; Moğollar böylece batıda Hârizmşahlara komşu oldu.","kaynak":"TDV: mogollar (MOĞOLLAR)","taraflar":["mogol-imparatorlugu","karahitay"],"etiket":["toprak-kazanc","yikilis","konu-askeri"]},{"onem":5,"dunya":5,"bolge_onem":5,"puan_s":"v2","odak_yer":["Karakurum"],"t":"1219-01-01","k":"fetih","tur":"fetih","b":"Cengiz Han Otrar'ı aldı; Moğol istilâsı başladı","gun":"616 h. (1219); gün bilinmiyor","yer":"Otrar","kisiler":"Cengiz Han, Alâeddin Muhammed, Kayırhan","d":"Otrar valisinin Moğol kervanını katletmesi ve Hârizmşah'ın elçileri öldürtmesi üzerine Cengiz Han Otrar'a yürüyüp şehri birkaç ayda aldı. Hârizmşah ordusunu kalelere dağıtıp Horasan'a çekildi, bütün Mâverâünnehir Moğollar'a geçti.","kaynak":"TDV: muhammed-b-tekis (MUHAMMED b. TEKİŞ)","taraflar":["mogol-imparatorlugu","harizmsah"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":5,"puan_s":"v2","t":"1220-01-01","k":"fetih","tur":"fetih","b":"Semerkant düştü; Mâverâünnehir Moğollar'a geçti","gun":"1220 (gün bilinmiyor)","yer":"Semerkant","yer_id":"Semerkant","kisiler":"Cengiz Han","d":"Otrar, Sığnak, Hucend ve Buhara'dan sonra Mâverâünnehir'in en güçlü savunma merkezi Semerkant da Moğollar'ın eline geçti; Cengiz ordusunu kollara ayırıp Hârizmşah vilâyetlerinin zaptına gönderdi.","kaynak":"TDV: harizmsahlar (HÂRİZMŞAHLAR)","taraflar":["mogol-imparatorlugu","harizmsah"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1220-02-10","k":"fetih","tur":"fetih","b":"Buhara Moğollara teslim oldu","gun":"10 Şubat 1220","yer":"Buhara","yer_id":"Buhara","kisiler":"Cengiz Han","d":"Otrar kuşatmasını oğullarına bırakan Cengiz Han Buhara üzerine yürüdü ve şehri üç günlük kuşatmadan sonra aldı; mart ayında Semerkant da teslim oldu. Mâverâünnehir'in düşmesiyle Hârizmşah Alâeddin Muhammed batıya kaçtı.","kaynak":"TDV: cengiz-han (CENGİZ HAN)","taraflar":["mogol-imparatorlugu","harizmsah"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1221-01-01","k":"fetih","tur":"fetih","b":"Gürgenç Moğollar'a düştü","gun":"Safer 618 / Nisan 1221 (gün bilinmiyor)","yer":"Gürgenç","yer_id":"Köhne Ürgenç (Gürgenç)","kisiler":"Humâr Tegin","d":"Başsız kalan Hârizmşah başşehri Gürgenç'i Humâr Tegin 90.000 kişilik orduyla savundu; şehir dört aylık kuşatmadan sonra Moğollar'ın eline geçti.","kaynak":"TDV: harizmsahlar (HÂRİZMŞAHLAR)","taraflar":["mogol-imparatorlugu","harizmsah"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1221-01-01","k":"fetih","tur":"fetih","b":"Moğollar Merâga'yı zaptetti","gun":"1221 (gün bilinmiyor)","yer":"Merâga","yer_id":"Merâga","d":"Moğol akınında Merâga düştü; o sırada Ahmedîlî hânedanının başında Revândiz Kalesi'nde oturan bir kadın bulunuyordu.","kaynak":"TDV: ahmedililer (AHMEDÎLÎLER)","taraflar":["mogol-imparatorlugu","ahmedili"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1221-01-01","k":"savas","tur":"savas","b":"Kıpçak-Rus kuvvetleri Selçuklu Suğdak'ını geri alamadı","gun":"1221 (gün/ay bilinmiyor)","yer":"Suğdak (Sudak), Kırım","yer_id":"Sudak (Suğdak)","d":"Anadolu Selçuklularının Kırım'daki ticaret merkezi Suğdak'ı zaptetmesi üzerine Kıpçak ve Rus kuvvetleri şehri geri almak için birlikte harekete geçtiler, ancak Selçuklu savunmasını kıramadılar.","kaynak":"TDV: kipcaklar (KIPÇAKLAR)","taraflar":["selcuklu","kipcak"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1221-11-26","k":"savas","tur":"savas","b":"Sind (İndus) Savaşı: Celâleddin Hindistan'a geçti","gun":"9 Şevval 618 / 26 Kasım 1221","yer":"Sind nehri kıyısı","odak_yer":["Peşâver"],"kisiler":"Celâleddin Hârizmşah, Cengiz Han","d":"Parvan'da Moğollar'ı yenen Celâleddin'i takip eden Cengiz Han, Sind nehri kıyısında ordusunu çembere aldı. Yenilen Celâleddin nehri geçerek Hindistan'a sığındı; Gazne ve Afganistan Moğollar'a açıldı.","kaynak":"TDV: harizmsahlar (HÂRİZMŞAHLAR)","taraflar":["mogol-imparatorlugu","harizmsah"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1223-01-01","k":"savas","tur":"savas","b":"Kalka Savaşı — Moğollar Rus-Kıpçak ordusunu bozdu","gun":"1223 (gün/ay TDV'de yok)","yer":"Kalka ırmağı","odak_yer":["Azak","Donets bozkırı"],"kisiler":"Cebe Noyan, Sübütay","d":"Cebe ve Sübütay kumandasındaki iki Moğol tümeni, Kafkasları aşıp Karadeniz'in kuzeyine geçtikten sonra Ruslarla ittifak yapan Kıpçakları Kalka'da yendi. Dönüşte İdil Bulgarları Moğol ordusuna ağır bir darbe vurdu.","kaynak":"TDV: kipcaklar (KIPÇAKLAR) · idil-bulgar-hanligi","taraflar":["mogol-imparatorlugu","kipcak"],"etiket":["konu-askeri"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1223-01-01","k":"savas","tur":"savas","b":"İdil Bulgarları Kalka dönüşü Moğol ordusunu yendi","gun":"1223 (gün/ay bilinmiyor)","yer":"İdil Bulgar ülkesi","odak_yer":["Bulgar"],"d":"Kalka'da Rus ve Kıpçak ordularını bozan Moğol birlikleri dönüş yolunda İdil Bulgarlarının saldırısına uğrayıp ağır kayıp verdi. Bu yenilgi 1236'daki Batu seferinin gerekçesi oldu.","kaynak":"TDV: idil-bulgar-hanligi (İDİL BULGAR HANLIĞI)","taraflar":["idil-bulgar","mogol-imparatorlugu"],"etiket":["konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1224-01-01","k":"olay","tur":"siyasi","b":"Özbek Harizmli kaçakları önce korudu, sonra Moğollara teslim etti","gun":"621/1224 (gün bilinmiyor)","yer":"Azerbaycan","odak_yer":["Tebriz"],"kisiler":"Özbek","d":"Cengiz Han'dan kaçan Harizmlileri himayesine alan Özbek, Moğol baskısı üzerine onları teslim etmek zorunda kaldı. Ertesi yıl Celâleddin Harizmşah Tebriz'e yürüdü.","kaynak":"TDV: ildenizliler (İLDENİZLİLER)","taraflar":["ildenizli","mogol-imparatorlugu"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","odak_yer":["Nihâvend"],"t":"1224-01-01","k":"hanedan","tur":"hanedan","b":"Lür-i Küçek kurucusu Şücâüddin Hurşîd öldü","gun":"621/1224 (gün bilinmiyor)","yer":"Hürremâbâd","kisiler":"Şücâüddin Hurşîd, Seyfeddin Rüstem","d":"Yeğeni Seyfeddin'in oğlu Bedreddin'i hileyle öldürmesinden sonra yüz yaşındaki Şücâüddin kederinden öldü; yerine Seyfeddin Rüstem geçti.","kaynak":"TDV: lur-i-kucek (LUR-ı KÜÇEK)","taraflar":["lur-i-kucek"],"etiket":["hanedan-degisimi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1225-01-01","k":"fetih","tur":"fetih","b":"Celâleddin Tebriz'i alıp Azerbaycan'ı ilhak etti","gun":"Temmuz 1225 (gün bilinmiyor)","yer":"Tebriz","yer_id":"Tebriz","kisiler":"Celâleddin Hârizmşah, Özbek b. Pehlivân","d":"1224'te Hindistan'dan dönüp Kirman ve Irâk-ı Acem'e hâkim olan Celâleddin, Merâga'dan sonra Tebriz'i aldı; İldenizliler'in bütün toprakları Hârizmşahlar'a geçti ve Tebriz başşehir oldu.","kaynak":"TDV: celaleddin-harizmsah (CELÂLEDDİN HÂRİZMŞAH)","taraflar":["harizmsah"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":5,"dunya":4,"bolge_onem":5,"puan_s":"v2","t":"1227-01-01","k":"olay","tur":"olum","b":"Cengiz Han Tangut seferinde öldü","gun":"Ağustos 1227 (gün bilinmiyor)","yer":"Tangut ülkesi","odak_yer":["Yinchuan","Lanzhou"],"kisiler":"Cengiz Han, Ögedey, Çağatay, Tuluy","d":"1226'da Tangut hükümdarını ve ileri gelenlerini öldürten Cengiz Han, Tangut başşehrine yeni bir sefer sırasında hastalanıp öldü. Vasiyetiyle Ögedey veliaht oldu, yasa işleri Çağatay'a, ordu Tuluy'a bırakıldı; ülke oğulları arasında pay edildi.","kaynak":"TDV: cengiz-han (CENGİZ HAN)","taraflar":["mogol-imparatorlugu"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1228-01-01","yer_id":"Kirman","k":"hanedan","tur":"hanedan","b":"Kutluğ Han Barak Gıyâseddin Pîrşah'ı Kirman'a çağırıp annesiyle evlendi","gun":"1228 (gün bilinmiyor)","yer":"Kirman","odak_yer":["Kirman"],"kisiler":"Barak Hâcib, Gıyâseddin Pîrşah","d":"Moğollara tâbi olan Barak, ağabeyi Celâleddin'le anlaşmazlığa düşen Harizmşah şehzadesi Gıyâseddin'i Kirman'a davet edip annesiyle evlendi; zehirleme planını öğrenince ikisini de öldürttü ve halifeden Kutluğ Sultan unvanı aldı.","kaynak":"TDV: kutlughanlilar (KUTLUĞHANLILAR)","taraflar":["kutlughanli","harizmsah"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","odak_yer":["Ahvaz"],"t":"1229-01-01","k":"hanedan","tur":"hanedan","b":"Lür-i Büzürg atabegi Hezâresb öldü","gun":"626/1229 (gün bilinmiyor)","yer":"Îzec","kisiler":"Nusreddin Hezâresb, İmâdüddin Pehlivan, Tukli","d":"Îzec'i başşehir yapıp emirliğin sınırlarını genişleten ve halifeden atabeg unvanı alan Hezâresb öldü; yerine bazı kaynaklara göre İmâdüddin Pehlivan, çoğuna göre Tukli geçti.","kaynak":"TDV: lur-i-buzurg (LUR-ı BÜZÜRG)","taraflar":["lur-i-buzurg"],"etiket":["hanedan-degisimi"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1229-01-01","k":"hanedan","tur":"hanedan","b":"Ögedey Kodege kurultayında büyük han oldu","gun":"1229 ilkbaharı (gün bilinmiyor)","yer":"Kerulen nehri, Kodege adası","odak_yer":["Karakurum"],"kisiler":"Ögedey Han, Çağatay, Otçigin Noyan","d":"Cengiz Han'ın ölümünden sonra devleti geçici olarak Tuluy yönetti. Kerulen nehrindeki kurultayda Ögedey büyük han unvanıyla tahta oturtuldu ve duraklayan seferleri yeniden başlattı.","kaynak":"TDV: ogedey-han (ÖGEDEY HAN)","taraflar":["mogol-imparatorlugu"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1230-01-01","k":"savas","tur":"savas","b":"Yassıçimen Savaşı","gun":"Ağustos 1230 (gün bilinmiyor)","yer":"Yassıçimen (Erzincan yakını)","odak_yer":["Erzincan"],"kisiler":"Celâleddin Hârizmşah, I. Alâeddin Keykubad, el-Melikü'l-Eşref","d":"Anadolu Selçuklu Sultanı I. Alâeddin Keykubad ile Eyyûbî el-Melikü'l-Eşref'in birleşik ordusu karşısında Celâleddin savaş alanını terk etti; Hârizmliler ağır kayıp verdi, hazine Selçuklular'a geçti. Yenilgi Hârizmşahlar'ın son gücünü kırdı.","kaynak":"TDV: celaleddin-harizmsah (CELÂLEDDİN HÂRİZMŞAH)","taraflar":["selcuklu","harizmsah"],"etiket":["toprak-kayip","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1230-01-01","k":"fetih","tur":"fetih","b":"Salgurlu Ebû Bekir Kays adasını aldı","gun":"627/1230 (gün bilinmiyor)","yer":"Kays adası (Basra körfezi)","yer_id":"Kiş (Kish)","kisiler":"Ebû Bekir b. Sa'd","d":"Moğollara itaat ederek Fars'ı koruyan Atabeg Ebû Bekir Kays adasına ordu gönderip burayı ele geçirdi ve Basra körfezi hâkimiyetini Arabistan kıyılarına kadar genişletti.","kaynak":"TDV: salgurlular (SALGURLULAR)","taraflar":["salgurlu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1235-01-01","k":"hanedan","tur":"hanedan","b":"Barak öldü; Kutbüddin Muhammed geçti, Moğollar Rükneddin'i tahta çıkardı","gun":"1235 (gün bilinmiyor)","yer":"Kirman","yer_id":"Kirman","kisiler":"Barak Hâcib, Kutbüddin Muhammed, Rükneddin Mübârek Hoca","d":"Sîstan'ı almaya çalışan Moğol ordusuna yardım eden Barak öldü. Yerine yeğeni Kutbüddin geçti, ama kısa süre sonra Moğollar Barak'ın oğlu Rükneddin'i tahta çıkardı.","kaynak":"TDV: kutlughanlilar (KUTLUĞHANLILAR)","taraflar":["mogol-imparatorlugu"],"etiket":["hanedan-degisimi"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1238-01-01","k":"fetih","tur":"fetih","b":"Batu Han'ın ordusu Moskova'yı yağmaladı","gun":"Şubat 1238 (gün bilinmiyor)","yer":"Moskova","yer_id":"Moskova","kisiler":"Batu Han","d":"1237 sonunda kış ortasında Rus knezliklerine giren Batu Han'ın ordusu iki üç ay içinde pek çok şehri aldı; 1238 Şubatında Moskova, 1239'da Çernigov yağmalandı.","kaynak":"TDV: batu-han (BATU HAN)","taraflar":["mogol-imparatorlugu"],"etiket":["konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":5,"puan_s":"v2","t":"1240-01-01","k":"fetih","tur":"fetih","b":"Kiev Moğollarca zaptedilip tahrip edildi","gun":"Aralık 1240 (gün TDV'de yok)","yer":"Kiev","yer_id":"Kiev","kisiler":"Batu Han","d":"Kumanları yurtlarından sürdükten sonra Ukrayna bozkırlarına inen Batu Han, bölgenin en büyük knezliği Kiev'i aldı. TDV'ye göre batı seferinin asıl hedefi Kiev'in zaptıyla tamamlandı; sonraki Polonya-Macaristan harekâtı yağmaya dönüştü.","kaynak":"TDV: batu-han (BATU HAN) · altin-orda-hanligi","taraflar":["mogol-imparatorlugu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1241-01-01","k":"fetih","tur":"fetih","b":"Tâir Bahadır Herat, Sîstan ve Lahor'u ele geçirdi","gun":"639 / 1241-42 (gün/ay bilinmiyor)","yer":"Herat · Sîstan · Lahor","yer_id":"Herat","odak_yer":["Herat","Lahor"],"kisiler":"Tâir Bahadır","d":"Ögedey'in dördüncü cephesi olan Gûr, Gazne ve Afganistan'a gönderilen Tâir Bahadır kumandasındaki Moğol ordusu Herat, Sîstan ve Lahor dahil bütün bölgeyi aldı.","kaynak":"TDV: mogollar (MOĞOLLAR) · ogedey-han","taraflar":["mogol-imparatorlugu"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1241-04-09","k":"savas","tur":"savas","b":"Liegnitz yakınında Moğollar Alman-Leh ordusunu yendi","gun":"9 Nisan 1241","yer":"Liegnitz (Legnica)","yer_id":"Liegnitz (Legnica)","kisiler":"Batu Han'ın kumandanları","d":"Batu Han'ın orduları Polonya, Macaristan, Avusturya ve Dalmaçya'ya kadar ilerledi ve Liegnitz yakınında karşılarına çıkan kuvvetleri yendi. Aralık 1241'de Ögedey'in ölüm haberi gelince sefer sona erdi.","kaynak":"TDV: batu-han (BATU HAN)","taraflar":["mogol-imparatorlugu"],"etiket":["konu-askeri"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1241-12-11","k":"olay","tur":"olum","b":"Ögedey Han öldü, batı seferi durdu","gun":"11 Aralık 1241","yer":"Moğolistan","odak_yer":["Karakurum"],"kisiler":"Ögedey Han, Töregene Hatun, Batu Han","d":"Ögedey'in ölümüyle bütün Moğol başbuğlarının dönmesi gerekti ve Avrupa seferi sona erdi. Töregene Hatun yaklaşık beş yıl nâibe olarak yönetti. Aynı yıl Çağatay da ölmüştü; Batu Cengiz'in torunlarının en yaşlısı oldu.","kaynak":"TDV: ogedey-han (ÖGEDEY HAN)","taraflar":["mogol-imparatorlugu"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1246-01-01","k":"hanedan","tur":"hanedan","b":"Güyük kurultayda büyük han seçildi","gun":"Ağustos 1246 (gün bilinmiyor)","yer":"Moğolistan","odak_yer":["Karakurum"],"kisiler":"Güyük Han, Töregene Hatun, Batu Han","d":"Beş yıla yakın naiplikten sonra toplanan kurultay Ögedey'in oğlu Güyük'ü büyük han seçti. Batu Han kurultaya katılmadı; Güyük onun Azerbaycan'daki kumandanlarını azletti ve 1248'de Batu üzerine yürürken öldü.","kaynak":"TDV: batu-han (BATU HAN)","taraflar":["mogol-imparatorlugu","altinorda"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":3,"bolge_onem":4,"puan_s":"v2","t":"1251-01-01","k":"hanedan","tur":"hanedan","b":"Mengü büyük han seçildi — hanlık Tuluy soyuna geçti","gun":"Temmuz 1251 (gün bilinmiyor)","yer":"Moğolistan","odak_yer":["Karakurum"],"kisiler":"Mengü (Möngke) Kağan, Batu Han","d":"Güyük'ün 1248'deki ölümünden sonra Batu Han'ın isteğiyle toplanan kurultay Tuluy'un büyük oğlu Mengü'yü kağan seçti; Ögedey soyu hâkimiyeti kaybetti. Mengü kardeşi Kubilay'ı Çin'e, Hülâgû'yu İran'a gönderdi.","kaynak":"TDV: batu-han (BATU HAN) · mogollar","taraflar":["mogol-imparatorlugu","altinorda"],"etiket":["hanedan-degisimi","konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1251-01-01","k":"hanedan","tur":"hanedan","b":"Kara Hülâgû Çağatay hanlığına döndü, Ergene Hatun nâibe oldu","gun":"1251 (gün/ay bilinmiyor)","yer":"Almalığ","yer_id":"Almalık (Almalığ)","kisiler":"Kara Hülâgû, Ergene Hatun, Mübârek Şah","d":"Mengü'nün büyük han seçildiği 1251 kurultayında Kara Hülâgû yeniden Çağatay Hanlığı'nın başına getirildi; aynı yıl ölünce eşi Ergene Hatun oğlu Mübârek Şah adına nâibe olarak yönetimi aldı.","kaynak":"TDV: cagatay-hanligi (ÇAĞATAY HANLIĞI)","taraflar":["cagatay","mogol-imparatorlugu"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1252-01-01","yer_id":"Kirman","k":"hanedan","tur":"hanedan","b":"Kutbüddin Kirman'a döndü; Rükneddin kaçtı","gun":"650/1252 (gün bilinmiyor)","yer":"Kirman","odak_yer":["Kirman"],"kisiler":"Kutbüddin Muhammed, Rükneddin Mübârek Hoca, Mengü Han","d":"Mengü Han döneminde Kirman'a gelen Kutbüddin tahtı geri aldı; kaçan Rükneddin halifeden, Lur atabeginden ve Mengü Han'dan yardım istediyse de sonuç alamadı ve öldürüldü.","kaynak":"TDV: kutlughanlilar (KUTLUĞHANLILAR)","taraflar":["kutlughanli","mogol-imparatorlugu"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1255-01-01","k":"olay","tur":"siyasi","b":"Hülâgû Şemseddin Kert'in Herat hâkimliğini onayladı","gun":"653/1255 (gün bilinmiyor)","yer":"Herat","yer_id":"Herat","kisiler":"Şemseddin Kert, Hülâgû","d":"Moğolların 1244'te Herat'a atadığı Şemseddin Kert'in hâkimiyeti Hülâgû tarafından onaylandı; şehirde Kert hânedanı yerleşti.","kaynak":"TDV: herat (HERAT)","taraflar":["mogol-imparatorlugu","kert"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1256-01-01","k":"hanedan","tur":"hanedan","b":"Berke Han Altın Orda tahtına çıktı","gun":"1256 sonu (gün/ay bilinmiyor)","yer":"Saray","yer_id":"Saray (Selitrennoye)","kisiler":"Berke Han, Sertak, Ulakçı","d":"Batu Han'ın 1255 sonu-1256 başındaki ölümünden sonra oğulları Sertak ve Ulakçı kısa aralıklarla öldü ve Batu'nun müslüman kardeşi Berke tahta geçti. Berke Galiçya isyanını bastırdı, Polonya'ya akınlar yaptırdı.","kaynak":"TDV: berke-han (BERKE HAN)","taraflar":["altinorda"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1258-01-01","k":"olay","tur":"taht","b":"Lür-i Büzürg atabegi Tukli Hülâgû'nun katliamından kurtulamadı","gun":"656/1258 (gün bilinmiyor)","yer":"Luristan","yer_id":"Luristan","kisiler":"Tukli, Hülâgû","d":"Bağdat seferinde ordusunu Hülâgû'ya katan Tukli, katliamdan korkup Luristan'a kaçtı ama kurtulamadı. Moğollar tahta kardeşi Şemseddin Alp Argun'u geçirdi.","kaynak":"TDV: lur-i-buzurg (LUR-ı BÜZÜRG)","taraflar":["mogol-imparatorlugu","lur-i-buzurg"],"etiket":["hanedan-degisimi","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1259-01-01","k":"isyan","tur":"isyan","b":"Rus şehirlerindeki vergi isyanları bastırıldı","gun":"1259 (gün/ay bilinmiyor)","yer":"Novgorod · Rostov · Suzdal · Yaroslavl","yer_id":"Novgorod","odak_yer":["Novgorod","Rostov","Suzdal","Yaroslavl"],"kisiler":"Berke Han, Aleksandr Yaroslaviç (Nevski)","d":"Vergi meselesinden çıkan ayaklanmalar Rus knezlikleriyle dostluğu bozdu; Novgorod, Rostov, Suzdal ve Yaroslavl'daki isyanlar bastırıldı ve Knez Aleksandr Berke'nin üstünlüğünü kabul etti.","kaynak":"TDV: berke-han (BERKE HAN)","taraflar":["altinorda","novgorod"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":3,"bolge_onem":5,"puan_s":"v2","t":"1259-09-12","yer_id":"Tebriz","k":"savas","tur":"savas","b":"Hülâgû Suriye seferine çıktı — Halep ve Dımaşk düştü","gun":"12 Eylül 1259 (Tebriz'den hareket)","yer":"Tebriz → Halep","odak_yer":["Halep","Şam"],"kisiler":"Hülâgû, Ketboğa Noyan","d":"Ketboğa'nın öncü birliklerinin ardından Hülâgû Tebriz'den hareket etti. Ortak cephe kuramayan Suriye şehirlerinden Urfa, Harran, Hama, Humus ve Dımaşk teslim oldu; Ermeni ve Haçlı destekli ordu Halep'i kuşatıp aldı, ardından Hârim kalesi düşürüldü.","kaynak":"TDV: hulagu (HÜLÂGÛ)","taraflar":["ilhanli","kilikya-ermeni"],"etiket":["toprak-kazanc","konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1260-01-01","k":"hanedan","tur":"hanedan","b":"Ebû Bekir b. Sa'd öldü; Salgurlu tahtı taht kavgasına düştü","gun":"658/1260 (gün bilinmiyor)","yer":"Şîraz","yer_id":"Şiraz","kisiler":"Ebû Bekir b. Sa'd, II. Sa'd, Adudüddin Muhammed, Terken Hatun","d":"Uzun süren saltanatın ardından Ebû Bekir öldü; oğlu II. Sa'd on iki gün sonra ölünce çocuk yaştaki Muhammed tahta çıkarıldı, nâibliği annesi Terken Hatun üstlendi.","kaynak":"TDV: salgurlular (SALGURLULAR)","taraflar":["salgurlu"],"etiket":["hanedan-degisimi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","odak_yer":["Tebriz"],"t":"1260-01-01","k":"fetih","tur":"fetih","b":"Yeşmut Meyyâfârikîn'i alıp Eyyûbîlerin bu koluna son verdi","gun":"658 / 1260 (gün/ay bilinmiyor)","yer":"Meyyâfârikîn (Silvan)","kisiler":"Yeşmut, el-Melikü'l-Kâmil Muhammed","d":"Hülâgû'nun oğlu Yeşmut'un kuvvetleri Meyyâfârikîn'i işgal edip el-Melikü'l-Kâmil Muhammed'i öldürdü; Eyyûbîlerin Meyyâfârikîn, Cebel ve Sincar kolu sona erdi.","kaynak":"TDV: hulagu (HÜLÂGÛ)","taraflar":["ilhanli"],"etiket":["toprak-kazanc","yikilis","konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1263-01-01","k":"hanedan","tur":"hanedan","b":"Selçuk Şah Hülâgû'nun emriyle öldürüldü; Fars fiilen Moğol denetimine girdi","gun":"662/1263-64 (gün bilinmiyor)","yer":"Kâzerûn","yer_id":"Kâzerûn","kisiler":"Selçuk Şah, Hülâgû, Âbiş Hatun","d":"Moğollarla savaşmayı seçen Atabeg Selçuk Şah Hülâgû'nun emriyle Kâzerûn'da yakalanıp öldürüldü. Ardından Âbiş Hatun atabeg ilân edildi; Fars resmen Moğol ülkeleri arasında sayıldı ve İlhanlı şahneleri yönetti.","kaynak":"TDV: salgurlular (SALGURLULAR)","taraflar":["ilhanli","salgurlu"],"etiket":["hanedan-degisimi","konu-askeri"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1263-01-01","k":"savas","tur":"savas","b":"Terek Savaşı — Berke Han Hülâgû'yu ağır yenilgiye uğrattı","gun":"Rebîülevvel 661 / Ocak 1263 (gün bilinmiyor)","yer":"Terek ırmağı","odak_yer":["Terek deltası","Derbend"],"kisiler":"Berke Han, Hülâgû","d":"İlhanlıların Azerbaycan'ı alıp sınırı Derbend'e dayaması ve Altın Ordalı tüccarları öldürmesi iki Cengizli devleti savaşa sürükledi. Memlük Sultanı Baybars ile anlaşan Berke, Terek'te Hülâgû'yu bozguna uğrattı; Altın Orda-Memlük ittifakı İlhanlıları iki cepheye böldü.","kaynak":"TDV: hulagu (HÜLÂGÛ) · berke-han","taraflar":["altinorda","ilhanli"],"etiket":["konu-askeri"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1265-01-01","k":"savas","tur":"savas","b":"Abaka ile Berke Kür ırmağında karşı karşıya geldi","gun":"1265 (gün/ay bilinmiyor)","yer":"Kür ırmağı","odak_yer":["Şamahı"],"kisiler":"Abaka Han, Berke Han","d":"Hülâgû'nun yerine geçen Abaka, Kuzey Azerbaycan için Altın Orda ile mücadeleyi sürdürdü ve Kür ırmağı kıyısına set kurdurdu. İki ordu ırmağın iki yakasında beklerken Berke nehri Tiflis tarafından geçmeye yöneldi, ama 1266'da öldü ve mücadele sona erdi.","kaynak":"TDV: berke-han (BERKE HAN) · abaka (ABAKA)","taraflar":["ilhanli","altinorda"],"etiket":["konu-askeri"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1266-01-01","k":"hanedan","tur":"hanedan","b":"Berke Han öldü, Mengü Timur Altın Orda hanı oldu","gun":"1266 (altin-orda-hanligi: 'yılı başlarında'; gün yok)","yer":"Saray","yer_id":"Saray (Selitrennoye)","kisiler":"Berke Han, Mengü Timur","d":"İlk müslüman Altın Orda hükümdarı Berke, İlhanlılara karşı seferde öldü ve Saray'a gömüldü. Oğlu olmadığından Batu'nun torunu Mengü Timur han ilan edildi. TDV'ye göre Berke zamanında Altın Orda büyük kağanlıktan ayrılıp kendi adına sikke bastırdı.","kaynak":"TDV: berke-han (BERKE HAN)","taraflar":["altinorda"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1270-01-01","k":"savas","tur":"savas","b":"Herat yakınında Abaka Çağatay Hanı Barak'ı yendi","gun":"1270 (gün/ay bilinmiyor)","yer":"Herat","yer_id":"Herat","kisiler":"Abaka Han, Barak Han, Yesudar Oğul","d":"Horasan'da hak iddia eden Çağatay Hanı Barak büyük bir orduyla Horasan'a girdi ve Abaka'nın barış teklifini reddetti. Herat yakınındaki savaşta yenildi; Abaka Horasan valiliğine kardeşi Yesudar'ı atadı, Yesudar sonra Buhara çevresini yağmaladı.","kaynak":"TDV: abaka (ABAKA)","taraflar":["ilhanli","cagatay"],"etiket":["konu-askeri"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","t":"1272-01-01","k":"hanedan","tur":"hanedan","b":"Bâdüsbânî Şehrâkim öldü","gun":"671/1272-73 (gün bilinmiyor)","yer":"Rûyân","odak_yer":["Âmül"],"kisiler":"Şehrâkim b. Nâmâver, Abaka Han","d":"Hülâgû ve Abaka'nın seferlerine katılıp sonra Moğol ordusunu terk eden, Abaka'nın gönderdiği Gazan Bahadır'dan özür dileyerek yarlık alan Şehrâkim öldü; yerine oğlu Şah Gazi geçti.","kaynak":"TDV: badusbaniler (BÂDÜSBÂNÎLER)","taraflar":["badusbani","ilhanli"],"etiket":["hanedan-degisimi"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","t":"1274-01-01","k":"hanedan","tur":"hanedan","b":"Alp Argun öldü; Abaka Han'ın sarayında yetişen Yûsuf Şah Lür-i Büzürg'ün başına getirildi","gun":"672/1274 (gün bilinmiyor)","yer":"Luristan","yer_id":"Luristan","kisiler":"Şemseddin Alp Argun, Yûsuf Şah, Abaka Han","d":"Moğolların tahrip ettiği yerleri imar eden Alp Argun öldü. Abaka Han Yûsuf Şah'a sonra Huzistan, Kuhgîlûye ve Gülpâyigân'ın yönetimini de verdi.","kaynak":"TDV: lur-i-buzurg (LUR-ı BÜZÜRG)","taraflar":["lur-i-buzurg","ilhanli"],"etiket":["hanedan-degisimi"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","odak_yer":["Nihâvend"],"t":"1278-01-01","k":"hanedan","tur":"hanedan","b":"Abaka Han Tâceddin'i Lür-i Küçek atabegi tayin etti","gun":"677/1278-79 (gün bilinmiyor)","yer":"Hürremâbâd","kisiler":"Abaka Han, Tâceddin b. Hüsâmeddin Halîl","d":"Taht kavgalarıyla geçen dönemden sonra İlhanlı Abaka Han Tâceddin'i atabeg atadı; Lür-i Küçek İlhanlı tâbiiyetinde sürdü.","kaynak":"TDV: lur-i-kucek (LUR-ı KÜÇEK)","taraflar":["ilhanli","lur-i-kucek"],"etiket":["hanedan-degisimi","konu-siyasi"]}];

