window.KRONOLOJI_COK_MS1_1000_ASYA = [{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0023-01-01","b":"Wang Mang’ın saltanatı sona erdi; Kızıl Kaşlar Chang’an’ı aldı","tur":"siyasi","etiket":["siyaset","konu-siyasi","konu-hanedan"],"yer":"Chang’an","taraflar":["xin-hanedani"],"d":"Wang Mang’ın 9–23 arası kısa saltanatı gasp sayılır; sonunda Chang’an Kızıl Kaşlar çetesince ele geçirildi ve Wang Mang saray içinde öldürüldü (aynı sayfa).","kaynak":"Britannica, «History of China: The Han dynasty» (https://www.britannica.com/topic/history-of-China/The-Han-dynasty): «Wang Mang’s short reign from 9 to 23 may be described as an act of usurpation.»","gun":"23 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Longcheng"],"onem":3,"dunya":2,"kapsam":"ic","t":"0046-01-01","b":"Hun ülkesinde büyük kıtlık: devlet zayıflamaya başlar, hükümdar Çin'le anlaşmak zorunda kalır","tur":"siyasi","etiket":["konu-iktisat","konu-siyasi"],"yer":"Hun ülkesi (Moğolistan bozkırı)","taraflar":["hunnu-xiongnu"],"d":"TDV'ye göre MS 46'da Hun ülkesindeki büyük kıtlık devleti zayıflattı ve hükümdarı Çinlilerle ekonomik bakımdan anlaşmaya zorladı; bu zayıflama 48'deki bölünmenin zeminini hazırladı.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «milâttan sonra 46 yılında Hun ülkesinde çıkan büyük bir kıtlık yüzünden devlet zayıflamaya başlayınca»","gun":"46 (yıl; gün kaynakta yok)"},{"odak_yer":["Longcheng"],"onem":3,"dunya":2,"kapsam":"ic","t":"0048-01-01","b":"Güney Hun Devleti Çin'e bağlanır","tur":"vassal","etiket":["konu-siyasi"],"yer":"Güney Hun ülkesi (Ordos çevresi)","taraflar":["hunnu-xiongnu"],"d":"MS 48'deki bölünmeden sonra Güney Hun Devleti Çin'e bağlandı; ilk dönemde silik kaldı, Çinliler asıl olarak Kuzey Hunlarla uğraştı (bölünmenin kendisi künye iskeletindedir).","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «Milâttan sonra 48’de Çin’e bağlanan Güney Hun Devleti ilk zamanlarında silik durumdaydı»","gun":"48 (yıl; gün kaynakta yok)"},{"odak_yer":["Jolbon"],"onem":2,"dunya":1,"kapsam":"ic","t":"0053-01-01","b":"Goguryeo Kralı Taejo tahta çıktı; kalıtsal krallık sistemi oturdu (hükümdarlık 53-146)","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Goguryeo (Kuzey Kore / Güney Mançurya)","taraflar":["goguryeo"],"d":"Britannica, Kral Taejo'nun hükümdarlığı (53-146) sırasında Goguryeo'da kalıtsal kraliyet sisteminin kurulduğunu bildirir.","kaynak":"Britannica, «Goguryeo» (https://www.britannica.com/place/Goguryeo): «By the reign of King Taejo (53–146 CE), a royal hereditary system had been established.»","gun":"53 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pratishthana"],"onem":2,"dunya":2,"kapsam":"ic","t":"0130-01-01","b":"Vaşişthiputra Pulumavi Satavahana tahtına çıkar (hüküm yak. 130-159)","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Deccan","taraflar":["satavahana"],"d":"Büyük Satavahana hükümdarı Gautamiputra'nın oğlu Pulumavi batıdan hüküm sürdü; eğilim doğu ve kuzeydoğuya genişlemekti (Andhra'da yazıt ve sikkeleri bulunur).","kaynak":"Britannica, «Satavahana dynasty» (https://www.britannica.com/topic/Satavahana-dynasty): «Gautamiputra’s son Vashisthiputra Pulumavi (reigned c. 130–159) ruled from the west.»","gun":"130 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Uccayn"],"onem":2,"dunya":2,"kapsam":"ic","t":"0174-01-01","b":"Şri Yajna Satakarni dönemi (yak. 174-203): Satavahana'nın son önemli hükümdarı; Kşatrapalara karşı başarı","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Krişna-Godavari, Berar, Saurashtra","taraflar":["satavahana","sakalar-bati-satraplar"],"d":"Şri Yajna Satavahana hanedanının tarihindeki son önemli figürdür ve Kşatrapalara karşı başarı kazanmıştır; ardıllarının hâkimiyet alanı sınırlı kalmış, imparatorluk parçalanmıştır.","kaynak":"Britannica, «Satavahana dynasty» (https://www.britannica.com/topic/Satavahana-dynasty): «Shri Yajna Shatakarni’s (reigned c. 174–203)» ; «Shri Yajna is the last important figure in the history of the Satavahana dynasty.»","gun":"174 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":3,"dunya":1,"kapsam":"ic","t":"0189-01-01","b":"Haremağası katliamı: konsort aileleri ile haremağaları kavgası","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Luoyang","taraflar":["dogu-han"],"d":"Doğu Han’ın son yarım yüzyılında saray aileleri ile haremağalarının rekabeti 189’da haremağalarının katline vardı; Britannica’ya göre bölge valileri merkezden neredeyse bağımsızlaştı.","kaynak":"Britannica, «History of China: The Han dynasty» (https://www.britannica.com/topic/history-of-China/The-Han-dynasty): «Rivalry between consorts’ families and eunuchs led to a massacre of the latter in 189»","gun":"189 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":4,"dunya":2,"kapsam":"ic","t":"0207-01-01","b":"Cao Cao Kuzey Çin’in denetimini ele geçirdi","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Kuzey Çin","taraflar":["dogu-han","cao-wei"],"d":"Han generali Cao Cao 207’ye kadar kuzeyde denetimi kurdu; Britannica, Kızıl Kayalık’ta Sun Quan’a yenilmeseydi tek hanedan altında birleştirebileceğini yazar.","kaynak":"Britannica, «History of China: The Han dynasty» (https://www.britannica.com/topic/history-of-China/The-Han-dynasty): «By 207 the great Han general Cao Cao had gained control over the north»","gun":"207 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pungnaptoseong (Wiryeseong/Hanseong, Seul)"],"onem":2,"dunya":1,"kapsam":"ic","t":"0234-01-01","b":"Baekje Kralı Koi tahta çıktı; Baekje tam gelişmiş krallık oldu (hükümdarlık 234-286)","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Baekje (Güneybatı Kore)","taraflar":["baekje"],"d":"Britannica, 3. yüzyılda Kral Koi döneminde (234-286) Baekje'nin tam gelişmiş bir krallık olarak ortaya çıktığını yazar.","kaynak":"Britannica, «Baekje» (https://www.britannica.com/place/Baekje): «By the 3rd century CE, during the reign of King Koi (234–286), Baekje emerged as a fully developed kingdom.»","gun":"234 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":2,"dunya":2,"kapsam":"dis","t":"0285-01-01","b":"Jin sarayı Fergana hükümdarına kral unvanı vermek üzere elçi gönderdi","tur":"diplomasi","etiket":["diplomasi","konu-diplomasi"],"yer":"Fergana (Orta Asya)","taraflar":["bati-jin"],"d":"Batı Jin’in kısa düzen döneminde Orta Asya vaha krallıkları ve güneyde Funan ile Champa ile temaslar yenilendi; 285’te Fergana’ya elçi gönderildi.","kaynak":"Britannica, «History of China: The Six Dynasties» (https://www.britannica.com/topic/history-of-China/The-Six-Dynasties): «in 285 the Jin court even sent an envoy to distant Fergana in Central Asia to confer the title of king»","gun":"285 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":4,"dunya":3,"kapsam":"ic","t":"0303-01-01","b":"Kuzey Çin’de Yabancı hanedanlar (On Altı Krallık) dönemi başladı","tur":"bolunme","etiket":["siyaset","konu-siyasi"],"yer":"Kuzey Çin","taraflar":["bati-jin"],"d":"Britannica geleneksel On Altı Krallık’ı Xiongnu, Xianbei, Di, Qiang vb. kavimlerin 303’ten itibaren kuzeyin tamamına ya da bir bölümüne hükmeden kısa ömürlü devletleri diye tanımlar.","kaynak":"Britannica, «History of China: The Six Dynasties» (https://www.britannica.com/topic/history-of-China/The-Six-Dynasties): «The term Sixteen Kingdoms traditionally denotes the plethora of short-lived non-Chinese dynasties that from 303 came to rule»","gun":"303 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pungnaptoseong (Wiryeseong/Hanseong, Seul)"],"onem":3,"dunya":1,"kapsam":"ic","t":"0346-01-01","b":"Baekje Kralı Geunchogo tahta çıktı; Han Nehri havzasının tamamı Baekje denetimine girdi (346-375)","tur":"hukumdar","etiket":["konu-askeri"],"yer":"Han Nehri havzası (Orta Kore)","taraflar":["baekje"],"d":"Kral Geunchogo (346-375) döneminde Baekje, Han Nehri havzasının bütününü denetimine aldı.","kaynak":"Britannica, «Baekje» (https://www.britannica.com/place/Baekje): «By the reign of King Geonchogo (346–375), it had established control over a region that included the whole Han River basin»","gun":"346 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Patna (Azîmâbâd)"],"onem":3,"dunya":2,"kapsam":"dis","t":"0350-01-01","b":"Samudragupta, Pallava kralı Vişnugopa'yı yener ve tahtına iade eder (4. yy ortası)","tur":"savas","etiket":["konu-askeri","yaklasik"],"yer":"Kançipuram","taraflar":["gupta","pallava"],"d":"Britannica'ya göre Pallava kralı Vişnugopa Gupta imparatoru Samudragupta tarafından yenilmiş, sonra serbest bırakılmıştır; olay yaklaşık 4. yüzyıl ortasına tarihlenir.","kaynak":"Britannica, «Pallava dynasty» (https://www.britannica.com/topic/Pallava-dynasty): «King Vishnugopa, who was defeated and then liberated by Samudra Gupta, the emperor of Magadha, about the middle of the 4th century CE.»","gun":"yaklaşık 350 (yüzyıl ortası; gün/yıl kaynaktan alınmadı)"},{"odak_yer":["Kyongcu"],"onem":3,"dunya":1,"kapsam":"ic","t":"0356-01-01","b":"Silla Kralı Naemul tahta çıktı; Kim hanedanının kalıtsal krallığı kuruldu (356-402)","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Silla (Güneydoğu Kore)","taraflar":["silla"],"d":"Britannica, Silla'nın Kim ailesinin kalıtsal monarşisinin Kral Naemul döneminde (356-402) kurulduğunu belirtir.","kaynak":"Britannica, «Silla» (https://www.britannica.com/place/Silla): «With the establishment of the hereditary monarchy of the Kim family during the reign of King Naemul (356–402)»","gun":"356 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pannonia"],"onem":3,"dunya":3,"kapsam":"dis","t":"0370-01-01","b":"İdil boyundaki Hunların başında Balamir bulunur (Avrupa Hun hareketi)","tur":"siyasi","etiket":["konu-siyasi"],"yer":"İdil (Volga) boyu","taraflar":["hun-avrupa"],"d":"TDV, 370'li yıllarda İdil boyundaki Hunların başında Balamir'in bulunduğunu bildirir; Hunlar bu sıralarda batıya, Karadeniz kuzeyi ve Tuna'ya doğru ilerledi.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «370’li yıllarda İdil boyundaki Hunlar’ın başında Balamir vardı.»","gun":"370'li yıllar (yıl; kesin yıl kaynakta yok)"},{"odak_yer":["Jolbon"],"onem":3,"dunya":1,"kapsam":"ic","t":"0371-01-01","b":"Goguryeo Kralı Sosurim tahta çıktı; merkezîleştirici yasalar çıkardı (371-384)","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Goguryeo","taraflar":["goguryeo"],"d":"Sosurim (371-384) döneminde çıkarılan yasa ve kararnameler Goguryeo'yu tam teşekküllü aristokratik devlet yaptı.","kaynak":"Britannica, «Goguryeo» (https://www.britannica.com/place/Goguryeo): «With the promulgation by King Sosurim (reigned 371–384) of various laws and decrees aimed at centralizing royal authority»","gun":"371 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Jolbon"],"onem":3,"dunya":2,"kapsam":"ic","t":"0372-01-01","b":"Goguryeo'ya Budizm girdi","tur":"din","etiket":["konu-din"],"yer":"Goguryeo","taraflar":["goguryeo"],"d":"Çin etkisiyle Budizm, yeni gelişen merkezî bürokrasinin ideolojik dayanağı olarak 372'de Goguryeo'ya girdi.","kaynak":"Britannica, «Goguryeo» (https://www.britannica.com/place/Goguryeo): «Buddhism was introduced in 372 CE as an ideological backing for the newly developed centralized bureaucracy»","gun":"372 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Edirne"],"onem":4,"dunya":4,"kapsam":"dis","t":"0378-01-01","b":"Edirne yakınında Vizigotlar ve Hunlar Bizans'ı yener, İmparator Valens ölür","tur":"savas","etiket":["konu-askeri"],"yer":"Edirne yakını (Adrianopolis)","taraflar":["hun-avrupa"],"d":"TDV'ye göre 378'de Edirne civarındaki savaşta Vizigotlar ve Hunlar Bizans ordusunu yendi, İmparator Valens öldürüldü.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «378’de Edirne civarında yapılan savaşta Vizigotlar’la Hunlar, Bizans’ı yenip imparatorları Valens’i öldürdüler.»","gun":"378 (yıl; gün kaynakta yok)"},{"odak_yer":["Jolbon"],"onem":4,"dunya":2,"kapsam":"ic","t":"0391-01-01","b":"Gwanggaeto Goguryeo tahtına çıktı; topraklar büyük ölçüde genişledi (391-412)","tur":"hukumdar","etiket":["konu-askeri"],"yer":"Goguryeo","taraflar":["goguryeo"],"d":"Kral Gwanggaeto döneminde (391-412) Goguryeo toprakları büyük ölçüde genişledi; Jangsu (413-491) bunu sürdürdü.","kaynak":"Britannica, «Goguryeo» (https://www.britannica.com/place/Goguryeo): «Its territory was extended greatly during the reign of King Gwanggaeto (391–412) and further by Jangsu»","gun":"391 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Jolbon"],"onem":3,"dunya":1,"kapsam":"ic","t":"0413-01-01","b":"Jangsu Goguryeo tahtına çıktı (413-491); Kore yarımadasının kuzey yarısı ve Liaodong Goguryeo'nun elinde","tur":"hukumdar","etiket":["konu-askeri"],"yer":"Goguryeo","taraflar":["goguryeo"],"d":"Jangsu (413-491) Goguryeo'nun topraklarını daha da genişletti; zirve dönemde yarımadanın kuzey yarısı ile Liaodong ve Mançurya'nın önemli bölümü Goguryeo yönetimindeydi.","kaynak":"Britannica, «Goguryeo» (https://www.britannica.com/place/Goguryeo): «further by Jangsu (reigned 413–491). The entire northern half of the Korean peninsula»","gun":"413 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pannonia"],"onem":4,"dunya":4,"kapsam":"dis","t":"0433-01-01","b":"Hun hükümdarı Rua ölür; Attila ve Bleda başa geçer","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Orta Tuna ve Tisa havzası","taraflar":["hun-avrupa"],"d":"Orta Tuna ve Tisa havzasına hâkim olan Rua 433'te ölünce Hunların başına Muncuk'un oğulları Attila ve Bleda geçti.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «Rua 433’te ölünce Hunlar’ın başına Muncuk’un oğulları Attila ve Bleda geçti.»","gun":"433 (yıl; gün kaynakta yok)"},{"odak_yer":["Kançipuram"],"onem":2,"dunya":1,"kapsam":"ic","t":"0436-01-01","b":"Pallava kralı Simhavarman'ın saltanatı başlar (Lokavibhaga'ya göre 436)","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Kançipuram","taraflar":["pallava"],"d":"Sanskritçe Lokavibhaga eserinde Pallava kralı Simhavarman'ın 436'dan itibaren hüküm sürdüğü belirtilir; Pallava kronolojisi Britannica'ya göre çok tartışmalıdır.","kaynak":"Britannica, «Pallava dynasty» (https://www.britannica.com/topic/Pallava-dynasty): «A later Pallava king, Simhavarman, is mentioned in the Sanskrit Lokavibhaga as reigning from 436 CE.»","gun":"436 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pannonia"],"onem":4,"dunya":4,"kapsam":"dis","t":"0445-01-01","b":"Bleda ölür; Attila Hunların tek hâkimi olur","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Orta Tuna havzası","taraflar":["hun-avrupa"],"d":"Attila ile ortak yönetimdeki Bleda 445'te ölünce Attila tek başına Hun hükümdarı oldu.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «445 yılında Bleda ölünce Attila tek hâkim oldu.»","gun":"445 (yıl; gün kaynakta yok)"},{"odak_yer":["Pannonia"],"onem":4,"dunya":4,"kapsam":"dis","t":"0447-01-01","b":"Attila'nın Balkan seferi: Theodosios ağır tazminat ve yıllık vergiyle barış yapar","tur":"antlasma","etiket":["konu-askeri","konu-diplomasi"],"yer":"Balkanlar","taraflar":["hun-avrupa"],"d":"Attila 447'deki büyük Balkan seferinde Bizans'ı bozguna uğrattı; İmparator Theodosios 6000 libre altın savaş tazminatı ve 2100 libre yıllık vergi karşılığında barış yaptı.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «447’de çıktığı büyük Balkan seferinde Attila, bozguna uğrattığı İmparator Theodosios’la 6000 libre altın savaş tazminatı»","gun":"447 (yıl; gün kaynakta yok)"},{"odak_yer":["Tohâristân"],"onem":3,"dunya":3,"kapsam":"dis","t":"0457-01-01","b":"Eftalit hanı Kün-han, Fîrûz'u Sâsânî tahtına çıkarır","tur":"siyaset","etiket":["konu-siyasi"],"yer":"İran / Tohâristân","taraflar":["eftalit"],"d":"TDV'ye göre Eftal hânedanından Kün-han, İran'ın iç işlerine karışıp nüfuzu altına aldığı veliaht Fîrûz'u Sâsânî hükümdarı yaptı (457).","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «Akhunlar’ın Eftal (Abdel) hânedanından Kün-han, İran’ın iç işlerine karışarak nüfuzu altına aldığı veliaht Fîrûz’u Sâsânî hükümdarı yaptı (457).»","gun":"457 (yıl; gün kaynakta yok)"},{"yer_id":"İstanbul","onem":3,"dunya":3,"kapsam":"dis","t":"0468-01-01","b":"Attila'nın oğlu Dengizik Bizans'a yenilir ve İstanbul'da idam edilir","tur":"savas","etiket":["konu-askeri"],"yer":"Balkanlar / İstanbul","taraflar":["hun-avrupa"],"d":"Hun devleti Attila'nın ölümünden sonra dağılırken oğlu Dengizik 468'de Bizans'a yenildi, esir düştü ve İstanbul'a getirilip idam edildi. TDV'nin başka maddesi Batı Hun devleti için 374-469 aralığını verir.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «Diğer oğlu Dengizik 468 yılında Bizanslılar’a yenildi ve esir düştü»","gun":"468 (yıl; gün kaynakta yok)"},{"odak_yer":["Datong"],"onem":4,"dunya":2,"kapsam":"ic","t":"0471-01-01","b":"Xiaowendi Kuzey Wei tahtına çıktı","tur":"hukumdar","etiket":["hukumdar","konu-kisiler","konu-hanedan"],"yer":"Pingcheng","taraflar":["kuzey-wei"],"d":"Kuzey Wei’nin yedinci imparatoru Xiaowendi 471’de tahta çıktı; 490’a kadar fiilî güç büyükannesindeydi.","kaynak":"Britannica, «Xiaowendi» (https://www.britannica.com/biography/Xiaowendi): «When Xiaowendi ascended the throne in 471»","gun":"471 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Datong"],"onem":4,"dunya":2,"kapsam":"ic","t":"0485-01-01","b":"Xiaowendi juntian (eşit tarla) toprak sistemini başlattı","tur":"reform","etiket":["islahat","konu-islahat","konu-idari"],"yer":"Kuzey Wei","taraflar":["kuzey-wei"],"d":"Her köylü aileye yaklaşık 140 mou toprak verildi; toprağın çoğu ölüm ya da emeklilikte devlete dönüyordu. Sistem Sui ve Tang’ın mali temelini hazırladı.","kaynak":"Britannica, «Xiaowendi» (https://www.britannica.com/biography/Xiaowendi): «In 485 he instituted a juntian (“equal-field”) system of agriculture»","gun":"485 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Datong"],"onem":2,"dunya":1,"kapsam":"ic","t":"0490-01-01","b":"Xiaowendi’nin büyükannesi öldü; imparator fiilî iktidarı aldı","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Kuzey Wei sarayı","taraflar":["kuzey-wei"],"d":"Fiilî yönetim önce büyükannesindeydi; 490’da onun ölümünden sonra Xiaowendi Çinleştirme politikalarını (Yuan soyadı, Luoyang’a taşınma, Çin dili) uyguladı.","kaynak":"Britannica, «Xiaowendi» (https://www.britannica.com/biography/Xiaowendi): «the actual power was first in the hands of his grandmother until she died in 490»","gun":"490 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Angkor Borei"],"onem":4,"dunya":2,"kapsam":"ic","t":"0500-01-01","b":"Funan, Çin kayıtlarına göre Zhenla (Çenla) tarafından ele geçiriliyor","tur":"bolunme","etiket":["konu-siyasi"],"yer":"Güney Kamboçya (Mekong deltası)","taraflar":["funan","chenla"],"d":"Çin kayıtlarına göre güney Kamboçya merkezli ticaret devleti Funan 6. yüzyıl içinde Zhenla tarafından ele geçirildi. Zhenla ile erken Khmer merkezleri arasındaki ilişki belirsizdir.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «According to Chinese records, Funan, a prosperous trading polity centered in southern Cambodia, is overtaken by Zhenla.»","gun":"500-600 (yıl aralığı; gün yok)"},{"odak_yer":["Üstyurt platosu"],"onem":3,"dunya":1,"kapsam":"ic","t":"0514-01-01","b":"Silla Kralı Beopheung tahta çıktı (514-540); Gaya'nın doğu yarısı bu dönemde Silla'ya katıldı","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Silla / Gaya","taraflar":["silla"],"d":"Britannica, Gaya'nın doğu yarısının Kral Beopheung döneminde (514-540) Silla'ya katılmasının Silla'yı tam krallık yaptığını belirtir.","kaynak":"Britannica, «Silla» (https://www.britannica.com/place/Silla): «the annexation of the eastern half of the Gaya state on the eastern tip of the peninsula in the reign of King Beopheung (514–540)»","gun":"514 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Üstyurt platosu"],"onem":3,"dunya":1,"kapsam":"ic","t":"0532-01-01","b":"Silla, Gaya konfederasyonunun doğu yarısını boyunduruk altına aldı","tur":"toprak-kazanc","etiket":["konu-askeri"],"yer":"Naktong Nehri havzası (Güneydoğu Kore) — Gaya","taraflar":["silla"],"d":"Naktong Nehri'nin batısındaki Gaya kabile birliğinin doğu yarısı 532'de Silla'ya tâbi kılındı. Gaya için ayrı künye yoktur; madde Silla'ya bağlıdır.","kaynak":"Britannica, «Kaya» (https://www.britannica.com/topic/Kaya-ancient-Korean-tribal-league): «Silla subjugated the eastern half of the kingdom in 532 and the western half in 562.»","gun":"532 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyongcu"],"onem":2,"dunya":1,"kapsam":"ic","t":"0540-01-01","b":"Silla Kralı Jinheung tahta çıktı (540-576); Hwarang askerî birliği kuruldu","tur":"hukumdar","etiket":["konu-askeri"],"yer":"Silla","taraflar":["silla"],"d":"Kral Jinheung döneminde (540-576) Hwa Rang Do adlı özel askerî birlik örgütlendi ve ordu yeniden düzenlendi.","kaynak":"Britannica, «Silla» (https://www.britannica.com/place/Silla): «In the reign of King Jinheung (540–576) a unique military corps, called the Hwa Rang Do, was organized»","gun":"540 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Hanoi (Thăng Long)"],"onem":4,"dunya":2,"kapsam":"ic","t":"0544-01-01","b":"Ly Bon Erken Ly hanedanını (Van Xuan) kuruyor","tur":"kurulus","etiket":["konu-kurulus"],"yer":"Kuzey Vietnam","taraflar":["van-xuan"],"d":"Ly Bon'un kurduğu Erken Ly hanedanı 544'ten 602/603'e kadar sürdü.","kaynak":"Britannica, «Early Ly dynasty» (https://www.britannica.com/topic/Early-Ly-dynasty): «the Earlier Ly dynasty, founded by Ly Bon and lasting from 544 to 602/603»","gun":"544 (yıl; gün kaynaktan alınmadı)"},{"onem":3,"dunya":3,"kapsam":"dis","t":"0558-01-01","b":"Avarlar Bizans'a elçi gönderip yerleşecek toprak ister","tur":"diplomasi","etiket":["konu-diplomasi"],"yer":"Kafkasya / Bizans","taraflar":["avar"],"d":"Kafkasya'da Alanları kendilerine bağlayan Avarlar 558'de Bizans'a elçiler göndererek topraklarında yerleşmek için bir bölge talep etti.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «Avarlar, 558’de Bizans’a elçiler göndererek topraklarında yerleşmek için bir bölge talep ettiler.»","gun":"558 (yıl; gün kaynakta yok)"},{"odak_yer":["Karakurum"],"onem":2,"dunya":2,"kapsam":"ic","t":"0558-01-01","b":"Kırgızlar Göktürk Devleti'ne bağlanır","tur":"tabi","etiket":["konu-siyasi"],"yer":"Yenisey havzası","taraflar":["gokturk-1","yenisey-kirgiz"],"d":"TDV'nin Türk maddesine göre Kırgızlar 558'de Göktürk Devleti'ne bağlandı; TDV'nin Kırgızlar maddesi aynı bağlanmayı Mukan Hakan zamanında 560 olarak verir.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «milâttan sonra 558’de Göktürk Devleti’ne bağlandılar»","gun":"558 (yıl; gün kaynakta yok)"},{"odak_yer":["Üstyurt platosu"],"onem":3,"dunya":1,"kapsam":"ic","t":"0562-01-01","b":"Silla, Gaya konfederasyonunun batı yarısını da boyunduruk altına aldı; Gaya sona erdi","tur":"toprak-kazanc","etiket":["konu-askeri"],"yer":"Gaya (Güney Kore)","taraflar":["silla"],"d":"Gaya'nın batı yarısının 562'de Silla'ya tâbi kılınmasıyla Gaya siyaseten ortadan kalktı. Gaya için ayrı künye yoktur.","kaynak":"Britannica, «Kaya» (https://www.britannica.com/topic/Kaya-ancient-Korean-tribal-league): «Silla subjugated the eastern half of the kingdom in 532 and the western half in 562.»","gun":"562 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Macaristan","İtalya"],"onem":4,"dunya":3,"kapsam":"dis","t":"0568-01-01","b":"Longobardlar İtalya'ya çekilir; Macaristan toprakları Avarlara kalır","tur":"toprak-kazanc","etiket":["konu-askeri"],"yer":"Pannonia (Macaristan)","taraflar":["avar"],"d":"568'den itibaren Longobardların Kuzey İtalya'ya göçmesiyle Macaristan toprakları Avarlara kaldı; Avarlar imparatorluklarını Orta Avrupa'da pekiştirdi.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «568’den itibaren Longobardlar’ın Kuzey İtalya’ya göçmesiyle Macaristan toprakları Avarlar’a kaldı.»","gun":"568 (yıl; gün kaynakta yok)"},{"odak_yer":["Ye"],"onem":4,"dunya":2,"kapsam":"ic","t":"0577-01-01","b":"Kuzey Zhou Kuzey Qi’yi fethedip kuzeyi birleştirdi","tur":"toprak-kazanc","etiket":["askeri","toprak-kazanc","konu-askeri"],"yer":"Kuzey Çin","taraflar":["kuzey-zhou","kuzey-qi"],"d":"Britannica’ya göre 577’de Bei Zhou, rakip kuzeydoğu hanedanı Bei Qi’yi fethederek Kuzey Çin’i yeniden birleştirdi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 577 the Bei Zhou had reunified northern China by conquering the rival northeastern dynasty of Bei Qi.»","gun":"577 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":1,"kapsam":"ic","t":"0579-01-01","b":"Yang Jian çocuk bir imparatoru kukla olarak tahta çıkardı","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Chang’an","taraflar":["kuzey-zhou","sui"],"d":"Wendi (Yang Jian), 579’da çocuk bir imparatoru kukla olarak yerleştirdi ve iki yıl sonra tahtı kendisi aldı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «Wendi was able to install a child as puppet emperor in 579 and seize the throne for himself two years later.»","gun":"579 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":3,"dunya":2,"kapsam":"ic","t":"0581-01-01","b":"Sui, 581 Ceza Kanunu’nu ilan etti","tur":"kanun","etiket":["kanun","konu-idari"],"yer":"Chang’an","taraflar":["sui"],"d":"Wendi’nin imparator olduktan sonraki ilk işlerinden biri yeni bir ceza kanunu (New Code of 581) çıkarmak oldu.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «one of his first acts on becoming emperor was to promulgate a penal code, the New Code of 581»","gun":"581 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":5,"dunya":3,"kapsam":"ic","t":"0581-03-04","b":"Yang Jian tahtta divan kurdu; Sui Hanedanı resmen kuruldu","tur":"kurulus","etiket":["kurulus","konu-siyasi","konu-hanedan"],"yer":"Chang’an (Daxing)","taraflar":["sui","kuzey-zhou"],"d":"Britannica Wendi maddesi, Yang Jian’ın 4 Mart 581’de imparatorluk unvanıyla divan kurduğunu ve Sui hanedanının kurulduğunu yazar. Künyedeki gün (581-03-04) bu kaynakla uyuşur.","kaynak":"Britannica, «Wendi (Sui)» (https://www.britannica.com/biography/Wendi-emperor-of-Sui-dynasty): «He assumed the imperial title, held an audience on March 4, 581, and the Sui dynasty was founded.»","gun":"0581-03-04 (kaynak günü Batı takvimiyle verir)"},{"odak_yer":["Luoyang"],"onem":4,"dunya":3,"kapsam":"ic","t":"0583-01-01","b":"Kaihuang Kanunu ve idari tüzük derlendi","tur":"kanun","etiket":["kanun","konu-idari"],"yer":"Sui","taraflar":["sui"],"d":"583’te bakanlar gözden geçirilmiş Kaihuang Kanunu ile idari tüzükleri derledi; Tang kanununa örnek oldu (Britannica).","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 583 his ministers compiled a revised code, the Kaihuang Code, and administrative statutes.»","gun":"583 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":3,"dunya":1,"kapsam":"ic","t":"0587-01-01","b":"Sui, Sonraki Liang imparatorunu tahttan indirdi","tur":"toprak-kazanc","etiket":["askeri","toprak-kazanc","konu-askeri"],"yer":"Orta Yangtze","taraflar":["sui"],"d":"Wendi 587’de, 555’ten beri Bei Zhou’nun kuklası olarak orta Yangtze vadisini yöneten Hou Liang imparatorunu tahttan indirdi; iki yıl sonra Chen’i yendi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 587 he dethroned the emperor of the Hou (Later) Liang»","gun":"587 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Indrapura"],"onem":3,"dunya":2,"kapsam":"ic","t":"0600-01-01","b":"Champa'nın My Son'unda en eski yapılar inşa ediliyor","tur":"siyasi","etiket":["konu-kultur","arkeoloji"],"yer":"My Son (Orta Vietnam)","taraflar":["linyi-champa"],"d":"Yaklaşık 600-700 arasında Champa'nın My Son merkezinde ilk yapılar inşa edildi; bölge yüzyıllarca önemli merkez kaldı.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «The earliest buildings are constructed at My Son in Champa (central Vietnam).»","gun":"600-700 (arkeoloji/yıl aralığı; gün yok)"},{"odak_yer":["Hanoi (Thăng Long)"],"onem":3,"dunya":2,"kapsam":"ic","t":"0602-01-01","b":"Erken Ly hanedanı sona eriyor (602/603)","tur":"hanedan","etiket":["konu-son"],"yer":"Kuzey Vietnam","taraflar":["van-xuan"],"d":"Ly Bon'un kurduğu Erken Ly hanedanı 602/603'te sona erdi.","kaynak":"Britannica, «Early Ly dynasty» (https://www.britannica.com/topic/Early-Ly-dynasty): «the Earlier Ly dynasty, founded by Ly Bon and lasting from 544 to 602/603»","gun":"602/603 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pannonia"],"onem":2,"dunya":2,"kapsam":"dis","t":"0602-01-01","b":"Bizans'ta Fokas isyanı Avarların imdadına yetişir","tur":"siyaset","etiket":["konu-askeri"],"yer":"Tisa / Tuna hattı","taraflar":["avar"],"d":"Tisa'ya kadar takip edilen Avarların imdadına Bizans ordusunda patlak veren Fokas isyanı yetişti (602).","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «Tisa nehrine kadar takip edilen Avarlar’ın imdadına Bizans ordusunda patlak veren Fokas isyanı yetişti (602).»","gun":"602 (yıl; gün kaynakta yok)"},{"odak_yer":["Luoyang"],"onem":4,"dunya":2,"kapsam":"ic","t":"0604-01-01","b":"Wendi öldü; Yangdi Sui tahtına çıktı","tur":"hukumdar","etiket":["hukumdar","konu-kisiler","konu-hanedan"],"yer":"Sui","taraflar":["sui"],"d":"Yangdi 604’te tahta çıktı; Britannica genel kanının, babası ve ağabeyini öldürterek tahta geçtiği yönünde olduğunu belirtir.","kaynak":"Britannica, «Yangdi» (https://www.britannica.com/biography/Yangdi): «He acceded to the throne in 604, and it is generally agreed that he did so after assassinating his father»","gun":"604 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":2,"dunya":1,"kapsam":"ic","t":"0607-01-01","b":"Sui Shanxi’de Büyük Sur’u onarıp güçlendirdi","tur":"askeri","etiket":["siyaset"],"yer":"Shanxi","taraflar":["sui"],"d":"607–608’de doğu Türklerine karşı önlem olarak Shanxi’de Büyük Sur’u yeniden inşa için kitlesel angarya uygulandı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «labor required to rebuild and strengthen the Great Wall in Shanxi in 607 and 608»","gun":"607 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Hangzhou"],"onem":3,"dunya":2,"kapsam":"ic","t":"0610-01-01","b":"Büyük Kanal Yangtze’nin güneyinde Hangzhou’ya uzatıldı","tur":"idari","etiket":["idari","konu-idari"],"yer":"Hangzhou","taraflar":["sui"],"d":"605’te Luoyang–Yangtze kanal sistemi açıldı, 610’da Hangzhou’ya uzatıldı; 611’de doğu ovasının bütün büyük nehirleri kanallarla bağlandı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «in 610 it was extended south of the Yangtze to Hangzhou as part of a general effort to rehabilitate and lengthen the Grand Canal»","gun":"610 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Badami"],"onem":3,"dunya":2,"kapsam":"ic","t":"0610-01-01","b":"II. Pulakeşin Badami Çalukya tahtında (yak. 610-642); Gujarat ve Malwa'nın bir kısmını alır","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Badami (Vatapi)","taraflar":["badami-calukya"],"d":"II. Pulakeşin Gujarat ve Malwa'nın bir kısmını aldı ve Kannauj'lu Harşa'ya meydan okudu; iki devlet arasındaki sınır Narmada Nehri'nde belirlendi.","kaynak":"Britannica, «Chalukya dynasty» (https://www.britannica.com/topic/Chalukya-dynasty): «Pulakeshin II (reigned c. 610–642) acquired parts of Gujarat and Malwa and defied the north Indian ruler Harsa of Kannauj»","gun":"610 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Angkor"],"onem":3,"dunya":2,"kapsam":"ic","t":"0612-01-01","b":"Angkor Borei'de Khmer dilindeki ilk yazıt oyuluyor","tur":"siyasi","etiket":["konu-kultur"],"yer":"Angkor Borei","taraflar":["chenla"],"d":"Khmer dilinde bilinen ilk yazıt Angkor Borei'de oyuldu; Chenla dönemi yerli kaynaklarının başlangıcıdır.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «The first inscription in the Khmer language is carved at Angkor Borei.»","gun":"612 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":3,"dunya":2,"kapsam":"dis","t":"0615-01-01","b":"Yangdi Yanmen’de Türkler tarafından kuşatıldı","tur":"kusatma","etiket":["askeri","konu-askeri"],"yer":"Yanmen (Shanxi)","taraflar":["sui"],"d":"615 yazında Büyük Sur savunmasını denetlerken Yangdi doğu Türklerince Yanmen’de kuşatıldı ve bir ay sonra kurtarıldı; Sui’nin güç kaybını gösterdi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «in the summer of 615 Yangdi went to inspect the defenses of the Great Wall, he was surrounded and besieged by the Turks at Yanmen»","gun":"615 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":3,"dunya":1,"kapsam":"ic","t":"0616-01-01","b":"Yangdi güney başkenti Jiangdu’ya çekildi; kuzey asi rejimlere bölündü","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Jiangdu (Yangzhou)","taraflar":["sui"],"d":"616 sonunda Yangdi Jiangdu’ya çekildi; kuzeydeki toprakların büyük kısmı birbiriyle yarışan asi rejimlerin eline geçti.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «Late in 616 Yangdi decided to withdraw to his southern capital of Jiangdu»","gun":"616 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["İtalya"],"onem":2,"dunya":2,"kapsam":"dis","t":"0616-01-01","b":"Avarlar Longobardlarla birlikte İtalya'ya akınlar yapar","tur":"askeri","etiket":["konu-askeri"],"yer":"İtalya","taraflar":["avar"],"d":"Avarlar Bizans'a karşı Longobardlarla birlikte hareket etti ve 616'dan sonra İtalya'ya akınlar yaptı.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «Avarlar, Bizans’a karşı Longobardlar’la birlikte hareket ettiler ve 616’dan sonra İtalya’ya akınlar yaptılar.»","gun":"616 (yıl; gün kaynakta yok)"},{"odak_yer":["Luoyang"],"onem":4,"dunya":2,"kapsam":"ic","t":"0618-01-01","b":"Yangdi Jiangdu’da maiyeti tarafından öldürüldü","tur":"olum","etiket":["hukumdar","konu-kisiler"],"yer":"Jiangdu (Yangzhou)","taraflar":["sui"],"d":"Yangdi 618 baharına kadar ad olarak imparator kaldı, sonra Jiangdu’da maiyetinden kişilerce öldürüldü; Li Yuan aynı yaz Tang’ı ilan etti.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «Yangdi remained nominally emperor until the spring of 618, when he was murdered by members of his entourage at Jiangdu.»","gun":"618 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Badami"],"onem":3,"dunya":3,"kapsam":"dis","t":"0620-01-01","b":"Harşa Dekan'a yürür, II. Pulakeşin tarafından Narmada'ya geri püskürtülür (yak. 620)","tur":"savas","etiket":["konu-askeri","yaklasik"],"yer":"Narmada Nehri","taraflar":["harsha","badami-calukya"],"d":"Harşa Dekan'ı fethetmeye çalıştı (yak. 620) ancak Çalukya imparatoru II. Pulakeşin tarafından Narmada Nehri'ne kadar geri sürüldü.","kaynak":"Britannica, «Harsha» (https://www.britannica.com/biography/Harsha): «He attempted to conquer the Deccan (c. 620) but was driven back to the Narmada River by the Chalukya emperor Pulakeshin II.»","gun":"620 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0621-01-01","b":"Li Shimin Dou Jiande’yi yenip yakaladı; Wang Shichong teslim oldu","tur":"toprak-kazanc","etiket":["askeri","toprak-kazanc","konu-askeri"],"yer":"Hebei / Luoyang","taraflar":["tang"],"d":"621 baharında Li Shimin, Luoyang kuşatmasını kaldırmaya gelen Dou Jiande’yi bozguna uğrattı; Wang Shichong teslim oldu ve Tang doğu ovasının çoğunu ele geçirdi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «in the spring of 621 Li Shimin attacked his army before it could lift the siege, routed it, and captured Dou.»","gun":"621 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":1,"kapsam":"ic","t":"0621-01-01","b":"Xiao Xian Tang’a teslim oldu; orta Yangtze ve uzak güney Tang’a geçti","tur":"toprak-kazanc","etiket":["askeri","toprak-kazanc","konu-askeri"],"yer":"Orta Yangtze","taraflar":["tang"],"d":"Sui sonrası karışıklıkta Liang imparatoru olan Xiao Xian, Yangtze’den inen Tang donanmasınca iki deniz savaşında yenildi ve teslim oldu.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 621 Xiao Xian surrendered to the Tang, who thus gained control of the central Yangtze and the far south.»","gun":"621 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":2,"dunya":1,"kapsam":"ic","t":"0623-01-01","b":"Liu Heita yenildi; Hebei isyanı bastırıldı","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Hebei","taraflar":["tang"],"d":"Dou Jiande yandaşlarının 621 sonunda yeniden çıkardığı isyan, veliaht Jiancheng komutasındaki Tang ordusunca 623 başında bastırıldı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «He was finally defeated by a Tang army under the crown prince Jiancheng at the beginning of 623.»","gun":"623 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":3,"kapsam":"ic","t":"0624-01-01","b":"Tang kanunlarının yeni kodifikasyonu tamamlandı","tur":"kanun","etiket":["kanun","konu-idari"],"yer":"Chang’an","taraflar":["tang"],"d":"Gaozu, merkezî hukukun tamamını yeniden derletti: kanun, tüzük, yönetmelik ve genelge; Britannica Tang hukukunu Japonya, Kore ve Vietnam’a örnek olan idari düzenin temeli sayar.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «Gaozu also undertook a new codification of all centralized law, completed in 624.»","gun":"624 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":2,"dunya":1,"kapsam":"ic","t":"0624-01-01","b":"Fu Gongtuo isyanı bastırıldı; Tang birliği tamam","tur":"isyan","etiket":["isyan","konu-isyan"],"yer":"Danyang (Nanjing)","taraflar":["tang"],"d":"624’te Danyang’da bağımsız rejim kuran general Fu Gongtuo hızla bastırıldı; Britannica on yıllık savaş ve karışıklıktan sonra imparatorluğun tamamen sulha ulaştığını söyler.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «A last southern rebellion by Fu Gongtuo, a general who set up an independent regime at Danyang (Nanjing) in 624, was speedily suppressed.»","gun":"624 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pedavegi"],"onem":3,"dunya":2,"kapsam":"ic","t":"0624-01-01","b":"II. Pulakeşin Vengi'yi Vişnukundinlerden alır, kardeşi Kubja Vişnuvardhana'yı Doğu Çalukya'nın ilk kralı yapar (yak. 624)","tur":"kurulus","etiket":["konu-siyasi","yaklasik"],"yer":"Vengi (Doğu Andhra)","taraflar":["dogu-calukya","badami-calukya"],"d":"Pulakeşin yak. 624'te Vengi krallığını Vişnukundinlerden alıp kardeşi Kubja Vişnuvardhana'ya verdi; bu, Doğu Çalukya (Vengi) hanedanının başlangıcıdır.","kaynak":"Britannica, «Chalukya dynasty» (https://www.britannica.com/topic/Chalukya-dynasty): «About 624, Pulakeshin II took the kingdom of Vengi from the Vishnukundins and gave it to his brother Kubja Vishnuvardhana»","gun":"624 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0626-01-01","b":"Xuanwu Kapısı darbesi: Li Shimin kardeşlerini öldürdü","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Chang’an","taraflar":["tang"],"d":"626’da Li Shimin birkaç adamıyla Xuanwu kapısını tutup kardeşlerini pusuya düşürerek öldürdü; iki ay sonra Gaozu tahtı ona bıraktı.","kaynak":"Britannica, «Taizong» (https://www.britannica.com/biography/Taizong-emperor-of-Tang-dynasty): «In 626 their relations reached a crisis point … Li Shimin, with a few followers, seized the Xuanwu gate»","gun":"626 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Hindistan"],"onem":3,"dunya":3,"kapsam":"dis","t":"0629-01-01","b":"Xuanzang Hindistan’a gitti (645’te döndü)","tur":"din","etiket":["din","konu-din"],"yer":"Hindistan","taraflar":["tang"],"d":"Tang’ın ünlü Budist hacısı Xuanzang 629’da Hindistan’a gitti, 645’te döndü; Sanskritçeden çevirilerde yeni bir titizlik getirdi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «The famous pilgrim Xuanzang, who went to India in 629 and returned in 645»","gun":"629 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Lhasa"],"onem":4,"dunya":3,"kapsam":"ic","t":"0629-01-01","b":"Songtsen Gampo Tibet kralı olarak taç giydi (629); yazı ve Lhasa merkezli krallık dönemi","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Lhasa / Yarlung (Tibet)","taraflar":["tibet-imparatorlugu","tibet-imparatorlugu"],"d":"Britannica'ya göre Songtsen Gampo (d. y. 617) 629'da taç giydi; Nepal'ı ve Hindistan ile Çin'in bazı kesimlerini kapsayacak biçimde hâkimiyetini genişletti, saray bilgininin Tibet yazısını yaratması da onun dönemindedir.","kaynak":"Britannica, «Srong-brtsan-sgam-po» (https://www.britannica.com/biography/Srong-brtsan-sgam-po): «was a Tibetan king (crowned 629) who extended his dominion to include Nepal and parts of India and China»","gun":"629 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Üstyurt platosu"],"onem":5,"dunya":3,"kapsam":"dis","t":"0630-01-01","b":"Tang doğu Türk Kağanlığı’nı yenip kağanı yakaladı","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Kuzey sınırı","taraflar":["tang"],"d":"630’da doğu Türkler iç çekişme ve tâbi kavimlerin isyanıyla bölündü; Çin kuvvetleri onları yenip kağanı esir aldı ve Taizong \"göksel kağan\" olarak tanındı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 630 the eastern Turks were split by dissension among their leadership and by the rebellion of their subject peoples.»","gun":"630 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pannonia"],"onem":3,"dunya":2,"kapsam":"dis","t":"0630-01-01","b":"Bulgarlar Avar hâkimiyetine isyan eder; Slav ve Alp ayaklanmaları Avarları zayıflatır","tur":"isyan","etiket":["konu-askeri"],"yer":"Orta Avrupa / Balkanlar","taraflar":["avar"],"d":"Alpler ile Dalmaçya'daki Slavların ve 630'da güvenilir müttefikleri Bulgarların isyanları Avarları zor durumda bıraktı.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «630’da güvenilir müttefikleri Bulgarlar’ın isyanları Avarlar’ı zor durumda bıraktı.»","gun":"630 (yıl; gün kaynakta yok)"},{"odak_yer":["Xi'an"],"onem":2,"dunya":1,"kapsam":"dis","t":"0634-01-01","b":"Taizong Tuyuhun’u (Koko Nor) yendi","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Koko Nor çevresi","taraflar":["tang"],"d":"Tuyuhun 630’ların başında sorun çıkarınca Taizong 634’te topraklarına girip onları yendi; ancak Tuyuhun boyun eğmedi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «Taizong invaded their territory in 634 and defeated them»","gun":"634 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Ishanapura"],"onem":3,"dunya":2,"kapsam":"dis","t":"0638-01-01","b":"Khmer devletlerinden ve Dvaravati'den Çin'e elçilikler","tur":"diplomasi","etiket":["konu-diplomasi"],"yer":"Çin (elçilik)","taraflar":["chenla","dvaravati"],"d":"638'de Khmer devletlerinden ve Dvaravati'den Çin'e elçilikler gönderildiği Çin kayıtlarında geçer.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «Embassies from Khmer polities as well as Dvaravati are recorded in China.»","gun":"638 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":2,"kapsam":"dis","t":"0645-01-01","b":"Tang ordusu Koguryo seferinden ağır kayıpla çekildi","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Koguryo (Mançurya-Kore)","taraflar":["tang"],"d":"Taizong’un dış politikadaki tek başarısızlığı: 645’te Kitan, Paekche ve Silla ile ittifak içinde Koguryo’ya girildi, ağır kayıpla geri çekildi; 647’de yeni sefer de sonuçsuz kaldı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «invaded Koguryŏ in 645 but were forced to withdraw with heavy losses»","gun":"645 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":2,"dunya":1,"kapsam":"dis","t":"0646-01-01","b":"Xueyantou Tang’ın vasalı oldu","tur":"vassal","etiket":["diplomasi","konu-diplomasi"],"yer":"Orhon-Ordos kuzeyi","taraflar":["tang"],"d":"Tang orduları, doğu Türklerin eski vasalı Xueyantou’yu (Syr Tardush) yenip 646’da vasal yaptı; 640’ların sonunda Tang askerî yönetimi Sincan’ın ötesine uzanmıştı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «the Tang armies defeated the Xueyantou (Syr Tardush), former vassals of the eastern Turks, who became Tang vassals in 646»","gun":"646 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0649-01-01","b":"Taizong öldü; Gaozong (Li Zhi) tahta çıktı","tur":"hukumdar","etiket":["hukumdar","konu-kisiler","konu-hanedan"],"yer":"Chang’an","taraflar":["tang"],"d":"Veraset kavgasından sonra seçilen Li Zhi (Gaozong) 649’da tahta çıktı; Britannica onu zayıf karakterli, ama sarayın güçlü isimlerince desteklenen biri olarak niteler.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «Li Zhi, prince of Jin (reigned 649–683; temple name Gaozong) was a weak character»","gun":"649 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Lhasa"],"onem":3,"dunya":2,"kapsam":"ic","t":"0650-01-01","b":"Songtsen Gampo öldü","tur":"olum","etiket":["konu-siyasi"],"yer":"Tibet","taraflar":["tibet-imparatorlugu","tibet-imparatorlugu"],"d":"Tibet'in ilk birleştirici kralı Songtsen Gampo 650'de öldü.","kaynak":"Britannica, «Srong-brtsan-sgam-po» (https://www.britannica.com/biography/Srong-brtsan-sgam-po): «Srong-brtsan-sgam-po (born c. 617, Rgya ma, Tibet—died 650)»","gun":"650 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0655-01-01","b":"Wuhou, imparatoriçe Wang’ı indirtip yerine geçti","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Chang’an","taraflar":["tang"],"d":"Düşük statülü Taiyuan ailesinden gelen Wuhou, 655’te meşru imparatoriçe Wang’ı tahttan indirtip kendisi imparatoriçe oldu; Taizong dönemi bakanları 657–659’da sürüldü ya da öldürüldü.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «managed in 655 to have the legitimate empress, Wang, deposed and herself appointed in her place»","gun":"655 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":3,"dunya":1,"kapsam":"ic","t":"0657-01-01","b":"Luoyang ikinci başkent ilan edildi","tur":"idari","etiket":["idari","konu-idari"],"yer":"Luoyang","taraflar":["tang"],"d":"Wuhou’nun siyasetiyle saray ve idare sık sık Luoyang’a taşındı; böylece iktidar kuzeybatı aristokrasisinin yurdundan uzaklaştırıldı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 657 Luoyang was made the second capital.»","gun":"657 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Angkor"],"onem":3,"dunya":2,"kapsam":"ic","t":"0657-01-01","b":"Jayavarman I Purandarapura'dan hüküm sürüyor (geleneksel ilk Angkor hükümdarı)","tur":"hukumdar","etiket":["konu-hukumdar"],"yer":"Purandarapura","taraflar":["chenla"],"d":"Jayavarman I geleneksel olarak Angkor hanedanının ilk hükümdarı sayılır ve başkenti Purandarapura'dır.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «Jayavarman I, traditionally listed as the first ruler of the Angkor dynasty, rules from his capital in Purandarapura.»","gun":"ca. 657 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":2,"dunya":1,"kapsam":"ic","t":"0659-01-01","b":"Tang, seçkin ailelerin yeni soy kütüğünü derledi","tur":"idari","etiket":["idari","konu-idari"],"yer":"Chang’an","taraflar":["tang"],"d":"659’da imparatorluğun seçkin ailelerinin yeni soy kütüğü, geleneksel statüye değil ulaşılan resmî makamlara göre sıralanarak düzenlendi; Wuhou’nun ailesi başa konuldu.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «the compilation in 659 of a new genealogy of all the empire’s eminent clans»","gun":"659 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":3,"kapsam":"dis","t":"0659-01-01","b":"Batı Türkler yenildi; Amu Derya’ya dek Tang himayesi","tur":"toprak-kazanc","etiket":["askeri","toprak-kazanc","konu-askeri"],"yer":"Tarım Havzası - Amu Derya","taraflar":["tang"],"d":"Gaozong döneminde 657’ye kadar süren savaşın ardından batı Türk toprakları Amu Derya vadisine kadar 659–661’de ad olarak Çin himayesine alındı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «placing their territories as far as the valley of the Amu Darya under a nominal Chinese protectorate in 659–661»","gun":"659 (yıl; gün kaynaktan alınmadı)"},{"onem":3,"dunya":2,"kapsam":"ic","t":"0665-01-01","b":"Karluklar bağımsızlaşır; şefleri «yabgu» unvanını alır","tur":"kurulus","etiket":["konu-siyasi"],"yer":"Altay batısı / Cungarya","taraflar":["karluk"],"d":"665'ten itibaren toparlanan Karluklar, Çin'e tâbi Doğu ve Batı Göktürklere bağlı olmadan bağımsız yaşamaya başladı; şefleri «kül erkin» yerine «yabgu» unvanını aldı. Künye f=766 (Tokmok-Talas'ta devlet kuruluşu); 665 öncül yabgu dönemidir.","kaynak":"TDV İslâm Ansiklopedisi, «KARLUKLAR» (https://islamansiklopedisi.org.tr/karluklar): «665 yılından itibaren tekrar toparlanan Karluklar, Çin İmparatorluğu’na tâbi Doğu ve Batı Gök-Türkler’e bağlı olmaksızın bağımsız yaşamaya başladılar»","gun":"665 (yıl; gün kaynakta yok)"},{"odak_yer":["Astrahan"],"onem":4,"dunya":3,"kapsam":"dis","t":"0665-01-01","b":"Hazarlar Büyük Bulgar Devleti'ni yıkar; Hazar ülkesinin sınırları iki katına çıkar","tur":"toprak-kazanc","etiket":["konu-askeri"],"yer":"Güney Rusya, Tuna'ya kadar uzanan düzlükler","taraflar":["hazar-kaganligi"],"d":"Kurt (Kuvrat) önderliğinde 630'dan sonra kurulan Büyük Bulgar Devleti, 665'ten sonra Hazarlar tarafından yıkıldı; böylece Hazar ülkesinin sınırları iki katına çıktı. (Büyük Bulgar için künye yok → öneri dosyası.)","kaynak":"TDV İslâm Ansiklopedisi, «HAZARLAR» (https://islamansiklopedisi.org.tr/hazarlar): «Güney Rusya’dan Tuna nehrine kadar geniş düzlüklere hükmeden bu devlet 665 yılından sonra Hazarlar tarafından yıkıldı»","gun":"665 (yıl; gün kaynakta yok)"},{"odak_yer":["Pyongyang"],"onem":4,"dunya":2,"kapsam":"dis","t":"0668-01-01","b":"Tang Pyongyang’ı aldı; Koguryo himayeye alındı","tur":"toprak-kazanc","etiket":["askeri","toprak-kazanc","konu-askeri"],"yer":"Pyongyang","taraflar":["tang"],"d":"Gaozong dönemi seferleri sonunda 668’de Koguryo başkenti alındı; ancak 676’ya kadar isyanlar ve Silla’nın yükselişi Çinlileri Güney Mançurya’ya kadar geri çekti.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 668 the Tang forces took P’yŏngyang (the capital), and Koguryŏ was also placed under a protectorate.»","gun":"668 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Asuka"],"onem":3,"dunya":2,"kapsam":"ic","t":"0669-01-01","b":"Nakatomi Kamatari'ye Fujiwara soyadı verildi; Fujiwara klanı doğdu","tur":"siyasi","etiket":["konu-siyasi"],"yer":"Yamato (Japonya)","taraflar":["yamato"],"d":"Taika reformlarının mimarı Kamatari 669'da hizmetlerinin ödülü olarak Fujiwara soyadını aldı; Fujiwara klanı sarayda yerleşti.","kaynak":"Britannica, «Fujiwara Kamatari» (https://www.britannica.com/biography/Fujiwara-Kamatari): «In 669, as a reward for his services, Kamatari was given the new surname of Fujiwara»","gun":"669 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Asuka"],"onem":2,"dunya":1,"kapsam":"ic","t":"0669-11-14","b":"Fujiwara (Nakatomi) Kamatari öldü","tur":"olum","etiket":["konu-siyasi"],"yer":"Yamato (Japonya)","taraflar":["yamato"],"d":"Fujiwara ailesinin kurucusu Kamatari (d. 614) Yamato eyaletinde öldü.","kaynak":"Britannica, «Fujiwara Kamatari» (https://www.britannica.com/biography/Fujiwara-Kamatari): «Fujiwara Kamatari (born 614, Yamato Province, Japan—died Nov. 14, 669, Yamato Province)»"},{"odak_yer":["Xi'an"],"onem":3,"dunya":2,"kapsam":"dis","t":"0670-01-01","b":"Tibetliler Tuyuhun’u Koko Nor yurdundan sürdü","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Koko Nor havzası","taraflar":["tang"],"d":"630’lardan beri Sichuan’ın kuzey sınırını zorlayan Tibetliler 670’e gelindiğinde Tuyuhun’u Koko Nor yurdundan çıkardı; kuzeybatı ağır biçimde tahkim edildi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «By 670 the Tibetans had driven the Tuyuhun from their homeland in the Koko Nor basin.»","gun":"670 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Lhasa"],"onem":4,"dunya":3,"kapsam":"dis","t":"0670-01-01","b":"Tibet-Çin barışı bozuldu; iki yüzyıllık Qinghai-Xinjiang sınır savaşları başladı","tur":"savas","etiket":["konu-askeri"],"yer":"Qinghai ve Xinjiang sınır kuşağı","taraflar":["tibet-imparatorlugu","tibet-imparatorlugu"],"d":"Songtsen Gampo'nun ölümünden 20 yıl sonra, 670'te Çin ile barış bozuldu; iki yüzyıl boyunca Tibet orduları Qinghai ve Xinjiang'da sınırı savaş halinde tuttu, Batı Türkleri ile ittifak kurup Orta Asya ticaret yollarında Çin'e meydan okudu.","kaynak":"Britannica, «Tibet — History» (https://www.britannica.com/place/Tibet/History): «In 670, 20 years after Srong-brtsan-sgam-po’s death, peace with China was broken»","gun":"670 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kançipuram"],"onem":3,"dunya":2,"kapsam":"ic","t":"0670-01-01","b":"I. Vikramaditya Pallava başkenti Kançipuram'ı alır (yak. 670)","tur":"savas","etiket":["konu-askeri","yaklasik"],"yer":"Kançipuram","taraflar":["badami-calukya","pallava"],"d":"Çalukya kralı I. Vikramaditya (655-680) yak. 670'te o dönemde Pallava'ya ait Kançipuram şehrini aldı.","kaynak":"Britannica, «Chalukya dynasty» (https://www.britannica.com/topic/Chalukya-dynasty): «Vikramaditya I (reigned 655–680) took Kanchipuram (ancient Kanci), at that time of the Pallava dynasty, about 670.»","gun":"670 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":2,"kapsam":"dis","t":"0676-01-01","b":"Tang Kore’den Güney Mançurya’ya çekildi; Silla yükseldi","tur":"toprak-kayip","etiket":["askeri","toprak-kayip","konu-askeri"],"yer":"Kore yarımadası","taraflar":["tang"],"d":"676’ya gelindiğinde isyanlar Çinlileri Güney Mançurya’ya çekilmeye zorladı; Kore, güneydeki Silla’nın hâkimiyetine girdi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «by 676 rebellions had forced the Chinese to withdraw to southern Manchuria»","gun":"676 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Tibet"],"onem":2,"dunya":1,"kapsam":"dis","t":"0679-01-01","b":"Tibet ilerleyişi nihayet durduruldu","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Kuzeybatı sınırı","taraflar":["tang"],"d":"Bir dizi zor seferin ardından Tibetliler 679’da durduruldu; aynı yıllarda (679–681) yerleştirilmiş doğu Türkler isyan edip ağır tahribat yaptı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «After a series of difficult campaigns, they were finally checked in 679.»","gun":"679 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0683-01-01","b":"Gaozong öldü; Zhongzong tahta çıktı, Wuhou naipliği ele aldı","tur":"hukumdar","etiket":["hukumdar","konu-kisiler","konu-hanedan"],"yer":"Luoyang","taraflar":["tang"],"d":"Gaozong’un 683’te ölümü üzerine genç Zhongzong tahta çıktı ama Wuhou imparatoriçe dul olarak yönetimi hemen ele geçirdi; bir yıl içinde Zhongzong’u indirip Ruizong’u kukla yaptı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «When Gaozong died in 683, he was succeeded by the young Zhongzong, but Wuhou was made empress dowager»","gun":"683 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Yangzhou"],"onem":2,"dunya":1,"kapsam":"ic","t":"0684-01-01","b":"Xu Jingye’nin Yangzhou isyanı bastırıldı","tur":"isyan","etiket":["isyan","konu-isyan"],"yer":"Yangzhou","taraflar":["tang"],"d":"Memnun kalmayan yönetici sınıf mensuplarının Xu Jingye önderliğinde 684’te Yangzhou’da çıkardığı ciddi isyan çabucak bastırıldı; Wuhou’nun saray terörü başladı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 684 disaffected members of the ruling class under Xu Jingye raised a serious rebellion at Yangzhou in the south»","gun":"684 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Palembang"],"onem":3,"dunya":2,"kapsam":"ic","t":"0684-01-01","b":"Talang Tuwo yazıtı: Srivijaya kralının park vakfı ve bodhisattva duası","tur":"din","etiket":["konu-kultur"],"yer":"Palembang (Sumatra)","taraflar":["srivijaya"],"d":"684 tarihli Talang Tuwo yazıtı kralın bağışladığı parkın tüm canlılara fayda sağlaması duasını kaydeder; hükümdar kendini bodhisattva olarak sunar.","kaynak":"Britannica, «Indonesia – The Malay kingdom of Srivijaya-Palembang» (https://www.britannica.com/place/Indonesia/The-Malay-kingdom-of-Srivijaya-Palembang): «The Talang Tuwo inscription of 684, which records the king’s prayer that a park he has endowed»","gun":"684 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":2,"dunya":1,"kapsam":"ic","t":"0688-01-01","b":"Wuhou Ming Tang (\"Işık Salonu\") yaptırdı","tur":"din","etiket":["din","konu-din"],"yer":"Luoyang","taraflar":["tang"],"d":"Wuhou Budist yazıtları kendi egemenliğine gerekçe yapmak üzere yorumlatırken 688’de Klasiklerde anlatılan, göğe adanmış simgesel en yüksek mabet olan Ming Tang’ı sınırsız savurganlıkla inşa ettirdi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «in 688 erected a Ming Tang (“Hall of Light”)»","gun":"688 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Palembang"],"onem":4,"dunya":3,"kapsam":"ic","t":"0695-01-01","b":"Srivijaya Malakka Boğazı'nın denetimini ele geçiriyor","tur":"toprak-kazanc","etiket":["konu-askeri","konu-ticaret"],"yer":"Malakka Boğazı","taraflar":["srivijaya"],"d":"Çinli rahip I-ching'in 695'te Güneydoğu Asya'dan ayrılmasından önce Srivijaya Malakka Boğazı'nın denetimini kazanmıştı.","kaynak":"Britannica, «Indonesia – The Malay kingdom of Srivijaya-Palembang» (https://www.britannica.com/place/Indonesia/The-Malay-kingdom-of-Srivijaya-Palembang): «before I-ching left Southeast Asia in 695, Srivijaya had gained control of the Strait of Malacca.»","gun":"695 (en geç; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":3,"dunya":2,"kapsam":"dis","t":"0696-01-01","b":"Kitanlar Çin valisine isyan edip Hebei’nin bir kısmını bastı","tur":"isyan","etiket":["isyan","konu-isyan"],"yer":"Hebei","taraflar":["wu-zhou"],"d":"696’da Mançurya’daki Kitanlar valilerine isyan edip Hebei’nin bir bölümünü istila etti; Çinliler Türk yardımıyla 697’de onları kovdu ve halka acımasız misilleme uyguladı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 696 the Khitan in Manchuria rebelled against their Chinese governor and overran part of Hebei.»","gun":"696 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Karakurum"],"onem":2,"dunya":2,"kapsam":"ic","t":"0696-01-01","b":"Kapgan Kağan Kırgızları devlete itaat ettirir","tur":"tabi","etiket":["konu-askeri"],"yer":"Yenisey havzası","taraflar":["dogu-gokturk-2","yenisey-kirgiz"],"d":"İkinci Göktürk Devleti 696-697'de Kırgızları devlete itaat ettirdi, ardından Türgişlere yöneldi; Kırgızlar 710'da isyandan sonra yeniden bağlandı.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «696-697’de Kırgızlar’ı devlete itaat ettirdi, ardından Türgişler’e yöneldi.»","gun":"696-697 (yıl aralığı; gün kaynakta yok)"},{"odak_yer":["Luoyang"],"onem":2,"dunya":1,"kapsam":"dis","t":"0698-01-01","b":"Türkler Hebei’yi istila etti; Wuhou veraseti Tang soyuna bıraktı","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Hebei","taraflar":["wu-zhou"],"d":"698’de Türkler Hebei’yi bastı ve ancak sözde Zhongzong komutasındaki bir ordu tarafından geri püskürtüldü; askerî kriz Wuhou’yu veraseti kendi ailesinde tutma planından vazgeçirdi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 698 the Turks in their turn invaded Hebei and were driven off only by an army»","gun":"698 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Karakurum"],"onem":3,"dunya":2,"kapsam":"ic","t":"0701-01-01","b":"Kapgan'ın Türk ordusu Demirkapı'ya (Temir Kapıg) ulaşır","tur":"askeri","etiket":["konu-askeri"],"yer":"Demirkapı (Temir Kapıg), Batı Türkistan","taraflar":["dogu-gokturk-2"],"d":"Batı Türkistan'a yönelen Kapgan ve Tonyukuk, Bilge ile Kültigin gibi komutanların idaresindeki Türk ordusu 701'de Demirkapı'ya ulaştı.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «Türk ordusu 701’de Demirkapı’ya (Temir Kapıg) ulaştı.»","gun":"701 (yıl; gün kaynakta yok)"},{"odak_yer":["Dongjingcheng (Sanggyeong / Shangjing Longquanfu)"],"onem":2,"dunya":1,"kapsam":"dis","t":"0705-01-01","b":"Çin (Tang) ile Balhae arasında dostane ilişkiler kuruldu","tur":"diplomasi","etiket":["konu-diplomasi"],"yer":"Balhae (Jilin) / Tang Çin","taraflar":["balhae"],"d":"Britannica'ya göre 705'e gelindiğinde Çin ile Balhae arasında dostane ilişkiler vardı; Tang 712'ye dek Dae Jo-yeong'u resmen kral tanıdı.","kaynak":"Britannica, «Parhae» (https://www.britannica.com/place/Parhae): «By 705 China and Parhae had established friendly relations»","gun":"705 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":3,"dunya":2,"kapsam":"ic","t":"0705-12-16","b":"Wuhou Luoyang’da öldü","tur":"olum","etiket":["hukumdar","konu-kisiler"],"yer":"Luoyang","taraflar":["tang"],"d":"Britannica Wuhou’nun ölüm gününü 16 Aralık 705 olarak verir; 690–705 arası kendi adıyla yöneten tek kadın hükümdar.","kaynak":"Britannica, «Wuhou» (https://www.britannica.com/biography/Wuhou): «died December 16, 705, Luoyang»","gun":"0705-12-16 (kaynak günü Batı takvimiyle verir)"},{"odak_yer":["Astrahan"],"onem":3,"dunya":3,"kapsam":"dis","t":"0708-01-01","b":"Mesleme b. Abdülmelik Hazar topraklarında şehir ve kaleler fetheder","tur":"fetih","etiket":["konu-askeri"],"yer":"Kuzey Kafkasya (Hazar sınırı)","taraflar":["hazar-kaganligi"],"d":"Halife I. Velîd zamanında (705-715) Halifenin kardeşi Mesleme b. Abdülmelik komutasındaki İslâm kuvvetleri Hazarlar üzerine yürüyüp bazı şehir ve kaleleri fethetti (708). Derbend'in ele geçirilişi (714) künye iskeletindedir.","kaynak":"TDV İslâm Ansiklopedisi, «HAZARLAR» (https://islamansiklopedisi.org.tr/hazarlar): «Halifenin kardeşi Mesleme b. Abdülmelik kumandasındaki İslâm kuvvetleri Hazarlar üzerine yürüyerek bazı şehir ve kaleleri fethettiler (708).»","gun":"708 (yıl; gün kaynakta yok)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":1,"kapsam":"ic","t":"0710-01-01","b":"Zhongzong öldü; İmparatoriçe Wei iktidarı ele geçirmeye kalkıştı","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Chang’an","taraflar":["tang"],"d":"Zhongzong’un 710’da ölümü (büyük olasılıkla zehirlenme) üzerine İmparatoriçe Wei Wuhou gibi hükümdar olmaya çalıştı; Li Longji ve Taiping Prenses ile saray ordusu Ruizong’u tahta geri getirdi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «When the emperor died in 710, probably poisoned by her, she tried to establish herself as ruler»","gun":"710 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Ishanapura"],"onem":2,"dunya":1,"kapsam":"ic","t":"0710-01-01","b":"Prasat Ak Yom: ilk tipik Khmer tapınak-dağı yapılıyor","tur":"siyasi","etiket":["konu-kultur","arkeoloji"],"yer":"Kamboçya","taraflar":["chenla"],"d":"8. yüzyıl başında yapılan Prasat Ak Yom, karakteristik Khmer tapınak-dağlarının ilkidir.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «Prasat Ak Yom, the first of the characteristic Khmer temple-mountains, is constructed in the early eighth century.»","gun":"ca. 710 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Karakurum"],"onem":2,"dunya":2,"kapsam":"ic","t":"0710-01-01","b":"Kırgızlar isyanın ardından yeniden Göktürk devletine bağlanır; birçok Türk boyu Çin'e sığınır","tur":"isyan","etiket":["konu-askeri"],"yer":"Yenisey havzası","taraflar":["dogu-gokturk-2","yenisey-kirgiz"],"d":"İsyan eden Kırgızlar 710'da yeniden devlete bağlandı; ancak birçok Türk boyu bu dönemde gidip Çin'e sığındı.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «İsyan eden Kırgızlar 710’da yeniden devlete bağlandıysa da birçok Türk boyu gidip Çin’e sığındı.»","gun":"710 (yıl; gün kaynakta yok)"},{"odak_yer":["Kûfe"],"onem":4,"dunya":3,"kapsam":"dis","t":"0711-01-01","b":"Muhammed b. Kāsım Mekrân'a ulaşır, Kannezbûr ve Ermâil'i fetheder (92/711)","tur":"fetih","etiket":["konu-askeri","sind"],"yer":"Mekrân, Sind","taraflar":["emevi"],"d":"Haccâc b. Yûsuf'un emrettiği 6000 kişilik ordunun başında Muhammed b. Kāsım Mekrân'a vardı ve Kannezbûr ile Ermâil'i fethetti; Sind seferi bu şekilde başladı.","kaynak":"TDV İslâm Ansiklopedisi, «MUHAMMED b. KĀSIM es-SEKAFÎ» (https://islamansiklopedisi.org.tr/muhammed-b-kasim-es-sekafi): «Mekrân’a varmasının (92/711) ardından Kannezbûr ve Ermâil’i fethetti»","gun":"92 (711) (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Deybül"],"onem":3,"dunya":2,"kapsam":"dis","t":"0712-01-01","b":"Muhammed b. Kāsım üç ay süren kuşatmanın ardından Deybül'ü alır (93/712)","tur":"fetih","etiket":["konu-askeri","sind"],"yer":"Deybül (Sind kıyısı)","taraflar":["emevi"],"d":"Üç ay süren kuşatma, Hindistan'da ilk kez kullanılan mancınığın kuleyi yıkmasıyla sona erdi ve Deybül düştü; Muhammed şehirde cami yaptırdı.","kaynak":"TDV İslâm Ansiklopedisi, «MUHAMMED b. KĀSIM es-SEKAFÎ» (https://islamansiklopedisi.org.tr/muhammed-b-kasim-es-sekafi): «Üç ay süren kuşatmanın sonunda ... şehir düştü (93/712).»","gun":"93 (712) (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kûfe"],"onem":5,"dunya":3,"kapsam":"dis","t":"0712-06-20","b":"Muhammed b. Kāsım Racâ Dâhir'i yener; Dâhir savaşta ölür, Sind'in tamamı ele geçirilir","tur":"savas","etiket":["konu-askeri","sind"],"yer":"Sind (İndus vadisi)","taraflar":["emevi"],"d":"Raca Dâhir'in öldüğü savaştan sonra Rûr, Brahmanâbâd ve Mültan fethedildi; 711-715 fetihleriyle Belûcistan'dan Kathiavar'a kadar bütün İndus vadisi İslâm hâkimiyetine girdi.","kaynak":"TDV İslâm Ansiklopedisi, «MUHAMMED b. KĀSIM es-SEKAFÎ» (https://islamansiklopedisi.org.tr/muhammed-b-kasim-es-sekafi): «Dâhir’le yaptığı bir savaşta raca hayatını kaybetti (10 Ramazan 93 / 20 Haziran 712).»","gun":"20 Haziran 712 (10 Ramazan 93)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0713-01-01","b":"İkinci darbe: Xuanzong tam iktidara geldi; Prenses Taiping intihar etti","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Chang’an","taraflar":["tang"],"d":"Britannica 712’de Ruizong’un Xuanzong’a tahtı bıraktığını, 713 darbesinin ise Xuanzong’u tümüyle başa getirdiğini yazar.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «A second coup, in 713, placed Xuanzong completely in charge and resulted in Ruizong’s retirement and the princess Taiping’s suicide.»","gun":"713 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kûfe"],"onem":3,"dunya":2,"kapsam":"dis","t":"0715-01-01","b":"Muhammed b. Kāsım Irak'a zincirle gönderilir ve öldürülür (96/715); Kannevc seferi yapılamaz","tur":"olum","etiket":["konu-siyasi","sind"],"yer":"Vâsıt (Irak)","taraflar":["emevi"],"d":"Halife I. Velîd'in ölümü ve Süleyman b. Abdülmelik'in halife olmasıyla Haccâc'ın adamları görevden alındı; Muhammed Yezîd b. Ebû Kebşe tarafından zincire vurulup Irak'a gönderildi ve Vâsıt'ta işkenceyle öldürüldü.","kaynak":"TDV İslâm Ansiklopedisi, «MUHAMMED b. KĀSIM es-SEKAFÎ» (https://islamansiklopedisi.org.tr/muhammed-b-kasim-es-sekafi): «Muhammed b. Kāsım b. Muhammed b. el-Hakem b. Ebî Akīl es-Sekafî (ö. 96/715)»","gun":"96 (715) (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Karakurum"],"onem":4,"dunya":2,"kapsam":"ic","t":"0716-01-01","b":"İlteriş'in oğlu Bilge Kağan tahta çıkar","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Ötüken","taraflar":["dogu-gokturk-2"],"d":"Kapgan'ın ölümünden sonra İlteriş'in oğlu Bilge kağan oldu; ilk işi boyların isyanını bastırmak, sonra Çinlilerle dostluk kurmaktı. TDV Karluklar maddesi Bilge Kağan dönemini 716-734 verir.","kaynak":"TDV İslâm Ansiklopedisi, «KARLUKLAR» (https://islamansiklopedisi.org.tr/karluklar): «Bilge Kağan döneminde ise (716-734) tekrar Göktürk hâkimiyetini benimsediler.»","gun":"716 (yıl; gün kaynakta yok)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":2,"kapsam":"ic","t":"0720-01-01","b":"Tang, nüfusun büyük çaplı yeniden sayımına başladı","tur":"reform","etiket":["islahat","konu-islahat","konu-idari"],"yer":"Tang","taraflar":["tang"],"d":"720’den sonra yapılan büyük çaplı yeniden kayıt, vergi mükelleflerini artırdı ve devletin kaydedilmemiş çok sayıda aile üzerindeki denetimini geri kazandırdı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «After 720 a large-scale re-registration of the population greatly increased the number of taxpayers»","gun":"720 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Tibet"],"onem":3,"dunya":2,"kapsam":"dis","t":"0727-01-01","b":"Tang–Tibet savaşı (727–729)","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Kuzeybatı sınırı","taraflar":["tang"],"d":"Xuanzong’un en tehlikeli düşmanı Tibet 714’ten beri her yıl kuzeybatıyı akın altında tutuyordu; 727–729’da geniş çaplı savaş yürütüldü.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 727–729 the Chinese undertook large-scale warfare against them»","gun":"727 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Dali"],"onem":3,"dunya":2,"kapsam":"ic","t":"0729-01-01","b":"Piluoge altı krallığı birleştirdi; Nanzhao (Göl Er çevresi) kuruldu","tur":"kurulus","etiket":["konu-siyasi"],"yer":"Er Gölü çevresi (Batı Yunnan)","taraflar":["nanzhao"],"d":"Britannica, Nanzhao'nun 729'da altı Tai krallığının birleşmesiyle oluştuğunu yazar; Piluoge komşu beş krallığı ele geçirirken Tibetlilere karşı Çin ile ittifak halindeydi.","kaynak":"Britannica, «Nanzhao» (https://www.britannica.com/place/Nanzhao): «Nanzhao was formed by the unification of six Tai kingdoms in 729.»","gun":"729 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Tibet"],"onem":2,"dunya":2,"kapsam":"dis","t":"0730-01-01","b":"Tang–Tibet sulh anlaşması","tur":"antlasma","etiket":["diplomasi","konu-diplomasi"],"yer":"Kuzeybatı sınırı","taraflar":["tang"],"d":"727–729 savaşlarının sonunda 730’da sulh sağlandı; ancak 730’larda çatışmalar yeniden başladı ve Tibet Tarım Havzası’ndaki Tang topraklarına yöneldi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «in 730 a settlement was concluded»","gun":"730 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Karakurum"],"onem":3,"dunya":2,"kapsam":"ic","t":"0731-01-01","b":"Kültigin ölür","tur":"olum","etiket":["konu-siyasi"],"yer":"Ötüken","taraflar":["dogu-gokturk-2"],"d":"Bilge Kağan'ın kardeşi Kültigin 731'de öldü; anısına ağabeyi Bilge Kağan 732'de Orhon yazıtını dikti.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «ikincisi 731’de ölen Kültigin için ağabeyi Bilge Kağan tarafından 732’de»","gun":"731 (yıl; gün kaynakta yok)"},{"odak_yer":["Mataram"],"onem":3,"dunya":2,"kapsam":"ic","t":"0732-01-01","b":"Sanjaya Java'da hüküm sürmeye başlıyor; Mataram krallığı Şiva'ya adanmış","tur":"hukumdar","etiket":["konu-hukumdar"],"yer":"Orta Java","taraflar":["medang"],"d":"Sanjaya'nın 732-760 arası saltanatında Mataram adıyla bilinen krallık Hindu tanrısı Şiva'ya adanmıştı.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «The rule of Sanjaya in Java. His kingdom, known as Mataram, is devoted to the Hindu god Shiva.»","gun":"732 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Karakurum"],"onem":4,"dunya":3,"kapsam":"ic","t":"0732-01-01","b":"Kültigin Yazıtı dikilir (Orhon yazıtları)","tur":"kurulus","etiket":["konu-kultur"],"yer":"Orhon vadisi, Ötüken","taraflar":["dogu-gokturk-2"],"d":"Orhon yazıtlarından Kültigin Yazıtı, 731'de ölen Kültigin için ağabeyi Bilge Kağan tarafından 732'de dikildi; Tonyukuk Yazıtı 716-734 arasında yazılmıştır.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «ikincisi 731’de ölen Kültigin için ağabeyi Bilge Kağan tarafından 732’de»","gun":"732 (yıl; gün kaynakta yok)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":2,"kapsam":"dis","t":"0734-01-01","b":"Bilge Kağan’ın ölümüyle Türk kuvvetinin sonu hızlandı","tur":"olum","etiket":["hukumdar","konu-kisiler"],"yer":"Moğolistan","taraflar":["tang"],"d":"734’te Bilge’nin ölümü Türk gücünün sonunu hızlandırdı; tâbi kabileler arasındaki mücadeleden Uygurlar galip çıktı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «Bilge’s death in 734 precipitated the end of Turkish power.»","gun":"734 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Dongjingcheng (Sanggyeong / Shangjing Longquanfu)"],"onem":2,"dunya":1,"kapsam":"dis","t":"0734-01-01","b":"Balhae ile Tang, Kitan tehdidi karşısında ittifakı yeniden kurdu (730'lardaki savaşlardan sonra)","tur":"antlasma","etiket":["konu-diplomasi"],"yer":"Balhae / Tang Çin","taraflar":["balhae"],"d":"İki devlet 730'larda defalarca birbirine saldırdıktan sonra 734'te Kitan kabilelerinin yayılmacı tehdidi nedeniyle ittifaklarını yeniden kurdu.","kaynak":"Britannica, «Parhae» (https://www.britannica.com/place/Parhae): «in 734 they reestablished their alliance amid the threat posed by the expansionist Khitan tribes of Central Asia»","gun":"734 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Karakurum"],"onem":4,"dunya":3,"kapsam":"ic","t":"0734-01-01","b":"Bilge Kağan ölür","tur":"olum","etiket":["konu-siyasi"],"yer":"Ötüken","taraflar":["dogu-gokturk-2"],"d":"TDV'ye göre Bilge Kağan 734'te öldü; anısına oğlu tarafından 735'te yazıt dikildi. Bilge Kağan'dan sonra gelen kağanlar yetersiz kaldığı için devlet kısa sürede zayıfladı.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «734’te ölen Bilge Kağan anısına oğlu tarafından 735 yılında dikilmiştir.»","gun":"734 (yıl; gün kaynakta yok)"},{"odak_yer":["Karakurum"],"onem":4,"dunya":3,"kapsam":"ic","t":"0735-01-01","b":"Bilge Kağan Yazıtı dikilir (Orhon yazıtları)","tur":"kurulus","etiket":["konu-kultur"],"yer":"Orhon vadisi, Ötüken","taraflar":["dogu-gokturk-2"],"d":"734'te ölen Bilge Kağan'ın anısına oğlu tarafından 735'te dikilen yazıt, Orhon yazıtlarının üçüncüsüdür; Danimarkalı Vilhelm Thomsen yazıtları 1893'te okudu.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «734’te ölen Bilge Kağan anısına oğlu tarafından 735 yılında dikilmiştir.»","gun":"735 (yıl; gün kaynakta yok)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":2,"kapsam":"ic","t":"0737-01-01","b":"Sınır komutanlıkları (askerî valilikler) resmîleşti","tur":"idari","etiket":["idari","konu-idari"],"yer":"Mançurya-Sichuan sınırı","taraflar":["tang"],"d":"Xuanzong sınırları stratejik komutanlıklara böldü; sistem 737’de Li Linfu zamanında resmîleşti. Bu valiler zamanla sivil yetkiler de edindi ve An Lushan’a zemin hazırladı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «This system developed gradually and was formalized in 737 under Li Linfu.»","gun":"737 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Astrahan"],"onem":4,"dunya":4,"kapsam":"dis","t":"0740-01-01","b":"Hazar hânedanı Yahudiliği kabul eder (Kuzari rivayeti; Bulan Han'ın dinî tartışması)","tur":"din","etiket":["konu-din"],"yer":"Hazar başkenti (Belencer/İdil çevresi)","taraflar":["hazar-kaganligi"],"d":"TDV, Judah Halevi'nin Kuzari'sine göre Hazar hânedanının 740'ta Yahudiliği kabul ettiğini aktarır (Hazar Han Bulan'ın huzurunda yapılan dinî tartışma, 740). Mes'ûdî olayı Hârûnürreşîd devrine (786-809) yerleştirir; tarih rivayettir.","kaynak":"TDV İslâm Ansiklopedisi, «HAZARLAR» (https://islamansiklopedisi.org.tr/hazarlar): «Hazar hânedanı 740 yılında Yahudiliği kabul etmiştir.»","gun":"740 (yıl; gün kaynakta yok)"},{"odak_yer":["Kançipuram"],"onem":2,"dunya":2,"kapsam":"ic","t":"0742-01-01","b":"II. Vikramaditya Kançipuram'ı yeniden alır, şehri korur (742)","tur":"savas","etiket":["konu-askeri"],"yer":"Kançipuram","taraflar":["badami-calukya","pallava"],"d":"Çalukya kralı II. Vikramaditya (733-746) 742'de Kançipuram'ı bir kez daha ele geçirdi ancak şehre zarar vermedi.","kaynak":"Britannica, «Chalukya dynasty» (https://www.britannica.com/topic/Chalukya-dynasty): «Vikramaditya II (reigned 733–746), again captured, but spared, the city, in 742.»","gun":"742 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":3,"kapsam":"dis","t":"0744-01-01","b":"Uygur Kağanlığı kuruldu","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Moğolistan","taraflar":["tang"],"d":"Türk devletinin dağılmasından sonra Uygurlar 744’te güçlü bir imparatorluk kurup 840’a kadar Çin’in kuzey sınırında baskın güç oldu; Tang ile ittifak politikası izlediler.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 744 they established a powerful empire that was to remain the dominant force on China’s northern border until 840.»","gun":"744 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Ordu-Balık"],"onem":4,"dunya":3,"kapsam":"ic","t":"0744-01-01","b":"Uygurlar Basmılları bozguna uğratıp Ötüken'de Büyük Uygur Kağanlığı'nı kurar","tur":"kurulus","etiket":["konu-siyasi"],"yer":"Ötüken / Orhon-Selenge","taraflar":["uygur-kaganligi","dogu-gokturk-2"],"d":"TDV Türk maddesi Uygurların Basmılları 744'te yenerek Ötüken Büyük Uygur Kağanlığı'nı kurduğunu söyler; Uygurlar maddesi kuruluşu (kağanlık ilanı) 745'e koyar. Orhon-Selenge merkezli Moğolistan hâkimiyeti izledi.","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «Uygurlar 744’te Basmıllar’ı bozguna uğratıp Ötüken Büyük Uygur Kağanlığı’nı kurdular»","gun":"744 (yıl; gün kaynakta yok)"},{"odak_yer":["Lhasa"],"onem":3,"dunya":2,"kapsam":"ic","t":"0747-01-01","b":"Padmasambhava Kral Trisong Detsen tarafından Tibet'e davet edildi","tur":"din","etiket":["konu-din"],"yer":"Samye (Tibet)","taraflar":["tibet-imparatorlugu","tibet-imparatorlugu"],"d":"Tantrik Budizm'i Tibet'e getirdiği anlatılan Padmasambhava 747'de Kral Trisong Detsen tarafından davet edilip Samye'ye geldi.","kaynak":"Britannica, «Padmasambhava» (https://www.britannica.com/biography/Padmasambhava): «He was invited to Tibet in 747 by King Thī-srong-detsan and arrived at Samye»","gun":"747 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Lhasa"],"onem":2,"dunya":1,"kapsam":"ic","t":"0749-01-01","b":"Samye manastırının inşası tamamlandı (Padmasambhava'ya göre)","tur":"din","etiket":["konu-din"],"yer":"Samye (Tibet)","taraflar":["tibet-imparatorlugu","tibet-imparatorlugu"],"d":"Padmasambhava, Samye manastırının inşasını 749'da tamamlattı; Tibet'te kurulan ilk Budist manastır sayılır.","kaynak":"Britannica, «Padmasambhava» (https://www.britannica.com/biography/Padmasambhava): «He supervised the completion of the monastery in 749.»","gun":"749 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Mataram"],"onem":4,"dunya":2,"kapsam":"ic","t":"0750-01-01","b":"Sailendra hanedanı Java'da yükselişe geçiyor (yaklaşık 750-850)","tur":"hanedan","etiket":["konu-hanedan"],"yer":"Orta Java","taraflar":["medang"],"d":"Sailendra hanedanı Java'da yaklaşık 750-850 arasında hüküm sürdü; Mahayana Budizmi'nin getirdiği kültürel bir canlanma ve çok sayıda tapınakla anılır.","kaynak":"Britannica, «Shailendra dynasty» (https://www.britannica.com/topic/Shailendra-dynasty): «a dynasty that flourished in Java from about 750 to 850»","gun":"ca. 750 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":4,"kapsam":"dis","t":"0751-01-01","b":"Talas Irmağı’nda Tang ordusu Araplara yenildi","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Talas Irmağı (Orta Asya)","taraflar":["tang"],"d":"Batıda aşırı gerilmiş Tang orduları 751’de Talas Irmağı’nda Araplarca yenildi; aynı on yılda güneybatıda Nanzhao seferi 50.000 kişilik bir ordunun neredeyse tamamını yok etti.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «the overextended imperial armies had been defeated by the Arabs in 751 on the Talas River»","gun":"751 (yıl; gün kaynaktan alınmadı)"},{"yer_id":"Taraz (Evliya-Ata)","onem":5,"dunya":5,"kapsam":"dis","t":"0751-07-01","b":"Talas Savaşı: Araplar ve Karluklar Çin ordusunu yener","tur":"savas","etiket":["konu-askeri"],"yer":"Talas nehri kıyısı (Atlah)","taraflar":["karluk"],"d":"Zilhicce 133'te (Temmuz 751) Talas kıyısında beş gün süren savaşta Müslüman Araplar ve Karluk Türkleri Çin ordularını yendi; Çinliler bölgeden çekildi. Karluklar savaşta Müslümanların yanında yer aldı.","kaynak":"TDV İslâm Ansiklopedisi, «TALAS SAVAŞI» (https://islamansiklopedisi.org.tr/talas-savasi): «Zilhicce 133’te (Temmuz 751) Talas nehri kıyısındaki Atlah mevkiinde cereyan eden savaş beş gün sürdü.»","gun":"Temmuz 751 (ay; gün kaynakta yok)"},{"odak_yer":["Tibet"],"onem":2,"dunya":1,"kapsam":"dis","t":"0752-01-01","b":"Tibet, Yunnan’daki Nanzhao ile ittifak kurdu","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Yunnan - Tibet","taraflar":["tang"],"d":"752’den itibaren Tibetliler Yunnan’daki Nanzhao devletini müttefik edinip batı sınırında sürekli bir tehdit oluşturdu.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «From 752 onward the Tibetans acquired a new ally in the Nanzhao state in Yunnan»","gun":"752 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Nara"],"onem":2,"dunya":2,"kapsam":"dis","t":"0753-01-01","b":"Çinli keşiş Ganjin altıncı denemede Nara'ya ulaştı; Ritsu mezhebini kurdu","tur":"din","etiket":["konu-din"],"yer":"Nara (Japonya)","taraflar":["nara-japonya"],"d":"Saray, Çinli keşişleri Nara'ya çekmeye çalıştı; en önemlisi Ganjin (Jianzhen) 753'te Nara'ya ulaşıp Tōshōdai Tapınağı'nda Ritsu mezhebini kurdu.","kaynak":"Britannica, «Japan — The Nara period (710–784)» (https://www.britannica.com/place/Japan/The-Nara-period-710-784): «Ganjin (Chinese: Jianzhen), who finally reached Nara in 753 on his sixth attempt»","gun":"753 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Dali"],"onem":3,"dunya":2,"kapsam":"dis","t":"0754-01-01","b":"Nanzhao ikinci Tang saldırısını da püskürttü","tur":"savas","etiket":["konu-askeri"],"yer":"Er Gölü çevresi (Yunnan)","taraflar":["nanzhao"],"d":"Başkentin coğrafî olarak aşılmaz olması nedeniyle Çin'in iki saldırısı 751 ve 754'te püskürtüldü (751 iskelette).","kaynak":"Britannica, «Nanzhao» (https://www.britannica.com/place/Nanzhao): «two Chinese attacks were repulsed in 751 and 754»","gun":"754 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Manyakheta"],"onem":4,"dunya":3,"kapsam":"ic","t":"0755-01-01","b":"Rastrakuta hanedanı Dekan'da hüküm sürmeye başlar (yak. 755; Dantidurga Çalukya'nın yerini alır)","tur":"kurulus","etiket":["konu-siyasi","yaklasik"],"yer":"Dekan","taraflar":["rastrakuta"],"d":"Rastrakutalar yak. 755'ten 975'e kadar Dekan'ı ve komşu bölgeleri yönetti; Çalukyaları yendikten sonra Hindistan'ın ikinci büyük siyasi birimi oldular.","kaynak":"Britannica, «Rashtrakuta dynasty» (https://www.britannica.com/topic/Rashtrakuta-dynasty): «Hindu dynasty that ruled the Deccan and neighbouring areas of India from about 755 to 975 CE.»","gun":"755 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":4,"dunya":2,"kapsam":"ic","t":"0756-01-01","b":"An Lushan Doğu Başkent Luoyang’ı aldı","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Luoyang","taraflar":["tang"],"d":"755 sonunda isyan eden An Lushan, Hebei’yi geçip 756 başında Luoyang’ı, aynı yıl Temmuz’da Chang’an’ı ele geçirdi; imparator Sichuan’a kaçtı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «captured the eastern capital, Luoyang, early in 756, and took the main Tang capital, Chang’an, in July of the same year»","gun":"756 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":1,"kapsam":"ic","t":"0756-01-01","b":"Suzong Tang tahtında (756–762)","tur":"hukumdar","etiket":["hukumdar","konu-kisiler","konu-hanedan"],"yer":"Lingwu","taraflar":["tang"],"d":"Lingwu’ya çekilen veliaht tahtı kendisi aldı; Suzong (756–762) çok zor bir askerî durumla karşı karşıya kaldı: asiler başkent ile Hebei ve Henan’ın büyük bölümünü elinde tutuyordu.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «The new emperor, Suzong (reigned 756–762), was faced with a desperately difficult military situation.»","gun":"756 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Manyakheta"],"onem":3,"dunya":2,"kapsam":"ic","t":"0756-01-01","b":"I. Krişna tahta çıkar (yak. 756-773); Ellora Kailasa tapınağını yaptırır","tur":"hukumdar","etiket":["konu-siyasi","konu-kultur"],"yer":"Ellora","taraflar":["rastrakuta"],"d":"I. Krişna döneminde Ellora'daki kayaya oyulmuş Kailasa tapınağı yapıldı (UNESCO Dünya Mirası, 1983).","kaynak":"Britannica, «Rashtrakuta dynasty» (https://www.britannica.com/topic/Rashtrakuta-dynasty): «Krishna I (reigned c. 756–773), built the rock temple of Kailasa at Ellora»","gun":"756 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":5,"dunya":3,"kapsam":"ic","t":"0756-01-01","b":"Chang’an An Lushan’ın eline geçti; Xuanzong Sichuan’a kaçtı","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Chang’an","taraflar":["tang"],"d":"Temmuz 756’da başkent Chang’an düştü; yolda Yang Guifei ve Yang hizbinin diğer üyeleri öldürüldü; veliaht Lingwu’da tahta çıktı (Suzong).","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «captured the eastern capital, Luoyang, early in 756, and took the main Tang capital, Chang’an, in July of the same year»","gun":"756 Temmuz (ay; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":2,"kapsam":"ic","t":"0757-01-01","b":"An Lushan öldürüldü; isyan oğlu ve Shi Siming ile sürdü","tur":"olum","etiket":["hukumdar","konu-kisiler"],"yer":"Luoyang","taraflar":["tang"],"d":"An Lushan 757 başında bir astı tarafından öldürüldü; isyanı önce oğlu, sonra Shi Siming ve oğlu Shi Chaoyi sürdürdü.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «An Lushan himself was murdered by a subordinate early in 757»","gun":"757 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Badami"],"onem":4,"dunya":2,"kapsam":"ic","t":"0757-01-01","b":"Badami Çalukya kralı II. Kirtivarman'ın yerini Raştrakuta alır (757)","tur":"siyasi","etiket":["konu-siyasi"],"yer":"Badami / Dekan","taraflar":["badami-calukya","rastrakuta"],"d":"Britannica'ya göre Çalukya kralı II. Kirtivarman'ın yerine Raştrakuta hanedanı geçti; Rastrakuta yaklaşık 755'ten itibaren Dekan'ı yönetir.","kaynak":"Britannica, «Chalukya dynasty» (https://www.britannica.com/topic/Chalukya-dynasty): «His successor, Kirtivarman II, was replaced by the Rashtrakuta dynasty in 757.»","gun":"757 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Mansûre"],"onem":2,"dunya":1,"kapsam":"dis","t":"0759-05-04","b":"Abbâsî valisi Ömer b. Hafs Mansûre'yi 11 aylık kuşatmadan sonra barışla alır (142/759)","tur":"idari","etiket":["konu-siyasi","sind"],"yer":"Mansûre (Sind)","taraflar":["abbasi"],"d":"Halife Ebû Ca'fer el-Mansûr'un Sind'e vali gönderdiği Ömer b. Hafs Mansûre'de isyanla karşılaştı; on bir ay süren kuşatmanın ardından şehre barış yoluyla hâkim oldu.","kaynak":"TDV İslâm Ansiklopedisi, «SİND» (https://islamansiklopedisi.org.tr/sind): «Ömer b. Hafs, Mansûre’de bir isyanla karşılaştı ve on bir ay süren kuşatmanın ardından ancak barış yoluyla şehre hâkim olabildi (142/759).»","gun":"142 (759) (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Lhasa"],"onem":3,"dunya":2,"kapsam":"ic","t":"0761-01-01","b":"Trisong Detsen Budizm yasağını kaldırdı","tur":"din","etiket":["konu-din"],"yer":"Tibet","taraflar":["tibet-imparatorlugu","tibet-imparatorlugu"],"d":"Kral Khri-srong-lde-brtsan başlangıçta Budizm'i yasaklamış, ancak bu kısıtlama 761'de kaldırıldı; 763'te Hint ve Çinli Budist öğretmenler davet edildi.","kaynak":"Britannica, «Tibet — History» (https://www.britannica.com/place/Tibet/History): «He initially had prohibited Buddhism, but that restriction was lifted in 761.»","gun":"761 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0763-01-01","b":"An Lushan–Shi Siming isyanı bastırıldı","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Hebei-Henan","taraflar":["tang"],"d":"755’te başlayan isyan, Shi Chaoyi’nin yenilgi ve ölümüyle 763’te sona erdi; Uygur paralı askerleri ve zaferden sonra uygulanan hoşgörü politikası etkili oldu.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «it was not suppressed until 763»","gun":"763 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0763-01-01","b":"Tibetliler Gansu’yu işgal edip başkenti yağmaladı","tur":"toprak-kayip","etiket":["askeri","toprak-kayip","konu-askeri"],"yer":"Gansu / Chang’an","taraflar":["tang"],"d":"Nanzhao müttefiki Tibetliler 763’te tüm Gansu’yu işgal etti ve yıl sonunda Tang başkentini ele geçirip yağmaladı; kuzeybatıyı 9. yüzyıla dek ellerinde tuttular.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «in 763 occupied the whole of present-day Gansu. Late in 763 they actually took and looted the capital.»","gun":"763 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Mungîr (Monghyr)"],"onem":3,"dunya":2,"kapsam":"ic","t":"0770-01-01","b":"Dharmapala Pala tahtında (yak. 770-810); krallığı genişletir, bir süre Kannauj'a hâkim olur","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Bengal-Bihar, Kannauj","taraflar":["pala"],"d":"Gopala'nın halefi Dharmapala krallığı büyük ölçüde genişletti ve bir süre Kannauj'u elinde tuttu.","kaynak":"Britannica, «Pala dynasty» (https://www.britannica.com/topic/Pala-dynasty): «His successor, Dharmapala (reigned c. 770–810), greatly expanded the kingdom and for a while was in control of Kannauj.»","gun":"770 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Mataram"],"onem":3,"dunya":3,"kapsam":"ic","t":"0778-01-01","b":"Borobudur'un inşası başlıyor (yaklaşık 778-850, Sailendra)","tur":"siyasi","etiket":["konu-kultur"],"yer":"Borobudur, Orta Java","taraflar":["medang"],"d":"Orta Java'daki Borobudur Budist anıtı Sailendra hanedanı döneminde yaklaşık 778-850 arasında inşa edildi.","kaynak":"Britannica, «Borobudur» (https://www.britannica.com/topic/Borobudur): «Borobudur was constructed between about 778 and 850 ce, under the Shailendra dynasty.»","gun":"ca. 778 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Lhasa"],"onem":2,"dunya":1,"kapsam":"ic","t":"0779-01-01","b":"Trisong Detsen Samye (Bsam-yas) tapınağını kurdu (yaklaşık 779)","tur":"din","etiket":["konu-din"],"yer":"Samye (Tibet)","taraflar":["tibet-imparatorlugu","tibet-imparatorlugu"],"d":"Britannica'ya göre Bsam-yas büyük tapınağı yaklaşık 779'da kuruldu ve Tibetliler burada keşiş olarak eğitildi.","kaynak":"Britannica, «Tibet — History» (https://www.britannica.com/place/Tibet/History): «about 779 he established the great temple of Bsam-yas, where Tibetans were trained as monks»","gun":"779 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0780-01-01","b":"Dezong yeni vergi sistemini (iki vergi) ilan etti","tur":"reform","etiket":["islahat","konu-islahat","konu-idari"],"yer":"Tang","taraflar":["tang"],"d":"780’de her eyalete vergi kotası konuldu ve vergi para üzerinden hesaplanmaya başlandı; sistem Ming dönemine kadar vergi yapısının temeli kaldı. Tuz tekeli merkezî gelirin büyük bölümünü sağlıyordu.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «in 780 he promulgated a new system of taxation, under which each province was assessed a quota of taxes»","gun":"780 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0781-01-01","b":"Hebei ve Huai eyaletlerinde isyan dalgası (781–786)","tur":"isyan","etiket":["isyan","konu-isyan"],"yer":"Hebei / Huai vadisi","taraflar":["tang"],"d":"Dezong’un yerel özerkliğe karşı sertliği üzerine kuzeydoğu, Huai vadisi ve başkent çevresinde isyanlar çıktı; Britannica bunun Tang’ı An Lushan isyanından bile yıkıma yaklaştırdığını yazar.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «From 781 to 786 there was a wave of rebellions not only in the northeastern provinces but also in the Huai valley»","gun":"781 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Nara"],"onem":3,"dunya":2,"kapsam":"ic","t":"0781-01-01","b":"Kammu imparator oldu (781-806); sonra Nagaoka'ya (784) ve Heian'a (794) taşıdı","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Nara / Japonya","taraflar":["nara-japonya"],"d":"Kammu 781'de tahta çıktı; Budist tarikatların gücünü sınırlayan fermanlar çıkardı ve kuzeyde Ainu/Emishi'yi boyunduruk altına aldı.","kaynak":"Britannica, «Kammu» (https://www.britannica.com/biography/Kammu): «Enthroned in 781 as the emperor Kammu, he was one of the strongest rulers Japan had known for several centuries.»","gun":"781 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kannauc"],"onem":2,"dunya":1,"kapsam":"ic","t":"0783-01-01","b":"Vatsaraja Ujjain kralı olarak belgelenir (783); Rastrakuta'dan ağır yenilgi alır","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Ujjain","taraflar":["gurjara-pratihara","rastrakuta"],"d":"Nagabhata I'in büyük yeğeni Vatsaraja 783'te Ujjain kralı olarak belgelenir; Rastrakutalardan büyük yenilgi aldı, o ve oğlu II. Nagabhata bir süre Rastrakuta üstünlüğünü kabul etti.","kaynak":"Britannica, «Gurjara-Pratihara dynasty» (https://www.britannica.com/topic/Gurjara-Pratihara-dynasty): «his grandnephew Vatsaraja is attested as king of Ujjain in 783.»","gun":"783 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Astrahan"],"onem":2,"dunya":2,"kapsam":"dis","t":"0799-01-01","b":"Hazarlar İslâm topraklarına yeni bir akın düzenler","tur":"savas","etiket":["konu-askeri"],"yer":"Güney Kafkasya / Azerbaycan","taraflar":["hazar-kaganligi"],"d":"TDV'ye göre bir prensesin zehirlenerek öldürüldüğü söylentileri üzerine Hazarlar 799'da İslâm topraklarına yeni bir akın düzenledi.","kaynak":"TDV İslâm Ansiklopedisi, «HAZARLAR» (https://islamansiklopedisi.org.tr/hazarlar): «799’da Hazarlar İslâm topraklarına yeni bir akın düzenlediler.»","gun":"799 (yıl; gün kaynakta yok)"},{"odak_yer":["Angkor"],"onem":3,"dunya":2,"kapsam":"ic","t":"0802-01-01","b":"Hariharalaya, Jayavarman II tarafından kuruluyor (Siem Reap yakını)","tur":"idari","etiket":["konu-idari"],"yer":"Hariharalaya (Siem Reap yakını)","taraflar":["angkor-kmer"],"d":"Jayavarman II'nin kurduğu başkentlerden Hariharalaya Siem Reap yakınındaydı.","kaynak":"Britannica, «Hariharalaya» (https://www.britannica.com/topic/Hariharalaya): «Founded by Jayavarman II around 802 CE, it was located near present-day Siem Reap»","gun":"ca. 802 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":2,"dunya":2,"kapsam":"dis","t":"0804-01-01","b":"Saichō Çin'e öğrenmeye gönderildi; Tendai mezhebini getirdi","tur":"din","etiket":["konu-din"],"yer":"Japonya / Tang Çin","taraflar":["heian-japonya"],"d":"Saichō 804'te Çin'e gönderildi, Tendai öğretileriyle döndü ve Hiei-zan'da manastırını kurdu.","kaynak":"Britannica, «Saichō» (https://www.britannica.com/biography/Saicho): «was sent to China to study in 804 and returned with the highly eclectic Tendai»","gun":"804 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":1,"kapsam":"ic","t":"0805-01-01","b":"Xianzong tahta çıktı; Tang gücünü yeniden kazandı","tur":"hukumdar","etiket":["hukumdar","konu-kisiler","konu-hanedan"],"yer":"Chang’an","taraflar":["tang"],"d":"Dezong’un 805’te ölümünden sonra kısa süren Shunzong dönemi geçti; Xianzong (805–820) taşra politikasında başarılı oldu ve merkezi otoriteyi çoğu bölgede yeniden kurdu.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «Under Xianzong (reigned 805–820) the Tang regained a great deal of its power.»","gun":"805 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":2,"dunya":2,"kapsam":"dis","t":"0806-01-01","b":"Kūkai Çin'den döndü; Shingon öğretisini yaymak için imparatorluk izni aldı","tur":"din","etiket":["konu-din"],"yer":"Japonya","taraflar":["heian-japonya"],"d":"Kūkai 804'te Çin'e gitmiş, 806'da dönerek Shingon (Gerçek Söz) okulunun öğretilerini yaymak için imparatorluk onayı almıştır.","kaynak":"Britannica, «Kūkai» (https://www.britannica.com/biography/Kukai): «Returning to Japan in 806, Kūkai was given imperial sanction to promulgate his new doctrines.»","gun":"806 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":3,"dunya":2,"kapsam":"ic","t":"0806-04-09","b":"İmparator Kammu Heian-kyō'da öldü","tur":"olum","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto)","taraflar":["heian-japonya"],"d":"Başkenti Heian-kyō'ya taşıyan Kammu 9 Nisan 806'da öldü.","kaynak":"Britannica, «Kammu» (https://www.britannica.com/biography/Kammu): «Kammu (born 737, Nara, Japan—died April 9, 806, Heian-kyō [now Kyōto])»"},{"odak_yer":["Mungîr (Monghyr)"],"onem":3,"dunya":2,"kapsam":"ic","t":"0810-01-01","b":"Devapala Pala tahtında (yak. 810-850); kuzeye, Dekan'a ve yarımadaya akınlar yapar","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Bengal-Bihar","taraflar":["pala"],"d":"Devapala döneminde Pala gücü sürdü; kuzeye, Dekan'a ve yarımadaya akınlar düzenlendi, ondan sonra hanedan gerilemeye başladı.","kaynak":"Britannica, «Pala dynasty» (https://www.britannica.com/topic/Pala-dynasty): «Pala power was maintained under Devapala (reigned c. 810–850), who carried out raids in the north, the Deccan, and the peninsula»","gun":"810 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Manyakheta"],"onem":3,"dunya":2,"kapsam":"ic","t":"0814-01-01","b":"I. Amoghavarşa tahta çıkar (yak. 814-878); Kavirajamarga'nın bir bölümünü yazar","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Manyakheta","taraflar":["rastrakuta"],"d":"I. Amoghavarşa yaklaşık 64 yıl hüküm sürdü; en eski bilinen Kannada şiiri Kavirajamarga'nın bir kısmının yazarıdır. Gujarat onun döneminde kaybedildi.","kaynak":"Britannica, «Rashtrakuta dynasty» (https://www.britannica.com/topic/Rashtrakuta-dynasty): «Amoghavarsha I, who reigned from about 814 to 878, was the author of part of the Kavirajamarga»","gun":"814 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":1,"dunya":1,"kapsam":"ic","t":"0816-01-01","b":"Kūkai Kōya Dağı'nda manastır inşasına başladı","tur":"din","etiket":["konu-din"],"yer":"Kōya Dağı (Japonya)","taraflar":["heian-japonya"],"d":"Kūkai 816'da Kōya Dağı'nda, sonradan en büyük manastır komplekslerinden birine dönüşen yapıyı kurmaya başladı.","kaynak":"Britannica, «Kūkai» (https://www.britannica.com/biography/Kukai): «In 816 he began building a monastery on Mount Kōya, in west-central Japan.»","gun":"816 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Mungîr (Monghyr)"],"onem":4,"dunya":3,"kapsam":"ic","t":"0816-01-01","b":"II. Nagabhata Kannauj'u Çakrayudha'dan alır ve yeni başkent yapar (yak. 816)","tur":"fetih","etiket":["konu-askeri","yaklasik"],"yer":"Kannauj","taraflar":["gurjara-pratihara","pala"],"d":"II. Nagabhata yak. 816'da Hint-Gang ovasına inip, Pala hükümdarı Dharmapala'nın koruması altındaki yerel kral Çakrayudha'dan Kannauj'u aldı; Kuzey Hindistan'ın en güçlü hükümdarı oldu.","kaynak":"Britannica, «Gurjara-Pratihara dynasty» (https://www.britannica.com/topic/Gurjara-Pratihara-dynasty): «About 816 he invaded the Indo-Gangetic Plain and captured Kannauj from the local king Chakrayudha»","gun":"816 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Dali"],"onem":3,"dunya":2,"kapsam":"dis","t":"0832-01-01","b":"Nanzhao Myanmar'ın derinliklerine sefer yaptı","tur":"savas","etiket":["konu-askeri"],"yer":"Myanmar (Burma)","taraflar":["nanzhao"],"d":"9. yüzyılda yayılmacı bir devlete dönüşen Nanzhao 832'de Myanmar'ın içlerine kadar savaştı.","kaynak":"Britannica, «Nanzhao» (https://www.britannica.com/place/Nanzhao): «waging war deep into Myanmar (Burma) in 832 and into Tongking in 862»","gun":"832 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":1,"kapsam":"ic","t":"0835-01-01","b":"Tatlı Çiy (Ganlu) darbesi başarısızlıkla bitti","tur":"siyaset","etiket":["siyaset","konu-siyasi"],"yer":"Chang’an","taraflar":["tang"],"d":"Wenzong’un haremağalarını devirme girişimi 835’te Tatlı Çiy darbesiyle sonuçlandı; plan ters tepti, birkaç bakan ve görevli öldü.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «the Sweet Dew (Ganlu) coup of 835, which misfired and led to the deaths of several ministers»","gun":"835 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kannauc"],"onem":3,"dunya":2,"kapsam":"ic","t":"0836-01-01","b":"Mihira Bhoja Pratihara tahtına çıkar (yak. 836)","tur":"hukumdar","etiket":["konu-siyasi","yaklasik"],"yer":"Kannauj","taraflar":["gurjara-pratihara"],"d":"Ramabhadra kısa saltanatın ardından Mihira Bhoja yak. 836'da tahta çıktı; Bhoja ve halefi Mahendrapala döneminde Pratihara imparatorluğu zirveye ulaştı.","kaynak":"Britannica, «Gurjara-Pratihara dynasty» (https://www.britannica.com/topic/Gurjara-Pratihara-dynasty): «succeeded by his son Mihira Bhoja about 836.»","gun":"836 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":1,"kapsam":"ic","t":"0840-01-01","b":"Wuzong tahta çıktı; haremağası gücü sınırlandı","tur":"hukumdar","etiket":["hukumdar","konu-kisiler","konu-hanedan"],"yer":"Chang’an","taraflar":["tang"],"d":"Haremağalarının iktidar zirvesi 840’ta Wuzong’un tahta çıkışıyla sona erdi; Wuzong ve bakanı Li Deyu özellikle ordu üzerindeki nüfuzlarını kısıtladı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «But the apogee of the eunuchs’ power was brief, ending with the accession of Wuzong in 840.»","gun":"840 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Turfan"],"onem":3,"dunya":3,"kapsam":"ic","t":"0840-01-01","b":"Uygur boyları dağılır: bir kısmı Beşbalık, Turfan, Hoço ve Kâşgar'a yerleşir","tur":"siyasi","etiket":["konu-siyasi"],"yer":"Beşbalık, Turfan, Hoço, Kâşgar","taraflar":["uygur-kaganligi","koco-uygur"],"d":"Kırgızların Uygur Kağanlığı'nı yıkmasından (840) sonra çevreye dağılan Uygur boylarının bir kısmı batıya giderek Beşbalık, Turfan, Hoço ve Kâşgar taraflarına yerleşti; Koço Uygur Devleti'nin zemini böyle hazırlandı. (Künye f=911; TDV Türk maddesi Koço Uygur Devleti için 850-1250, Turfan maddesi 850 dolaylarını verir.)","kaynak":"TDV İslâm Ansiklopedisi, «TÜRK» (https://islamansiklopedisi.org.tr/turk): «840’ta çevreye dağılan Uygur boylarından bir kısmı batıya giderek Beşbalık, Turfan, Hoço, Kâşgar taraflarında yerleşti.»","gun":"840 (yıl; gün kaynakta yok)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":3,"kapsam":"ic","t":"0843-01-01","b":"Wuzong Budizm’i bastırdı (843–845)","tur":"din","etiket":["din","konu-din"],"yer":"Tang","taraflar":["tang"],"d":"Fanatik Taoist Wuzong, kısmen mali sebeplerle 40.000 tapınak ve mabedi kapattı, 260.000 rahip/rahibeyi lay hayata döndürdü; bastırma kısa sürdü ama Çin Budizmi için kalıcı hasar bıraktı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «In 843–845 the emperor Wuzong, a fanatical Daoist, proceeded to suppress Buddhism.»","gun":"843 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Tibet"],"onem":3,"dunya":2,"kapsam":"ic","t":"0843-01-01","b":"Langdarma (Glang-dar-ma) Budizm'in bastırılmasını emretti","tur":"din","etiket":["konu-din"],"yer":"Tibet","taraflar":["tibet-imparatorlugu","tibet-imparatorlugu"],"d":"Britannica'ya göre Glandar-ma (hükümdarlık 841-846) 843'te Budizm'in bastırılmasını emretti; Tibet'in Budist gelenekleri bir yüzyıldan fazla kesintiye uğradı.","kaynak":"Britannica, «Tibet — Disunity, 9th-14th century» (https://www.britannica.com/place/Tibet/Disunity-9th-to-14th-century): «In 843, during that period, Glandar-ma (reigned 841–846) ordered the suppression of Buddhism»","gun":"843 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Pagan"],"onem":4,"dunya":3,"kapsam":"ic","t":"0849-01-01","b":"Burmalılar Pagan'ı başkent yapıyor; Pagan krallığı kuruluyor","tur":"kurulus","etiket":["konu-kurulus"],"yer":"Pagan (Irrawaddy)","taraflar":["pagan"],"d":"Nanzhao akınlarıyla oluşan siyasi boşlukta Burmalılar 849'da Pagan'ı başkent edindi.","kaynak":"Britannica, «Myanmar – History» (https://www.britannica.com/topic/history-of-Myanmar): «The Burmans moved into this political vacuum, establishing Pagan as their capital city in 849.»","gun":"849 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kançipuram (Kanchipuram)"],"onem":4,"dunya":2,"kapsam":"ic","t":"0850-01-01","b":"Vijayalaya (yak. 850-870) Pallava topraklarını işgale başlar; Çola yükselişinin başlangıcı","tur":"kurulus","etiket":["konu-siyasi","yaklasik"],"yer":"Tancavur / Tondaimandalam","taraflar":["cola","pallava"],"d":"Vijayalaya Pallava topraklarının işgaline başladı; I. Aditya (yak. 870-907) döneminde bu genişleme sürdü.","kaynak":"Britannica, «Chola dynasty» (https://www.britannica.com/topic/Chola-dynasty): «Vijayalaya (reigned c. 850–870) began the occupation of the territory of the Pallavas»","gun":"850 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Kâbil"],"onem":3,"dunya":2,"kapsam":"dis","t":"0850-01-01","b":"Brahman Kallâr Türkşâhî tahtını ele geçirip Hindûşâhî hanedanını kurar (yak. 850)","tur":"kurulus","etiket":["konu-siyasi","yaklasik"],"yer":"Kâbil","taraflar":["hindu-sahiler"],"d":"Son Türkşâhî hükümdarı Lagatûrman'ın veziri Kallâr tahtı ele geçirdi ve yaklaşık 850'de Hindûşâhîler denilen hânedanı kurdu.","kaynak":"TDV İslâm Ansiklopedisi, «HİNDÛŞÂHÎLER» (https://islamansiklopedisi.org.tr/hindusahiler): «tahtı ele geçirmiş ve yaklaşık 850 yılında Hindûşâhîler (Hindûşâhiyye) denilen bu hânedanı kurmuştur.»","gun":"850 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Mataram"],"onem":3,"dunya":2,"kapsam":"ic","t":"0850-01-01","b":"Prambanan Hindu tapınak grubu inşa ediliyor (yaklaşık 850-875)","tur":"siyasi","etiket":["konu-kultur"],"yer":"Prambanan, Orta Java","taraflar":["medang"],"d":"Şiva, Vişnu ve Brahma'ya adanmış büyük Hindu tapınak grubu Prambanan yaklaşık 850-875 arasında Orta Java'da yapıldı.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «A major Hindu temple group dedicated to Shiva, Vishnu, and Brahma is constructed at Prambanan in Central Java.»","gun":"ca. 850 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":3,"dunya":1,"kapsam":"ic","t":"0857-01-01","b":"Fujiwara no Yoshifusa dajō daijin (büyük devlet bakanı) atandı","tur":"idari","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto)","taraflar":["heian-japonya"],"d":"Yoshifusa 857'de, sarayın birkaç kuşaktır boş bıraktığı dajō daijin makamına atandı; ertesi yıl torununu tahta çıkarıp naip oldu (858, iskelette).","kaynak":"Britannica, «Fujiwara Yoshifusa» (https://www.britannica.com/biography/Fujiwara-Yoshifusa): «In 857 Yoshifusa was appointed to the influential post of great minister of state (dajō daijin)»","gun":"857 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":3,"dunya":2,"kapsam":"dis","t":"0858-01-01","b":"Nanzhao ile Annam–Sichuan savaşı (858–866)","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Annam / Sichuan","taraflar":["tang"],"d":"Annam’daki Çin himayesi sınırında başlayan Nanzhao savaşı Sichuan’a yayıldı ve 858–866 arasında sürdü; 870’te yeniden savaş çıktı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «which later spread to Sichuan and dragged on from 858 until 866»","gun":"858 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kûfe"],"onem":3,"dunya":1,"kapsam":"dis","t":"0861-03-17","b":"Hebbârî valisi Ömer b. Abdülazîz Mütevekkil'in öldürülmesinden sonra Sind'de bağımsızlığını ilân eder (247/861)","tur":"isyan","etiket":["konu-siyasi","sind"],"yer":"Sind","taraflar":["abbasi"],"d":"Abbâsî valisi Ömer b. Abdülazîz el-Hebbârî Halife Mütevekkil'in öldürülmesinin ardından bağımsızlığını ilân etti; Sind bundan sonra Gazneliler'in gelişine kadar Hebbârîler tarafından yönetildi (Saffârîlere devir dışında).","kaynak":"TDV İslâm Ansiklopedisi, «SİND» (https://islamansiklopedisi.org.tr/sind): «Abbâsî Valisi Ömer b. Abdülazîz el-Hebbârî, Halife Mütevekkil-Alellah’ın öldürülmesini (247/861) takiben bağımsızlığını ilân etti.»","gun":"247 (861) (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Dali"],"onem":3,"dunya":2,"kapsam":"dis","t":"0862-01-01","b":"Nanzhao Tongking'e (Kuzey Vietnam) sefer yaptı","tur":"savas","etiket":["konu-askeri"],"yer":"Tongking (Kuzey Vietnam)","taraflar":["nanzhao"],"d":"Nanzhao 862'de Tongking'e (Kuzey Vietnam) savaş açtı; 832'de Myanmar'da savaşmıştı.","kaynak":"Britannica, «Nanzhao» (https://www.britannica.com/place/Nanzhao): «waging war deep into Myanmar (Burma) in 832 and into Tongking in 862»","gun":"862 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":2,"dunya":1,"kapsam":"ic","t":"0872-10-07","b":"Fujiwara no Yoshifusa öldü; Mototsune Fujiwara başı oldu","tur":"olum","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto)","taraflar":["heian-japonya"],"d":"Fujiwara hâkimiyetini başlatan Yoshifusa 7 Ekim 872'de öldü; yerine evlatlığı Mototsune Fujiwara klanının başına geçti.","kaynak":"Britannica, «Fujiwara Yoshifusa» (https://www.britannica.com/biography/Fujiwara-Yoshifusa): «Fujiwara Yoshifusa (born 804, Kyōto, Japan—died Oct. 7, 872, Kyōto)»"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0874-01-01","b":"Kuraklık sonrası köylü ayaklanmaları dalgası başladı","tur":"isyan","etiket":["isyan","konu-isyan"],"yer":"Henan / Huai","taraflar":["tang"],"d":"Henan’daki sel ve şiddetli kuraklığın ardından 874’te çiftçi ayaklanmaları başladı; en büyüğünün lideri Huang Chao oldu.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «a wave of uprisings by farmers began in 874, following a terrible drought»","gun":"874 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":3,"dunya":1,"kapsam":"ic","t":"0876-01-01","b":"Fujiwara no Mototsune çocuk imparator Yōzei'ye naip oldu","tur":"idari","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto)","taraflar":["heian-japonya"],"d":"Mototsune 872'de Fujiwara başı olduktan dört yıl sonra, reşit olmayan Yōzei tahta çıkınca naiplik makamını üstlendi.","kaynak":"Britannica, «Fujiwara Mototsune» (https://www.britannica.com/biography/Fujiwara-Mototsune): «Mototsune assumed the post of regent when another minor, Yōzei, succeeded to the throne four years later.»","gun":"876 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Manyakheta"],"onem":2,"dunya":2,"kapsam":"ic","t":"0878-01-01","b":"II. Krişna tahta çıkar; Amoghavarşa'nın kaybettiği Gujarat'ı yeniden alır, Vengi'yi alamaz","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Gujarat","taraflar":["rastrakuta"],"d":"II. Krişna 878'de tahta çıktı ve Gujarat'ı yeniden elde etti; fakat Vengi'yi geri alamadı.","kaynak":"Britannica, «Rashtrakuta dynasty» (https://www.britannica.com/topic/Rashtrakuta-dynasty): «Krishna II, who succeeded in 878, reacquired Gujarat, which Amoghavarsha I had lost, but failed to retake Vengi.»","gun":"878 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Luoyang"],"onem":4,"dunya":2,"kapsam":"ic","t":"0880-01-01","b":"Huang Chao Luoyang’ı aldı","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Luoyang","taraflar":["tang"],"d":"Güneye inip Guangzhou’yu yağmalayan Huang Chao kuzeye dönüp 880 sonlarında Luoyang’ı ele geçirdi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «he took Luoyang in late 880 and Chang’an in 881»","gun":"880 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":5,"dunya":3,"kapsam":"ic","t":"0881-01-01","b":"Huang Chao Chang’an’ı aldı; Daqi hanedanını ilan etti","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Chang’an","taraflar":["tang"],"d":"Huang Chao 881’de başkent Chang’an’ı aldı ve Daqi hanedanının ilk imparatoru olduğunu ilan etti; ancak gıda tedarikini örgütleyemedi.","kaynak":"Britannica, «Huang Chao» (https://www.britannica.com/biography/Huang-Chao): «capturing the capital at Chang’an (now Xi’an) in 881. He proclaimed himself the first emperor of the Daqi dynasty»","gun":"881 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0883-01-01","b":"Tang, Şato Türklerinin yardımıyla Huang Chao’yu başkentten çıkardı","tur":"savas","etiket":["askeri","konu-askeri"],"yer":"Chang’an","taraflar":["tang"],"d":"883’te hükümet, göçebe Türk Şatolarla ittifak ederek Huang Chao’yu başkentten sürdü; sonraki yıl Huang’ın birlikleri yenildi.","kaynak":"Britannica, «Huang Chao» (https://www.britannica.com/biography/Huang-Chao): «in 883 the government, aided by an alliance with a group of nomadic Turkish tribes, the Shatuo, drove him from the capital»","gun":"883 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":3,"dunya":1,"kapsam":"ic","t":"0884-01-01","b":"Mototsune, kendisine karşı çıkan imparator Yōzei'yi tahttan çekilmeye zorladı","tur":"siyaset","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto)","taraflar":["heian-japonya"],"d":"Yōzei 884'te Mototsune'nin yönetimine meydan okuyunca Mototsune onu tahttan çekilmeye zorladı.","kaynak":"Britannica, «Fujiwara Mototsune» (https://www.britannica.com/biography/Fujiwara-Mototsune): «When in 884 the emperor Yōzei challenged his rule, Mototsune forced his abdication.»","gun":"884 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Xi'an"],"onem":4,"dunya":2,"kapsam":"ic","t":"0884-01-01","b":"Huang Chao Shandong’da öldü; Tang fiilen çöktü","tur":"olum","etiket":["hukumdar","konu-kisiler"],"yer":"Laiwu (Shandong)","taraflar":["tang"],"d":"Huang Chao Temmuz 884’te Shandong’da öldü; 10 yıllık isyan Tang’ın denetimini yok etti. Tahtı gasp eden Zhu Wen onun eski generallerindendi.","kaynak":"Britannica, «Huang Chao» (https://www.britannica.com/biography/Huang-Chao): «died July 884, Laiwu, Shandong province»","gun":"884 Temmuz (ay; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":2,"dunya":1,"kapsam":"ic","t":"0887-01-01","b":"İmparator Uda tahta çıktı (887-897); annesi Fujiwara olmayan ilk imparator","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto)","taraflar":["heian-japonya"],"d":"Uda (887-897), birkaç kuşaktır annesi Fujiwara olmayan ilk Japon hükümdarıydı; kampaku makamı bu dönemde boş bırakıldı.","kaynak":"Britannica, «Fujiwara Tadahira» (https://www.britannica.com/biography/Fujiwara-Tadahira): «the emperor Uda (reigned 887–897), the first Japanese sovereign in several generations whose mother was not a Fujiwara»","gun":"887 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Tibet"],"onem":3,"dunya":2,"kapsam":"ic","t":"0889-01-01","b":"Tibet birbirinden ayrı beyliklerin yığınına dönüştü","tur":"bolunme","etiket":["konu-siyasi"],"yer":"Tibet","taraflar":["tibet-imparatorlugu","tibet-imparatorlugu"],"d":"9. yüzyıl başında eski kraliyet ailesinin bir kolu Batı Tibet'e göç edip halef krallıklar kurdu; 889'a gelindiğinde Tibet ayrı beyliklerin yığını hâline gelmişti.","kaynak":"Britannica, «Tibet — Disunity, 9th-14th century» (https://www.britannica.com/place/Tibet/Disunity-9th-to-14th-century): «by 889 Tibet was a mere congeries of separate lordships»","gun":"889 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Angkor"],"onem":4,"dunya":3,"kapsam":"ic","t":"0889-01-01","b":"Yashovarman I Yashodharapura'yı (bugünkü Angkor) başkent yapıyor","tur":"idari","etiket":["konu-idari"],"yer":"Yashodharapura (Angkor)","taraflar":["angkor-kmer"],"d":"Yashovarman I (889–ca. 910/12) bugünkü Angkor'da Yashodharapura başkentini kurdu; Phnom Bakheng onun tapınak-dağıdır.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «Yashovarman I establishes a capital at Yashodharapura at present-day Angkor in Cambodia.»","gun":"889 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Mungîr (Monghyr)"],"onem":3,"dunya":2,"kapsam":"ic","t":"0890-01-01","b":"Mahendrapala Pratihara tahtında (yak. 890-910); imparatorluk Gujarat'tan Kuzey Bengal'e uzanır","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Kannauj","taraflar":["gurjara-pratihara","pala"],"d":"Mahendrapala döneminde Pratihara toprakları Gujarat ve Kathiawar'dan kuzey Bengal'e kadar uzanıyordu; ancak büyük kısmı vasal kralların elindeydi.","kaynak":"Britannica, «Gurjara-Pratihara dynasty» (https://www.britannica.com/topic/Gurjara-Pratihara-dynasty): «Mahendrapala (reigned c. 890–910), reached from Gujarat and Kathiawar to northern Bengal»","gun":"890 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":2,"dunya":1,"kapsam":"ic","t":"0891-02-25","b":"Fujiwara no Mototsune öldü","tur":"olum","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto)","taraflar":["heian-japonya"],"d":"Dört yetişkin imparatora naiplik yapan, kampaku makamını yaratan Mototsune 25 Şubat 891'de öldü.","kaynak":"Britannica, «Fujiwara Mototsune» (https://www.britannica.com/biography/Fujiwara-Mototsune): «Fujiwara Mototsune (born 836, Kyōto, Japan—died Feb. 25, 891, Kyōto)»"},{"odak_yer":["Kyongcu"],"onem":3,"dunya":1,"kapsam":"ic","t":"0892-01-01","b":"Gyeon Hwon Sonraki Baekje'yi (Hubaekje) kurdu; Geç Üç Krallık dönemi başladı","tur":"kurulus","etiket":["konu-siyasi"],"yer":"Güneybatı Kore","taraflar":["hubaekje","silla"],"d":"Silla'nın yerel güç sahiplerinin yükselişiyle zayıflaması sırasında Gyeon Hwon Sonraki Baekje'yi (892), Gung Ye ise Sonraki Goguryeo'yu (901) kurdu; Silla ile birlikte Geç Üç Krallık denir.","kaynak":"Britannica, «Korea — Unified Silla» (https://www.britannica.com/place/Korea/Unified-Silla): «established, respectively, the Later Baekje (892) and Later Goguryeo (also called Majin or Taebong; 901) kingdoms»","gun":"892 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":2,"dunya":1,"kapsam":"ic","t":"0897-01-01","b":"Daigo imparator oldu (897-930); Fujiwara'yı kampaku yapmadan yönetmeyi denedi","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto)","taraflar":["heian-japonya"],"d":"Uda'nın oğlu Daigo 897'de tahta çıktı; babası gibi Fujiwara'dan kampaku atamadı, ancak Fujiwara baskısına direnemedi.","kaynak":"Britannica, «Daigo» (https://www.britannica.com/biography/Daigo): «he ascended the throne in 897 and assumed the reign name Daigo»","gun":"897 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Angkor"],"onem":3,"dunya":3,"kapsam":"ic","t":"0900-01-01","b":"Khmer krallığı bugünkü Burma, Laos ve Tayland'ın geniş alanlarını kapsıyor","tur":"toprak-kazanc","etiket":["konu-askeri"],"yer":"Kamboçya, Burma, Laos, Tayland","taraflar":["angkor-kmer"],"d":"Yaklaşık 900-1000 arasında Khmer krallığı bugünkü Burma, Laos ve Tayland'ın geniş alanlarını kendine kattı.","kaynak":"Metropolitan Museum of Art, «Southeast Asia, 500–1000 A.D.», Heilbrunn Timeline of Art History (https://www.metmuseum.org/toah/ht/06/sse.html): «The Khmer kingdom of Cambodia expands to incorporate large areas of present-day Burma, Laos, and Thailand.»","gun":"ca. 900-1000 (yıl aralığı; gün yok)"},{"odak_yer":["Kyoto"],"onem":3,"dunya":1,"kapsam":"ic","t":"0901-01-01","b":"Sugawara no Michizane, Fujiwara no Tokihira'nın hasmane girişimiyle Kyushu'ya sürüldü","tur":"siyaset","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto) → Dazaifu (Kyushu)","taraflar":["heian-japonya"],"d":"Fujiwara no Tokihira, imparatoru Michizane'nin ihanet planladığına inandırdı; Michizane başkentten uzaklaştırılıp Kyushu'daki idari göreve gönderildi.","kaynak":"Britannica, «Sugawara Michizane» (https://www.britannica.com/biography/Sugawara-Michizane): «in 901 Fujiwara Tokihira, Sugawara’s rival, convinced the emperor that Sugawara was plotting treason»","gun":"901 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":2,"dunya":1,"kapsam":"ic","t":"0903-03-26","b":"Sugawara no Michizane Dazaifu'da öldü (sonradan Tenjin olarak tanrılaştırıldı)","tur":"olum","etiket":["konu-siyasi"],"yer":"Dazaifu (Kyushu)","taraflar":["heian-japonya"],"d":"Sürgündeki Michizane 26 Mart 903'te öldü; sonradan Tenjin adıyla bilginlerin hamisi sayıldı.","kaynak":"Britannica, «Sugawara Michizane» (https://www.britannica.com/biography/Sugawara-Michizane): «Sugawara Michizane (born 845, Japan—died March 26, 903, Dazaifu, Japan)»"},{"odak_yer":["Madurai"],"onem":3,"dunya":2,"kapsam":"ic","t":"0907-01-01","b":"I. Parantaka Çola tahtında (907-yak. 955); Madurai'nin yıkıcısı","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Tancavur","taraflar":["cola","pandya-1"],"d":"I. Parantaka Pandya başkenti Madurai'yi yıktı, Sinhalli işgalcileri yendi ve Çola ile Pandya topraklarını birleştirdi.","kaynak":"Britannica, «Chola dynasty» (https://www.britannica.com/topic/Chola-dynasty): «Parantaka I (reigned 907–c. 955), known as the destroyer of Madurai»","gun":"907 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":2,"dunya":1,"kapsam":"ic","t":"0909-01-01","b":"Fujiwara no Tadahira kardeşi Tokihira'nın ölümüyle Fujiwara klanının başına geçti","tur":"siyaset","etiket":["konu-siyasi"],"yer":"Heian-kyō (Kyōto)","taraflar":["heian-japonya"],"d":"Tadahira 909'da kardeşi Tokihira'nın ölümü üzerine Fujiwara başı oldu; onun döneminde eyaletlerde isyanlar ve eşkıyalık yaygınlaştı.","kaynak":"Britannica, «Fujiwara Tadahira» (https://www.britannica.com/biography/Fujiwara-Tadahira): «assumed the leadership of the Fujiwara family in 909 upon the death of his brother Tokihira»","gun":"909 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kannauc"],"onem":3,"dunya":2,"kapsam":"ic","t":"0914-01-01","b":"III. Indra tahta çıkar; Kannauj'u alır, Rastrakuta gücü zirveye ulaşır","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Kannauj","taraflar":["rastrakuta","gurjara-pratihara"],"d":"III. Indra 914'te tahta çıktı; Kannauj'u ele geçirerek Rastrakuta gücünü doruğa çıkardı.","kaynak":"Britannica, «Rashtrakuta dynasty» (https://www.britannica.com/topic/Rashtrakuta-dynasty): «Indra III, who came to the throne in 914, captured Kannauj and brought Rashtrakuta power to its peak.»","gun":"914 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kannauc"],"onem":4,"dunya":3,"kapsam":"ic","t":"0916-01-01","b":"Rastrakuta III. Indra Pratihara başkenti Kannauj'u yağmalar (yak. 916)","tur":"savas","etiket":["konu-askeri","yaklasik"],"yer":"Kannauj","taraflar":["rastrakuta","gurjara-pratihara"],"d":"Dekan'dan gelen büyük akında III. Indra yak. 916'da Kannauj'u yağmaladı; Pratiharalar eski nüfuzlarını bir daha geri kazanamadı.","kaynak":"Britannica, «Gurjara-Pratihara dynasty» (https://www.britannica.com/topic/Gurjara-Pratihara-dynasty): «a great raid from the Deccan, led by the Rastrakuta king Indra III, who about 916 sacked Kannauj.»","gun":"916 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Bağdat"],"onem":3,"dunya":3,"kapsam":"dis","t":"0921-06-21","b":"İbn Fadlân'ın elçilik heyeti Bağdat'tan İdil Bulgarlarına yola çıkar","tur":"diplomasi","etiket":["konu-diplomasi"],"yer":"Bağdat","taraflar":["idil-bulgar"],"d":"Bulgar hanı Almış'ın Abbâsî halifesinden talebi üzerine Sevsen er-Ressî başkanlığındaki, İbn Fadlân'ın kâtip ve danışman olarak bulunduğu heyet 11 Safer 309'da (21 Haziran 921) Bağdat'tan yola çıktı; Rey, Nîşâbur, Merv, Buhara ve Hârizm üzerinden gitti.","kaynak":"TDV İslâm Ansiklopedisi, «İBN FADLÂN» (https://islamansiklopedisi.org.tr/ibn-fadlan): «11 Safer 309 (21 Haziran 921) tarihinde Bağdat’tan yola çıkan heyet»","gun":"21 Haziran 921 (kaynak Milâdî günü verir)"},{"odak_yer":["Bulgar (Bolgar)"],"onem":4,"dunya":4,"kapsam":"dis","t":"0922-05-12","b":"İbn Fadlân heyeti İdil Bulgar hanının karargâhına ulaşır","tur":"diplomasi","etiket":["konu-diplomasi","konu-din"],"yer":"İdil (Volga) boyu, Bulgar hanının karargâhı","taraflar":["idil-bulgar"],"d":"İbn Fadlân'ın bulunduğu Abbâsî heyeti 12 Muharrem 310'da (12 Mayıs 922) Bulgar hanı Almış'ın İdil boyundaki karargâhına ulaştı. Almış, İslâmiyet'i kabul etmek istediğini bildirip halifeden din adamı istemişti.","kaynak":"TDV İslâm Ansiklopedisi, «İDİL BULGAR HANLIĞI» (https://islamansiklopedisi.org.tr/idil-bulgar-hanligi): «heyet, 12 Muharrem 310’da (12 Mayıs 922) Bulgar hanının İdil boyundaki karargâhına ulaştı.»","gun":"12 Mayıs 922 (kaynak Milâdî günü verir; hicrî 12 Muharrem 310 hesabı da 12 Mayıs 922 verir)"},{"odak_yer":["Kançipuram (Kanchipuram)"],"onem":3,"dunya":2,"kapsam":"ic","t":"0926-01-01","b":"Çola ve Pandya toprakları I. Parantaka eliyle birleştirilir (926-942)","tur":"toprak-kazanc","etiket":["konu-askeri"],"yer":"Madurai, Tamil ülkesi","taraflar":["cola","pandya-1"],"d":"Parantaka I Sinhalli işgalcileri yendi ve 926-942 arasında Çola ve Pandya ülkelerini birleştirdi.","kaynak":"Britannica, «Chola dynasty» (https://www.britannica.com/topic/Chola-dynasty): «united the lands of the Cholas and the Pandyas between 926 and 942.»","gun":"926 (yıl; aralık 926-942, ilk yıl)"},{"odak_yer":["Kyoto"],"onem":3,"dunya":1,"kapsam":"ic","t":"0939-01-01","b":"Taira no Masakado Kantō'yu ele geçirip kendini 'Yeni İmparator' ilan etti","tur":"isyan","etiket":["konu-askeri"],"yer":"Kantō bölgesi (Japonya)","taraflar":["heian-japonya"],"d":"İmparator Kammu soyundan gelen Masakado, Kantō'da denetim kurup kendi sarayını oluşturdu ve sekiz kuzey eyaletine vali atadı; isyan merkezî hükûmetin taşra üzerindeki gücünün zayıflamasının belirtisiydi.","kaynak":"Britannica, «Taira Masakado» (https://www.britannica.com/biography/Taira-Masakado): «In 939 Masakado gained control of the Kantō region in central Japan and used the mystique of his Imperial blood»","gun":"939 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kyoto"],"onem":3,"dunya":1,"kapsam":"ic","t":"0940-03-25","b":"Taira no Masakado isyanı bastırıldı; Masakado öldü (Tengyō no ran)","tur":"isyan","etiket":["konu-askeri"],"yer":"Kitayama, Shimōsa Eyaleti (Japonya)","taraflar":["heian-japonya"],"d":"Masakado iki yerel rakip tarafından denetim altına alındı ve 25 Mart 940'ta öldü (Tengyō Savaşı).","kaynak":"Britannica, «Taira Masakado» (https://www.britannica.com/biography/Taira-Masakado): «Taira Masakado (died March 25, 940, Kitayama, Shimōsa Province, Japan) was a Japanese rebel leader»"},{"odak_yer":["Kançipuram (Kanchipuram)"],"onem":3,"dunya":2,"kapsam":"ic","t":"0948-01-01","b":"III. Krişna Kançi'yi ve Tamil ovalarının büyük bölümünü işgal eder (948-966/967)","tur":"isgal","etiket":["konu-askeri"],"yer":"Kançipuram, Tamil ovaları","taraflar":["rastrakuta","cola"],"d":"III. Krişna kuzey seferlerinde (yak. 940) ve 948-966/967 arasında Kançi'nin ve Tamil ovalarının büyük bölümünün işgalinde III. Indra'yı geride bıraktı; Çola yönetimindeki Tondaimandalam'ı da ele geçirmişti.","kaynak":"Britannica, «Rashtrakuta dynasty» (https://www.britannica.com/topic/Rashtrakuta-dynasty): «Krishna III outdid him in northern campaigns (c. 940) and in a spectacular occupation of Kanchi and much of the Tamil plains (948–966/967).»","gun":"948 (yıl; aralık 948-966/967, ilk yıl)"},{"odak_yer":["Kiev"],"onem":3,"dunya":3,"kapsam":"dis","t":"0964-01-01","b":"Kiev Rus Knezliği İdil Bulgar ülkesini istilâ eder (ilk istilâ)","tur":"isgal","etiket":["konu-askeri"],"yer":"İdil Bulgar ülkesi","taraflar":["idil-bulgar"],"d":"TDV'ye göre İdil Bulgar ülkesi 964 ve 985'te iki defa Kiev Rus Knezliği'nin istilâsına uğradı; hücumlar etkisiz hale getirildi. 985 seferi künye iskeletindedir.","kaynak":"TDV İslâm Ansiklopedisi, «İDİL BULGAR HANLIĞI» (https://islamansiklopedisi.org.tr/idil-bulgar-hanligi): «İdil Bulgar ülkesi 964 ve 985 yılında iki defa Kiev Rus Knezliği’nin istilâsına uğradıysa da bu hücumlar etkisiz hale getirildi.»","gun":"964 (yıl; gün kaynakta yok)"},{"odak_yer":["Chengdu"],"onem":4,"dunya":2,"kapsam":"ic","t":"0965-01-01","b":"Song, Sichuan’daki Sonraki Shu’yu aldı","tur":"toprak-kayip","etiket":["askeri","toprak-kayip","konu-askeri"],"yer":"Sichuan","taraflar":["sonraki-shu"],"d":"Song kurucusu Taizu’nun planlı stratejisi önce güneybatıda Sichuan’ı 965’te, ardından aşırı güneyi 971’de aldı.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «A well-planned strategy first took Sichuan in the southwest in 965, the extreme south in 971»","gun":"965 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Manyakheta"],"onem":2,"dunya":1,"kapsam":"ic","t":"0968-01-01","b":"IV. Amoghavarşa (Khottiga) tahta çıkar (968-972); başkenti koruyamaz","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Manyakheta","taraflar":["rastrakuta"],"d":"Khottiga Amoghavarşa IV başkenti koruyamadı; başkentin yağması hanedana duyulan güveni yıktı.","kaynak":"Britannica, «Rashtrakuta dynasty» (https://www.britannica.com/topic/Rashtrakuta-dynasty): «Khottiga Amoghavarsha IV (968–972) failed to protect the capital, and its sack destroyed faith in the dynasty.»","gun":"968 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Ninh Binh"],"onem":5,"dunya":3,"kapsam":"ic","t":"0968-01-01","b":"Dinh Bo Linh 11 beyi yenip imparator ilan ediyor; ülke Dai Co Viet","tur":"kurulus","etiket":["konu-kurulus","konu-hukumdar"],"yer":"Hoa Lu (Kuzey Vietnam)","taraflar":["dinh"],"d":"Dinh Bo Linh diğer 11 beyi yenerek 968'e kadar tüm Nam Viet'i ele geçirdi, kendini imparator ilan etti ve birleşik ülkeye Dai Co Viet adını verdi.","kaynak":"Britannica, «Dinh Bo Linh» (https://www.britannica.com/biography/Dinh-Bo-Linh): «Proclaiming himself emperor, he called the reunited country Dai Co Viet.»","gun":"968 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kalyani"],"onem":4,"dunya":2,"kapsam":"ic","t":"0975-01-01","b":"Rastrakuta hanedanı son bulur; Taila I Çalukya mirası alır, ikinci (Batı/Kalyani) Çalukya kurulur (yak. 975)","tur":"siyasi","etiket":["konu-siyasi","yaklasik"],"yer":"Dekan (Kalyani)","taraflar":["rastrakuta","bati-calukya"],"d":"Son Rastrakuta kralı Batı Gatlar'a kaçtı; Taila I Çalukya yak. 975'te mirası aldı ve Kalyani merkezli ikinci Batı Çalukya hanedanını kurdu.","kaynak":"Britannica, «Rashtrakuta dynasty» (https://www.britannica.com/topic/Rashtrakuta-dynasty): «until Taila I Chalukya won the succession about 975.»","gun":"975 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Taiyuan"],"onem":4,"dunya":2,"kapsam":"ic","t":"0979-01-01","b":"Taizong Kuzey Han’ı fethetti; Onkrallık dönemi son buldu","tur":"siyasi","etiket":["siyaset","konu-siyasi","konu-hanedan"],"yer":"Taiyuan (Shanxi)","taraflar":["kuzey-han-10krallik"],"d":"Song kurucusunun ölümünden sonra Taizong kuzeye yönelip son Shiguo devleti Kuzey Han’ı 979’da fethetti; ardından Kitan imparatorluğuyla savaştı ve 986’da ağır yenildi.","kaynak":"Britannica, «History of China: The Sui dynasty» [Sui, Tang ve Beş Hanedan bölümlerini içerir] (https://www.britannica.com/topic/history-of-China/The-Sui-dynasty): «turned northward to attack and conquer Bei Han (979), the last remaining Shiguo»","gun":"979 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Ninh Binh"],"onem":4,"dunya":2,"kapsam":"ic","t":"0979-01-01","b":"Dinh Tien Hoang ve veliaht, bir kâhin tarafından öldürülüyor","tur":"olum","etiket":["konu-hukumdar"],"yer":"Kuzey Vietnam","taraflar":["dinh"],"d":"Dinh Bo Linh (Dinh Tien Hoang) ve veliaht prens 979'da kendini gerçek imparator sanan bir kâhin tarafından öldürüldü; varisler küçük olduğundan hanedan bir yıl içinde çöktü.","kaynak":"Britannica, «Dinh Bo Linh» (https://www.britannica.com/biography/Dinh-Bo-Linh): «He and the crown prince were assassinated in 979 by a mystic seer»","gun":"979 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kaesong"],"onem":3,"dunya":1,"kapsam":"ic","t":"0981-01-01","b":"Goryeo Kralı Seongjong tahta çıktı (981-997); merkezî bürokrasi ve sınav sistemi kuruldu","tur":"reform","etiket":["konu-siyasi"],"yer":"Goryeo (Kaesong)","taraflar":["goryeo"],"d":"Seongjong döneminde (981-997) eski aristokratik kabile düzeninin yerine merkezî bürokratik sistem kuruldu; eğitim ve memuriyet sınavlarıyla taşra güç sahipleri merkeze bağlandı.","kaynak":"Britannica, «Goryeo dynasty» (https://www.britannica.com/topic/Goryeo-dynasty): «A centralized bureaucratic system was established during the reign (981–997) of King Seongjong»","gun":"981 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Kançipuram (Kanchipuram)"],"onem":4,"dunya":3,"kapsam":"ic","t":"0985-01-01","b":"I. Rajaraja Çola tahtında (985-1014)","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Tancavur","taraflar":["cola"],"d":"Yetenekli yönetici Rajaraja Vengi'yi korudu, Batı Gangaları ezdi ve Gangavadi'yi işgal etti; Tancavur'daki büyük Brihadishvara tapınağını yaptırdı.","kaynak":"Britannica, «Chola dynasty» (https://www.britannica.com/topic/Chola-dynasty): «Rajaraja I (reigned 985–1014), an able administrator, protected Vengi»","gun":"985 (yıl; gün kaynaktan alınmadı)"},{"odak_yer":["Mungîr (Monghyr)"],"onem":3,"dunya":2,"kapsam":"ic","t":"0988-01-01","b":"I. Mahipala Pala tahtında (yak. 988-1038); Pala gücünü yeniden canlandırır, etkisi Varanasi'ye uzanır","tur":"hukumdar","etiket":["konu-siyasi"],"yer":"Bengal-Bihar","taraflar":["pala"],"d":"Gerileyen Pala gücü I. Mahipala ile yeniden güçlendi; etkisi Varanasi'ye kadar ulaştı.","kaynak":"Britannica, «Pala dynasty» (https://www.britannica.com/topic/Pala-dynasty): «Pala strength was restored by Mahipala I (reigned c. 988–1038), whose influence reached as far as Varanasi»","gun":"988 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Kançipuram (Kanchipuram)"],"onem":3,"dunya":2,"kapsam":"dis","t":"0993-01-01","b":"Çola I. Rajaraja güney Dekan'ı işgal eder (yak. 993); Çola akınları 1021'e kadar sürer","tur":"isgal","etiket":["konu-askeri","yaklasik"],"yer":"Güney Dekan","taraflar":["cola","bati-calukya"],"d":"Çola kralı Rajaraja yak. 993'te güney Dekan'ı istila etti; yaylaya tekrarlanan Çola akınları yak. 1021'e kadar sürdü.","kaynak":"Britannica, «Chalukya dynasty» (https://www.britannica.com/topic/Chalukya-dynasty): «The Chola king Rajaraja I invaded the south Deccan about 993»","gun":"993 (yıl, yaklaşık; gün kaynaktan alınmadı)"},{"odak_yer":["Kançipuram (Kanchipuram)"],"onem":4,"dunya":2,"kapsam":"ic","t":"0996-01-01","b":"Rajaraja 996'ya kadar Kerala'yı (Çera ülkesi) fetheder, kuzey Sri Lanka'yı alır","tur":"fetih","etiket":["konu-askeri"],"yer":"Kerala, kuzey Sri Lanka","taraflar":["cola","kulasekhara-cera"],"d":"Rajaraja 996'ya kadar Kerala'yı (Çera ülkesi) fethetti ve kuzey Sri Lanka'yı aldı; elde ettiği ganimetle Tancavur'daki Brihadishvara tapınağını yaptırdı.","kaynak":"Britannica, «Chola dynasty» (https://www.britannica.com/topic/Chola-dynasty): «By 996 he had conquered Kerala (the Chera country) and acquired northern Sri Lanka.»","gun":"996 (yıl; 'by 996' = en geç 996, gün kaynaktan alınmadı)"}];

