window.KRONOLOJI_COK_INCE_ANADOLU_IRAN = [{"t":"1378-01-01","k":"hukumdar","tur":"hukumdar","onem":4,"dunya":1,"kapsam":"ic","b":"Şeyh İbrâhim Şirvanşah oldu — Derbendî Şirvanşahları dönemi başladı","gun":"1378 (TDV sirvansahlar saltanatı 1378-1418 diye verir; gün yok)","yer_id":"","odak_yer":"Şamahı","d":"Şirvanşahların ikinci tabakası olan Derbendî kolunun ilk hükümdarı Şeyh İbrâhim tahta çıktı. Timur'a tâbi olarak ülkesini koruyan İbrâhim, Karakoyunlulara karşı Gürcü kralı ve Şeki hâkimiyle ittifak kurdu; kırk yıllık saltanatı Şirvan'ın Timur sonrası dönemdeki bağımsızlığının temelini attı.","kaynak":"TDV: sirvansahlar ('İkinci tabakanın (Derbendî Şirvanşahları) ilk hükümdarı olan Şeyh İbrâhim (1378-1418) Timur'a tâbi olup Karakoyunlular'a karşı Gürcü Kralı Köstendil ve Şeki hâkimi Seyyid Ahmed ile ittifak yaptı')","taraflar":["sirvansah"],"etiket":["hukumdar","konu-siyasi","konu-hanedan"]},{"t":"1418-01-01","k":"hukumdar","tur":"hukumdar","onem":3,"dunya":1,"kapsam":"ic","b":"Şeyh İbrâhim öldü — Sultan Halil (Halîlullah) Şirvanşah oldu","gun":"1418 (TDV sirvansahlar saltanat aralıklarından; gün yok)","yer_id":"","odak_yer":"Şamahı","d":"Kırk yıl hüküm süren Şeyh İbrâhim'in ölümüyle yerine oğlu Sultan Halil (Halîlullah) geçti. Kırk beş yıllık saltanatı (1418-1463) Şirvan'ın Karakoyunlu ve Akkoyunlu arasında dengede kaldığı uzun bir istikrar dönemidir.","kaynak":"TDV: sirvansahlar ('Vefatında yerine Sultan Halil (Halîlullah, 1418-1463) ve Ferruh Yesâr (Siyer) (1463-1500) geçti')","taraflar":["sirvansah"],"etiket":["hukumdar","konu-hanedan"]},{"t":"1463-01-01","k":"hukumdar","tur":"hukumdar","onem":3,"dunya":1,"kapsam":"ic","b":"Ferruh Yesâr Şirvanşah oldu","gun":"1463 (TDV sirvansahlar saltanat aralıklarından; gün yok)","yer_id":"","odak_yer":"Şamahı","d":"Sultan Halil'in ölümüyle Şirvan tahtına Ferruh Yesâr geçti. Otuz yedi yıl süren saltanatı, 1500'de Şah İsmâil'in intikam seferinde öldürülmesiyle sona erecek ve Şirvanşahların fiilî bağımsızlığı onunla kapanacaktı.","kaynak":"TDV: sirvansahlar ('Vefatında yerine Sultan Halil (Halîlullah, 1418-1463) ve Ferruh Yesâr (Siyer) (1463-1500) geçti')","taraflar":["sirvansah"],"etiket":["hukumdar","konu-hanedan"]},{"t":"1328-01-01","k":"antlasma","tur":"antlasma","onem":3,"dunya":1,"kapsam":"dis","b":"Bizans İmparatoru III. Andronikos Biga'da Karesioğlu Demirhan Bey ile saldırmazlık anlaşması yaptı","gun":"1328 (TDV karesiogullari gün vermez)","yer_id":"Biga","d":"Bizans İmparatoru III. Andronikos Biga'ya gelerek Demirhan Bey ile bir saldırmazlık anlaşması imzaladı. Anlaşma, Demirhan Bey'in bağımsız bir bey gibi davrandığını ve Karesioğulları'nın Balıkesir ile Bergama olmak üzere iki merkezden yönetilen geniş bir beyliğe dönüştüğünü gösterir.","kaynak":"TDV: karesiogullari ('Andronikos'un 1328'de Biga'ya gelerek Demirhan Bey'le bir saldırmazlık anlaşması yapması, Demirhan Bey'in müstakil bir bey gibi hareket ettiğini ve böylece Karesioğulları'nın biri Balıkesir, diğeri Bergama olmak üzere iki merkezden yönetilen geniş topraklara sahip bir beylik haline geldiğini göstermektedir')","taraflar":["karesi","bizans"],"etiket":["antlasma","diplomasi","konu-diplomasi"]},{"t":"1334-01-01","k":"savas","tur":"savas","onem":3,"dunya":1,"kapsam":"dis","b":"Edremit deniz savaşı — Haçlı donanması Yahşi Bey'in Karesi donanmasını yendi","gun":"735 Muharremi (Eylül 1334) — TDV karesiogullari; gün yok","yer_id":"Edremit","d":"Yahşi Bey kumandasındaki Karesi donanması Edremit sularında Haçlı donanmasıyla karşılaştı ve ağır bir yenilgiye uğradı. Ege'de akınlarıyla Latin devletlerini tedirgin eden Türk beyliklerine karşı kurulan ilk Haçlı deniz birliğinin bu zaferi, Karesi'nin deniz gücünü geçici olarak kırdı.","kaynak":"TDV: karesiogullari ('735 Muharreminde (Eylül 1334) Edremit sularında Yahşi Bey'in kumandasındaki Türk donanmasıyla Haçlılar arasında meydana gelen şiddetli savaşta Haçlı donanması Türkler'i ağır bir yenilgiye uğrattı')","taraflar":["karesi"],"etiket":["savas","askeri","konu-askeri"]},{"t":"1379-01-01","k":"siyaset","tur":"siyaset","onem":4,"dunya":1,"kapsam":"dis","b":"Tâceddin Bey Niksar'da Kadı Burhâneddin ile Eretna kuvvetlerini bozdu, Eretna'ya vergiyi kesip bağımsızlaştı","gun":"781 (1379) ilkbaharı — TDV taceddinogullari; gün yok","yer_id":"Niksar","d":"1379 ilkbaharında Niksar'a saldıran Kadı Burhâneddin ile Eretna Beyi Alâeddin Ali'nin kuvvetlerini bozan Tâceddin Bey, Eretna Beyliği'ne vergi vermeyi kesti ve bağımsız hareket etmeye başladı. Canik bölgesindeki bu küçük beylik böylece Orta Karadeniz'de Eretna sonrası kargaşanın bağımsız aktörlerinden biri oldu.","kaynak":"TDV: taceddinogullari ('1379 ilkbaharında Niksar'a saldıran Kadı Burhâneddin ile Eretna Beyi Alâeddin Ali'nin kuvvetlerini bozan Tâceddin Bey, Eretna Beyliği'ne vergi vermeyi kesti; 781'den (1379) itibaren de bağımsız hareket etmeye başladı')","taraflar":["taceddin","eretna"],"etiket":["siyaset","konu-siyasi"]},{"t":"1381-01-01","k":"savas","tur":"savas","onem":3,"dunya":1,"kapsam":"dis","b":"Tâceddin Bey Dânişmendiye'de Kadı Burhâneddin'e yenildi","gun":"783 (1381) — TDV taceddinogullari; gün yok","yer_id":"","odak_yer":"Tokat","d":"Tâceddin Bey, Hacı Şadgeldi ile birlikte Kadı Burhâneddin'e karşı Tokat yakınındaki Dânişmendiye köyünde savaştı ve yenildi. Sivas'ta yeni kurulan Kadı Burhâneddin devleti, Canik beylikleri üzerindeki üstünlüğünü bu zaferle kurmaya başladı.","kaynak":"TDV: taceddinogullari ('Kadı Burhâneddin'e karşı Hacı Şadgeldi ile birlikte Tokat'ın Dânişmendiye köyü yakınında yaptığı savaşı kaybetti (783/1381)')","taraflar":["taceddin","burhaneddin"],"etiket":["savas","konu-askeri"]},{"t":"1392-01-01","k":"siyaset","tur":"siyaset","onem":4,"dunya":1,"kapsam":"dis","b":"Tâceddinoğulları Yıldırım Bayezid'e bağlılık bildirdi","gun":"794 (1392) — TDV taceddinogullari; gün yok","yer_id":"","odak_yer":"Niksar","d":"Yıldırım Bayezid'in Candaroğulları topraklarını, Kastamonu, Küre, Osmancık ve Samsun'u ele geçirmesi üzerine Tâceddinoğulları, Amasya Emîri Ahmed ve Taşanoğlu ile birlikte Osmanlı hükümdarının yanına gidip bağlılık bildirdi. Beylik bundan sonra Kadı Burhâneddin'e karşı Osmanlı'ya yaslanacaktı.","kaynak":"TDV: taceddinogullari ('Yıldırım Bayezid'in Candarlı Beyliği üzerine yürümesi ve beyliğin topraklarını ele geçirmesi (794/1392), Kastamonu, Küre, Osmancık ve Samsun'u zaptetmesi karşısında müttefikleri Amasya Emîri Ahmed, Taşanoğlu ve kendi kardeşi Kılıcarslan ile birlikte Yıldırım Bayezid'in yanına gidip Osmanlı Devleti'ne bağlılık bildirdiler')","taraflar":["taceddin"],"etiket":["siyaset","diplomasi","konu-siyasi"]},{"t":"1318-01-01","k":"siyaset","tur":"siyaset","onem":4,"dunya":1,"kapsam":"dis","b":"Eşrefoğlu Mehmed Bey ve öteki beyler İlhanlı valisi Demirtaş'ı tanımayıp yeniden bağımsızlık ilan etti","gun":"1318 (Demirtaş'ın Anadolu valiliğine atanış yılı; TDV esrefogullari gün vermez)","yer_id":"","odak_yer":"Beyşehir","d":"Çocuk yaştaki Ebû Said adına İlhanlı yönetimini üstlenen Emîr Çoban'ın 1318'de Anadolu'ya vali atadığı oğlu Demirtaş'ı, aralarında Eşrefoğlu Mehmed Bey'in de bulunduğu Türk beyleri tanımadı ve yeniden istiklâllerini ilan etti. Bu direniş sekiz yıl sonra Demirtaş'ın Beyşehir'e girip beyliği ortadan kaldırmasıyla sonuçlanacaktı.","kaynak":"TDV: esrefogullari ('Eşrefoğlu Mehmed Bey'in de bulunduğu Türk beyleri, Emîr Çoban'ın 1318'de Anadolu'ya vali tayin ettiği oğlu Demirtaş'ı (Timurtaş) tanımayıp yeniden istiklâllerini ilân ettiler')","taraflar":["esrefogullari","ilhanli"],"etiket":["siyaset","konu-siyasi"]},{"t":"1320-01-01","k":"hukumdar","tur":"hukumdar","onem":3,"dunya":1,"kapsam":"ic","b":"Eşrefoğlu Mehmed Bey öldü, yerine oğlu II. Süleyman geçti","gun":"1320 (TDV esrefogullari gün vermez)","yer_id":"","odak_yer":"Beyşehir","d":"Beyşehir merkezli Eşrefoğulları Beyliği'nin başındaki Mehmed Bey 1320'de öldü ve yerine oğlu II. Süleyman geçti. Beyliğin son hükümdarı olan II. Süleyman, 1326'da Demirtaş'ın Beyşehir'e girmesiyle öldürülecekti.","kaynak":"TDV: esrefogullari ('Eşrefoğlu Mehmed Bey 1320 yılında ölünce yerine oğlu II. …' — gövde)","taraflar":["esrefogullari"],"etiket":["hukumdar","konu-hanedan"]},{"t":"1235-01-01","k":"olum","tur":"olum","onem":4,"dunya":1,"kapsam":"dis","b":"Kirman hükümdarı Barak Hâcib öldü — Moğollara yardımından sonra","gun":"1235 (TDV kutlughanlilar gün vermez)","yer_id":"","odak_yer":"Kirman","d":"Harezmşahların hizmetinden yükselip Kirman'a hâkim olan hanedanın kurucusu Barak Hâcib, Sîstan'ı almaya çalışan Moğol ordusuna yardım ettiği yıl öldü. Barak'ın Moğollarla erken uzlaşması, küçük Kirman hanedanının İlhanlı çağında yarım asır daha yaşamasının temeli oldu.","kaynak":"TDV: kutlughanlilar ('1235'te Sîstan'ı zaptetmeye çalışan Moğol ordusuna yardım eden Barak aynı yıl öldü')","taraflar":["kutlughanli"],"etiket":["hukumdar","olum","konu-hanedan"]},{"t":"1257-01-01","k":"hukumdar","tur":"hukumdar","onem":4,"dunya":1,"kapsam":"ic","b":"Kutluğ Terken Hatun Kirman hükümdarı oldu","gun":"655 (1257) — TDV kutlughanlilar; gün yok","yer_id":"","odak_yer":"Kirman","d":"Kutbüddin'in ölümü üzerine Kirman ileri gelenleri ile bazı Moğol beylerinin katıldığı bir mecliste, oğlu Haccâc küçük olduğu için hanımı Kutluğ Terken Hatun'un hükümdarlığına karar verildi. Kutluğ Hatun'un yirmi beş yıllık saltanatı (1257-1282) Kirman halkı için rahat bir dönem olarak anılır.","kaynak":"TDV: kutlughanlilar ('Kutbüddin ölünce (655/1257) … hanımı İsmetü'd-dünyâ ve'd-dîn Kutluğ Terken Hatun'un hükümdarlığı konusunda karar alındı. Kutluğ Hatun zamanında (1257-1282) Kirman halkı çok rahat bir dönem geçirdi')","taraflar":["kutlughanli"],"etiket":["hukumdar","konu-hanedan"]},{"t":"1379-01-01","k":"toprak-kazanc","tur":"toprak-kazanc","onem":3,"dunya":1,"kapsam":"dis","b":"Mar'aşîler Emîr Velî'yi yenip Esterâbâd'ı aldı","gun":"781 (1379) — TDV marasiler; gün yok","yer_id":"Esterâbâd (Gürgân)","d":"Mâzenderan'daki seyyid hâkimiyeti doğuya yöneldi: Horasan'ın bir kısmına hükmeden Emîr Velî ile yapılan savaşı kazanan Mar'aşîler Esterâbâd'ı ele geçirdi. Beylik böylece Hazar'ın güneydoğu kıyısında en geniş sınırlarına ulaştı.","kaynak":"TDV: marasiler ('Doğuda Horasan'ın bir kısmında hüküm süren Emîr Velî ile yaptıkları savaşı kazanan Mar'aşîler Esterâbâd'ı aldılar (781/1379)')","taraflar":["mazenderan-marasi"],"etiket":["askeri","toprak-kazanc","konu-askeri"]},{"t":"1380-01-01","k":"savas","tur":"savas","onem":3,"dunya":1,"kapsam":"dis","b":"Mar'aşîler Mîrândeşt'te Rüstemdâr Meliki Kubâd'ı yendi","gun":"782 (1380) — TDV marasiler; gün yok","yer_id":"","odak_yer":"Âmül","d":"Batıya, Rüstemdârların bölgesine yönelen Mar'aşîler Mîrândeşt'te Melik Kubâd'ı bozguna uğratıp Küçûr'a kadar olan kesimi aldı; ertesi yıl Lekter'deki ikinci savaşta Melik Kubâd öldürüldü ve Rüstemdâr ordusu dağıtıldı.","kaynak":"TDV: marasiler ('Mîrândeşt'te Melik Kubâd'ı hezimete uğratıp (782/1380) Küçûr'a kadar olan kesimi zaptettiler; ertesi yıl Lekter'de yapılan, Melik Kubâd'ın öldürüldüğü ikinci savaşta Rüstemdâr ordusunu tamamen dağıttılar')","taraflar":["mazenderan-marasi"],"etiket":["savas","konu-askeri"]},{"t":"1385-01-01","k":"siyaset","tur":"siyaset","onem":4,"dunya":1,"kapsam":"dis","b":"Seyyid Kemâleddin Esterâbâd'da Timur'a itaat etti","gun":"787 (1385) — TDV marasiler; gün yok","yer_id":"Esterâbâd (Gürgân)","d":"Esterâbâd'a yürüyen Timur'un şehri kolayca ele geçirmesinden etkilenen Seyyid Kemâleddin, oğlu Gıyâseddin ile birlikte değerli hediyelerle huzura çıkıp itaatini arz etti ve Timur adına sikke bastırdı. Bu bağlılık uzun sürmeyecek, 1392'de Timur'un Mâzenderan seferi Mar'aşîlerin Mâhâneser Kalesi'nde teslimiyle bitecekti.","kaynak":"TDV: marasiler ('Seyyid Kemâleddin, oğlu Gıyâseddin'i de yanına alarak değerli hediyelerle birlikte huzura çıktı ve itaatini arzetti (787/1385); arkasından da onun adına sikke bastırdı (Hâfız-ı Ebrû, II, 628)')","taraflar":["mazenderan-marasi","timurlu"],"etiket":["siyaset","konu-siyasi"]},{"t":"1300-01-01","k":"idari","tur":"idari","onem":5,"dunya":2,"kapsam":"ic","b":"Hürmüz halkı Moğol akınlarından Cerûn adasına taşındı — Yeni Hürmüz kuruldu","gun":"1300 (TDV hurmuz--iran gün vermez)","yer_id":"Hürmüz Adası","d":"Kirman, Sîstan ve Horasan'ın denize açılan kapısı olan Hürmüz'ün ahalisi, Moğol akınları sırasında hükümdar Kutbüddin Tehemten tarafından boğazın kuzeyindeki Cerûn adasına nakledildi ve orada kurulan liman şehrine Yeni Hürmüz adı verildi. Adaya taşınan sultanlık, iki yüzyıl boyunca Hint Okyanusu ticaretinin en işlek limanlarından birini yönetti.","kaynak":"TDV: hurmuz--iran ('ahalisi Moğol akınları sırasında hükümdarları Kutbüddin Tehemten tarafından boğazın kuzeyinde yer alan Cerûn adasına nakledilmiş (1300) ve burada kurulan liman şehrine Yeni Hürmüz adı verilmiştir')","taraflar":["hurmuz-sultanligi"],"etiket":["idari","konu-idari","konu-ekonomi"]},{"t":"1297-01-01","k":"hukumdar","tur":"hukumdar","onem":3,"dunya":1,"kapsam":"ic","b":"Pervâneoğlu Mehmed Bey Konya'da öldü, yerine yeğeni Mühezzebüddin Mesud geçti","gun":"696 (1297) — TDV pervaneogullari; gün yok","yer_id":"Konya","d":"Sinop merkezli beyliğin kurucusu Muînüddin Mehmed Bey 1297'de Konya'da öldü ve yerine kardeşinin oğlu Mühezzebüddin Mesud geçti. Mesud Bey'in üç yıllık saltanatından sonra beylik, deniz gücüne yönelecek olan Gazi Çelebi'ye kalacaktı.","kaynak":"TDV: pervaneogullari ('Nihayet Mehmed Bey 696'da (1297) Konya'da öldü; yerine kardeşi Mühezzebüddin Ali'nin oğlu Mühezzebüddin Mesud geçti')","taraflar":["pervane"],"etiket":["hukumdar","konu-hanedan"]},{"t":"1319-01-01","k":"savas","tur":"savas","onem":3,"dunya":1,"kapsam":"dis","b":"Pervâneoğlu Gazi Çelebi Trabzon'a saldırdı","gun":"1319 (TDV pervaneogullari gün vermez)","yer_id":"Trabzon","d":"Sinop'un deniz gücünü geliştiren Gazi Çelebi 1319'da Trabzon Rum İmparatorluğu'na karşı hücuma geçti. Karadeniz'de korsanlık ve deniz seferleriyle tanınan beylik, Ceneviz ve Trabzon ticaretini tehdit eden bölgesel bir güç hâline gelmişti.","kaynak":"TDV: pervaneogullari ('1319 yılında Trabzon'a karşı hücuma geçti')","taraflar":["pervane","trabzon-rum"],"etiket":["savas","konu-askeri"]},{"t":"1322-01-01","k":"savas","tur":"savas","onem":3,"dunya":1,"kapsam":"dis","b":"Gazi Çelebi Cenevizlilerin Sinop saldırısını püskürttü","gun":"1322 (TDV pervaneogullari gün vermez)","yer_id":"Sinop","d":"Cenevizliler 1322'de Sinop'a bir saldırı düzenledi; Gazi Çelebi saldırıyı püskürttü. Aynı yıl Sinop, Candaroğlu Süleyman Bey'in eline geçecek ve Pervâneoğulları'nın bağımsız varlığı sona erecekti.","kaynak":"TDV: pervaneogullari ('Cenevizliler'in 1322'de Sinop'a düzenledikleri saldırıyı püskürttü')","taraflar":["pervane"],"etiket":["savas","konu-askeri"]},{"t":"1280-01-01","k":"hukumdar","tur":"hukumdar","onem":3,"dunya":1,"kapsam":"ic","b":"Muzafferüddin Yavlak Arslan Çobanoğulları'nın başına geçti","gun":"'1280 yılı civarında' (TDV cobanogullari) — yaklaşık yıl, gün yok","yer_id":"","odak_yer":"Kastamonu","d":"Siyasî ve ekonomik bağımsızlıklarını yitirmiş olan Kastamonu merkezli Çobanoğulları'nın başına 1280 civarında Alp Yürek'in oğlu Muzafferüddin Yavlak Arslan geçti. Beyliğin Selçuklu-Moğol çekişmesi içindeki son dönemi onun ve oğlunun zamanında geçti; 1309'da Candaroğlu Süleyman Bey beyliğe son verecekti.","kaynak":"TDV: cobanogullari ('Sadece siyasî değil ekonomik bağımsızlıklarını da kaybeden Çobanoğulları'nın başına 1280 yılı civarında Alp Yürek'in oğlu Muzafferüddin Yavlak Arslan geçti')","taraflar":["cobanogullari"],"etiket":["hukumdar","konu-hanedan"]}];

