window.KRONOLOJI_COK_SAFRIKA_DENETIM_1029 = [{"t":"1884-07-05","k":"siyasi","b":"Nachtigal, Togo kıyısında yerel şefle antlaşma imzaladı; Alman Togolandı himayesi başladı (Almanya'nın Afrika'daki ilk edinimi)","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Lomé","gun":"5 Temmuz 1884 (encyclopedia.com gün verir; TDV yalnız 1884 verir)","yer":"Lomé","kisiler":"Gustav Nachtigal","d":"Dr. Gustav Nachtigal 5 Temmuz 1884'te Togo'nun şefiyle antlaşma yaptı; küçük bir kıyı şeridi üzerinde Alman himayesi kuruldu. Himaye 26 Ağustos 1914'e dek sürdü.","kaynak":"encyclopedia.com «Togo» (Encyclopedia of World Geography/political geography), sayfa bu oturumda okundu: «on 5 July 1884, when Dr. Gustav Nachtigal made a treaty with the chief of Togo» · TDV İslâm Ansiklopedisi «Togo»: «1884 yılında … III. Mlapa ile bir himaye anlaşması imzaladı» (yıl)","taraflar":["alman-togo","almanya"],"etiket":["konu-siyasi","sahra-alti-afrika","bati-afrika","somurge"]},{"t":"1884-07-01","k":"siyasi","b":"Kamerun'da yerel yöneticilerle Alman hükümeti arasında himaye antlaşması imzalandı (Temmuz 1884)","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Duala","gun":"Temmuz 1884 (TDV ay verir; gün yazılmadı — ayın 1'i hassasiyet işareti)","yer":"Duala","d":"Kamerun kıyısındaki yerel yöneticilerle Alman hükümeti arasında Temmuz 1884'te himaye antlaşması imzalandı; Alman Kamerunu (1884–1916) böylece başladı. Yerleşim zincirindeki geçiş günü (14 Temmuz, Alman bayrağının çekilişi) Vikipedi/ikincil kaynaklıdır.","kaynak":"TDV İslâm Ansiklopedisi «Kamerun», sayfa bu oturumda okundu: «yerel yöneticilerle Alman hükümeti arasında bir himaye antlaşması imzalandı (Temmuz 1884).»","taraflar":["alman-kamerun","almanya"],"etiket":["konu-siyasi","sahra-alti-afrika","orta-afrika","somurge"]},{"t":"1884-08-07","k":"siyasi","b":"Alman bayrağı Angra Pequeña'da resmen çekildi — Alman Güneybatı Afrikası (Namibya) himayesi başladı","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Lüderitz","gun":"7 Ağustos 1884 (Dierks kronolojisi gün verir; SAHO yalnız 1884)","yer":"Lüderitz","d":"7 Ağustos 1884'te Angra Pequeña'da (bugünkü Lüderitz) Alman bayrağı resmen çekildi; Güneybatı Afrika Alman himayesine girdi. Alman yönetimi 9 Temmuz 1915'te Khorab'da Güney Afrika'ya teslimle bitti.","kaynak":"Klaus Dierks, Chronology of Namibian History (klausdierks.com/Chronology/38.htm), bu oturumda okundu: «The German flag is officially hoisted at Angra Pequeña» (07.08.1884) · SAHO «Namibian Timeline»: «SWA becomes a German protectorate» (1884) ve «The Germans surrender to the South African military on 9 July 1915 at Khorab»","taraflar":["alman-guneybati-afrikasi","almanya"],"etiket":["konu-siyasi","sahra-alti-afrika","guney-afrika","somurge"]},{"t":"1890-01-01","k":"siyasi","b":"Helgoland-Zanzibar Antlaşması: Zengibar Sultanlığı dış işlerinde İngiltere'nin himayesine bırakıldı","tur":"antlasma","onem":3,"dunya":3,"kapsam":"dis","yer_id":"Zanzibar (Zengibar)","gun":"1890 (TDV yıl verir; gün yazılmadı)","yer":"Zanzibar (Zengibar)","d":"1890'da Almanya ile İngiltere arasında imzalanan Helgoland-Zanzibar Antlaşması'yla Zengibar İngiliz nüfuz alanına bırakıldı; sultan iç işlerinde kaldı ama dış işlerinde yetkisi elinden alındı. Zanzibar adası bu tarihten bağımsızlığa (10 Aralık 1963) dek İngiliz himayesindedir; Tanganyika mandasına dahil edilmemiştir.","kaynak":"TDV İslâm Ansiklopedisi «Zengibar», sayfa bu oturumda okundu: «1890'da Almanya ile İngiltere arasında imzalanan Helgoland-Zanzibar Antlaşması'yla … dış işlerinde yetkileri elinden alınarak İngiltere'nin himayesine bırakıldı.»","taraflar":["umman-zengibar","ingiltere"],"etiket":["konu-siyasi","sahra-alti-afrika","dogu-afrika","somurge"]},{"t":"1908-11-15","k":"siyasi","b":"Belçika, Kongo Serbest Devleti'ni sömürge olarak ilhak etti — Belçika Kongosu başladı","tur":"toprak-kazanc","onem":4,"dunya":3,"kapsam":"dis","yer_id":"Boma","gun":"15 Kasım 1908 (history.state.gov gün verir)","yer":"Boma","d":"II. Leopold'ün şahsî mülkü olan Kongo Serbest Devleti 15 Kasım 1908'de Belçika tarafından sömürge olarak ilhak edildi; Belçika Kongosu 30 Haziran 1960'a dek sürdü. Haritada 1885–1908 dilimi kongo-serbest-devleti, sonrası belcika-kongo olarak boyanır.","kaynak":"U.S. Department of State, Office of the Historian, «Congo Free State» (history.state.gov/countries/congo-free-state), bu oturumda okundu: «the Congo Free State was annexed as a colony by Belgium on November 15, 1908.» · TDV İslâm Ansiklopedisi «Kongo Demokratik Cumhuriyeti»: «15 Kasım 1908 tarihinde ülkeyi resmen sömürgeleştirdi»","taraflar":["kongo-serbest-devleti","belcika-kongo","belcika"],"etiket":["konu-siyasi","sahra-alti-afrika","orta-afrika","somurge"]},{"t":"1920-12-17","k":"siyasi","b":"Milletler Cemiyeti Konseyi Güneybatı Afrika'yı C-tipi manda olarak Güney Afrika Birliği'ne verdi","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Vindhuk (Windhoek)","gun":"17 Aralık 1920 (SAHO ve manda metni gün verir)","yer":"Vindhuk (Windhoek)","d":"Eski Alman Güneybatı Afrikası, 9 Temmuz 1915'ten beri Güney Afrika işgalindeyken 17 Aralık 1920 tarihli manda anlaşmasıyla resmen Güney Afrika'ya mandaya verildi; yönetim Namibya bağımsızlığına (21 Mart 1990) dek sürdü. Haritada 1915-07-09 → 1920-12-17 askerî işgal dilimi 'ingiltere', sonrası guneybati-afrika-mandasi.","kaynak":"SAHO «Namibian Timeline» (sahistory.org.za), bu oturumda okundu: mandate agreement dated 17 December 1920; «Namibia gains independence from South Africa» (21 Mart 1990) · künye guneybati-afrika-mandasi kaynağı: manda metni (AALCO) «Made at Geneva on the 17th day of December, 1920»","taraflar":["guneybati-afrika-mandasi","ingiltere"],"etiket":["konu-siyasi","sahra-alti-afrika","guney-afrika","manda"]},{"t":"1922-07-20","k":"siyasi","b":"Milletler Cemiyeti, eski Alman Doğu Afrikası'nı İngiliz (Tanganyika) ve Belçika (Ruanda-Urundi) mandalarına, Togo'yu Fransız/İngiliz mandalarına verdi","tur":"antlasma","onem":4,"dunya":3,"kapsam":"dis","yer_id":"Dodoma","gun":"20 Temmuz 1922 (SAHO + FRUS gün verir)","yer":"Dodoma","d":"20 Temmuz 1922'de Milletler Cemiyeti Konseyi B-tipi mandaları onayladı: Alman Doğu Afrikası'nın büyük kısmı İngiltere'ye (Tanganyika), Ruanda-Urundi Belçika'ya, Togo Fransa ve İngiltere'ye verildi (Kamerun için ayrı maddeye bakınız). TDV Togo maddesi de mandaların 1922'de onaylandığını yazar. Zincirlerdeki eski 29 Ekim 1923 pencere işareti bu günle değiştirildi.","kaynak":"SAHO «League of Nations hands over German colonies» (sahistory.org.za/node/11445), bu oturumda okundu: «On 20 July 1922 the League of Nations agreed to hand over three former German colonies as mandates» (Tanganyika, Togo, Kamerun) · FRUS 1923 c.I d280 (history.state.gov/historicaldocuments/frus1923v01/d280) — arama özetinde Konsey'in 20 Temmuz 1922'de onayladığı yazıyor, sayfa AÇILMADI · TDV «Togo»: «1922'de Milletler Cemiyeti tarafından Fransa ve İngiltere'nin mandası onaylandı»","taraflar":["ingiliz-tanganika-mandasi","ruanda-urundi-mandasi","fransiz-togo","ingiliz-togoland","belcika","ingiltere"],"etiket":["konu-siyasi","sahra-alti-afrika","dogu-afrika","manda"]},{"t":"1906-01-01","k":"siyasi","b":"Fransızlar Agadez'i işgal etti — Aïr Tuareg sultanlığı bağımsızlığını yitirdi (Arlit, Fachi, In Gall zinciri Agadez'den devralındı)","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Agadez","gun":"1906 (TDV yıl verir; gün yok)","yer":"Agadez","d":"Fransızlar 1906'da Agadez'i işgal ederek halkın Osmanlı Devleti ile irtibatını kesti; Tevârikler Mart 1917'de şehri kısa süre geri aldı ama Fransız kuvvetlerince bastırıldı. Haritada Agadez ve Aïr (Arlit, Fachi, In Gall) 1906'da Fransız Batı Afrikası'na geçer; eski 1900 ve 1923-10-29 kırılma günleri kaynaksız/pencere işaretiydi.","kaynak":"TDV İslâm Ansiklopedisi «Nijer» (A. Kavas), sayfa bu oturumda okundu: «Fransızlar, Agâdes'i işgal edip halkın Osmanlı Devleti ile irtibata geçmesini engelledi (1906).» ve «Agâdes Tevârikleri, 1917 yılı Mart ayında … şehri ele geçirdilerse»","taraflar":["agadez-sultanligi","tuareg-air","fransa-cumhuriyet","fransiz-bati-afrika"],"etiket":["konu-siyasi","sahra-alti-afrika","bati-afrika","tuareg"]},{"t":"1900-01-01","k":"siyasi","b":"Buganda, İngilizlerle yapılan 1900 antlaşmasıyla resmen İngiliz himayesine girdi","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Mengo (Buganda)","gun":"1900 (TDV yıl verir; gün yok)","yer":"Mengo (Buganda)","d":"1900 antlaşmasıyla Buganda toprakları resmen sömürgeleştirildi; krallık kurumları himaye altında sürdü, 24 Mayıs 1966'da II. Mutesa'nın sürgünüyle lağvedildi (1993'te yeniden kuruldu). Mengo zinciri 1900'de buganda → ingiliz-uganda-himayesi olur (eski 1923-10-29 bitişi pencere işaretiydi).","kaynak":"TDV İslâm Ansiklopedisi «Uganda», sayfa bu oturumda okundu: «1900 yılında İngilizler'le yapılan antlaşmayla Buganda toprakları resmen sömürgeleştirildi.» · «24 Mayıs 1966'da … sürgüne gönderildiğinde lağvedilen Buganda Krallığı 1993 yılında tekrar konuldu»","taraflar":["buganda","ingiliz-uganda-himayesi","ingiltere"],"etiket":["konu-siyasi","sahra-alti-afrika","dogu-afrika","somurge"]},{"t":"1902-05-31","k":"siyasi","b":"Vereeniging Barış Antlaşması: Transvaal ve Orange Hür Devleti bağımsızlıklarını yitirdi, İngiliz egemenliğine girdi","tur":"antlasma","onem":4,"dunya":3,"kapsam":"dis","yer_id":"Transvaal (Bur cumhuriyeti)","gun":"31 Mayıs 1902 (SAHO gün verir)","yer":"Transvaal (Bur cumhuriyeti)","d":"31 Mayıs 1902'de imzalanan barışla İkinci Boer Savaşı bitti; Bur cumhuriyetlerinin bağımsızlığı sona erdi ve iki ülke İngiliz idaresine geçti; 31 Mayıs 1910'da Güney Afrika Birliği kuruldu.","kaynak":"SAHO «Peace of Vereeniging» (sahistory.org.za/node/59798), bu oturumda okundu: «by 31 May 1902 the peace agreement was official» (Boer kuvvetlerinin silah bırakması; iki eski cumhuriyetin bölünmemesi) · transvaal/oranj künye t = 1902-05-31 (Cambridge Univ. Press kronolojisi)","taraflar":["transvaal","oranj","ingiltere"],"etiket":["konu-siyasi","sahra-alti-afrika","guney-afrika","savas"]},{"t":"1952-10-01","k":"siyasi","b":"Kenya'da Mau Mau isyanı üzerine olağanüstü hâl ilan edildi (Ekim 1952)","tur":"isyan","onem":4,"dunya":2,"kapsam":"dis","yer_id":"Nairobi","gun":"Ekim 1952 (ay hassasiyeti; ikincil kaynaklar 20 Ekim der, birincil doğrulanamadı)","yer":"Nairobi","kisiler":"Jomo Kenyatta","d":"Ekim 1952'de Kenya sömürge yönetimi olağanüstü hâl ilan etti ve Jomo Kenyatta ile KAU yöneticilerini tutukladı. ABD Dışişleri belgesi (24 Ekim 1952 tarihli not) «the three days since the declaration of the State of Emergency» der — ilan Ekim 1952'nin üçüncü haftasındadır. Yıl düzeyinde 1952 maddesine ayrı bir ay maddesi olarak eklendi.","kaynak":"U.S. Department of State, FRUS 1952-54 c.XI p.1 d152 (history.state.gov/historicaldocuments/frus1952-54v11p1/d152), bu oturumda okundu: «The rapidity with which the Government has acted in the three days since the declaration of the State of Emergency»; belge 24 Ekim 1952 tarihli · gün için IWM/DADM ikincil özetleri (20 Ekim) — sayfalar 403 verdi / açılamadı","taraflar":["ingiliz-kenya-kolonisi","kenya"],"etiket":["konu-siyasi","sahra-alti-afrika","dogu-afrika","somurge"]},{"t":"1994-03-01","k":"siyasi","b":"Walvis Bay, 84 yıllık Güney Afrika yönetiminin ardından Namibya'ya devredildi","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Valvis Körfezi","gun":"1 Mart 1994 (SAHO gün verir)","yer":"Valvis Körfezi","d":"Güney Afrika, Walvis Bay limanını ve açıktaki on iki adayı 1 Mart 1994'te Namibya'ya devretti; Namibya bağımsızlığından (21 Mart 1990) sonra da enklav Güney Afrika'da kalmıştı. Önceki zincir Walvis Bay'i 1990'da Namibya'ya geçiriyordu (hata düzeltildi).","kaynak":"SAHO «Walvis Bay handed over to Namibia» (sahistory.org.za/dated-event/walvis-bay-handed-over-namibia), bu oturumda okundu: 1 Mart 1994, «The South African government ended eighty-four years of control over the Walvis Bay enclave.» · Treaty on Walvis Bay (28 Şubat 1994 imza) arama özetinde","taraflar":["guney-afrika-cumhuriyeti","namibya"],"etiket":["konu-siyasi","sahra-alti-afrika","guney-afrika"]}];

