window.KRONOLOJI_COK_INCE_GUNEY_ASYA = [{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1725-01-01","k":"siyasi","tur":"siyasi","b":"Bâbürlü sarayı Nizâmülmülk'ü resmen Dekken valiliğine tayin etti","gun":"Haziran 1725 (gün bilinmiyor)","yer":"Dekken","yer_id":"Haydarâbâd (Dekken)","kisiler":"Nizâmülmülk Âsafcâh","d":"Bir yıl önce fiilen bağımsızlığını ilân eden Nizâmülmülk, Bâbürlü sultanı tarafından Dekken valiliğine resmen tayin edildi; böylece fiilî bağımsızlık Bâbürlü üst hâkimiyeti görüntüsü altında sürdü.","kaynak":"TDV: haydarabad-nizamligi (HAYDARÂBÂD NİZAMLIĞI)","taraflar":["haydarabad-nizam"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1748-05-21","k":"hukumdar","tur":"hukumdar","b":"Nizâmülmülk Âsafcâh öldü, Haydarabad'da taht mücadelesi başladı","gun":"21 Mayıs 1748","yer":"Haydarâbâd","yer_id":"Haydarâbâd (Dekken)","kisiler":"Nizâmülmülk Âsafcâh · Nâsır Ceng","d":"Hanedanın kurucusu Nizâmülmülk Âsafcâh'ın ölümünün ardından oğulları ve torunu arasında taht mücadelesi başladı; önce Nâsır Ceng, sonra Muzaffer Ceng ve Salâbet Ceng kısa aralıklarla tahta geçti, İngiliz ve Fransız şirketleri bu mücadelede taraf tuttu.","kaynak":"TDV: haydarabad-nizamligi (HAYDARÂBÂD NİZAMLIĞI)","taraflar":["haydarabad-nizam"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1762-01-01","k":"hukumdar","tur":"hukumdar","b":"Nizam Ali, Salâbet Ceng'i tahttan indirerek Haydarabad tahtına geçti","gun":"Temmuz 1762 (gün bilinmiyor)","yer":"Haydarâbâd","yer_id":"Haydarâbâd (Dekken)","kisiler":"Nizam Ali · Salâbet Ceng","d":"Fransız desteğiyle ayakta durmaya çalışan Salâbet Ceng tahttan indirildi; yerine geçen Nizam Ali kırk yılı aşan saltanatında Fransızları bölgeden uzaklaştırıp İngiliz Doğu Hindistan Şirketi ile yakınlaştı.","kaynak":"TDV: haydarabad-nizamligi (HAYDARÂBÂD NİZAMLIĞI)","taraflar":["haydarabad-nizam"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1790-01-01","k":"savas","tur":"savas","b":"Haydarabad, Meysûr Sultanı Tîpû'ya karşı İngilizlerle ortak cephe kurdu","gun":"(kaynak yıl verir)","yer":"Dekken","yer_id":"Haydarâbâd (Dekken)","kisiler":"Nizam Ali · Tîpû Sultan","d":"Nizam Ali, Meysûr Sultanı Tîpû'ya karşı İngiliz Doğu Hindistan Şirketi ile ortak cephe aldı; bu ittifak 1799'da Tîpû'nun ölümü ve Meysûr topraklarının paylaşılmasıyla sonuçlanacak sürecin başlangıcıdır.","kaynak":"TDV: haydarabad-nizamligi (HAYDARÂBÂD NİZAMLIĞI)","taraflar":["haydarabad-nizam"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","t":"1869-02-27","k":"hukumdar","tur":"hukumdar","b":"Efdalüddevle öldü, üç yaşındaki Mîr Mahbûb Ali Han nizam oldu","gun":"27 Şubat 1869","yer":"Haydarâbâd","yer_id":"Haydarâbâd (Dekken)","kisiler":"Efdalüddevle · Mîr Mahbûb Ali Han · Sâlâr Ceng","d":"Nizam Efdalüddevle'nin ölümü üzerine üç yaşındaki oğlu Mîr Mahbûb Ali Han tahta çıktı; yönetim fiilen başvezir Sâlâr Ceng'in elinde kaldı ve genç nizam idareyi ancak 1884'te bizzat üstlendi.","kaynak":"TDV: haydarabad-nizamligi (HAYDARÂBÂD NİZAMLIĞI)","taraflar":["haydarabad-nizam"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1911-01-01","k":"hukumdar","tur":"hukumdar","b":"Mîr Osman Ali Han Haydarabad'ın yedinci ve son nizamı oldu","gun":"(kaynak yıl verir)","yer":"Haydarâbâd","yer_id":"Haydarâbâd (Dekken)","kisiler":"Mîr Mahbûb Ali Han · Mîr Osman Ali Han","d":"Nizam Mahbûb Ali Han'ın ölümüyle yerine oğlu Osman Ali Han geçti; döneminde Câmiatü'l-Osmâniyye kuruldu, Urduca resmî ve eğitim dili oldu. 1948'de Hindistan'a katılmaya kadar tahtta kaldı.","kaynak":"TDV: haydarabad-nizamligi (HAYDARÂBÂD NİZAMLIĞI)","taraflar":["haydarabad-nizam"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1659-01-01","k":"savas","tur":"savas","b":"Şivâcî, Efdal (Afzal) Han komutasındaki Âdilşâhî ordusunu tuzağa düşürüp yendi","gun":"(kaynak yıl verir)","yer":"Pratapgad","yer_id":"Pûne (Poona)","kisiler":"Şivâcî · Efdal Han","d":"Bîcâpûr Sultanlığı'nın Şivâcî'yi bastırmak için gönderdiği Efdal Han kumandasındaki Âdilşâhî ordusu, Maratha reisi Şivâcî tarafından tuzağa düşürülerek yenildi; zafer Şivâcî'nin Batı Gatlar'daki gücünü pekiştirdi.","kaynak":"TDV: adilsahiler (ÂDİLŞÂHÎLER)","taraflar":["maratha","bicapur"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1665-06-11","k":"antlasma","tur":"antlasma","b":"Purandar Antlaşması: Şivâcî kalelerinin çoğunu Bâbürlülere bıraktı","gun":"11 Haziran 1665","yer":"Purandar","yer_id":"Pûne (Poona)","kisiler":"Şivâcî · Mirza Raca Cay Singh","d":"Bâbürlü komutanı Cay Singh'in kuşatması karşısında Şivâcî, Purandar'da yaptığı antlaşmayla yirmi üç kalesini Bâbürlülere bıraktı ve Bîcâpûr'a karşı Bâbürlülerle birlikte savaşmayı üstlendi; ertesi yıl Agra'da gözaltına alınıp kaçtı.","kaynak":"Stewart Gordon, The Marathas 1600–1818 (The New Cambridge History of India II.4, Cambridge UP, 1993)","taraflar":["maratha"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1713-01-01","k":"siyasi","tur":"siyasi","b":"Bâlâjî Vişvanâth peşva oldu, Maratha devletinde peşvalık dönemi başladı","gun":"(kaynak yıl verir)","yer":"Satara","yer_id":"Pûne (Poona)","kisiler":"Bâlâjî Vişvanâth · Şâhû","d":"Kral Şâhû'nun Bâlâjî Vişvanâth'ı peşva (başvezir) tayin etmesiyle fiilî iktidar Pune merkezli peşvalara geçti; makam onun soyunda babadan oğula intikal ederek Maratha genişlemesinin yönetim merkezi oldu.","kaynak":"Stewart Gordon, The Marathas 1600–1818 (The New Cambridge History of India II.4, Cambridge UP, 1993)","taraflar":["maratha"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1802-12-31","k":"antlasma","tur":"antlasma","b":"Bassein Antlaşması: Peşva II. Bâcî Rao İngiliz himayesini kabul etti","gun":"31 Aralık 1802","yer":"Bassein (Vasai)","yer_id":"Bombay","kisiler":"II. Bâcî Rao","d":"Holkar'a yenilip Pune'dan kaçan Peşva II. Bâcî Rao, İngiliz Doğu Hindistan Şirketi ile Bassein'de antlaşma yaparak Şirket askerini topraklarında kabul etti ve dış ilişkilerini Şirket'e bıraktı; öteki Maratha reislerinin tepkisi İkinci Anglo-Maratha Savaşı'nı doğurdu.","kaynak":"Stewart Gordon, The Marathas 1600–1818 (The New Cambridge History of India II.4, Cambridge UP, 1993)","taraflar":["maratha"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1442-01-01","k":"hukumdar","tur":"hukumdar","b":"Devletin asıl kurucusu sayılan I. Ahmed Şah öldü","gun":"(kaynak yıl verir)","yer":"Ahmedâbâd","yer_id":"Ahmedâbâd","kisiler":"I. Ahmed Şah","d":"Ahmedâbâd'ı kurup başkent yapan ve Gucerât Sultanlığı'nın asıl kurucusu kabul edilen I. Ahmed Şah öldü; ertesi yıllarda halefleri İdar ve Çâmpâner üzerine seferlerle genişlemeyi sürdürdü.","kaynak":"TDV: gucerat (GUCERÂT)","taraflar":["gucerat-sultanligi"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1458-01-01","k":"hukumdar","tur":"hukumdar","b":"Mahmud Şah (Begra) Gucerât tahtına çıktı","gun":"(kaynak yıl verir)","yer":"Ahmedâbâd","yer_id":"Ahmedâbâd","kisiler":"Mahmud Şah Begra","d":"Mahmud Şah'ın 1511'e kadar süren uzun saltanatı Gucerât Sultanlığı'nın en güçlü dönemlerinden biri oldu; sınırlar Kathiavar ve Çâmpâner'e doğru genişledi, Portekizlilerle deniz rekabeti bu dönemde başladı.","kaynak":"TDV: gucerat (GUCERÂT)","taraflar":["gucerat-sultanligi"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1535-01-01","k":"siyasi","tur":"siyasi","b":"Bahadır Şah, Portekizlilere Diu'da kale yapma izni verdi","gun":"(kaynak yıl verir)","yer":"Diu","yer_id":"Diu","kisiler":"Bahadır Şah","d":"Bâbürlü baskısı altındaki Bahadır Şah, Portekiz desteği karşılığında onlara Diu'da kale kurma izni verdi; bu izin Portekiz'in Gucerât kıyısında kalıcı olarak yerleşmesine ve iki yıl sonra sultanın Portekizlilerce öldürülmesine giden yolu açtı.","kaynak":"TDV: gucerat (GUCERÂT)","taraflar":["gucerat-sultanligi","portekiz"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1554-01-01","k":"hukumdar","tur":"hukumdar","b":"III. Mahmud Şah öldü, Gucerât'ta emîrler arası bölünme derinleşti","gun":"(kaynak yıl verir)","yer":"Mahmudâbâd","yer_id":"Ahmedâbâd","kisiler":"III. Mahmud Şah","d":"İkametini Mahmudâbâd'a taşımış olan III. Mahmud Şah'ın ölümünden sonra sultanlık emîrler arasında paylaşılan zayıf bir yapıya dönüştü; bu dağınıklık 1572'de Ekber'in Gucerât'a girmesini kolaylaştırdı.","kaynak":"TDV: gucerat (GUCERÂT)","taraflar":["gucerat-sultanligi"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1510-01-01","k":"savas","tur":"savas","b":"Portekizliler Goa'yı Âdilşâhîlerden kesin olarak aldı","gun":"Kasım 1510 (gün bilinmiyor)","yer":"Goa","yer_id":"Goa","d":"Portekizlilerin işgal ettiği Goa limanını Âdilşâhîler 20 Mayıs 1510'da geri aldı; ancak Portekizliler aynı yılın kasım ayında limanı yeniden ele geçirdi. Goa Portekiz'in Asya'daki merkezi oldu, Âdilşâhîler kıyıdaki en önemli limanlarını yitirdi.","kaynak":"TDV: adilsahiler (ÂDİLŞÂHÎLER)","taraflar":["bicapur","portekiz"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1558-01-01","k":"hukumdar","tur":"hukumdar","b":"Ali Âdilşah Bîcâpûr tahtına çıktı","gun":"(kaynak yıl verir)","yer":"Bîcâpûr","yer_id":"Bîcâpur (Bijapur)","kisiler":"I. Ali Âdilşah","d":"Ali Âdilşah başşehirde büyük camiyi ve şehir surlarını inşa ettirdi; saltanatında Bîcâpûr, 1565 Talikota'da Vijayanagara'yı yenen Dekken ittifakının önde gelen üyesi oldu.","kaynak":"TDV: bicapur (BÎCÂPÛR)","taraflar":["bicapur"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1619-01-01","k":"savas","tur":"savas","b":"Bîcâpûr, Berîdşâhî Sultanlığı'nı ortadan kaldırıp Bîdar'ı ilhak etti","gun":"(kaynak yıl verir)","yer":"Bîdar","yer_id":"Bîdar","kisiler":"II. İbrâhim Âdilşah","d":"II. İbrâhim Âdilşah, Behmenî mirasının küçük ardıllarından Berîdşâhîlerin merkezi Bîdar'ı alarak sultanlığa son verdi; Bîcâpûr kuzeydoğuda Golkonda ve Ahmednagar ile doğrudan sınır komşusu oldu.","kaynak":"Richard M. Eaton, A Social History of the Deccan, 1300–1761 (The New Cambridge History of India I.8, Cambridge UP, 2005)","taraflar":["bicapur"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1636-01-01","k":"antlasma","tur":"antlasma","b":"Bîcâpûr, Şah Cihan'la antlaşarak Bâbürlü üst hâkimiyetini tanıdı","gun":"(kaynak yıl verir)","yer":"Dekken","yer_id":"Bîcâpur (Bijapur)","kisiler":"Muhammed Âdilşah · Şah Cihan","d":"Muhammed Âdilşah döneminde Âdilşâhîler, Bâbürlü hâkimiyetini tanıyan bir barışa zorlandı; Bîcâpûr iç işlerinde serbest kalmakla birlikte Bâbürlülerin üst hâkimiyeti altına girdi.","kaynak":"TDV: adilsahiler (ÂDİLŞÂHÎLER)","taraflar":["bicapur"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1657-01-01","k":"savas","tur":"savas","b":"Şehzade Evrengzîb Bîcâpûr'u kuşattı, babası hastalanınca geri çekildi","gun":"1067 h. / 1656-57 (kaynak yıl verir)","yer":"Bîcâpûr","yer_id":"Bîcâpur (Bijapur)","kisiler":"Evrengzîb · Şah Cihan","d":"Dekken valisi Şehzade Evrengzîb Bîcâpûr'u kuşattı; ancak Şah Cihan'ın hastalanması ve başlayan taht mücadelesi üzerine kuşatmayı kaldırdı. Şehir ancak 1686'da onun padişahlığında alınacaktı.","kaynak":"TDV: bicapur (BÎCÂPÛR)","taraflar":["bicapur"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1543-01-01","k":"hukumdar","tur":"hukumdar","b":"Kurucu Kulı Kutbülmülk öldürüldü, oğlu Cemşîd tahta geçti","gun":"(kaynak yıl verir)","yer":"Golkonda","yer_id":"Golkonda","kisiler":"Kulı Kutbülmülk · Cemşîd Kutubşah","d":"Kutubşâhî devletinin kurucusu Sultan Kulı, oğlu Cemşîd tarafından öldürüldü ve Cemşîd hükümdar oldu; onun kısa saltanatından sonra taht İbrâhim Kutubşah'a geçti.","kaynak":"TDV: kutubsahiler (KUTUBŞÂHÎLER)","taraflar":["golkonda"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1636-01-01","k":"antlasma","tur":"antlasma","b":"Golkonda, Şah Cihan'la antlaşarak Bâbürlü üst hâkimiyetini tanıdı","gun":"(kaynak yıl verir)","yer":"Golkonda","yer_id":"Golkonda","kisiler":"Abdullah Kutubşah · Şah Cihan","d":"Abdullah Kutubşah, Şah Cihan'ın Dekken seferi karşısında Bâbürlü padişahının adını hutbede okutmayı ve yıllık harac ödemeyi kabul eden bir bağlılık belgesi imzaladı; sultanlık iç işlerinde serbest kaldı ama Bâbürlü tâbii oldu.","kaynak":"John F. Richards, The Mughal Empire (The New Cambridge History of India I.5, Cambridge UP, 1993)","taraflar":["golkonda"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1656-01-01","k":"savas","tur":"savas","b":"Evrengzîb'in Golkonda seferi: Abdullah Kutubşah kaleye çekildi","gun":"(kaynak yıl verir)","yer":"Golkonda","yer_id":"Golkonda","kisiler":"Evrengzîb · Abdullah Kutubşah","d":"Dekken valisi Şehzade Evrengzîb'in Golkonda üzerine seferi sırasında Sultan Abdullah Kutubşah kaleye çekildi ve savunma için Kal'a-i Nev'i inşa ettirdi.","kaynak":"TDV: gulkunde (GÜLKÜNDE)","taraflar":["golkonda"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1459-01-01","k":"siyasi","tur":"siyasi","b":"Rao Codha, Mârvâr'ın yeni başşehri Codhpur'u kurdu","gun":"(kaynak yıl verir)","yer":"Codhpur","yer_id":"Codhpûr (Jodhpur)","kisiler":"Rao Codha","d":"Rathor hanedanından Rao Codha, Mârvâr'ın merkezini Mandor'dan taşıyarak kendi adını taşıyan Codhpur'u ve Mehrangarh kalesini kurdu; şehir 1947'ye kadar Mârvâr devletinin başşehri kaldı.","kaynak":"Imperial Gazetteer of India, c. XIV (Oxford, 1908), 'Jodhpur State'","taraflar":["racput"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1488-01-01","k":"siyasi","tur":"siyasi","b":"Rao Bîka, Bîkâner şehrini kurup ayrı bir Rathor devleti oluşturdu","gun":"(kaynak yıl verir)","yer":"Bîkâner","yer_id":"Bikaner","kisiler":"Rao Bîka · Rao Codha","d":"Rao Codha'nın oğlu Rao Bîka, Thar çölünün kuzeyinde Cangaldeş bölgesini fethederek kendi adını taşıyan Bîkâner'i kurdu; Bîkâner, Mârvâr'dan ayrı bir Racput devleti olarak 1947'ye kadar sürdü.","kaynak":"Imperial Gazetteer of India, c. VIII (Oxford, 1908), 'Bikaner State'","taraflar":["racput"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1740-01-01","k":"hukumdar","tur":"hukumdar","b":"Bopal'in kurucusu Dost Muhammed Han öldü, oğlu Yâr Muhammed Han yerine geçti","gun":"(kaynak yıl verir)","yer":"Bopal","yer_id":"Bhopâl","kisiler":"Dost Muhammed Han · Yâr Muhammed Han","d":"Berâsiye bölgesinin idaresini alıp nevablığını kuran Dost Muhammed Han öldü; yerine oğlu Yâr Muhammed Han geçti ve hanedan Maratha baskısı altında bölgedeki varlığını sürdürdü.","kaynak":"TDV: bopal--devlet (BOPAL)","taraflar":["bhopal"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","t":"1844-01-01","k":"hukumdar","tur":"hukumdar","b":"İskender Begüm, kocası Cihangir Muhammed'in ölümüyle Bopal'de idareyi üstlendi","gun":"(kaynak yıl verir)","yer":"Bopal","yer_id":"Bhopâl","kisiler":"İskender Begüm · Cihangir Muhammed","d":"1837'de İngiliz desteğiyle iktidara gelen Cihangir Muhammed'in ölümünden sonra idare karısı İskender Begüm'e geçti; Bopal'de kadın hükümdarlar dönemi onunla kalıcılaştı.","kaynak":"TDV: bopal--devlet (BOPAL)","taraflar":["bhopal"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":1,"puan_s":"v2","t":"1868-01-01","k":"hukumdar","tur":"hukumdar","b":"İskender Begüm öldü, kızı Şah Cihan Begüm Bopal tahtına geçti","gun":"(kaynak yıl verir)","yer":"Bopal","yer_id":"Bhopâl","kisiler":"İskender Begüm · Şah Cihan Begüm","d":"İskender Begüm'ün ölümü üzerine kızı Şah Cihan Begüm hükümdar oldu; 1885'te idarî yetkisini bıraktı, 1901'deki ölümüne kadar unvanını korudu.","kaynak":"TDV: bopal--devlet (BOPAL)","taraflar":["bhopal"],"etiket":["konu-siyasi"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1811-01-01","k":"hukumdar","tur":"hukumdar","b":"II. Sâdık Muhammed Han Bahâvelpûr nevvâbı oldu, güney toprakları için İngiliz himayesi istedi","gun":"(kaynak yıl verir)","yer":"Bahâvelpûr","yer_id":"Bahâvelpûr","kisiler":"II. Sâdık Muhammed Han","d":"II. Sâdık Muhammed Han'ın 1811-1826 arasındaki saltanatında emirlik, güney topraklarını korumak için İngilizlerden himaye talep etti; bu, 1833 ve 1838 antlaşmalarına giden yakınlaşmanın başlangıcıdır.","kaynak":"TDV: bahavelpur (BAHÂVELPÛR)","taraflar":["bahavelpur"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1947-01-01","k":"siyasi","tur":"siyasi","b":"İngiliz himaye antlaşması sona erdi, Bahâvelpûr Pakistan'a katıldı","gun":"(kaynak yıl verir)","yer":"Bahâvelpûr","yer_id":"Bahâvelpûr","d":"İngiliz idaresinin Hindistan'dan çekilmesiyle 1838 himaye antlaşması sona erdi ve nevvâblık Pakistan'a katıldı; iç yönetimini 1955'e kadar ayrı bir devlet olarak sürdürdü.","kaynak":"TDV: bahavelpur (BAHÂVELPÛR)","taraflar":["bahavelpur"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1955-01-01","k":"siyasi","tur":"siyasi","b":"Bahâvelpûr Pencap eyaletine katıldı, nevvâblık sona erdi","gun":"(kaynak yıl verir)","yer":"Bahâvelpûr","yer_id":"Bahâvelpûr","d":"Bahâvelpûr toprakları komşu idarî birimlerle birleştirilerek Pakistan'ın Pencap eyaletine katıldı; nevvâblığın ayrı devlet olarak varlığı böylece bitti.","kaynak":"TDV: bahavelpur (BAHÂVELPÛR)","taraflar":["bahavelpur"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1662-01-01","k":"savas","tur":"savas","b":"Bâbürlü valisi Mîr Cümle Assam'ı istila edip Ahom başşehri Garhgaon'u aldı","gun":"(kaynak yıl verir)","yer":"Garhgaon","yer_id":"Sibsâgar (Rangpûr)","kisiler":"Mîr Cümle · Cayadhvac Singha","d":"Bengal valisi Mîr Cümle'nin seferi Ahom başşehri Garhgaon'u ele geçirdi ve Ahom kralını ağır bir barışa zorladı; ancak yağmur mevsimi ve salgın Bâbürlü ordusunu yıprattı, kazanımlar birkaç yıl içinde geri alındı.","kaynak":"Edward Gait, A History of Assam (Calcutta, 1906)","taraflar":["ahom"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1769-01-01","k":"siyasi","tur":"siyasi","b":"Moamoria ayaklanması Ahom krallığını sarsmaya başladı","gun":"(kaynak yıl verir)","yer":"Assam","yer_id":"Sibsâgar (Rangpûr)","d":"Moamoria mezhebine bağlı köylülerin başlattığı ayaklanma başşehri birkaç kez ele geçirdi ve on yıllarca süren iç savaşa dönüştü; krallığı zayıflatarak Birmanya istilasına ve İngiliz müdahalesine zemin hazırladı.","kaynak":"Edward Gait, A History of Assam (Calcutta, 1906)","taraflar":["ahom"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1792-01-01","k":"savas","tur":"savas","b":"Yüzbaşı Welsh'in seferi Ahom kralı Gaurinath Singha'yı tahtına geri oturttu","gun":"(kaynak yıl verir)","yer":"Assam","yer_id":"Sibsâgar (Rangpûr)","kisiler":"Gaurinath Singha · Thomas Welsh","d":"Moamoria isyancılarına karşı yardım isteyen Gaurinath Singha için İngiliz Doğu Hindistan Şirketi Yüzbaşı Thomas Welsh komutasında bir birlik gönderdi; kralın otoritesi geçici olarak yeniden kuruldu, Şirket Assam işlerine ilk kez doğrudan girdi.","kaynak":"Edward Gait, A History of Assam (Calcutta, 1906)","taraflar":["ahom"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1529-01-01","k":"siyasi","tur":"siyasi","b":"Vişvanâtha Nâyak, Vijayanagara adına Madurai nâyaklığını kurdu","gun":"(kaynak yıl verir)","yer":"Madurai","yer_id":"Madurai","kisiler":"Vişvanâtha Nâyak","d":"Vijayanagara'nın Tamil ülkesindeki valisi Vişvanâtha Nâyak Madurai'de nâyaklığı kurdu; beylik Vijayanagara'ya bağlı başladı, 1565 Talikota yenilgisinden sonra fiilen bağımsızlaştı.","kaynak":"R. Sathyanatha Aiyar, History of the Nayaks of Madura (Oxford UP, 1924)","taraflar":["nayak-devletleri"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1623-01-01","k":"hukumdar","tur":"hukumdar","b":"Tirumala Nâyak Madurai tahtına çıktı","gun":"(kaynak yıl verir)","yer":"Madurai","yer_id":"Madurai","kisiler":"Tirumala Nâyak","d":"Tirumala Nâyak'ın 1659'a kadar süren saltanatı Madurai nâyaklığının en güçlü dönemi oldu; başşehir Tiruçirapalli'den Madurai'ye döndü, Meysûr ve Bîcâpûr ile savaşlar yapıldı.","kaynak":"R. Sathyanatha Aiyar, History of the Nayaks of Madura (Oxford UP, 1924)","taraflar":["nayak-devletleri"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1673-01-01","k":"savas","tur":"savas","b":"Madurai nâyakı Çokkanâtha Tancavur'u alıp Tancavur nâyaklığına son verdi","gun":"(kaynak yıl verir)","yer":"Tancavur","yer_id":"Tancûr (Thanjavur)","kisiler":"Çokkanâtha Nâyak · Vicayarâghava Nâyak","d":"Madurai nâyakı Çokkanâtha, komşu Tancavur nâyaklığını ele geçirdi ve son Tancavur nâyakı Vicayarâghava öldürüldü; kısa süre sonra Tancavur, Bîcâpûr hizmetindeki Maratha komutanı Ekocî'nin eline geçti.","kaynak":"R. Sathyanatha Aiyar, History of the Nayaks of Madura (Oxford UP, 1924)","taraflar":["nayak-devletleri"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1754-01-01","k":"hukumdar","tur":"hukumdar","b":"Şücâüddevle, babası Safder Cenk'in ölümüyle Avad nevabı oldu","gun":"(kaynak yıl verir)","yer":"Faizâbâd","yer_id":"Feyzâbâd (Ayodhya)","kisiler":"Şücâüddevle · Safder Cenk","d":"Safder Cenk'in ölümü üzerine oğlu Şücâüddevle Avad nevabı oldu; Bâbürlü vezirliğini de üstlenen nevab, 1764 Buksar yenilgisine kadar Kuzey Hindistan'ın en güçlü hükümdarlarından biriydi.","kaynak":"Michael H. Fisher, A Clash of Cultures: Awadh, the British and the Mughals (Riverdale, 1987)","taraflar":["avad"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1775-01-01","k":"siyasi","tur":"siyasi","b":"Âsafüddevle Avad başşehrini Faizâbâd'dan Leknev'e taşıdı","gun":"(kaynak yıl verir)","yer":"Leknev (Lucknow)","yer_id":"Leknev (Lucknow)","kisiler":"Âsafüddevle","d":"Şücâüddevle'nin ölümüyle tahta çıkan Âsafüddevle, Leknev'i kendisine merkez yaptı; şehir bundan sonra Avad nevvâblarının başşehri olarak gelişti.","kaynak":"TDV: leknev (LEKNEV)","taraflar":["avad"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1801-01-01","k":"antlasma","tur":"antlasma","b":"Avad, Şirket'le antlaşmayla topraklarının yaklaşık yarısını bıraktı","gun":"(kaynak yıl verir)","yer":"Leknev","yer_id":"Leknev (Lucknow)","kisiler":"Saâdet Ali Han · Richard Wellesley","d":"Genel Vali Wellesley'nin baskısıyla Nevab Saâdet Ali Han, Şirket askerinin masrafı karşılığında Rohilkhand ve Aşağı Doâb dahil topraklarının yaklaşık yarısını İngiliz Doğu Hindistan Şirketi'ne terk etti.","kaynak":"Michael H. Fisher, A Clash of Cultures: Awadh, the British and the Mughals (Riverdale, 1987)","taraflar":["avad"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1819-01-01","k":"siyasi","tur":"siyasi","b":"Gâziyüddin Haydar padişah unvanı alarak Bâbürlü üst hâkimiyetinden ayrıldı","gun":"(kaynak yıl verir)","yer":"Leknev","yer_id":"Leknev (Lucknow)","kisiler":"Gâziyüddin Haydar","d":"İngilizler Avad nevvâbı Gâziyüddin Haydar'ı kral ilân etti ve Leknev bir krallık başşehri oldu; Avad hükümdarları böylece Delhi'deki Bâbürlü padişahına biçimsel bağlılığı da bıraktı.","kaynak":"TDV: leknev (LEKNEV)","taraflar":["avad"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1739-01-01","k":"hukumdar","tur":"hukumdar","b":"Sri Vicaya Racasinha ile Kandy'de Nâyak kökenli hanedan başladı","gun":"(kaynak yıl verir)","yer":"Kandy","yer_id":"Kandy","kisiler":"Sri Vicaya Racasinha · II. Vira Narendrasinha","d":"Son Sinhala kökenli kral II. Vira Narendrasinha'nın ölümünden sonra tahta Madurai Nâyak soyundan kayınbiraderi Sri Vicaya Racasinha geçti; bu hanedan 1815'e kadar Kandy'yi yönetti.","kaynak":"K. M. de Silva, A History of Sri Lanka (London: C. Hurst, 1981)","taraflar":["kandy"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1766-01-01","k":"antlasma","tur":"antlasma","b":"Kandy, Hollandalılarla antlaşmayla bütün kıyı şeridini bıraktı","gun":"(kaynak yıl verir)","yer":"Kandy","yer_id":"Kandy","kisiler":"Kirti Sri Racasinha","d":"Hollanda'nın 1765'te başşehri alıp yakmasından sonra imzalanan antlaşmayla Kandy, adanın bütün kıyı şeridini Hollanda Doğu Hindistan Şirketi'ne bıraktı ve denizle bağlantısını yitirdi.","kaynak":"K. M. de Silva, A History of Sri Lanka (London: C. Hurst, 1981)","taraflar":["kandy"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1803-01-01","k":"savas","tur":"savas","b":"Birinci Kandy Savaşı: İngilizler başşehri aldı ama geri çekilmek zorunda kaldı","gun":"(kaynak yıl verir)","yer":"Kandy","yer_id":"Kandy","kisiler":"Sri Vikrama Racasinha","d":"Kıyıyı Hollandalılardan devralan İngilizler Kandy'yi işgal edip kendi adaylarını tahta çıkarmaya çalıştı; hastalık ve Kandy karşı saldırısı karşısında garnizon imha edildi, krallık 1815'e kadar bağımsız kaldı.","kaynak":"K. M. de Silva, A History of Sri Lanka (London: C. Hurst, 1981)","taraflar":["kandy"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1744-01-01","k":"hukumdar","tur":"hukumdar","b":"Enverüddin Han, Nizâmülmülk tarafından Karnatik nevabı tayin edildi","gun":"(kaynak yıl verir)","yer":"Arkot","yer_id":"Arkot (Arcot)","kisiler":"Enverüddin Han · Nizâmülmülk Âsafcâh","d":"Nevayet hanedanının iç karışıklıklarından sonra Haydarabad nizamı Nizâmülmülk, Karnatik'e dışarıdan Enverüddin Han'ı nevab olarak tayin etti; eski hanedanın taraftarları Fransızlarla birleşerek karşı cephe kurdu.","kaynak":"H. H. Dodwell, Dupleix and Clive: The Beginning of Empire (London, 1920)","taraflar":["karnatik","haydarabad-nizam"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1749-08-03","k":"savas","tur":"savas","b":"Ambur Savaşı: Karnatik nevabı Enverüddin Han öldürüldü","gun":"3 Ağustos 1749","yer":"Ambur","yer_id":"Vellor (Vellore)","kisiler":"Enverüddin Han · Çanda Sâhib · Muzaffer Cenk","d":"Fransız destekli Çanda Sâhib ile Muzaffer Cenk'in kuvvetleri Ambur'da Nevab Enverüddin Han'ı yenip öldürdü; oğlu Muhammed Ali İngilizlere sığındı ve Karnatik taht mücadelesi İngiliz-Fransız savaşına dönüştü.","kaynak":"H. H. Dodwell, Dupleix and Clive: The Beginning of Empire (London, 1920)","taraflar":["karnatik"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1731-01-01","k":"antlasma","tur":"antlasma","b":"Varna Antlaşması: Kolhapur ile Satara arasında Maratha tahtı bölüşüldü","gun":"(kaynak yıl verir)","yer":"Varna","yer_id":"Kolhapûr","kisiler":"Şâhû · II. Sambhâcî","d":"Satara'daki Şâhû ile Kolhapur'daki II. Sambhâcî, Varna'da yaptıkları antlaşmayla iki ayrı Maratha tahtını karşılıklı tanıdı; Varna nehrinin güneyi Kolhapur'a bırakıldı ve Kolhapur ayrı bir devlet olarak kaldı.","kaynak":"Stewart Gordon, The Marathas 1600–1818 (The New Cambridge History of India II.4, Cambridge UP, 1993)","taraflar":["kolhapur","maratha"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1802-01-01","k":"antlasma","tur":"antlasma","b":"Baroda'nın Gaikvad hükümdarı İngiliz Şirketi ile tâbi ittifak antlaşması yaptı","gun":"(kaynak yıl verir)","yer":"Baroda","yer_id":"Baroda (Vadodara)","kisiler":"Anand Rao Gaikvad","d":"İç taht mücadelesi içindeki Gaikvad hükümeti, İngiliz Doğu Hindistan Şirketi'nin askerî desteği karşılığında Şirket birliklerini topraklarında beslemeyi kabul etti; Baroda Peşva'dan fiilen ayrılıp İngiliz himayesine girdi.","kaynak":"Imperial Gazetteer of India, c. VII (Oxford, 1908), 'Baroda State'","taraflar":["baroda"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1875-01-01","k":"hukumdar","tur":"hukumdar","b":"Malhar Rao Gaikvad tahttan indirildi, III. Sayacirao Baroda hükümdarı seçildi","gun":"(kaynak yıl verir)","yer":"Baroda","yer_id":"Baroda (Vadodara)","kisiler":"Malhar Rao Gaikvad · III. Sayacirao Gaikvad","d":"İngiliz mukimi zehirlemeye teşebbüsle suçlanan Malhar Rao, Hindistan hükümetince tahttan indirildi; hanedanın uzak bir kolundan III. Sayacirao hükümdar seçildi ve 1939'a kadar süren saltanatında Baroda reformcu bir devlet oldu.","kaynak":"Imperial Gazetteer of India, c. VII (Oxford, 1908), 'Baroda State'","taraflar":["baroda"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1767-01-01","k":"hukumdar","tur":"hukumdar","b":"Ahilyabai Holkar İndor'un yönetimini üstlendi","gun":"(kaynak yıl verir)","yer":"Mahesvar","yer_id":"İndor (Indore)","kisiler":"Ahilyabai Holkar · Malhar Rao Holkar","d":"Kayınpederi Malhar Rao Holkar'ın ve oğlunun ölümlerinden sonra Ahilyabai Holkar devletin yönetimini üstlendi; 1795'teki ölümüne kadar Mahesvar'dan yönettiği İndor, Maratha dünyasında istikrarlı bir dönem yaşadı.","kaynak":"Stewart Gordon, The Marathas 1600–1818 (The New Cambridge History of India II.4, Cambridge UP, 1993)","taraflar":["indor"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","t":"1782-05-17","k":"antlasma","tur":"antlasma","b":"Salbai Antlaşması: Mahâdcî Sindiya'nın arabuluculuğuyla Birinci Anglo-Maratha Savaşı bitti","gun":"17 Mayıs 1782","yer":"Salbai","yer_id":"Gvalyar (Gwalior)","kisiler":"Mahâdcî Sindiya","d":"Gvalyar hükümdarı Mahâdcî Sindiya'nın arabuluculuğuyla imzalanan Salbai Antlaşması Birinci Anglo-Maratha Savaşı'nı bitirdi; Sindiya'nın Hindistan siyasetindeki ağırlığı arttı, Salsette İngilizlerde kaldı.","kaynak":"Stewart Gordon, The Marathas 1600–1818 (The New Cambridge History of India II.4, Cambridge UP, 1993)","taraflar":["gvalyar","maratha"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1843-12-29","k":"savas","tur":"savas","b":"Mahârâcpur ve Panniar savaşları: İngilizler Gvalyar ordusunu yendi","gun":"29 Aralık 1843","yer":"Mahârâcpur","yer_id":"Gvalyar (Gwalior)","d":"Gvalyar sarayındaki naiplik krizi üzerine giren İngiliz kuvvetleri aynı gün Mahârâcpur ve Panniar'da Sindiya ordusunu yendi; ardından yapılan antlaşmayla Gvalyar ordusu küçültüldü ve devlet İngiliz denetimine daha sıkı bağlandı.","kaynak":"Imperial Gazetteer of India, c. XII (Oxford, 1908), 'Gwalior State'","taraflar":["gvalyar"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1947-01-01","k":"siyasi","tur":"siyasi","b":"Cunagadh nevabı devletini Pakistan'a bağlama kararı aldı","gun":"Ağustos-Eylül 1947 (gün yazılmadı)","yer":"Cunagadh","yer_id":"Cûnâgadh","kisiler":"III. Mahabet Han","d":"Halkının çoğunluğu Hindu olan ve Pakistan'la kara bağlantısı bulunmayan Cunagadh'ın nevabı, devletini Pakistan'a bağlama kararı aldı; Hindistan bunu tanımayıp çevreyi ablukaya aldı.","kaynak":"V. P. Menon, The Story of the Integration of the Indian States (Longmans, 1956)","taraflar":["cunagadh"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1947-11-09","k":"siyasi","tur":"siyasi","b":"Hindistan Cunagadh'ın idaresini devraldı","gun":"9 Kasım 1947","yer":"Cunagadh","yer_id":"Cûnâgadh","kisiler":"III. Mahabet Han","d":"Nevabın Karaçi'ye kaçmasından sonra devlet divanının çağrısıyla Hindistan hükümeti Cunagadh'ın idaresini devraldı; Şubat 1948'deki halk oylamasıyla katılma kesinleşti.","kaynak":"V. P. Menon, The Story of the Integration of the Indian States (Longmans, 1956)","taraflar":["cunagadh"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","t":"1831-01-01","k":"siyasi","tur":"siyasi","b":"İngilizler Meysûr racalığının yönetimini doğrudan üstlendi","gun":"(kaynak yıl verir)","yer":"Meysûr","yer_id":"Meysûr (Mysore)","kisiler":"III. Krişnaraca Vodeyar","d":"Nagar bölgesindeki köylü ayaklanması ve mâlî kötü yönetim gerekçesiyle Genel Vali Bentinck, III. Krişnaraca Vodeyar'ı yönetimden uzaklaştırdı; Meysûr elli yıl İngiliz komiserlerince yönetildi ve 1881'de hanedana iade edildi.","kaynak":"Imperial Gazetteer of India, c. XVIII (Oxford, 1908), 'Mysore State'","taraflar":["meysur-racaligi"],"etiket":["konu-siyasi"]},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","t":"1740-01-01","k":"savas","tur":"savas","b":"Giria Savaşı: Alîverdi Han, Nevab Serferaz Han'ı öldürüp Bengal nevabı oldu","gun":"(kaynak yıl verir)","yer":"Giria","yer_id":"Murşidâbâd","kisiler":"Alîverdi Han · Serferaz Han","d":"Bihar naibi Alîverdi Han, Giria'da Nevab Serferaz Han'ı yenip öldürdü ve Bengal nevablığını ele geçirdi; Murşid Kulı Han'ın soyunun iktidarı böylece sona erdi.","kaynak":"P. J. Marshall, Bengal: The British Bridgehead, Eastern India 1740–1828 (The New Cambridge History of India II.2, Cambridge UP, 1987)","taraflar":["bengal-nevabligi"],"etiket":["konu-siyasi"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","t":"1751-01-01","k":"antlasma","tur":"antlasma","b":"Alîverdi Han, Maratha akınlarını Orissa'yı bırakıp haraç ödeyerek durdurdu","gun":"(kaynak yıl verir)","yer":"Bengal","yer_id":"Murşidâbâd","kisiler":"Alîverdi Han","d":"1742'den beri Bengal'i yağmalayan Nagpur Maratha akınlarına son vermek için Alîverdi Han, Orissa'nın fiilen Marathalara bırakıldığı ve Bengal'in yıllık haraç ödediği bir antlaşma yaptı.","kaynak":"P. J. Marshall, Bengal: The British Bridgehead, Eastern India 1740–1828 (The New Cambridge History of India II.2, Cambridge UP, 1987)","taraflar":["bengal-nevabligi","maratha"],"etiket":["konu-siyasi"]}];

